VALUES ('c0f9d95a-27bc-4bc0-8351-9ff181087244', 'NC26.3.ANR.2', 1, 'choice', 'Subtract in a story with regrouping', 'Lena had 86 stickers. She gave 39 of them to a friend. How many stickers does Lena have now?', '["47","53","57","125"]', '47', '86-39', 'Subtract: 86 − 39. You cannot take 9 ones from 6 ones, so trade one ten for 10 ones: 16 − 9 = 7 ones. Now there are 7 tens left: 7 − 3 = 4 tens. The answer is 47. Check: 47 + 39 = 86.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"86 - 39 = 86 - 40 + 1 = 47.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
