VALUES ('9a445fe2-7b97-4b91-b87e-798e698e759e', 'NC26.3.ANR.2', 1, 'numeric', 'Add in a story', 'A bakery sold 128 muffins in the morning and 145 muffins in the afternoon. How many muffins did it sell in all?', '[]', '273', '128+145', 'Add: 128 + 145. Ones: 8 + 5 = 13, write 3 and carry 1 ten. Tens: 2 + 4 + 1 = 7. Hundreds: 1 + 1 = 2. The total is 273.', 'checked', '{"lint":[],"solve":{"answer":"273","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"128 + 145: 100+100 = 200, 20+40 = 60, 8+5 = 13. 200+60+13 = 273.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
