VALUES ('29880fb0-b581-46c5-badc-031d7044337c', 'NC26.3.ANR.2', 2, 'choice', 'Add by place value (expanded form)', 'Sam adds $364 + 258$ by adding the hundreds, then the tens, then the ones. Which choice shows his steps?', '["300 + 200, then 60 + 50, then 4 + 5","300 + 20, then 60 + 5, then 4 + 8","300 + 200, then 6 + 5, then 4 + 8","300 + 200, then 60 + 50, then 4 + 8"]', '300 + 200, then 60 + 50, then 4 + 8', NULL, '364 = 300 + 60 + 4 and 258 = 200 + 50 + 8. So the hundreds are 300 + 200, the tens are 60 + 50, and the ones are 4 + 8. (500 + 110 + 12 = 622.)', 'checked', '{"lint":[],"solve":{"answer":"300 + 200, then 60 + 50, then 4 + 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"364 = 300+60+4, 258 = 200+50+8. Hundreds 300+200, tens 60+50, ones 4+8. Only the last option has all three right.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
