VALUES ('8c5af546-c519-4d78-9aa0-d5be19c75673', 'NC26.3.ANR.2', 2, 'choice', 'Subtract in a story with regrouping twice', 'A school has 453 students. Of these, 178 ride the bus. How many students do not ride the bus?', '["285","275","325","631"]', '275', '453-178', 'Subtract: 453 − 178. Ones: trade a ten, 13 − 8 = 5. Tens: now 4 tens, so trade a hundred, 14 − 7 = 7. Hundreds: now 3 hundreds, 3 − 1 = 2. The answer is 275. Check: 275 + 178 = 453.', 'checked', '{"lint":[],"solve":{"answer":"275","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"453 - 178: 453 - 200 = 253, + 22 = 275. Check 275 + 178 = 453.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
