VALUES ('6f4548c5-bc72-4690-96f1-6e72a1968009', 'NC26.3.ANR.2', 3, 'choice', 'Add by changing one number (compensation)', 'Which expression has the same value as $352 + 199$?', '["$352 + 200 - 1$","$352 + 200 + 1$","$352 - 200 + 1$","$352 + 100 - 1$"]', '$352 + 200 - 1$', NULL, '199 is 1 less than 200. Adding 200 adds one too many, so take 1 away: $352 + 200 - 1 = 551$. This is the same as $352 + 199 = 551$.', 'checked', '{"lint":[],"solve":{"answer":"$352 + 200 - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"199 = 200 - 1, so 352 + 199 = 352 + 200 - 1 = 551.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
