VALUES ('fac9577d-cfa1-493e-9213-bc3a654fd01f', 'NC26.3.ANR.3', 3, 'choice', 'Patterns made by repeated adding', 'A pattern starts at 0 and adds 4 each time: 0, 4, 8, 12, and so on. Which number will be in the pattern?', '["30","34","38","36"]', '36', '4*9', 'The numbers in the pattern are what you get by counting by 4s: 4, 8, 12, 16, 20, 24, 28, 32, 36. So 36 is in the pattern ($4 \times 9 = 36$). The numbers 30, 34 and 38 are skipped.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pattern is multiples of 4. 36 = 4 x 9 is in it; 38, 34, 30 are not multiples of 4.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5282d6bf-ebd0-4198-81c7-7c33b0c209e9', 'NC26.3.ANR.3', 3, 'choice', 'Break a multiplication fact using 10', 'Which expression is equal to $6 \times 9$?', '["$(6 \\times 10) - 6$","$(6 \\times 10) - 9$","$(6 \\times 10) + 6$","$(6 \\times 10) - 1$"]', '$(6 \times 10) - 6$', NULL, '9 is one less than 10, so $6 \times 9$ is 6 less than $6 \times 10$. That is $60 - 6 = 54$, and $6 \times 9 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"$(6 \\times 10) - 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 9 = 54. (6 x 10) - 6 = 60 - 6 = 54. Others: 59, 51, 66.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4acd5117-3f4f-464a-b7f5-a9d6826a19b4', 'NC26.3.ANR.4', 1, 'numeric', 'Share equally: size of each group', '12 cookies are shared equally among 4 children. How many cookies does each child get?', '[]', '3', '12/4', 'Share 12 into 4 equal groups: $12 \div 4 = 3$. Each child gets 3 cookies.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 4 = 3.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
