INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3bc6821-fcec-4a2d-bb1a-a61732a55646', 'NC26.3.ANR.4', 1, 'choice', 'Match a story to a division sentence', 'Which story matches $18 \div 3$?', '["Maya has 18 pencils and gets 3 more.","3 students each have 18 pencils.","18 pencils are shared equally among 3 students.","Maya has 18 pencils and loses 3."]', '18 pencils are shared equally among 3 students.', NULL, '$18 \div 3$ means making equal shares of 18. Sharing 18 pencils equally among 3 students matches. The other stories are adding, multiplying and subtracting.', 'checked', '{"lint":[],"solve":{"answer":"18 pencils are shared equally among 3 students.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 3 is sharing 18 equally into 3 groups. The other stories are multiplication, subtraction and addition.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
