INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf0e2b5d-9d81-49de-9d23-034d875346d7', 'NC26.3.ANR.4', 2, 'numeric', 'Equation with an unknown divisor', '$36 \div \square = 9$. What number goes in the box?', '[]', '4', '36/9', '$36 \div \square = 9$ means $9 \times \square = 36$. Since $9 \times 4 = 36$, the box is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / ? = 9, so ? = 36 / 9 = 4. Check 36 / 4 = 9.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
