INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c0ee155-65ed-4688-9a2c-fa8c10a289e9', 'NC26.3.ANR.4', 2, 'numeric', 'Division as repeated subtraction', 'Dan has 28 beads. He takes away 4 beads again and again until he has none left. How many times does he take away 4 beads?', '[]', '7', '28/4', 'Taking away 4 until nothing is left finds how many 4s are in 28. $28 \div 4 = 7$, so he takes away 4 beads seven times.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 - 4 repeatedly: 24, 20, 16, 12, 8, 4, 0 = 7 times. 28 / 4 = 7.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
