INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f155c2d8-8bad-42e3-ad14-7c461ce865a8', 'NC26.3.ANR.4', 3, 'numeric', 'Equation with an unknown dividend', 'A number divided by 6 is 7. What is the number?', '[]', '42', '7*6', 'Division and multiplication undo each other. If a number split into groups of 6 gives 7 groups, then the number is $7 \times 6 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? / 6 = 7, so ? = 6 x 7 = 42.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
