INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a15f83c-ed9b-4f8a-ae51-73486610acf9', 'NC26.3.ANR.4', 3, 'choice', 'Write an equation for a division story', '24 students are split into 4 teams with the same number of students on each team. Let $n$ be the number of students on each team. Which equation can be used to find $n$?', '["$n \\times 24 = 4$","$24 \\times 4 = n$","$n + 4 = 24$","$4 \\times n = 24$"]', '$4 \times n = 24$', NULL, '4 teams with $n$ students each is $4 \times n$, and that equals 24 students. So $4 \times n = 24$, which gives $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times n = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 teams of n students make 24: 4 x n = 24 (n = 6). Other equations are wrong.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a950668-d804-4f5e-bdbd-3f5fea04b409', 'NC26.3.ANR.4', 3, 'choice', 'Meaning of the quotient', '72 buttons are put into equal groups of 9 buttons, and $72 \div 9 = 8$. What does the 8 tell you?', '["The number of buttons in each group","The total number of buttons","The number of buttons left over","The number of groups"]', 'The number of groups', NULL, 'Each group has 9 buttons (that is the divisor). The total is 72. The answer 8 tells how many groups of 9 can be made.', 'checked', '{"lint":[],"solve":{"answer":"The number of groups","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Groups of 9 is the group size; 72 / 9 = 8 tells how many groups.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
