INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e93d67c-d09c-4fc5-a311-fe16c6de7718', 'NC26.3.ANR.5', 2, 'choice', 'Use a multiplication fact to divide', 'Which multiplication fact can help you solve $48 \div 6$?', '["$6 \\times 6 = 36$","$4 \\times 8 = 32$","$6 \\times 8 = 48$","$48 \\times 6 = 288$"]', '$6 \times 8 = 48$', NULL, '$48 \div 6$ asks: 6 times what number makes 48? The fact $6 \times 8 = 48$ answers it, so $48 \div 6 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 8 = 48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 6 = ? is the same as 6 x ? = 48; 6 x 8 = 48.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
