INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc1998ec-69b8-4ac0-8127-7041afdd1b71', 'NC26.3.ANR.5', 3, 'choice', 'Inverse operation in a story', 'Pia has 42 stickers. She puts 6 stickers on each page. Let $p$ be the number of pages she fills. Which equation can she use to find $p$?', '["$42 \\times 6 = p$","$p + 6 = 42$","$42 \\times p = 6$","$6 \\times p = 42$"]', '$6 \times p = 42$', NULL, '$p$ pages with 6 stickers on each page is $6 \times p$ stickers, and that is 42. So $6 \times p = 42$, and $p = 42 \div 6 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times p = 42$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p pages with 6 each make 42: 6 x p = 42 (p = 7).","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08ddb18c-eec2-4de1-a633-480875f7e611', 'NC26.3.ANR.5', 3, 'choice', 'Which equation is true', 'Which equation is true?', '["$8 \\div 4 = 4 \\div 8$","$8 \\times 0 = 8$","$8 \\times 1 = 1$","$8 \\times 5 = 5 \\times 8$"]', '$8 \times 5 = 5 \times 8$', NULL, 'Order does not matter in multiplication: $8 \times 5 = 40$ and $5 \times 8 = 40$. But $8 \div 4 = 2$ and $4 \div 8$ is not 2; $8 \times 0 = 0$; and $8 \times 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 5 = 5 \\times 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 0 = 0 (false), 8 x 1 = 8 (false), 8 x 5 = 40 = 5 x 8 (true, commutative), 8 / 4 = 2 but 4 / 8 is not 2 (false).","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
