VALUES ('9b5099dc-ba8d-463e-b932-f38bd4076133', 'NC26.3.ANR.6', 1, 'numeric', 'Two-step: add then subtract', 'Ben has 12 stickers. He buys 8 more stickers. Then he gives 5 stickers to his sister. How many stickers does Ben have now?', '[]', '15', '12+8-5', 'First: 12 + 8 = 20. Then: 20 − 5 = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 8 = 20; 20 - 5 = 15.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
