VALUES ('b26bb15d-0b9d-41b6-a9ae-b3710c82fc29', 'NC26.3.ANR.6', 1, 'choice', 'Estimate a sum by rounding', 'Which is the best estimate of $398 + 205$?', '["500","600","700","800"]', '600', '400+200', 'Round each number to the nearest hundred: 398 is about 400 and 205 is about 200. Then $400 + 200 = 600$. (The exact sum is 603.)', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"398 is about 400, 205 is about 200; 400 + 200 = 600 (exact 603).","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
