VALUES ('9cd03fa9-5ba7-4b06-9b17-b6f2f20e5e81', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: multiply then subtract from a total', 'Carlos has 50 dollars. He buys 3 notebooks that cost 7 dollars each. How many dollars does he have left?', '["21","43","29","71"]', '29', '50-3*7', 'The notebooks cost $3 \times 7 = 21$ dollars. Then 50 − 21 = 29 dollars are left.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 7 = 21 dollars spent; 50 - 21 = 29.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
