INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4640c1d0-3290-4c89-b9c8-00738983481b', 'NC26.3.ANR.6', 2, 'choice', 'Estimate in a two-step story', 'A baker made 289 cookies on Monday and 311 cookies on Tuesday. She sold 395 cookies. About how many cookies are left?', '["200","100","600","1,000"]', '200', '300+300-400', 'Round to the nearest hundred: 289 is about 300, 311 is about 300, 395 is about 400. Cookies made: about $300 + 300 = 600$. Take away the sold ones: $600 - 400 = 200$.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimate: 300 + 300 - 400 = 200. Exact: 289 + 311 = 600, 600 - 395 = 205, about 200.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
