VALUES ('602ae1bb-42c7-48a8-af55-6ac6b2c02f0c', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: add then multiply', 'Each bag has 7 red marbles and 8 blue marbles. How many marbles are in 4 bags?', '["15","60","19","36"]', '60', '4*(7+8)', 'One bag has 7 + 8 = 15 marbles. Four bags have $4 \times 15 = 60$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each bag 7 + 8 = 15 marbles; 4 x 15 = 60.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
