INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('750523e4-b47f-4a01-8ef9-892c7d65c7a2', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: multiply then compare', 'Nina has 7 boxes with 8 beads in each box. Omar has 39 beads. How many more beads does Nina have than Omar?', '[]', '17', '7*8-39', 'Nina has $7 \times 8 = 56$ beads. Then 56 − 39 = 17 more beads.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nina 7 x 8 = 56; 56 - 39 = 17.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
