INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cba2ba6-eb38-4bdd-bfb1-c1f5045f9f71', 'NC26.3.ANR.7', 1, 'choice', 'Unit fraction of a whole', 'A pizza is cut into 8 equal slices. Mia eats 1 slice. What fraction of the pizza did she eat?', '["$\\frac{1}{7}$","$\\frac{7}{8}$","$\\frac{8}{1}$","$\\frac{1}{8}$"]', '$\frac{1}{8}$', NULL, 'The pizza has 8 equal slices, so each slice is $\frac{1}{8}$ of the pizza. Mia ate 1 slice, so she ate $\frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 of 8 equal slices is 1/8 of the pizza.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fbd3739-4003-40d0-9c2e-c0c2d2ad6e55', 'NC26.3.ANR.7', 1, 'numeric', 'Numerator counts shaded parts (area model in words)', 'A rectangle is cut into 6 equal parts. 5 of the parts are shaded. What fraction of the rectangle is shaded? Write your answer like 1/2.', '[]', '5/6', '5/6', 'The rectangle has 6 equal parts, so each part is $\frac{1}{6}$. 5 parts are shaded, so $\frac{5}{6}$ is shaded.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 of 6 equal parts shaded: 5/6.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
