INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd78b9ba-2d67-4657-a723-06cc535fdc59', 'NC26.3.ANR.7', 1, 'choice', 'A whole as a fraction', 'A pie is cut into 4 equal pieces. Which fraction shows all of the pie?', '["$\\frac{1}{4}$","$\\frac{3}{4}$","$\\frac{4}{4}$","$\\frac{4}{1}$"]', '$\frac{4}{4}$', NULL, 'Each piece is $\frac{1}{4}$ of the pie. All 4 pieces together are $\frac{4}{4}$, which is 1 whole pie.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All 4 of 4 equal pieces: 4/4 = 1 whole. 4/1 would be 4 whole pies.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ce65cc8-9cc1-4eb2-9425-5bc6bb682386', 'NC26.3.ANR.7', 2, 'numeric', 'Equivalent fractions', 'What number makes $\frac{1}{2} = \frac{\square}{6}$ true?', '[]', '3', '1/2*6', 'Cut each half into 3 equal parts. The whole has 2 halves, which is 6 sixths. So 1 half is 3 sixths, and $\frac{1}{2} = \frac{3}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 6 sixths is 3 sixths: 1/2 = 3/6.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
