INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('885376ba-890f-4330-9b26-ab96f9e5b2de', 'NC26.3.ANR.7', 2, 'choice', 'Compare to one half', 'Which fraction is greater than $\frac{1}{2}$?', '["$\\frac{3}{4}$","$\\frac{1}{3}$","$\\frac{1}{4}$","$\\frac{3}{8}$"]', '$\frac{3}{4}$', NULL, 'Half of 4 fourths is 2 fourths, so $\frac{3}{4}$ is more than $\frac{1}{2}$. Half of 8 eighths is 4 eighths, so $\frac{3}{8}$ is less than $\frac{1}{2}$. And $\frac{1}{3}$ and $\frac{1}{4}$ are less than half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8 = 2/4. 3/4 > 2/4 = 1/2. 1/3, 1/4 and 3/8 are each less than 1/2.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d31c5a3-8375-4650-a734-7ec4e978a788', 'NC26.3.ANR.7', 2, 'numeric', 'Fraction at a point on a number line (in words)', 'A number line from 0 to 1 is split into 8 equal parts. A point is on the 5th mark after 0. What fraction names the point? Write your answer like 1/2.', '[]', '5/8', '5/8', 'Each part of the number line is $\frac{1}{8}$ long. The 5th mark after 0 is 5 of those parts from 0, so the point is at $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each part is 1/8; the 5th mark after 0 is 5/8.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3177bab-c4e1-4ace-8985-52df02831bf1', 'NC26.3.ANR.7', 3, 'choice', 'Equal pair of fractions', 'Which pair of fractions is equal?', '["$\\frac{3}{4}$ and $\\frac{3}{8}$","$\\frac{1}{2}$ and $\\frac{1}{4}$","$\\frac{2}{3}$ and $\\frac{4}{6}$","$\\frac{2}{4}$ and $\\frac{2}{8}$"]', '$\frac{2}{3}$ and $\frac{4}{6}$', NULL, 'Split each third into 2 equal parts: the whole has 6 equal parts, and 2 thirds becomes 4 sixths. So $\frac{2}{3} = \frac{4}{6}$. In the other pairs the denominators are different but the numerators are the same, so the fractions are not equal.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$ and $\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6 (double top and bottom). 2/4 = 4/8 not 2/8; 1/2 > 1/4; 3/4 = 6/8 not 3/8.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('289612ca-8750-479f-8fd6-581717e1579b', 'NC26.3.ANR.7', 3, 'numeric', 'A fraction equal to a whole number', 'Each sandwich is cut into 4 equal pieces. Lee eats 8 pieces. How many sandwiches did Lee eat?', '[]', '2', '8/4', '4 pieces make 1 sandwich, so $\frac{4}{4} = 1$. 8 pieces make 2 sandwiches, so $\frac{8}{4} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 pieces make one sandwich; 8 pieces = 8/4 = 2 sandwiches.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a29c883-6a79-4566-8f6b-b93e89d24ed8', 'NC26.3.ANR.7', 3, 'choice', 'Order unit fractions', 'Which list puts $\frac{1}{2}$, $\frac{1}{4}$ and $\frac{1}{8}$ in order from least to greatest?', '["$\\frac{1}{2}, \\frac{1}{4}, \\frac{1}{8}$","$\\frac{1}{8}, \\frac{1}{4}, \\frac{1}{2}$","$\\frac{1}{4}, \\frac{1}{2}, \\frac{1}{8}$","$\\frac{1}{8}, \\frac{1}{2}, \\frac{1}{4}$"]', '$\frac{1}{8}, \frac{1}{4}, \frac{1}{2}$', NULL, 'When the top number is 1, the more parts the whole is cut into, the smaller each part is. Eighths are the smallest, then fourths, then halves. The order is $\frac{1}{8}, \frac{1}{4}, \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}, \\frac{1}{4}, \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator: more parts means smaller parts. 1/8 < 1/4 < 1/2.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2d3c5d7-85d2-41aa-b2a6-49d27d213567', 'NC26.3.SGMR.1', 1, 'choice', 'Name parallel lines', 'Two lines on a page never cross, no matter how far they go. What are these lines called?', '["parallel lines","perpendicular lines","intersecting lines","line segments"]', 'parallel lines', NULL, 'Lines that stay the same distance apart and never cross are parallel lines. Perpendicular lines cross at a square corner, and intersecting lines cross.', 'checked', '{"lint":[],"solve":{"answer":"parallel lines","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lines in one plane that never meet are parallel lines.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
