VALUES ('0b2d6b23-3172-45e8-a438-5324909df260', 'NC26.3.SGMR.1', 1, 'numeric', 'Right angles in a rectangle', 'How many right angles does a rectangle have?', '[]', '4', '4', 'Every corner of a rectangle is a square corner (a right angle). A rectangle has 4 corners, so it has 4 right angles.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle has 4 right angles, one at each corner.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
