VALUES ('9b774c4b-441a-41f2-b2da-c9b1b6b46bc5', 'NC26.3.SGMR.1', 1, 'choice', 'Name a right angle', 'An angle makes a square corner, like the corner of a book. What kind of angle is it?', '["acute angle","obtuse angle","right angle","straight angle"]', 'right angle', NULL, 'An angle that makes a square corner is a right angle.', 'checked', '{"lint":[],"solve":{"answer":"right angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square corner is a right angle.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
