INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65a4f26a-a374-4466-8dcc-9086a0c4888d', 'NC26.3.SGMR.1', 2, 'choice', 'Name an obtuse angle', 'An angle opens wider than a square corner, but not as wide as a straight line. What kind of angle is it?', '["acute angle","right angle","straight angle","obtuse angle"]', 'obtuse angle', NULL, 'An angle smaller than a square corner is acute. A square corner is a right angle. An angle wider than a square corner but not yet a straight line is obtuse.', 'checked', '{"lint":[],"solve":{"answer":"obtuse angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wider than a right angle but less than a straight angle: obtuse.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
