INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc72bac7-218c-4ec5-90e1-02bb3e71734f', 'NC26.3.SGMR.1', 2, 'choice', 'Identify a kind of quadrilateral', 'A quadrilateral has 4 equal sides and no right angles. Which shape could it be?', '["square","rectangle","pentagon","rhombus"]', 'rhombus', NULL, 'A square and a rectangle both have 4 right angles, so they are out. A pentagon has 5 sides, so it is not a quadrilateral. A rhombus has 4 equal sides and does not need right angles.', 'checked', '{"lint":[],"solve":{"answer":"rhombus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides: rhombus or square. Square has right angles, rectangle has right angles, pentagon has 5 sides. So rhombus.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
