INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c13ae07b-8e3a-489c-bb9a-914a05737880', 'NC26.3.SGMR.1', 2, 'numeric', 'Parallel sides of a rectangle', 'How many pairs of parallel sides does a rectangle have?', '[]', '2', '2', 'The two long sides are parallel to each other. The two short sides are parallel to each other. That makes 2 pairs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides of a rectangle are parallel: 2 pairs.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
