INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('156efefd-d145-45cf-9d0f-57d1d4353fbd', 'NC26.3.SGMR.1', 3, 'choice', 'Relate kinds of quadrilaterals', 'Which statement is true?', '["Every rectangle is also a square.","Every rhombus has four right angles.","Every square is also a rectangle.","Every quadrilateral has four equal sides."]', 'Every square is also a rectangle.', NULL, 'A square has 4 sides and 4 right angles, so it is a special kind of rectangle. But a rectangle can have long and short sides, so not every rectangle is a square. A rhombus can lean, and any quadrilateral can have sides of different lengths.', 'checked', '{"lint":[],"solve":{"answer":"Every square is also a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has 4 right angles and opposite sides parallel/equal, so it is a rectangle. The other statements are false (a non-square rhombus has no right angles, a 2-by-3 rectangle is not a square, a trapezoid need not have equal sides).","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d00e2122-4f46-4042-af4d-d87772a4b9e3', 'NC26.3.SGMR.1', 3, 'choice', 'Perpendicular to a parallel pair', 'Lines A, B and C are all on one flat page. Line A is parallel to line B. Line C crosses line A and makes a right angle with it. What is true about line C and line B?', '["Line C is perpendicular to line B.","Line C is parallel to line B.","Line C is the same line as line B.","Line C makes an acute angle with line B."]', 'Line C is perpendicular to line B.', NULL, 'Parallel lines A and B lean the same way. If line C makes a square corner with line A, it makes a square corner with line B too. So line C is perpendicular to line B.', 'checked', '{"lint":[],"solve":{"answer":"Line C is perpendicular to line B.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C is perpendicular to A, and B is parallel to A, so C crosses B at a right angle too: C is perpendicular to B.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f303aac-8a84-47a9-a303-fada02d93679', 'NC26.3.SGMR.1', 3, 'numeric', 'Count right angles in three shapes', 'A page has a rectangle, a square and a rhombus that is not a square. How many right angles do the three shapes have in all?', '[]', '8', '4+4+0', 'The rectangle has 4 right angles and the square has 4. A rhombus that is not a square has no right angles. In all: 4 + 4 + 0 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 4 right angles, square 4, a rhombus that is not a square has none (one right angle would force all four). 4 + 4 + 0 = 8.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f704cbb-0c50-45fa-b622-e4c7390ea1ec', 'NC26.3.SGMR.2', 1, 'numeric', 'Elapsed time within an hour', 'Soccer practice starts at 4:10 and ends at 4:45. How many minutes long is practice?', '[]', '35', '45-10', 'From 4:10 to 4:45 is the same hour. Subtract the minutes: 45 − 10 = 35 minutes.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:10 to 4:45 = 45 - 10 = 35 minutes.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
