VALUES ('2371e430-15d8-4479-80c6-0978aa73e354', 'NC26.3.SGMR.2', 1, 'choice', 'Choose a unit of weight', 'Which unit is best for measuring the weight of a watermelon?', '["inches","pounds","cups","gallons"]', 'pounds', NULL, 'Weight is measured in ounces or pounds. A watermelon is heavy, so pounds is the best unit. Inches measure length, and cups and gallons measure how much a container holds.', 'checked', '{"lint":[],"solve":{"answer":"pounds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weight in customary units: pounds. Inches is length; cups and gallons are capacity.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
