VALUES ('17cb7b99-6248-457f-a806-371d50c075fa', 'NC26.3.SGMR.2', 1, 'numeric', 'One-step length problem', 'A string is 12 inches long. Dina cuts off 4 inches. How many inches of string are left?', '[]', '8', '12-4', '12 − 4 = 8 inches are left.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 4 = 8 inches.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
