INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9516478e-f350-4033-9dbf-0e1c1e357e87', 'NC26.3.SGMR.2', 2, 'choice', 'Find an end time across the hour', 'A lesson starts at 3:40 and lasts 35 minutes. What time does the lesson end?', '["4:15","4:05","4:25","4:35"]', '4:15', NULL, 'From 3:40 to 4:00 is 20 minutes. There are 35 − 20 = 15 minutes left to count. 4:00 plus 15 minutes is 4:15.', 'checked', '{"lint":[],"solve":{"answer":"4:15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3:40 + 20 min = 4:00; 15 more min = 4:15.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
