INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('076d5c13-5b33-466b-b687-8f696bdcdaf9', 'NC26.3.SGMR.2', 2, 'numeric', 'Elapsed time across the hour', 'A bus leaves at 7:50 and arrives at 8:20. How many minutes is the bus trip?', '[]', '30', '10+20', 'From 7:50 to 8:00 is 10 minutes. From 8:00 to 8:20 is 20 minutes. In all: 10 + 20 = 30 minutes.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7:50 to 8:00 = 10 min; 8:00 to 8:20 = 20 min; total 30.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
