VALUES ('fdc752e0-315e-4f5f-a83b-de2abbf28e7a', 'NC26.3.SGMR.2', 2, 'choice', 'Estimate a length', 'About how long is a new pencil?', '["7 feet","7 yards","7 inches","70 inches"]', '7 inches', NULL, 'A new pencil is a little shorter than a ruler that is 12 inches long, so about 7 inches is reasonable. 7 feet and 7 yards are taller than a person, and 70 inches is about as tall as a grown-up.', 'checked', '{"lint":[],"solve":{"answer":"7 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A new pencil is about 7 inches long. 7 feet, 7 yards and 70 inches are far too long.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
