INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c31f1e86-541f-43d7-a0b2-11fe9788c73b', 'NC26.3.SGMR.2', 3, 'numeric', 'Elapsed time in two parts', 'Ravi reads from 4:35 to 5:10. After a short break, he reads for 20 more minutes. How many minutes did Ravi read in all?', '[]', '55', '25+10+20', 'From 4:35 to 5:00 is 25 minutes. From 5:00 to 5:10 is 10 minutes. So the first reading time is 25 + 10 = 35 minutes. Then add 20 more: 35 + 20 = 55 minutes.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:35 to 5:00 = 25 min, 5:00 to 5:10 = 10 min, so 35 min. 35 + 20 = 55 minutes.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fa82693-94e9-4a14-8cf9-de38a0a002a7', 'NC26.3.SGMR.2', 3, 'choice', 'Elapsed time: find the start time', 'A dance class ended at 5:20. The class lasted 45 minutes. What time did it start?', '["6:05","4:35","5:25","4:15"]', '4:35', NULL, 'Count back 45 minutes from 5:20. Going back 20 minutes reaches 5:00. There are 45 - 20 = 25 more minutes to go back, and 25 minutes before 5:00 is 4:35. Check: 4:35 plus 45 minutes is 5:20.', 'checked', '{"lint":[],"solve":{"answer":"4:35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start = 5:20 - 45 min. 5:20 - 20 min = 5:00; 25 more minutes back = 4:35. Check: 4:35 + 45 min = 5:20. 4:15 is 65 min before; 6:05 adds instead of subtracts; 5:25 is after the end.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a4eea25-02a9-4849-9ee4-63a92cf3d5ef', 'NC26.3.SGMR.2', 3, 'numeric', 'Capacity: find the amount used', 'A fish tank had 75 gallons of water in it. Some of the water was drained, and 48 gallons were left. How many gallons of water were drained?', '[]', '27', '75-48', 'The amount drained is the part that is missing from 75. Subtract: 75 - 48 = 27. Check: 48 + 27 = 75.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drained = 75 - 48 = 27 gallons. Check: 48 + 27 = 75.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24addd7d-a096-448d-b244-2494595fd9a7', 'NC26.3.SGMR.3', 1, 'numeric', 'Area by counting square tiles', 'A rectangle is 4 units long and 3 units wide. It is covered with squares that are 1 unit by 1 unit, with no gaps and no overlaps. How many squares cover it?', '[]', '12', '4*3', 'The squares make 3 rows with 4 squares in each row. $3 \times 4 = 12$ squares.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 = 12 unit squares.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
