INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('007adc3d-8c14-4562-8542-67d2d0555103', 'NC26.3.SGMR.3', 1, 'numeric', 'Perimeter of a square', 'A square has sides that are each 5 inches long. What is the perimeter of the square in inches?', '[]', '20', '4*5', 'The perimeter is the distance around. A square has 4 equal sides: 5 + 5 + 5 + 5 = 20 inches.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 sides x 5 inches = 20 inches.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
