INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4453f6f6-cd8e-4ec7-85c5-a69808f183df', 'NC26.3.SGMR.3', 1, 'choice', 'Area or perimeter: which to find', 'Mia wants to know how much carpet is needed to cover the floor of a rectangular room. What should she find?', '["the area of the floor","the perimeter of the floor","the length of one wall","the height of the room"]', 'the area of the floor', NULL, 'Covering a flat surface is measured by area. Perimeter is the distance around the edge.', 'checked', '{"lint":[],"solve":{"answer":"the area of the floor","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Covering a floor is a question of area.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
