INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a2726f5-9a56-491e-a36a-b1612fa46d7d', 'NC26.3.SGMR.3', 2, 'numeric', 'Area by multiplying side lengths', 'A rectangular garden is 9 feet long and 6 feet wide. What is the area of the garden in square feet?', '[]', '54', '9*6', 'Area of a rectangle = length × width. $9 \times 6 = 54$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 6 = 54 square feet.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
