INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b72fa8b3-2013-4626-9cb4-6b725b37cb19', 'NC26.3.SGMR.3', 2, 'choice', 'Perimeter of a rectangle', 'A rectangle is 8 centimeters long and 3 centimeters wide. What is its perimeter in centimeters?', '["24","11","22","14"]', '22', '2*(8+3)', 'A rectangle has 2 long sides and 2 short sides: 8 + 3 + 8 + 3 = 22 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 3 + 8 + 3 = 22 cm.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
