INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56bd91db-23f8-48e3-9323-e0fab2345372', 'NC26.3.SGMR.3', 2, 'numeric', 'Missing side of a triangle from its perimeter', 'A triangle has a perimeter of 24 inches. Two of its sides are 7 inches and 9 inches long. How many inches long is the third side?', '[]', '8', '24-7-9', 'The two known sides add to 7 + 9 = 16 inches. The third side is the rest of the perimeter: 24 − 16 = 8 inches.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 9 = 16; 24 - 16 = 8 inches. (7, 9, 8 makes a real triangle.)","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
