INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1590d734-c1f3-4697-8027-b626b3b2758a', 'NC26.3.SGMR.3', 3, 'numeric', 'Missing side of a rectangle from its perimeter', 'A rectangle has a perimeter of 30 centimeters. It is 9 centimeters long. How many centimeters wide is it?', '[]', '6', '30/2-9', 'The length and width together are half the perimeter: 30 ÷ 2 = 15 centimeters. The width is 15 − 9 = 6 centimeters. Check: 9 + 6 + 9 + 6 = 30.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 30 / 2 = 15; width = 15 - 9 = 6. Check 9+6+9+6 = 30.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bee4ec1d-fb7e-4f38-9a64-efe71feb11dc', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A floor is made of two rectangles joined together with no overlap. One rectangle is 6 feet by 4 feet. The other is 3 feet by 2 feet. What is the total area of the floor in square feet?', '[]', '30', '6*4+3*2', 'First rectangle: $6 \times 4 = 24$ square feet. Second rectangle: $3 \times 2 = 6$ square feet. Total: 24 + 6 = 30 square feet.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24; 3 x 2 = 6; 24 + 6 = 30 square feet.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16ec01b5-197a-4e5b-be09-406e20b105cb', 'NC26.3.SGMR.3', 3, 'choice', 'Same area, different perimeter', 'Rectangle A is 6 units by 2 units. Rectangle B is 4 units by 3 units. Both have an area of 12 square units. Which statement is true?', '["Rectangle B has the greater perimeter.","Rectangle A has the greater perimeter.","The perimeters are equal because the areas are equal.","The perimeters are equal because both have four sides."]', 'Rectangle A has the greater perimeter.', NULL, 'Perimeter of A: 6 + 2 + 6 + 2 = 16 units. Perimeter of B: 4 + 3 + 4 + 3 = 14 units. So A has the greater perimeter, even though the areas are equal.', 'checked', '{"lint":[],"solve":{"answer":"Rectangle A has the greater perimeter.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6+2+6+2 = 16. B: 4+3+4+3 = 14. A has the greater perimeter.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a0d038c-1042-4bdf-84d3-db2ff8161fd6', 'NC26.3.RD.1', 1, 'numeric', 'Total from a frequency list', 'Ms. Lee''s class voted for a favorite fruit. Apple got 8 votes, banana got 5 votes and grape got 7 votes. How many students voted in all?', '[]', '20', '8+5+7', 'Add all the votes: 8 + 5 + 7 = 20 students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 5 + 7 = 20.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
