INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5260fb3a-9415-49e2-8e30-413f586a7072', 'NC26.3.RD.1', 1, 'numeric', 'Read a picture graph with a key', 'In a picture graph, each star stands for 2 books. The row for Monday has 5 stars. How many books does the Monday row stand for?', '[]', '10', '5*2', 'Each of the 5 stars stands for 2 books. $5 \times 2 = 10$ books.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 stars x 2 books = 10.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
