INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('130c70f9-9814-4ea3-a2ae-5954fa78453c', 'NC26.3.RD.1', 1, 'choice', 'Find the most popular category', 'Students voted for a favorite pet. Dog got 9 votes, cat got 12 votes, fish got 4 votes and bird got 7 votes. Which pet got the most votes?', '["dog","cat","fish","bird"]', 'cat', NULL, 'Compare the votes: 9, 12, 4 and 7. The greatest is 12, which is for cat.', 'checked', '{"lint":[],"solve":{"answer":"cat","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 (cat) is more than 9, 7 and 4.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
