INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ec18576-fc6d-4eca-9fdc-dd589135710c', 'NC26.3.RD.1', 2, 'numeric', 'Read a bar between two scale marks', 'A bar graph has a scale that counts by 10s: 0, 10, 20, 30, 40. The bar for soccer ends halfway between 20 and 30. How many students chose soccer?', '[]', '25', '(20+30)/2', 'Halfway between 20 and 30 is 25, because 10 split in half is 5 and $20 + 5 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halfway between 20 and 30 is 25.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
