INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39e146fd-7639-4baf-a51f-3896ea5e8dee', 'NC26.3.RD.1', 2, 'choice', 'Difference using a picture graph scale', 'In a picture graph, each picture stands for 4 pets. The dog row has 6 pictures and the fish row has 3 pictures. How many more dogs than fish are shown?', '["3","24","12","9"]', '12', '(6-3)*4', 'The dog row has 3 more pictures than the fish row. Each picture is 4 pets, so $3 \times 4 = 12$ more dogs.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 6 x 4 = 24, fish 3 x 4 = 12; 24 - 12 = 12 more dogs.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4569bab8-840b-4603-9bbc-c652b9a30295', 'NC26.3.RD.1', 2, 'choice', 'Pose a question that collects data', 'Mr. Cruz''s class wants to collect data from their classmates. Which question should they ask?', '["Which fruit do you like best: apple, banana or grape?","How many days are in one week?","What is 7 + 5?","What color is Mr. Cruz''s car?"]', 'Which fruit do you like best: apple, banana or grape?', NULL, 'A question for collecting data should have answers that can be different for different classmates. Everyone gives the same answer to the days in a week and to 7 + 5, and the car has just one color. Favorite fruit gives different answers that the class can count.', 'checked', '{"lint":[],"solve":{"answer":"Which fruit do you like best: apple, banana or grape?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A data question has answers that vary among classmates and fall into categories: favourite fruit. The others have one fixed answer.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('636dd41d-b544-4ab1-b7d5-3bf0a92ecbec', 'NC26.3.RD.1', 3, 'numeric', 'Picture graph with a half symbol', 'In a picture graph, each smiley face stands for 6 students. The row for art has 3 whole smiley faces and 1 half smiley face. How many students does the art row stand for?', '[]', '21', '3*6+6/2', '3 whole faces: $3 \times 6 = 18$ students. A half face is half of 6, which is 3 students. Total: 18 + 3 = 21 students.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 faces x 6 = 18; half face = 3; 18 + 3 = 21.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('551e9b4e-ab27-4d1d-afba-8d13a31f4db0', 'NC26.3.RD.1', 3, 'choice', 'Draw a conclusion from a frequency table', 'A class made a frequency table of how students get to school: walk 12, bus 18, car 8, bike 2. Which statement is supported by the data?', '["More students walk than ride the bus.","Most students ride a bike.","Exactly half of the students ride the bus.","More students ride the bus than walk."]', 'More students ride the bus than walk.', NULL, 'The bus has 18 and walking has 12, so more students ride the bus. Bike has the fewest (2). The class has 12 + 18 + 8 + 2 = 40 students, and half of 40 is 20, not 18.', 'checked', '{"lint":[],"solve":{"answer":"More students ride the bus than walk.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus 18 > walk 12, so more ride the bus than walk (true). Bike 2 is fewest; total 40, half is 20, bus is 18, not half.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('821e58ee-a321-4f01-84f9-5eee48ef2101', 'NC26.3.RD.1', 3, 'choice', 'Show a number of students with whole and half symbols', 'In a picture graph, each circle stands for 8 students, and half a circle stands for 4 students. 28 students chose art. Which shows the row for art?', '["3 whole circles and 1 half circle","3 whole circles and 2 half circles","7 whole circles","4 whole circles"]', '3 whole circles and 1 half circle', NULL, 'Each whole circle is 8 students. 3 whole circles are 3 x 8 = 24 students, and 28 - 24 = 4 students are left. 4 students is exactly 1 half circle. So the row has 3 whole circles and 1 half circle.', 'checked', '{"lint":[],"solve":{"answer":"3 whole circles and 1 half circle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 8 = 3 remainder 4, so 3 whole circles (24) and 1 half circle (4) = 28. Others: 4 whole = 32; 7 whole = 56; 3 whole + 2 halves = 24 + 8 = 32. Only one option equals 28.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
