VALUES ('9b000000-0000-4000-8000-000000000004', 'NC26.4.ANR.1', 2, 'choice', 'Comparing numbers', 'Which comparison is true?', '["$56{,}091 > 56{,}109$","$56{,}091 < 56{,}109$","$56{,}091 = 56{,}109$","$56{,}190 < 56{,}109$"]', '$56{,}091 < 56{,}109$', NULL, 'Both start with $56$ thousands. In the hundreds place, $0 < 1$, so $56{,}091 < 56{,}109$.', 'approved', '{"lint":[],"solve":null}', 'manual', '0c000000-0000-4000-8000-000000000001', '2026-10-17T00:00:00.000Z')
