INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b000000-0000-4000-8000-000000000005', 'NC26.4.ANR.1', 3, 'numeric', 'Each place is ten times the place to its right', 'In $33{,}333$, the value of the digit in the thousands place is how many times the value of the digit in the hundreds place?', '[]', '10', '3000/300', 'The thousands digit is worth $3{,}000$ and the hundreds digit $300$. $3{,}000 \div 300 = 10$.', 'approved', '{"lint":[],"solve":null}', 'manual', '0c000000-0000-4000-8000-000000000001', '2026-10-17T00:00:00.000Z')
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b000000-0000-4000-8000-000000000006', 'NC26.4.ANR.1', 3, 'choice', 'Ordering numbers', 'Which list puts $70{,}512$, $70{,}215$ and $75{,}021$ in order from least to greatest?', '["70,215; 70,512; 75,021","70,512; 70,215; 75,021","75,021; 70,512; 70,215","70,215; 75,021; 70,512"]', '70,215; 70,512; 75,021', NULL, '$75{,}021$ has the most thousands, so it is greatest. Of the other two, $70{,}215$ has fewer hundreds than $70{,}512$.', 'approved', '{"lint":[],"solve":null}', 'manual', '0c000000-0000-4000-8000-000000000001', '2026-10-17T00:00:00.000Z')
ON CONFLICT (id) DO NOTHING;
