VALUES ('d9bbbc27-84a7-48f3-9190-08f4c3ced831', 'NC26.4.ANR.1', 1, 'choice', 'Value of a digit in a 5-digit number', 'What is the value of the digit 7 in the number $37{,}428$?', '["7,000","70,000","700","70"]', '7,000', '7000', 'Read the places from the left: 3 is in the ten-thousands place, 7 is in the thousands place, 4 is in the hundreds place, 2 is in the tens place and 8 is in the ones place. So the 7 stands for 7 thousands, which is 7,000.', 'checked', '{"lint":[],"solve":{"answer":"7,000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In 37,428 the 7 is in the thousands place, so its value is 7 x 1,000 = 7,000.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
