INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('124b7257-9f98-4d26-95c9-cda050a323be', 'NC26.4.ANR.1', 1, 'choice', 'Compare 5-digit numbers', 'Which of these numbers is the greatest?', '["41,086","40,968","41,680","41,608"]', '41,680', '41680', 'Compare from the left. All four have 4 ten-thousands, and 40,968 has only 0 thousands, so it is the least. The other three have 1 thousand. Compare the hundreds: 41,086 has 0, while 41,680 and 41,608 each have 6. Compare the tens: 41,680 has 8 and 41,608 has 0. So 41,680 is the greatest.', 'checked', '{"lint":[],"solve":{"answer":"41,680","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All have 4 ten-thousands. 40,968 has 0 thousands, the rest 1, so it is not greatest. Among 41,608, 41,680, 41,086 compare hundreds: 6, 6, 0; then tens: 41,608 has 0 tens, 41,680 has 8 tens. Greatest is 41,680.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11da634d-ff74-40ad-9bd2-92f876e35f05', 'NC26.4.ANR.1', 2, 'numeric', 'Each place is ten times the place to its right', 'In the number $26{,}640$, the first 6 (in the thousands place) is worth how many times as much as the second 6 (in the hundreds place)?', '[]', '10', '6000/600', 'The first 6 is worth 6,000 and the second 6 is worth 600. Since $6{,}000 \div 600 = 10$, the first 6 is worth 10 times as much. Each place is 10 times the place to its right.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thousands 6 is worth 6,000; hundreds 6 is worth 600. 6,000 / 600 = 10.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
