INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fbeb9ad-2c6a-4d0e-ba89-24f2fe612b9e', 'NC26.4.ANR.1', 2, 'choice', 'Expanded form of a 5-digit number with zeros', 'Which shows $50{,}209$ in expanded form?', '["$5{,}000 + 200 + 9$","$50{,}000 + 20 + 9$","$50{,}000 + 200 + 9$","$50{,}000 + 2{,}000 + 9$"]', '$50{,}000 + 200 + 9$', NULL, 'The 5 is in the ten-thousands place, so it is worth 50,000. The thousands digit is 0. The 2 is in the hundreds place, so it is worth 200. The tens digit is 0, and the 9 is 9 ones. So $50{,}209 = 50{,}000 + 200 + 9$.', 'checked', '{"lint":[],"solve":{"answer":"$50{,}000 + 200 + 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50,209 = 5 ten-thousands + 0 thousands + 2 hundreds + 0 tens + 9 ones = 50,000 + 200 + 9.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d2333cc-573f-45c0-a511-6aa08fcb3e6b', 'NC26.4.ANR.1', 2, 'choice', 'Order three 5-digit numbers', 'Which list puts $35{,}412$, $34{,}999$ and $35{,}142$ in order from least to greatest?', '["$35{,}412$, $35{,}142$, $34{,}999$","$34{,}999$, $35{,}412$, $35{,}142$","$35{,}142$, $34{,}999$, $35{,}412$","$34{,}999$, $35{,}142$, $35{,}412$"]', '$34{,}999$, $35{,}142$, $35{,}412$', NULL, '34,999 has 4 thousands, so it is the least. The other two both have 5 thousands, so compare the hundreds: 35,142 has 1 hundred and 35,412 has 4 hundreds. From least to greatest: 34,999; 35,142; 35,412.', 'checked', '{"lint":[],"solve":{"answer":"$34{,}999$, $35{,}142$, $35{,}412$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34,999 < 35,142 < 35,412 (34 thousand is least; then 35,142 has 1 hundred vs 4 hundreds).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54a2a68d-e5a2-4982-9fce-15d1d080901a', 'NC26.4.ANR.1', 3, 'choice', 'Find the number where a digit has a given value', 'In which number does the digit 4 have a value of $4{,}000$?', '["42,815","28,415","28,154","24,815"]', '24,815', '24815', 'A 4 is worth 4,000 only in the thousands place. In 42,815 the 4 is in the ten-thousands place (40,000). In 28,415 it is in the hundreds place (400). In 28,154 it is in the ones place (4). In 24,815 it is in the thousands place, worth 4,000.', 'checked', '{"lint":[],"solve":{"answer":"24,815","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42,815: 4 is 40,000. 28,154: 4 is 4. 24,815: 4 is in thousands = 4,000. 28,415: 4 is 400. Answer 24,815.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
