INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d196afa2-a390-48ad-9d72-61af1ceecc92', 'NC26.4.ANR.1', 3, 'numeric', 'Build a number from place values that include zeros', 'A number has 3 ten-thousands, 0 thousands, 7 hundreds, 0 tens and 2 ones. What is the number?', '[]', '30702', '3*10000+7*100+2', 'Write the digits from the largest place to the smallest: 3, 0, 7, 0, 2. The number is 30,702.', 'checked', '{"lint":[],"solve":{"answer":"30702","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 10,000 + 0 + 7 x 100 + 0 + 2 = 30,702.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
