INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('578ade9e-e484-4766-8e30-ce4d7ceb419a', 'NC26.4.ANR.2', 1, 'numeric', 'Subtract two 4-digit numbers', 'What is $8{,}465 - 3{,}142$?', '[]', '5323', '8465-3142', 'Subtract each place, starting with the ones: 5 - 2 = 3, 6 - 4 = 2, 4 - 1 = 3, 8 - 3 = 5. The difference is 5,323.', 'checked', '{"lint":[],"solve":{"answer":"5323","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8,465 - 3,142: ones 5-2=3, tens 6-4=2, hundreds 4-1=3, thousands 8-3=5. = 5,323.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
