INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7c47c6b-3a22-4724-8eb7-656bdbeda6ea', 'NC26.4.ANR.2', 1, 'choice', 'Add with regrouping in a word problem', 'A school collected 1,250 cans in May and 1,375 cans in June. How many cans did it collect in all?', '["2,625","2,525","2,725","2,635"]', '2,625', '2625', 'Add: 1,250 + 1,375. Ones: 0 + 5 = 5. Tens: 5 + 7 = 12, so write 2 and regroup 1 hundred. Hundreds: 2 + 3 + 1 = 6. Thousands: 1 + 1 = 2. The total is 2,625. (2,525 forgets the regrouped hundred.)', 'checked', '{"lint":[],"solve":{"answer":"2,625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,250 + 1,375 = 2,625.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
