INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf617b0-a28f-4177-8df2-1a97cf093c8b', 'NC26.4.ANR.2', 2, 'numeric', 'Add 5-digit numbers with regrouping', 'What is $37{,}482 + 25{,}619$?', '[]', '63101', '37482+25619', 'Ones: 2 + 9 = 11, write 1, regroup 1. Tens: 8 + 1 + 1 = 10, write 0, regroup 1. Hundreds: 4 + 6 + 1 = 11, write 1, regroup 1. Thousands: 7 + 5 + 1 = 13, write 3, regroup 1. Ten-thousands: 3 + 2 + 1 = 6. The sum is 63,101.', 'checked', '{"lint":[],"solve":{"answer":"63101","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"37,482 + 25,619: 37,482 + 25,000 = 62,482; + 619 = 63,101. Check: 63,101 - 25,619 = 37,482.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a3fc122-3f93-41e8-bb3e-2622eab474ff', 'NC26.4.ANR.2', 2, 'numeric', 'Subtract across zeros', 'What is $52{,}000 - 18{,}745$?', '[]', '33255', '52000-18745', 'Regroup across the zeros: 52,000 is 51,999 + 1, so 52,000 - 18,745 = 51,999 - 18,745 + 1 = 33,254 + 1 = 33,255. You can check by adding: 18,745 + 33,255 = 52,000.', 'checked', '{"lint":[],"solve":{"answer":"33255","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52,000 - 18,745 = 33,255. Check: 18,745 + 33,255 = 52,000.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
