VALUES ('467ec5df-aebb-4d77-aaeb-13769860ab40', 'NC26.4.ANR.2', 2, 'choice', 'Subtract in a word problem', 'A stadium has 45,380 seats. At one game, 28,947 of the seats are filled. How many seats are empty?', '["17,433","16,433","23,647","74,327"]', '16,433', '16433', 'Subtract the filled seats from all the seats: 45,380 - 28,947 = 16,433. Check: 28,947 + 16,433 = 45,380. (74,327 comes from adding instead, and 23,647 from taking the smaller digit from the larger in every column.)', 'checked', '{"lint":[],"solve":{"answer":"16,433","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Empty = 45,380 - 28,947 = 16,433. Check: 28,947 + 16,433 = 45,380.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
