INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf596239-c16a-44b3-b8cd-35a18a8adbaa', 'NC26.4.ANR.3', 2, 'numeric', 'Division with a remainder in context', 'A baker puts 8 muffins in each box. She has 75 muffins. How many boxes can she fill completely?', '[]', '9', '72/8', '75 divided by 8 is 9 with a remainder of 3, because 8 x 9 = 72 and 75 - 72 = 3. The 3 left-over muffins do not fill a box, so she fills 9 boxes.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"75 / 8 = 9 remainder 3 (8 x 9 = 72). 9 full boxes.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a5a4cc9-8819-4c86-b8db-6b38041bd8de', 'NC26.4.ANR.3', 2, 'choice', 'Multiplicative comparison: find the smaller amount', 'A red ribbon is 36 centimeters long. It is 4 times as long as a blue ribbon. How long is the blue ribbon, in centimeters?', '["144","32","40","9"]', '9', '36/4', '"4 times as long" means red = 4 x blue. So blue = 36 divided by 4 = 9 centimeters. Check: 4 x 9 = 36. (144 multiplies instead, 32 subtracts 4 and 40 adds 4.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red = 4 x blue, so blue = 36 / 4 = 9 cm.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fae14c9c-4390-442f-ac0a-dfdfedc8b6da', 'NC26.4.ANR.3', 3, 'numeric', 'Four-digit by one-digit quotient with a zero', 'What is $3{,}648 \div 6$?', '[]', '608', '3648/6', '6 x 600 = 3,600, and 3,648 - 3,600 = 48. Then 48 divided by 6 is 8. So the quotient is 600 + 8 = 608. Check: 6 x 608 = 3,648.', 'checked', '{"lint":[],"solve":{"answer":"608","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,648 / 6: 36/6 = 6, 4/6 = 0 r4, 48/6 = 8 -> 608. Check 6 x 608 = 3,648.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7327b39-4c4c-44cb-af43-453983b214d2', 'NC26.4.ANR.3', 3, 'numeric', 'Count the factor pairs of a number', 'A factor pair is two whole numbers that multiply to make a number. The order does not matter, so $2 \times 18$ and $18 \times 2$ are the same pair. How many factor pairs does 36 have?', '[]', '5', NULL, 'The factor pairs of 36 are 1 x 36, 2 x 18, 3 x 12, 4 x 9 and 6 x 6. That is 5 pairs. (6 x 6 counts as one pair.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs for 36: 1x36, 2x18, 3x12, 4x9, 6x6. 5 does not divide 36. That is 5 pairs (6x6 counts, as two whole numbers 6 and 6 multiply to 36).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab6e77e2-db14-47fa-8988-fc944f98ad64', 'NC26.4.ANR.3', 3, 'choice', 'Interpret a remainder', 'A school trip has 150 students. Each bus seats 40 students. What is the fewest number of buses needed so that every student has a seat?', '["3","4","5","30"]', '4', '(150-30)/40+1', '150 divided by 40 is 3 with a remainder of 30. Three buses seat 120 students, and 30 students are left without a seat, so one more bus is needed. The fewest number of buses is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 / 40 = 3 remainder 30; 3 buses seat 120, so 30 students need a 4th bus. 4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f84e3b2-76ff-4cce-85d2-7cfa0bdc6f4d', 'NC26.4.ANR.4', 1, 'numeric', 'Two-step problem: multiply then subtract', 'Ben has 5 packs of cards with 8 cards in each pack. He gives 6 cards to a friend. How many cards does Ben have left?', '[]', '34', '5*8-6', 'First find how many cards Ben starts with: 5 x 8 = 40. Then subtract the 6 he gives away: 40 - 6 = 34.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 8 = 40 cards; 40 - 6 = 34.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('946cf622-b682-4f3e-8835-f604574d8eaa', 'NC26.4.ANR.4', 1, 'choice', 'Choose the equation that matches a story', 'Tom has 4 bags with the same number of marbles in each bag, and 3 loose marbles. He has 31 marbles in all. Let $n$ be the number of marbles in each bag. Which equation matches the story?', '["$4 + n + 3 = 31$","$4 + n \\times 3 = 31$","$4 \\times n + 3 = 31$","$4 \\times (n + 3) = 31$"]', '$4 \times n + 3 = 31$', NULL, 'The 4 bags hold $4 \times n$ marbles. Adding the 3 loose marbles gives $4 \times n + 3$, and that equals 31. So the equation is $4 \times n + 3 = 31$.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times n + 3 = 31$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 bags of n marbles = 4 x n, plus 3 loose = 31: 4 x n + 3 = 31 (n = 7).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64a8c029-3a99-42d7-b38a-68faddf1f473', 'NC26.4.ANR.4', 1, 'numeric', 'Two-step problem: divide then subtract', 'A farmer has 56 apples. He puts them into bags of 8 apples each. Then he sells 3 of the bags. How many bags are left?', '[]', '4', '56/8-3', '56 apples in bags of 8 makes 56 divided by 8 = 7 bags. After selling 3 bags, 7 - 3 = 4 bags are left.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / 8 = 7 bags; 7 - 3 = 4 bags left.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1b9bf4c-0127-4672-ba08-55c90f871f49', 'NC26.4.ANR.4', 2, 'numeric', 'Three quantities: cost and change', 'Mr. Lee buys 6 notebooks that cost 3 dollars each and a backpack that costs 18 dollars. He pays with 50 dollars. How many dollars of change does he get back?', '[]', '14', '50-(6*3+18)', 'The notebooks cost 6 x 3 = 18 dollars. Together with the backpack, he spends 18 + 18 = 36 dollars. His change is 50 - 36 = 14 dollars.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 3 = 18; 18 + 18 = 36 dollars spent; 50 - 36 = 14.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c87929-a084-4177-aa96-c2ce57820ec6', 'NC26.4.ANR.4', 2, 'numeric', 'Solve a two-step equation with a letter', 'Find the value of $n$ in this equation: $n \times 6 + 4 = 52$.', '[]', '8', '(52-4)/6', 'Undo the adding first: $n \times 6 = 52 - 4 = 48$. Then undo the multiplying: $n = 48 \div 6 = 8$. Check: $8 \times 6 + 4 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n x 6 + 4 = 52 -> n x 6 = 48 -> n = 8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e46bef0-a17e-4de7-8705-57aa2aab7015', 'NC26.4.ANR.4', 2, 'choice', 'Estimate to check an answer', 'Sam wants to estimate $29 \times 31 + 48$. Which expression gives the best estimate?', '["$20 \\times 30 + 50$","$30 \\times 30 + 50$","$30 \\times 40 + 50$","$30 \\times 30 + 500$"]', '$30 \times 30 + 50$', NULL, 'Round each number to the nearest ten: 29 to 30, 31 to 30 and 48 to 50. That gives $30 \times 30 + 50$. The other expressions round one of the numbers to something that is not close.', 'checked', '{"lint":[],"solve":{"answer":"$30 \\times 30 + 50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Round 29 to 30, 31 to 30, 48 to 50: 30 x 30 + 50 = 950 (exact 947).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9772a3fa-6bbe-4374-884d-fd850a51c9e0', 'NC26.4.ANR.4', 3, 'numeric', 'Multiplicative comparison then add', 'A theater sells 128 tickets on Friday. On Saturday it sells 3 times as many tickets as on Friday. How many tickets does it sell on the two days together?', '[]', '512', '128+3*128', 'Saturday: 3 x 128 = 384 tickets. Both days: 128 + 384 = 512 tickets.', 'checked', '{"lint":[],"solve":{"answer":"512","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Saturday 3 x 128 = 384; total 128 + 384 = 512.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40158e9d-1771-4146-9ccb-5621989587c3', 'NC26.4.ANR.4', 3, 'numeric', 'Work backward to find a starting amount', 'Kai had some marbles. He bought 3 bags with 15 marbles in each bag. Now he has 80 marbles. How many marbles did Kai have at first?', '[]', '35', '80-3*15', 'The bags hold 3 x 15 = 45 marbles. Kai had 80 - 45 = 35 marbles at first. Check: 35 + 45 = 80.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bought 3 x 15 = 45; start = 80 - 45 = 35.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
