INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6f989d9-d68a-4280-b2f9-1c91140e73a6', 'NC26.4.ANR.4', 3, 'choice', 'Match a story to an equation', 'Which story can be solved with $n = 3 \times 14 + 8$?', '["14 bags of 8 beads each, then 3 more beads are added. How many beads?","3 bags of 14 beads each, then 8 beads are given away. How many beads are left?","14 beads are shared equally by 3 bags, then 8 more beads are added. How many beads?","3 bags of 14 beads each, then 8 more beads are added. How many beads?"]', '3 bags of 14 beads each, then 8 more beads are added. How many beads?', NULL, '$3 \times 14$ means 3 groups of 14, and $+ 8$ means 8 more. So the story is 3 bags of 14 beads each with 8 more beads added.', 'checked', '{"lint":[],"solve":{"answer":"3 bags of 14 beads each, then 8 more beads are added. How many beads?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 14 + 8 = 3 groups of 14, then add 8: 3 bags of 14 beads each, then 8 more added.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56fa85e7-d8bc-45c8-b384-d2684b5a6149', 'NC26.4.ANR.5', 1, 'numeric', 'Find an equivalent fraction', 'What number does $n$ stand for so that the fractions are equal? $\frac{1}{2} = \frac{n}{8}$', '[]', '4', '1*8/2', 'The denominator 2 was multiplied by 4 to make 8, so multiply the numerator 1 by 4 as well. $n = 4$, and $\frac{1}{2} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8 (multiply top and bottom by 4). n = 4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad62ccf2-4129-4759-aa7c-4a86020d0996', 'NC26.4.ANR.5', 1, 'choice', 'Tenths as decimals', 'Which decimal is equal to $\frac{7}{10}$?', '["0.07","0.17","0.7","7.10"]', '0.7', '7/10', '$\frac{7}{10}$ means 7 tenths, which is written 0.7. (0.07 is 7 hundredths.)', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/10 = seven tenths = 0.7.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab72ad21-f827-4a36-be6b-69ec23b4f87c', 'NC26.4.ANR.5', 1, 'choice', 'Compare a fraction to one half', 'Which fraction is greater than $\frac{1}{2}$?', '["$\\frac{3}{8}$","$\\frac{2}{5}$","$\\frac{1}{3}$","$\\frac{5}{8}$"]', '$\frac{5}{8}$', NULL, 'Half of 8 is 4, so a fraction with denominator 8 is greater than $\frac{1}{2}$ when its numerator is more than 4. $\frac{5}{8}$ is greater than $\frac{1}{2}$, and $\frac{3}{8}$ is less. Half of 5 is 2 and a half, so $\frac{2}{5}$ (numerator 2) is less than $\frac{1}{2}$. One of 3 equal parts is less than half of the whole, so $\frac{1}{3}$ is less than $\frac{1}{2}$. Only $\frac{5}{8}$ is greater than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 8 is 4, so 5/8 > 4/8 = 1/2. 2/5 < 2.5/5, 1/3 < 1/2, 3/8 < 4/8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('290a5367-604d-4453-b6e6-557e959a52f1', 'NC26.4.ANR.5', 2, 'numeric', 'Decimals and hundredths', 'Look at the decimal 0.6 written as hundredths: $0.6 = \frac{n}{100}$. What number does $n$ stand for?', '[]', '60', '0.6*100', '0.6 is 6 tenths. Each tenth is 10 hundredths, so 6 tenths is 60 hundredths. So $0.6 = \frac{60}{100}$ and $n = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 = 6 tenths = 60 hundredths, so n = 60.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa2291b5-7d44-4be0-82fd-281b952fa50f', 'NC26.4.ANR.5', 2, 'choice', 'Order decimals', 'Which list shows $0.4$, $0.38$, $0.5$ and $0.09$ in order from least to greatest?', '["0.09, 0.4, 0.38, 0.5","0.09, 0.38, 0.4, 0.5","0.5, 0.4, 0.38, 0.09","0.38, 0.09, 0.4, 0.5"]', '0.09, 0.38, 0.4, 0.5', NULL, 'Write them with hundredths: 0.40, 0.38, 0.50 and 0.09. In order from least to greatest: 0.09, 0.38, 0.40, 0.50. (0.4 is greater than 0.38, even though 4 is less than 38.)', 'checked', '{"lint":[],"solve":{"answer":"0.09, 0.38, 0.4, 0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"As hundredths: 0.40, 0.38, 0.50, 0.09. Order: 0.09, 0.38, 0.4, 0.5.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec543be0-8306-4a7c-9b16-44374f39cc4b', 'NC26.4.ANR.5', 2, 'choice', 'Recognize an equivalent fraction', 'Which fraction is equivalent to $\frac{3}{4}$?', '["$\\frac{6}{8}$","$\\frac{4}{5}$","$\\frac{3}{8}$","$\\frac{6}{7}$"]', '$\frac{6}{8}$', NULL, 'Multiply the numerator and the denominator by the same number. With 2: $\frac{3 \times 2}{4 \times 2} = \frac{6}{8}$. The others change the numerator and denominator differently.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = (3x2)/(4x2) = 6/8. 6/7, 4/5, 3/8 are not equal to 3/4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fed0b11-19c2-4422-a279-d9e89f6676f3', 'NC26.4.ANR.5', 3, 'choice', 'Compare fractions with unlike denominators', 'Which comparison is true?', '["$\\frac{2}{3} > \\frac{3}{4}$","$\\frac{1}{4} > \\frac{1}{3}$","$\\frac{5}{8} > \\frac{3}{5}$","$\\frac{3}{10} > \\frac{1}{2}$"]', '$\frac{5}{8} > \frac{3}{5}$', NULL, 'Use common denominators. $\frac{2}{3} = \frac{8}{12}$ and $\frac{3}{4} = \frac{9}{12}$, so the first is false. A third is bigger than a fourth, so the second is false. $\frac{5}{8} = \frac{25}{40}$ and $\frac{3}{5} = \frac{24}{40}$, so $\frac{5}{8} > \frac{3}{5}$ is true. $\frac{3}{10}$ is less than $\frac{5}{10} = \frac{1}{2}$, so the last is false.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8} > \\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 8/12 < 9/12 = 3/4 (false). 3/10 < 5/10 (false). 1/4 < 1/3 (false). 5/8 = 25/40 > 24/40 = 3/5 (true).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
