VALUES ('053fb83a-26c8-4d83-946f-8d770dbb0c4b', 'NC26.4.ANR.5', 3, 'choice', 'Find a decimal between two decimals', 'Which decimal is between $0.3$ and $0.4$?', '["0.04","0.35","0.45","0.25"]', '0.35', '0.35', 'Write 0.3 as 0.30 and 0.4 as 0.40. The numbers between them have hundredths from 0.31 to 0.39, such as 0.35. 0.04 is less than 0.3, and 0.45 and 0.25 are outside the two numbers.', 'checked', '{"lint":[],"solve":{"answer":"0.35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 0.30 and 0.40: 0.35. 0.25 < 0.3, 0.45 > 0.4, 0.04 < 0.3.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
