INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a527b8c1-b47b-4fd8-b792-78bed192cfff', 'NC26.4.ANR.6', 1, 'numeric', 'Subtract fractions with like denominators', 'What is $\frac{7}{9} - \frac{4}{9}$?', '[]', '1/3', '7/9-4/9', 'The denominators are the same, so subtract the numerators: 7 - 4 = 3. The difference is $\frac{3}{9}$, which is the same as $\frac{1}{3}$. Either form is correct.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/9 - 4/9 = 3/9, which equals 1/3. Entry must accept either form.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c24ca82c-50c7-4afb-999a-2a9119ff3f88', 'NC26.4.ANR.6', 1, 'choice', 'Decompose a fraction into a sum', 'Which sum is equal to $\frac{5}{6}$?', '["$\\frac{2}{6} + \\frac{2}{6}$","$\\frac{2}{6} + \\frac{3}{6}$","$\\frac{3}{6} + \\frac{3}{6}$","$\\frac{2}{3} + \\frac{3}{3}$"]', '$\frac{2}{6} + \frac{3}{6}$', NULL, '$\frac{5}{6}$ is 5 sixths. 2 sixths + 3 sixths = 5 sixths. The first sum is 4 sixths, the third is 6 sixths, and the last has thirds, not sixths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{6} + \\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/6 + 3/6 = 5/6. Others: 5/3, 6/6, 4/6.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acf16cd1-14ef-40a0-aaf0-18ff55eee4cc', 'NC26.4.ANR.6', 2, 'numeric', 'Add mixed numbers with like denominators', 'What is $2\frac{3}{8} + 1\frac{2}{8}$?', '[]', '3 5/8', '2+3/8+1+2/8', 'Add the whole numbers: 2 + 1 = 3. Add the fractions: $\frac{3}{8} + \frac{2}{8} = \frac{5}{8}$. The sum is $3\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3 5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 2 + 1 = 3; eighths 3/8 + 2/8 = 5/8. Total 3 5/8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e52c3fc-5d7b-43af-a9ed-c43f6c384e5d', 'NC26.4.ANR.6', 2, 'numeric', 'Multiply a fraction by a whole number', 'What is $4 \times \frac{3}{5}$?', '[]', '12/5', '4*3/5', '4 groups of $\frac{3}{5}$ is $\frac{3}{5} + \frac{3}{5} + \frac{3}{5} + \frac{3}{5} = \frac{12}{5}$, which is also $2\frac{2}{5}$. Either form is correct.', 'checked', '{"lint":[],"solve":{"answer":"12/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3/5 = 12/5 = 2 2/5.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12b4944d-5610-42c2-96d4-b3887c7b8bef', 'NC26.4.ANR.6', 2, 'choice', 'Find a fraction of a set', 'A bag has 24 marbles. $\frac{3}{8}$ of the marbles are red. How many marbles are red?', '["3","72","21","9"]', '9', '24/8*3', '$\frac{1}{8}$ of 24 is 24 divided by 8 = 3. So $\frac{3}{8}$ of 24 is 3 x 3 = 9 marbles. (3 is only one eighth, and 72 is 24 x 3.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 of 24 = 3; 3/8 of 24 = 9.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('594456c3-e938-4fc7-ad0d-c6726cee2402', 'NC26.4.ANR.6', 3, 'numeric', 'Subtract mixed numbers with regrouping', 'What is $4\frac{1}{5} - 1\frac{3}{5}$?', '[]', '2 3/5', '4+1/5-1-3/5', 'Write each as a fraction: $4\frac{1}{5} = \frac{21}{5}$ and $1\frac{3}{5} = \frac{8}{5}$. Subtract: $\frac{21}{5} - \frac{8}{5} = \frac{13}{5} = 2\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2 3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 1/5 - 1 3/5 = 21/5 - 8/5 = 13/5 = 2 3/5.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7088f85b-c18c-42cd-b5cb-3bef41bf1220', 'NC26.4.ANR.6', 3, 'numeric', 'Multiply a fraction by a whole number in context', 'Dara runs $\frac{3}{8}$ of a mile each morning for 5 mornings. How many miles does she run in all?', '[]', '1 7/8', '5*3/8', '$5 \times \frac{3}{8} = \frac{15}{8}$. Since $\frac{8}{8}$ is 1 whole, $\frac{15}{8} = 1\frac{7}{8}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"15/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 3/8 = 15/8 = 1 7/8 miles.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
