INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('faa9ab9c-e758-4ac0-acfd-c5b045ce9657', 'NC26.4.ANR.6', 3, 'choice', 'Write a mixed number as a fraction', 'Which fraction is equal to $2\frac{3}{5}$?', '["$\\frac{6}{5}$","$\\frac{13}{5}$","$\\frac{23}{5}$","$\\frac{10}{5}$"]', '$\frac{13}{5}$', NULL, 'Each whole is $\frac{5}{5}$, so 2 wholes are $\frac{10}{5}$. Add the $\frac{3}{5}$: $\frac{10}{5} + \frac{3}{5} = \frac{13}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 3/5 = 10/5 + 3/5 = 13/5.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
