INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e8362aa-5d3f-4afd-8931-3e1cd39210a3', 'NC26.4.ANR.7', 1, 'numeric', 'Continue a pattern from its rule', 'A pattern starts at 4 and adds 6 each time: 4, 10, 16, 22, ... What is the next number in the pattern?', '[]', '28', '22+6', 'Add 6 to the last number: 22 + 6 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 + 6 = 28.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
