INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19a6fdeb-f283-4127-912d-61019cb6f55a', 'NC26.4.ANR.7', 1, 'choice', 'Find the rule of a number pattern', 'Which rule describes this pattern? 5, 10, 15, 20, 25', '["Multiply by 2","Add 10","Add 5","Add 4"]', 'Add 5', NULL, 'Each number is 5 more than the one before: 10 - 5 = 5, 15 - 10 = 5, and so on. The rule is add 5. (Multiplying by 2 works for 5 to 10, but 10 x 2 = 20, not 15.)', 'checked', '{"lint":[],"solve":{"answer":"Add 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each term is 5 more than the one before: add 5. Multiply by 2 fails at 10 -> 15.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
