INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f905d240-0767-41d7-83bd-08c41708c4f6', 'NC26.4.ANR.7', 2, 'numeric', 'Pattern with a subtraction rule', 'A pattern starts at 100 and subtracts 8 each time. What is the fifth number in the pattern?', '[]', '68', '100-4*8', 'The numbers are 100, 92, 84, 76, 68. The fifth number is 68.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100, 92, 84, 76, 68. Fifth number = 68.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
