INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0645328a-9aca-4254-8cc0-fdc670ef22ad', 'NC26.4.ANR.7', 2, 'choice', 'Find the rule from input and output', 'A rule changes each input number into an output number. 2 becomes 6, 3 becomes 9 and 5 becomes 15. Which rule fits all three?', '["Add 4","Multiply by 3","Add 6","Multiply by 2"]', 'Multiply by 3', NULL, 'Check each rule on all three. Multiply by 3 gives 2 x 3 = 6, 3 x 3 = 9 and 5 x 3 = 15, which are all correct. Add 4 fits 2 to 6 but not 3 to 9.', 'checked', '{"lint":[],"solve":{"answer":"Multiply by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 3 = 6, 3 x 3 = 9, 5 x 3 = 15. Add 4 gives 7 for 3; add 6 gives 8 for 2; x2 gives 4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
