INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29bbdb93-3f50-43b9-a547-39988d35a49e', 'NC26.4.ANR.7', 2, 'numeric', 'Growing shape pattern', 'A pattern of toothpick figures uses 4 toothpicks in Figure 1, 7 toothpicks in Figure 2 and 10 toothpicks in Figure 3. It keeps going by adding 3 more toothpicks each time. How many toothpicks are in Figure 6?', '[]', '19', '4+5*3', 'Figure 4 has 13, Figure 5 has 16 and Figure 6 has 19. Another way: Figure 6 is 5 steps after Figure 1, so 4 + 5 x 3 = 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, 7, 10, 13, 16, 19 for figures 1-6. Figure 6 = 19 (3n + 1).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
