INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95cb7f25-9e64-4df7-ba55-32bca62dd7f0', 'NC26.4.ANR.7', 3, 'numeric', 'Find a later term of a pattern', 'A pattern starts at 7 and adds 5 each time: 7, 12, 17, 22, ... What is the 10th number in the pattern?', '[]', '52', '7+9*5', 'The 10th number is 9 steps after the first. Each step adds 5, so 7 + 9 x 5 = 7 + 45 = 52.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10th = 7 + 9 x 5 = 52.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
