INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5e342c7-4f6e-4f39-90e2-32f738ff7558', 'NC26.4.ANR.7', 3, 'choice', 'List a pattern from a multiplication rule', 'A pattern starts at 3 and follows the rule "multiply by 2". Which list shows the first four numbers?', '["3, 6, 12, 24","3, 6, 9, 12","3, 5, 7, 9","3, 6, 10, 16"]', '3, 6, 12, 24', NULL, 'Start with 3. 3 x 2 = 6, 6 x 2 = 12, and 12 x 2 = 24. The list is 3, 6, 12, 24. (3, 6, 9, 12 adds 3 each time.)', 'checked', '{"lint":[],"solve":{"answer":"3, 6, 12, 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3, 6, 12, 24.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
