INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cea87297-ea17-4218-bd15-69d568b72b05', 'NC26.4.ANR.7', 3, 'choice', 'Decide whether a number belongs to a pattern', 'The pattern 4, 9, 14, 19, 24, ... follows the rule "add 5". Which number is in this pattern?', '["60","59","61","56"]', '59', '59', 'Every number in the pattern is 4 more than a multiple of 5, so it ends in 4 or 9. Only 59 ends in 9. Check: 4 + 11 x 5 = 59.', 'checked', '{"lint":[],"solve":{"answer":"59","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms are 4 more than a multiple of 5 (end in 4 or 9): ..., 54, 59, 64. 59 is in; 56, 60, 61 are not.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
