INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3304af5a-7fe4-4ffa-934f-1082e4696a2c', 'NC26.4.SGMR.1', 1, 'numeric', 'Degrees in a half-turn', 'A full turn around a circle is 360 degrees. How many degrees is a half-turn?', '[]', '180', '360/2', 'A half-turn is half of a full turn: 360 divided by 2 = 180 degrees.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360 / 2 = 180.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
