INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6300e954-2cb2-4839-a408-1c66d63b6da4', 'NC26.4.SGMR.1', 1, 'choice', 'Name an angle by its measure', 'An angle measures 120 degrees. What kind of angle is it?', '["acute","right","straight","obtuse"]', 'obtuse', NULL, 'An acute angle is less than 90 degrees, a right angle is exactly 90 degrees, and an obtuse angle is greater than 90 degrees and less than 180 degrees. A straight angle is 180 degrees. 120 degrees is between 90 and 180, so it is obtuse.', 'checked', '{"lint":[],"solve":{"answer":"obtuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 90 and 180 degrees: obtuse.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
