INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15330690-668a-4a6f-a50a-4dc570ba90ee', 'NC26.4.SGMR.1', 1, 'choice', 'Estimate an angle', 'Which angle is closest to a right angle?', '["15 degrees","88 degrees","120 degrees","150 degrees"]', '88 degrees', NULL, 'A right angle is 90 degrees. 88 degrees is only 2 degrees away. The others are 75, 30 and 60 degrees away.', 'checked', '{"lint":[],"solve":{"answer":"88 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance from 90: 150->60, 15->75, 88->2, 120->30. Closest: 88 degrees.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
