INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6c3214c-a90c-439d-8bbc-86456f4b6401', 'NC26.4.SGMR.1', 2, 'numeric', 'Add adjacent angles', 'Ray BD is inside angle ABC and splits it into two angles. Angle ABD measures 47 degrees and angle DBC measures 38 degrees. How many degrees does angle ABC measure?', '[]', '85', '47+38', 'The whole angle is the sum of its two parts: 47 + 38 = 85 degrees.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 + 38 = 85.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
