INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2176f69b-a5ca-47b1-80ec-00409f281907', 'NC26.4.SGMR.1', 2, 'numeric', 'Find an unknown angle on a straight line', 'Angle PQR and angle RQS are next to each other on a straight line, so together they measure 180 degrees. Angle PQR measures 112 degrees. How many degrees does angle RQS measure?', '[]', '68', '180-112', 'Subtract the known angle from 180: 180 - 112 = 68 degrees. Check: 112 + 68 = 180.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 112 = 68.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
