INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0807cd07-ee16-476f-9cc8-09dd634502fb', 'NC26.4.SGMR.1', 2, 'choice', 'Angle as a fraction of a circle', 'An angle opens through $\frac{1}{6}$ of a full circle. A full circle is 360 degrees. How many degrees is the angle?', '["36","45","60","90"]', '60', '360/6', '$\frac{1}{6}$ of 360 is 360 divided by 6 = 60 degrees. (90 degrees is $\frac{1}{4}$ of a circle and 45 degrees is $\frac{1}{8}$.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360 / 6 = 60.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
