INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2995fd-9e29-41e0-a5b6-b87c5a105c42', 'NC26.4.SGMR.1', 3, 'numeric', 'Find the third angle along a straight line', 'Three angles are next to each other along a straight line. Two of them measure 48 degrees and 75 degrees. How many degrees does the third angle measure?', '[]', '57', '180-48-75', 'Together the three angles measure 180 degrees. The two known angles add to 48 + 75 = 123 degrees. The third angle is 180 - 123 = 57 degrees.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 48 - 75 = 57.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48b5c991-c0c2-4f87-b2da-d18572d95234', 'NC26.4.SGMR.1', 3, 'choice', 'A turn as a fraction of a circle', 'A turn through 270 degrees is what fraction of a full circle (360 degrees)?', '["$\\frac{3}{4}$","$\\frac{1}{4}$","$\\frac{2}{3}$","$\\frac{1}{3}$"]', '$\frac{3}{4}$', NULL, 'A quarter of a circle is 90 degrees. 270 is 3 x 90, so the turn is 3 quarters, or $\frac{3}{4}$, of the circle. Check: $\frac{270}{360} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"270 / 360 = 27/36 = 3/4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('575fd2d9-dd24-49ff-b677-1891a8f5b206', 'NC26.4.SGMR.1', 3, 'numeric', 'Angles with a given difference', 'Two angles are next to each other and together measure 150 degrees. The larger angle is 20 degrees greater than the smaller angle. How many degrees does the smaller angle measure?', '[]', '65', '(150-20)/2', 'If the larger angle were 20 degrees smaller, the two angles would be equal and would add to 150 - 20 = 130 degrees. Each would measure 130 divided by 2 = 65 degrees. So the smaller angle is 65 degrees and the larger is 85 degrees. Check: 65 + 85 = 150.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remove the extra 20: 150 - 20 = 130; 130 / 2 = 65. Check 65 + 85 = 150, 85 - 65 = 20. A sum-and-difference problem; a stretch for grade 4 but solvable by guess and check.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
