VALUES ('cd65ee4f-6da1-495b-a7c7-cba7adee0280', 'NC26.4.SGMR.2', 1, 'choice', 'Classify a triangle by its sides', 'A triangle has side lengths of 6 cm, 7 cm and 8 cm. What kind of triangle is it, by its sides?', '["isosceles","equilateral","scalene","right"]', 'scalene', NULL, 'The three sides are all different lengths. A triangle with no equal sides is scalene. (An isosceles triangle has two equal sides and an equilateral triangle has three.)', 'checked', '{"lint":[],"solve":{"answer":"scalene","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All three sides different: scalene.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
