INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12edc0a3-9a0e-42db-b713-6a7e0c02cd7b', 'NC26.4.SGMR.2', 1, 'numeric', 'Parallel sides of a quadrilateral', 'How many pairs of parallel sides does a rectangle have?', '[]', '2', NULL, 'In a rectangle, the two long sides are parallel to each other, and the two short sides are parallel to each other. That makes 2 pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle''s opposite sides are parallel: top with bottom, left with right. That is 2 pairs.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
