INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88a6480e-d165-4706-b7eb-6735a7492295', 'NC26.4.SGMR.2', 2, 'choice', 'Classify a triangle by its angle measures', 'A triangle has angles that measure 40 degrees, 45 degrees and 95 degrees. What kind of triangle is it, by its angles?', '["obtuse","acute","right","equilateral"]', 'obtuse', NULL, 'One angle, 95 degrees, is greater than 90 degrees, so the triangle has an obtuse angle. It is an obtuse triangle.', 'checked', '{"lint":[],"solve":{"answer":"obtuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"95 > 90, so one obtuse angle: obtuse triangle (40 + 45 + 95 = 180).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
