INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39e51cd2-b027-4160-a079-8779064a9c3f', 'NC26.4.SGMR.2', 2, 'choice', 'Name a quadrilateral from its attributes', 'A quadrilateral has four right angles. Two of its sides are 6 cm long and the other two sides are 3 cm long. Which name is correct for this shape?', '["square","rhombus","pentagon","rectangle"]', 'rectangle', NULL, 'A quadrilateral with four right angles is a rectangle. It is not a square or a rhombus, because those need all four sides equal. It is not a pentagon, which has five sides.', 'checked', '{"lint":[],"solve":{"answer":"rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four right angles with opposite sides 6 and 3 (not all equal): rectangle, not square or rhombus.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
