INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42eadc1a-db00-4d0e-9781-37a614213f7e', 'NC26.4.SGMR.2', 2, 'choice', 'Notation for a ray', 'Which symbol names the ray that starts at point P and passes through point Q?', '["$\\overrightarrow{QP}$","$\\overrightarrow{PQ}$","$\\overline{PQ}$","$\\overleftrightarrow{PQ}$"]', '$\overrightarrow{PQ}$', NULL, 'A ray has one endpoint and goes on forever in one direction. Its name starts with the endpoint and has an arrow pointing the way it goes: $\overrightarrow{PQ}$. $\overrightarrow{QP}$ starts at Q, $\overline{PQ}$ is a line segment and $\overleftrightarrow{PQ}$ is a line.', 'checked', '{"lint":[],"solve":{"answer":"$\\overrightarrow{PQ}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ray starting at P through Q: arrow over PQ pointing right, $\\overrightarrow{PQ}$.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
