INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8603d746-4321-43a6-b4a6-cd5dc2acce20', 'NC26.4.SGMR.2', 3, 'choice', 'Relationships between quadrilaterals', 'Which statement is true?', '["Every rectangle is a square.","Every rhombus has four right angles.","A square has no parallel sides.","Every square is a rectangle."]', 'Every square is a rectangle.', NULL, 'A square has four right angles, so it is a rectangle with all sides equal. Every square is a rectangle. But a rectangle does not need equal sides, a rhombus does not need right angles, and a square has two pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Every square is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has four right angles, so it is a rectangle. The others are false.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
