INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1f14235-34b0-4161-8e68-b6051003e00d', 'NC26.4.SGMR.2', 3, 'numeric', 'Count quadrilaterals in a list', 'Here are six shapes: square, triangle, rectangle, pentagon, rhombus, trapezoid. How many of them are quadrilaterals?', '[]', '4', NULL, 'A quadrilateral has four sides. The square, rectangle, rhombus and trapezoid each have four sides. The triangle has 3 sides and the pentagon has 5. So 4 of them are quadrilaterals.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrilaterals: square, rectangle, rhombus, trapezoid = 4. Triangle (3) and pentagon (5) are not.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
