INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8a7c9df-e64d-4651-923c-6097663b9ca8', 'NC26.4.SGMR.2', 3, 'choice', 'Attributes that always hold for a quadrilateral', 'Which quadrilateral always has four sides of equal length?', '["rhombus","rectangle","parallelogram","trapezoid"]', 'rhombus', NULL, 'A rhombus is defined as a quadrilateral with four equal sides. A rectangle can have long and short sides, a parallelogram only needs opposite sides equal, and a trapezoid can have sides of four different lengths.', 'checked', '{"lint":[],"solve":{"answer":"rhombus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rhombus has 4 equal sides by definition. Parallelograms, rectangles and trapezoids need not.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
