INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c695f65b-3f27-471c-beeb-62d98dea599d', 'NC26.4.SGMR.3', 1, 'numeric', 'Elapsed time in minutes', 'Sara starts her homework at 4:20 p.m. and finishes at 5:05 p.m. How many minutes does she work?', '[]', '45', '40+5', 'From 4:20 to 5:00 is 40 minutes. From 5:00 to 5:05 is 5 more minutes. 40 + 5 = 45 minutes.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:20 -> 5:00 is 40 min; 5:00 -> 5:05 is 5 min. 45.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
