VALUES ('fdebdc34-45a8-4d50-b234-f9ee3ad282e7', 'NC26.4.SGMR.3', 1, 'choice', 'Choose a unit for mass', 'Which unit is best for measuring the mass of a pencil?', '["kilograms","grams","milliliters","meters"]', 'grams', NULL, 'A pencil is very light, so use a small unit of mass: grams. A kilogram is 1,000 grams, much too big. Milliliters measure capacity and meters measure length.', 'checked', '{"lint":[],"solve":{"answer":"grams","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A pencil has a mass of a few grams.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
