VALUES ('be93ba06-6d32-4a4c-b137-13be83ff4c83', 'NC26.4.SGMR.3', 2, 'numeric', 'Capacity: convert and subtract', 'A jug holds 4 liters of water. Ben pours 750 milliliters into a glass. How many milliliters of water are left in the jug?', '[]', '3250', '4*1000-750', '4 liters is 4 x 1,000 = 4,000 milliliters. After pouring out 750 milliliters, 4,000 - 750 = 3,250 milliliters are left.', 'checked', '{"lint":[],"solve":{"answer":"3250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 L = 4,000 mL; 4,000 - 750 = 3,250.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
