VALUES ('95f3611a-aec3-4484-99e5-52eba9c14c84', 'NC26.4.SGMR.3', 2, 'choice', 'Elapsed time across the hour', 'A bus leaves at 8:50 a.m. and arrives at 10:15 a.m. How long is the trip?', '["2 hours 35 minutes","1 hour 15 minutes","1 hour 25 minutes","1 hour 35 minutes"]', '1 hour 25 minutes', NULL, 'From 8:50 to 9:00 is 10 minutes. From 9:00 to 10:00 is 1 hour. From 10:00 to 10:15 is 15 minutes. Total: 1 hour and 10 + 15 = 25 minutes, so 1 hour 25 minutes.', 'checked', '{"lint":[],"solve":{"answer":"1 hour 25 minutes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8:50 -> 9:50 = 1 h; 9:50 -> 10:15 = 25 min. 1 hour 25 minutes.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
