VALUES ('6f92dafd-2cba-4ab5-9da7-d6279d856dad', 'NC26.4.SGMR.3', 2, 'choice', 'Estimate a length', 'Which is the best estimate for the height of a classroom door?', '["2 centimeters","20 meters","2 kilometers","2 meters"]', '2 meters', NULL, 'A door is a little taller than a tall adult, about 2 meters. 2 centimeters is about the width of a finger, and 20 meters or 2 kilometers are far too long.', 'checked', '{"lint":[],"solve":{"answer":"2 meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A door is about 2 m tall.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
