VALUES ('b1116232-c030-4645-bb23-be9ac9e53d58', 'NC26.4.SGMR.3', 3, 'choice', 'Find the end time', 'Practice starts at 3:35 p.m. and lasts 1 hour 50 minutes. At what time does it end?', '["5:25 p.m.","4:25 p.m.","5:15 p.m.","5:35 p.m."]', '5:25 p.m.', NULL, 'Add 1 hour: 3:35 + 1 hour = 4:35. Add 50 minutes: 4:35 to 5:00 is 25 minutes, and 25 more minutes make 50, so the end time is 5:25 p.m.', 'checked', '{"lint":[],"solve":{"answer":"5:25 p.m.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3:35 + 1 h = 4:35; + 50 min = 5:25 p.m.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
