VALUES ('652634b5-be2d-4973-9dfe-2d9375ddcfdf', 'NC26.4.SGMR.3', 3, 'numeric', 'Capacity: convert then divide', 'A water bottle holds 500 milliliters. How many bottles can be filled completely from 6 liters of water?', '[]', '12', '6*1000/500', '6 liters is 6 x 1,000 = 6,000 milliliters. Each bottle takes 500 milliliters, so 6,000 divided by 500 = 12 bottles.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 L = 6,000 mL; 6,000 / 500 = 12.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
