VALUES ('a601b7b5-6fbe-412e-9ca9-4836cdfdd618', 'NC26.4.SGMR.4', 1, 'numeric', 'Area of a rectangle', 'A rectangle is 8 cm long and 5 cm wide. What is its area in square centimeters?', '[]', '40', '8*5', 'Area = length x width = 8 x 5 = 40 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 5 = 40.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
