INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62ea30c8-a5b6-4ab0-96b7-400d667163dc', 'NC26.4.SGMR.4', 1, 'choice', 'Perimeter of a rectangle', 'What is the perimeter, in centimeters, of a rectangle that is 9 cm long and 4 cm wide?', '["36","26","13","22"]', '26', '2*(9+4)', 'Perimeter = 2 x (length + width) = 2 x (9 + 4) = 2 x 13 = 26 centimeters. (36 is the area, 13 is only half of the way around and 22 leaves out one of the widths.)', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x (9 + 4) = 26.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
