INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b9bcf04-5afa-455c-affb-b98d73218628', 'NC26.4.SGMR.4', 1, 'choice', 'Choose the perimeter formula', 'Which expression gives the perimeter of a rectangle that is 12 m long and 5 m wide?', '["$12 \\times 5$","$12 + 5$","$2 \\times 12 \\times 5$","$2 \\times (12 + 5)$"]', '$2 \times (12 + 5)$', NULL, 'A rectangle has two lengths and two widths, so the perimeter is $2 \times (12 + 5)$. $12 \times 5$ is the area.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times (12 + 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 12 + 5 + 12 + 5 = 2 x (12 + 5).","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
