INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c7d6477-b284-472c-bef8-aac07f0e1a21', 'NC26.4.SGMR.4', 2, 'numeric', 'Find a missing side from the area', 'A rectangular garden has an area of 72 square meters. Its length is 9 meters. How many meters wide is it?', '[]', '8', '72/9', 'Area = length x width, so width = 72 divided by 9 = 8 meters. Check: 9 x 8 = 72.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 / 9 = 8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
