INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61979056-c606-4033-bec1-62da86766e45', 'NC26.4.SGMR.4', 2, 'numeric', 'Find a missing side from the perimeter', 'A rectangle has a perimeter of 30 cm. Its length is 9 cm. How many centimeters wide is it?', '[]', '6', '30/2-9', 'A length and a width together are half of the perimeter: 30 divided by 2 = 15 cm. The width is 15 - 9 = 6 cm. Check: 2 x (9 + 6) = 30.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 30 / 2 = 15; width = 15 - 9 = 6.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
