INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9fe8daa-85f1-4dfa-bad9-3e5e4957923a', 'NC26.4.SGMR.4', 2, 'numeric', 'Area of a figure made of two rectangles', 'A floor is made of two rectangles that do not overlap. One rectangle is 10 meters by 4 meters. The other is 6 meters by 3 meters. What is the total area of the floor in square meters?', '[]', '58', '10*4+6*3', 'The first rectangle has area 10 x 4 = 40 square meters. The second has area 6 x 3 = 18 square meters. Together: 40 + 18 = 58 square meters.', 'checked', '{"lint":[],"solve":{"answer":"58","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 4 = 40; 6 x 3 = 18; 40 + 18 = 58.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
