INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('deb73bfd-8218-4ebe-a589-a322d4b0d7ca', 'NC26.4.SGMR.4', 3, 'numeric', 'Same area, different perimeter', 'Rectangle A is 6 units by 4 units. Rectangle B is 12 units by 2 units. They have the same area. How many units greater is the perimeter of rectangle B than the perimeter of rectangle A?', '[]', '8', '2*(12+2)-2*(6+4)', 'Both have area 24 square units. Perimeter of A: 2 x (6 + 4) = 20 units. Perimeter of B: 2 x (12 + 2) = 28 units. The difference is 28 - 20 = 8 units.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2 x (6 + 4) = 20. B: 2 x (12 + 2) = 28. 28 - 20 = 8. (Both areas 24.)","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
