INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065f9633-b463-4482-bae1-6ce3bc003d80', 'NC26.4.SGMR.4', 3, 'choice', 'Smallest perimeter for a given area', 'Which rectangle has an area of 64 square centimeters and the smallest perimeter?', '["8 cm by 8 cm","4 cm by 16 cm","2 cm by 32 cm","1 cm by 64 cm"]', '8 cm by 8 cm', NULL, 'All four have area 64 square centimeters. Perimeters: 8 by 8 is 2 x 16 = 32 cm, 4 by 16 is 2 x 20 = 40 cm, 2 by 32 is 2 x 34 = 68 cm and 1 by 64 is 2 x 65 = 130 cm. The smallest is 8 cm by 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 1x64 -> 130, 2x32 -> 68, 4x16 -> 40, 8x8 -> 32. Smallest: 8 cm by 8 cm.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
