INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1335cd80-f738-4dbf-b098-ee6b10b0a2c2', 'NC26.4.SGMR.4', 3, 'numeric', 'Same perimeter, different area', 'Rectangle P is 7 units long and 5 units wide. Rectangle Q has the same perimeter as rectangle P, and Q is 9 units long. How many more square units of area does rectangle P have than rectangle Q?', '[]', '8', '7*5-(12-9)*9', 'The perimeter of P is 2 x (7 + 5) = 24 units, so a length and a width of Q add up to 24 / 2 = 12. Q is 9 units long, so it is 12 - 9 = 3 units wide. The area of P is 7 x 5 = 35 square units. The area of Q is 9 x 3 = 27 square units. P has 35 - 27 = 8 more square units.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter of P = 2 x (7 + 5) = 24. Q has perimeter 24 and length 9, so 9 + width = 12, width = 3. Area P = 7 x 5 = 35; area Q = 9 x 3 = 27. Difference = 35 - 27 = 8.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f3b48f0-a2e9-49e7-a387-56444a5a3cac', 'NC26.4.RD.1', 1, 'numeric', 'Range of a data set', 'Five students read 3, 5, 5, 8 and 9 books. What is the range of the number of books?', '[]', '6', '9-3', 'The range is the greatest value minus the least value: 9 - 3 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 3 = 6.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
