INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5940ef5-8f3a-4f6c-a0cb-b423eaf2a6f3', 'NC26.4.RD.1', 1, 'numeric', 'Mode of a data set', 'What is the mode of these numbers: 4, 7, 7, 2, 9, 7, 4?', '[]', '7', NULL, 'The mode is the value that appears most often. 7 appears 3 times, 4 appears 2 times, and 2 and 9 appear once. The mode is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 appears 3 times, 4 twice, others once. Mode 7.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
