INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ff3d6aa-bafa-44f6-9e99-865b344186bd', 'NC26.4.RD.1', 1, 'choice', 'Numerical versus categorical questions', 'Which question can be answered with a number, so it is a numerical question?', '["What is your favorite color?","Which sport do you like best?","How many pets do you have?","What is your favorite food?"]', 'How many pets do you have?', NULL, 'A numerical question is answered with a number. "How many pets do you have?" is answered with a number. The others are answered with a color, a sport or a food, which are categories.', 'checked', '{"lint":[],"solve":{"answer":"How many pets do you have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pets is answered with a count; the others with a category.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
