INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5c64702-b811-4f10-b25a-b87f187eb6c2', 'NC26.4.RD.1', 2, 'numeric', 'Median of a data set', 'Seven students read 12, 8, 15, 10, 9, 11 and 14 pages. What is the median number of pages?', '[]', '11', NULL, 'Put the numbers in order: 8, 9, 10, 11, 12, 14, 15. The median is the middle number. With 7 numbers, the middle is the 4th, which is 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 8, 9, 10, 11, 12, 14, 15. Middle (4th) = 11.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
