VALUES ('8fd0e9eb-c27b-4565-b302-c2460d9f39be', 'NC26.4.RD.1', 2, 'choice', 'Total from a frequency table', 'Students were asked how many siblings they have. 0 siblings: 5 students. 1 sibling: 9 students. 2 siblings: 6 students. 3 siblings: 2 students. How many students were asked in all?', '["20","17","6","22"]', '22', '5+9+6+2', 'Add the number of students in every row: 5 + 9 + 6 + 2 = 22. (6 is 0 + 1 + 2 + 3, the number of siblings added up, not the number of students.)', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 9 + 6 + 2 = 22.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
