INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c3cc17d-6d34-4ef1-bea7-da8ea3408f99', 'NC26.4.RD.1', 2, 'numeric', 'Read a line plot described in words', 'A line plot shows the number of goals a team scored in 10 games. There are 2 Xs above 0, 3 Xs above 1, 4 Xs above 2 and 1 X above 3. In how many games did the team score more than 1 goal?', '[]', '5', '4+1', 'Each X is one game. More than 1 goal means 2 goals or 3 goals. There are 4 Xs above 2 and 1 X above 3, so 4 + 1 = 5 games.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More than 1 goal = 2 or 3 goals: 4 + 1 = 5.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
