INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7504ba6f-708b-4d07-bc67-120aaa3c6547', 'NC26.4.RD.1', 3, 'numeric', 'Median from a frequency table', 'Nine worms were measured to the nearest centimeter. 3 cm: 2 worms. 4 cm: 3 worms. 5 cm: 1 worm. 6 cm: 3 worms. What is the median length, in centimeters?', '[]', '4', NULL, 'List the lengths in order: 3, 3, 4, 4, 4, 5, 6, 6, 6. There are 9 lengths, so the median is the 5th one, which is 4 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered: 3,3,4,4,4,5,6,6,6. Middle (5th) value = 4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
