INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af0e9757-bc29-404d-8d3e-f2143901da9f', 'NC26.4.RD.1', 3, 'choice', 'Draw a conclusion from two sets of data', 'Two classes voted for their favorite fruit. Class A: apples 8, bananas 6, grapes 4. Class B: apples 5, bananas 9, grapes 7. Which fruit got the most votes from the two classes together?', '["Apples","Bananas","Grapes","They all got the same number"]', 'Bananas', NULL, 'Add the two classes. Apples: 8 + 5 = 13. Bananas: 6 + 9 = 15. Grapes: 4 + 7 = 11. Bananas got the most votes. (Apples got the most votes in Class A alone.)', 'checked', '{"lint":[],"solve":{"answer":"Bananas","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Apples 8+5=13, bananas 6+9=15, grapes 4+7=11. Bananas.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
