INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbe35c6c-85ea-4477-99ff-87d6a4e42c0a', 'NC26.4.RD.1', 3, 'numeric', 'Range and mode together', 'Nine students'' scores on a quiz are 5, 8, 6, 8, 7, 8, 5, 6 and 9. What is the sum of the range and the mode?', '[]', '12', '(9-5)+8', 'The range is 9 - 5 = 4. The mode is the most common score: 8 appears 3 times, 5 and 6 appear twice, 7 and 9 once. So the mode is 8. The sum is 4 + 8 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range 9 - 5 = 4. Mode 8 (three times; 5 and 6 twice). 4 + 8 = 12.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
