INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e307d596-3d51-4b29-8380-7909233c78f5', 'NC26.5.ANR.1', 1, 'numeric', 'Order of operations: multiplication before addition', 'Find the value of $6 + 4 \times 3$.', '[]', '18', '6+4*3', 'Multiply first: $4 \times 3 = 12$. Then add: $6 + 12 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply first: 4 x 3 = 12. Then 6 + 12 = 18.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
