INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4e69b83-29bd-4342-b549-2381c3f3b24f', 'NC26.5.ANR.1', 1, 'choice', 'Order of operations: division before subtraction', 'What is the value of $30 - 12 \div 3$?', '["6","18","26","34"]', '26', '30-12/3', 'Divide first: $12 \div 3 = 4$. Then subtract: $30 - 4 = 26$. (Subtracting first would give 6, which is a common mistake.)', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide first: 12 / 3 = 4. Then 30 - 4 = 26.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
