INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('113fa276-5c0e-472a-87b0-67450ba3fb67', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a described calculation', 'Which expression means "add 5 and 2, then multiply the result by 3"?', '["$5 + 2 \\times 3$","$(5 + 2) \\times 3$","$5 \\times 3 + 2$","$5 + 2 + 3$"]', '$(5 + 2) \times 3$', NULL, 'The adding happens first, so $5 + 2$ goes inside parentheses and the result is multiplied by 3: $(5 + 2) \times 3$. Without parentheses, the multiplication would be done first.', 'checked', '{"lint":[],"solve":{"answer":"$(5 + 2) \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 5 and 2 first needs parentheses: (5 + 2), then times 3: (5 + 2) x 3 = 21.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60b125b0-8c22-4716-8c0d-4979aaa40255', 'NC26.5.ANR.1', 2, 'numeric', 'Parentheses change the order of operations', 'Find the value of $36 \div (2 + 4)$.', '[]', '6', '36/(2+4)', 'Work inside the parentheses first: $2 + 4 = 6$. Then divide: $36 \div 6 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parentheses: 2 + 4 = 6. 36 / 6 = 6.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('657921ea-c90c-481d-819e-dc22ef366534', 'NC26.5.ANR.1', 2, 'choice', 'Distributive property', 'Which expression is equal to $7 \times (20 + 4)$?', '["$7 \\times 20 + 4$","$7 \\times 20 \\times 4$","$7 \\times 20 - 7 \\times 4$","$7 \\times 20 + 7 \\times 4$"]', '$7 \times 20 + 7 \times 4$', NULL, 'The 7 multiplies both numbers in the parentheses: $7 \times 20 + 7 \times 4$. Check: $7 \times 24 = 168$ and $140 + 28 = 168$.', 'checked', '{"lint":[],"solve":{"answer":"$7 \\times 20 + 7 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distributive property: 7 x (20 + 4) = 7 x 20 + 7 x 4 = 140 + 28 = 168. Others: 144, 560, 112.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('045524bc-fab6-424a-b604-9e385f95712e', 'NC26.5.ANR.1', 2, 'numeric', 'Associative property of addition', 'What number goes in the box to make the equation true? $12 + (8 + 15) = (12 + \square) + 15$', '[]', '8', NULL, 'Numbers can be grouped in a different way without changing a sum. On the right, 12 is now added to the first number of the pair, which is 8. So the box is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property: 12 + (8 + 15) = (12 + 8) + 15, so the box is 8. Check: 35 = 35.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037a88e1-019e-482d-b4df-d3a8b1e0c3bc', 'NC26.5.ANR.1', 3, 'numeric', 'Evaluate an expression with parentheses and two other operations', 'Find the value of $2 \times (15 - 6) + 4 \times 3$.', '[]', '30', '2*(15-6)+4*3', 'Parentheses first: $15 - 6 = 9$. Then multiply: $2 \times 9 = 18$ and $4 \times 3 = 12$. Then add: $18 + 12 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 - 6 = 9; 2 x 9 = 18; 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e6bf441-28e3-45a9-8463-bd6fdc8d7d29', 'NC26.5.ANR.1', 3, 'choice', 'Compare the values of expressions', 'Which expression has the greatest value?', '["$24 \\div 4 + 2$","$24 \\div (4 + 2)$","$(24 - 4) \\times 2$","$24 - 4 \\times 2$"]', '$(24 - 4) \times 2$', NULL, '$24 \div 4 + 2 = 8$, $24 \div (4 + 2) = 4$, $24 - 4 \times 2 = 16$, and $(24 - 4) \times 2 = 40$. The greatest is $(24 - 4) \times 2$.', 'checked', '{"lint":[],"solve":{"answer":"$(24 - 4) \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(24-4) x 2 = 40; 24/(4+2) = 4; 24 - 4x2 = 16; 24/4 + 2 = 8. Greatest is 40.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c2b990f-e1e9-4c7b-aba8-a56a1341fadb', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a situation', 'Each box holds 6 red pens and 4 blue pens. Which expression gives the number of pens in 3 boxes?', '["$3 \\times (6 + 4)$","$3 \\times 6 + 4$","$3 + 6 \\times 4$","$3 \\times 6 \\times 4$"]', '$3 \times (6 + 4)$', NULL, 'One box holds $6 + 4$ pens. Three boxes hold 3 times that: $3 \times (6 + 4) = 30$ pens. The other expressions multiply only one kind of pen by 3, or multiply all three numbers.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times (6 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each box has 6 + 4 = 10 pens; 3 boxes: 3 x (6 + 4) = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('629dacb6-1103-4921-8440-3f117303c8a7', 'NC26.5.ANR.2', 1, 'numeric', 'Value of a digit up to the millions', 'In the number $3{,}482{,}915$, what is the value of the digit 4?', '[]', '400000', '4*100000', 'Reading from the left, the places are millions (3), hundred thousands (4), ten thousands (8), and so on. The 4 is in the hundred thousands place, so its value is $4 \times 100{,}000 = 400{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"400000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,482,915: 3 millions, 4 hundred thousands. Value = 400,000.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c641146-d135-4dcd-bfec-85fe2bcc86fb', 'NC26.5.ANR.2', 1, 'choice', 'Expanded form of a decimal', 'Which number is equal to $6 + 0.2 + 0.05$?', '["6.025","6.25","6.205","6.52"]', '6.25', '6+0.2+0.05', 'The 6 is the ones, 0.2 is 2 tenths, and 0.05 is 5 hundredths. Together they make 6.25.', 'checked', '{"lint":[],"solve":{"answer":"6.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 0.2 + 0.05 = 6.25.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
