VALUES ('b69f8f40-5165-4170-92d9-a492187579fa', 'NC26.5.ANR.2', 2, 'choice', 'Order decimals', 'Which list shows these decimals in order from least to greatest: 0.45, 0.405, 0.054, 0.5?', '["0.054, 0.405, 0.45, 0.5","0.5, 0.45, 0.405, 0.054","0.5, 0.45, 0.054, 0.405","0.054, 0.45, 0.405, 0.5"]', '0.054, 0.405, 0.45, 0.5', NULL, 'Write each with three decimal places: 0.450, 0.405, 0.054, 0.500. From least to greatest: 0.054, 0.405, 0.450, 0.500.', 'checked', '{"lint":[],"solve":{"answer":"0.054, 0.405, 0.45, 0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"As thousandths: 0.450, 0.405, 0.054, 0.500. Order: 0.054, 0.405, 0.45, 0.5.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
