INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31a8a173-c318-4cf0-82a5-b7f19019e67d', 'NC26.5.ANR.2', 3, 'numeric', 'Compare the value of a digit in two numbers', 'How many times as great is the value of the digit 7 in $7{,}214$ as the value of the digit 7 in $3.072$?', '[]', '100000', '7000/0.07', 'In $7{,}214$ the 7 is in the thousands place, so its value is 7,000. In $3.072$ the 7 is in the hundredths place, so its value is 0.07. Since $7{,}000 \div 0.07 = 100{,}000$, the first is 100,000 times as great.', 'checked', '{"lint":[],"solve":{"answer":"100000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In 7,214 the 7 is worth 7,000. In 3.072 the 7 is in the hundredths place, worth 0.07. 7,000 / 0.07 = 100,000 (five places apart, 10^5).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
