INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4cbd36f-4a87-48f4-acf6-42b03247a424', 'NC26.5.ANR.2', 3, 'numeric', 'Reverse a pattern of dividing by ten', 'A number is divided by 10. The result is 0.38. What is the number?', '[]', '3.8', '0.38*10', 'Dividing by 10 moves each digit one place to the right, so to undo it multiply by 10: $0.38 \times 10 = 3.8$.', 'checked', '{"lint":[],"solve":{"answer":"3.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n / 10 = 0.38, so n = 0.38 x 10 = 3.8.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
