VALUES ('ce24ab06-39b0-465f-8d90-6609badad014', 'NC26.5.ANR.2', 3, 'choice', 'Compare decimals', 'Which comparison is true?', '["$0.15 > 0.5$","$2.04 > 2.4$","$0.7 > 0.699$","$3.1 < 3.099$"]', '$0.7 > 0.699$', NULL, 'Compare place by place. $0.700 > 0.699$ is true. The others are false: $0.15 < 0.50$, $2.04 < 2.40$, and $3.100 > 3.099$.', 'checked', '{"lint":[],"solve":{"answer":"$0.7 > 0.699$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.15 < 0.5; 3.1 > 3.099; 2.04 < 2.4; 0.700 > 0.699 is true.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
