VALUES ('c53f88f6-297a-49d9-b533-3ca835a47809', 'NC26.5.ANR.3', 1, 'numeric', 'Multiply a three-digit number by a two-digit number', 'Find $124 \times 12$.', '[]', '1488', '124*12', '$124 \times 10 = 1{,}240$ and $124 \times 2 = 248$. Add: $1{,}240 + 248 = 1{,}488$.', 'checked', '{"lint":[],"solve":{"answer":"1488","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"124 x 12 = 124 x 10 + 124 x 2 = 1,240 + 248 = 1,488.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
