VALUES ('c1951f61-c466-42e1-b390-9447b35cbb83', 'NC26.5.ANR.3', 3, 'numeric', 'Find the remainder in a division problem', 'A baker packs 7 muffins into each bag. She has $4{,}000$ muffins. After she fills as many bags as she can, how many muffins are left over?', '[]', '3', '4000-7*571', '$4{,}000 \div 7 = 571$ with a remainder. $7 \times 571 = 3{,}997$, and $4{,}000 - 3{,}997 = 3$. So 3 muffins are left over.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,000 / 7: 7 x 571 = 3,997, remainder 3.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
