VALUES ('2915b4f5-9a8f-4adb-a777-a193eb9e9dc6', 'NC26.5.ANR.5', 2, 'choice', 'Scaling: multiplying by a fraction less than 1', 'Without finding the products, which expression is less than $\frac{5}{8}$?', '["$\\frac{5}{8} \\times \\frac{4}{3}$","$\\frac{5}{8} \\times \\frac{5}{5}$","$\\frac{5}{8} \\times \\frac{3}{4}$","$\\frac{5}{8} \\times 2$"]', '$\frac{5}{8} \times \frac{3}{4}$', NULL, 'Multiplying by a number less than 1 makes a number smaller. Only $\frac{3}{4}$ is less than 1. The factor $\frac{5}{5}$ equals 1 (no change), and $\frac{4}{3}$ and 2 are greater than 1 (larger).', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8} \\times \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying by a fraction less than 1 gives a smaller product. 5/5 = 1 (equal), 2 and 4/3 are greater than 1, 3/4 < 1. So 5/8 x 3/4 < 5/8.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bbf0087-8540-49a4-a3d4-914cb3bedd06', 'NC26.5.ANR.5', 3, 'numeric', 'Divide a unit fraction by a whole number', 'One-third of a pizza is shared equally among 4 people. What fraction of the whole pizza does each person get?', '[]', '1/12', '(1/3)/4', 'Each person gets $\frac{1}{3} \div 4 = \frac{1}{12}$ of the pizza. (Cut each third into 4 equal parts; 12 such parts make the whole.)', 'checked', '{"lint":[],"solve":{"answer":"1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 / 4 = 1/3 x 1/4 = 1/12.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c680e00c-c796-4944-b17f-19cb3bd17a23', 'NC26.5.ANR.5', 3, 'choice', 'Divide a whole number by a unit fraction', 'A ribbon 4 meters long is cut into pieces that are each $\frac{1}{5}$ of a meter long. How many pieces are there?', '["4/5","20","1/20","5/4"]', '20', '4/(1/5)', 'Each meter makes 5 pieces, so 4 meters make $4 \times 5 = 20$ pieces. That is $4 \div \frac{1}{5} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (1/5) = 4 x 5 = 20 pieces.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccf4260c-1301-41f2-99c4-b2f349732b88', 'NC26.5.ANR.5', 3, 'numeric', 'Add fractions with unlike denominators in a mixed-number answer', 'Tom ran $\frac{2}{3}$ mile on Monday and $\frac{3}{4}$ mile on Tuesday. How many miles did he run in all? Write your answer as a mixed number.', '[]', '1 5/12', '2/3+3/4', 'Use a common denominator of 12: $\frac{8}{12} + \frac{9}{12} = \frac{17}{12} = 1\frac{5}{12}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"1 5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 + 3/4 = 8/12 + 9/12 = 17/12 = 1 5/12 miles.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03602c9-757a-4fac-b962-fe34580d5e5c', 'NC26.5.ANR.6', 1, 'numeric', 'Extend an adding pattern', 'A pattern starts at 0 and adds 3 each time: 0, 3, 6, 9, ... What is the 6th number in the pattern?', '[]', '15', '0+5*3', 'Continue the pattern: 0, 3, 6, 9, 12, 15. The 6th number is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0, 3, 6, 9, 12, 15: the 6th number is 15.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
