INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('351bb115-dbba-40d6-9fb0-a93e9364b013', 'NC26.5.ANR.6', 1, 'choice', 'Relationship between matching numbers of two patterns', 'Pattern A starts at 0 and adds 2: 0, 2, 4, 6. Pattern B starts at 0 and adds 6: 0, 6, 12, 18. How are the matching numbers related?', '["Each number in B is 4 more than the matching number in A","Each number in B is 6 more than the matching number in A","Each number in B is 3 times the matching number in A","Each number in B is 2 times the matching number in A"]', 'Each number in B is 3 times the matching number in A', NULL, 'Match them up: $0 \to 0$, $2 \to 6$, $4 \to 12$, $6 \to 18$. Each number in B is 3 times the number in A.', 'checked', '{"lint":[],"solve":{"answer":"Each number in B is 3 times the matching number in A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs (0,0), (2,6), (4,12), (6,18): B = 3 x A. Differences vary (4, 8, 12), so not a constant ''more than''.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8448b512-ca64-41a4-8d9e-036410134acf', 'NC26.5.ANR.6', 1, 'numeric', 'Extend a multiplying pattern', 'A pattern starts at 3 and multiplies by 2 each time: 3, 6, 12, 24, ... What is the next number?', '[]', '48', '24*2', 'Each number is double the one before it, so the next number is $24 \times 2 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 2 = 48.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c62643b2-8e3a-44a7-bd83-4f2a903b5963', 'NC26.5.ANR.6', 2, 'numeric', 'Use the relationship between two patterns to predict', 'Pattern A: 0, 4, 8, 12, ... Pattern B: 0, 8, 16, 24, ... The 10th number in Pattern A is 36. What is the 10th number in Pattern B?', '[]', '72', '36*2', 'Each number in B is 2 times the matching number in A ($4 \to 8$, $8 \to 16$, $12 \to 24$). So the 10th number in B is $36 \times 2 = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A''s nth term 4(n-1): 10th = 36 (matches). B''s nth term 8(n-1) = 2 x A: 10th = 72.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b33c68c-3640-4e53-9cfe-c219087555ce', 'NC26.5.ANR.6', 2, 'choice', 'Relationship between matching numbers of two patterns', 'Pattern X starts at 1 and adds 2: 1, 3, 5, 7. Pattern Y starts at 4 and adds 2: 4, 6, 8, 10. Which statement describes the matching numbers?', '["Each number in Y is 3 more than the matching number in X","Each number in Y is 3 times the matching number in X","Each number in Y is 2 more than the matching number in X","Each number in Y is 4 more than the matching number in X"]', 'Each number in Y is 3 more than the matching number in X', NULL, 'Match them up: $1 \to 4$, $3 \to 6$, $5 \to 8$, $7 \to 10$. The difference is always 3.', 'checked', '{"lint":[],"solve":{"answer":"Each number in Y is 3 more than the matching number in X","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs (1,4), (3,6), (5,8), (7,10): Y = X + 3 each time. Not 3 times (1 -> 4).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b67f5338-3ddd-42a2-8264-4b975679d58b', 'NC26.5.ANR.6', 2, 'numeric', 'Find the position of a number in a pattern', 'A pattern starts at 7 and adds 6 each time: 7, 13, 19, 25, ... In what position is the number 43? (The number 7 is in position 1.)', '[]', '7', '(43-7)/6+1', 'Continue: 7 (1st), 13 (2nd), 19 (3rd), 25 (4th), 31 (5th), 37 (6th), 43 (7th). The number 43 is in position 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + 6(n-1) = 43 -> 6(n-1) = 36 -> n - 1 = 6 -> n = 7. List: 7, 13, 19, 25, 31, 37, 43 (7th).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('794c0d76-4770-4d09-90df-1268b2fb7abd', 'NC26.5.ANR.6', 3, 'numeric', 'Use the relationship between two patterns, with division', 'Pattern A starts at 0 and adds 6. Pattern B starts at 0 and adds 2. The 8th number in Pattern A is 42. What is the 8th number in Pattern B?', '[]', '14', '42/3', 'Each number in A is 3 times the matching number in B, because 6 is 3 times 2. So the 8th number in B is $42 \div 3 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A''s 8th = 7 x 6 = 42 (matches). B''s 8th = 7 x 2 = 14; each B term is 1/3 of A''s: 42/3 = 14.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('116d7b4e-8b2e-4862-8cae-91f2382d3ca6', 'NC26.5.ANR.6', 3, 'choice', 'Choose rules that make a given relationship', 'Two patterns both start at 0. Each number in the second pattern must be twice the matching number in the first pattern. Which pair of rules does this?', '["First pattern: add 3. Second pattern: add 5.","First pattern: add 3. Second pattern: add 6.","First pattern: add 6. Second pattern: add 3.","First pattern: add 3. Second pattern: add 9."]', 'First pattern: add 3. Second pattern: add 6.', NULL, 'Both start at 0, so the second pattern''s step must be twice the first pattern''s step. With add 3 in the first pattern the second must add 6.', 'checked', '{"lint":[],"solve":{"answer":"First pattern: add 3. Second pattern: add 6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both start at 0; if first adds 3 and second adds 6, terms are 3k and 6k, so second = 2 x first. Add 6/add 3 gives half; add 5 and add 9 give 5/3 and 3 times.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b35c6d-6ec3-4753-b270-60c44ea37c9a', 'NC26.5.ANR.6', 3, 'numeric', 'Work backward using the relationship between two patterns', 'Pattern X: 0, 5, 10, 15, ... Pattern Y: 0, 10, 20, 30, ... A number in Pattern Y is 90. What is the matching number in Pattern X?', '[]', '45', '90/2', 'Each number in Y is 2 times the matching number in X. So the matching number in X is $90 \div 2 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Y = 2 x X (10 = 2 x 5 etc.). 90 / 2 = 45. (Y: 90 is 10th term 9x10; X 10th = 45.)","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
