INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfa4d510-e046-441d-85fb-8a09d3407bc7', 'NC26.5.SGMR.1', 1, 'choice', 'Name a quadrilateral from its properties', 'A quadrilateral has 4 sides of equal length and 4 right angles. Which name describes it most specifically?', '["rectangle","rhombus","parallelogram","square"]', 'square', NULL, 'A rectangle, a rhombus and a parallelogram all describe it, but a square is the most specific name: it has equal sides and right angles.', 'checked', '{"lint":[],"solve":{"answer":"square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides and 4 right angles -> square, the most specific name.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('604e6363-3086-4a12-8535-a5149341349d', 'NC26.5.SGMR.1', 1, 'choice', 'Hierarchy: which category fits inside another', 'Which statement is true?', '["Every square is a rectangle.","Every rectangle is a square.","Every rhombus is a rectangle.","Every parallelogram is a square."]', 'Every square is a rectangle.', NULL, 'A square has 4 right angles, which is what makes a rectangle. But a rectangle can have sides of different lengths, so it is not always a square.', 'checked', '{"lint":[],"solve":{"answer":"Every square is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has 4 right angles and opposite sides parallel, so it is a rectangle. The others are false (a rhombus need not have right angles, etc.).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f6c2995-82a7-49e0-b107-7fe636a2ff46', 'NC26.5.SGMR.1', 1, 'numeric', 'Parallel sides of a rectangle', 'How many pairs of parallel sides does a rectangle have?', '[]', '2', NULL, 'The two long sides are parallel to each other and the two short sides are parallel to each other. That makes 2 pairs.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle is a parallelogram: 2 pairs of parallel sides.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
