INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3016ea5-ecde-4ace-8879-55ed85293d67', 'NC26.5.SGMR.1', 2, 'choice', 'Attributes that every rhombus has', 'Which attribute do ALL rhombuses have?', '["Four right angles","Four sides of equal length","Opposite sides that are different lengths","Exactly one pair of parallel sides"]', 'Four sides of equal length', NULL, 'A rhombus is defined by four sides of equal length. Only some rhombuses (squares) have right angles. A rhombus has 2 pairs of parallel sides, and all its sides are equal.', 'checked', '{"lint":[],"solve":{"answer":"Four sides of equal length","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus is defined by four equal sides. Right angles not required; it has 2 pairs of parallel sides; opposite sides are equal.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be5639e5-d816-446d-8f07-b0afd4594f37', 'NC26.5.SGMR.1', 2, 'choice', 'Shapes that always have four right angles', 'Which list contains only shapes that ALWAYS have four right angles?', '["square, rhombus","rectangle, parallelogram","square, rectangle","rhombus, parallelogram"]', 'square, rectangle', NULL, 'Squares and rectangles always have four right angles. Rhombuses and parallelograms can lean over, so their angles are not always right angles.', 'checked', '{"lint":[],"solve":{"answer":"square, rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares and rectangles always have four right angles; rhombuses and parallelograms need not.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
