INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4878db0-9296-45f5-9a42-ec90b86b3a12', 'NC26.5.SGMR.1', 2, 'numeric', 'Use an attribute of a category to find a measurement', 'A rhombus has four sides of equal length. One side is 7 centimeters long. What is the perimeter of the rhombus, in centimeters?', '[]', '28', '7*4', 'All 4 sides are 7 centimeters long, so the perimeter is $4 \times 7 = 28$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 7 = 28 cm.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
