INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37ae1ce6-3b88-44c9-bac2-c54f6e3256f8', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Which statement about the attributes of quadrilaterals is true?', '["Every attribute of a square is also an attribute of a rectangle.","Every attribute of a rhombus is also an attribute of a rectangle.","Every attribute of a square is also an attribute of a rhombus.","Every attribute of a rectangle is also an attribute of a square."]', 'Every attribute of a rectangle is also an attribute of a square.', NULL, 'A square is a kind of rectangle, so it has every attribute that rectangles have. The other statements fail: a square has four equal sides, which a rectangle does not always have, and a square has right angles, which a rhombus does not always have.', 'checked', '{"lint":[],"solve":{"answer":"Every attribute of a rectangle is also an attribute of a square.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is a special rectangle, so every property all rectangles have (4 right angles, opposite sides parallel and equal) holds for squares. Square->rectangle fails (equal sides), square->rhombus fails (right angles), rhombus->rectangle fails (right angles).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec246ab0-4628-49fb-9ddd-c22f02702e81', 'NC26.5.SGMR.1', 3, 'choice', 'Use a counterexample to test a claim', 'Sam says: "This shape has four sides of equal length, so it must be a square." Which shape shows that Sam is wrong?', '["A rhombus with angles of 60 degrees and 120 degrees","A rectangle with sides 4 centimeters and 6 centimeters","A square with sides of 4 centimeters","A parallelogram with sides 3 centimeters and 5 centimeters"]', 'A rhombus with angles of 60 degrees and 120 degrees', NULL, 'We need a shape with four equal sides that is not a square. A rhombus with no right angles is one. The other shapes either do not have four equal sides, or are squares.', 'checked', '{"lint":[],"solve":{"answer":"A rhombus with angles of 60 degrees and 120 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus with 60 and 120 degree angles has four equal sides but no right angles, so it is not a square. Rectangle 4x6 and parallelogram 3x5 do not have equal sides; a square agrees with Sam.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41846ef8-51e4-4411-be2f-3a09140b4d51', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that always have an attribute', 'Look at these four shapes: square, rectangle, rhombus, parallelogram. How many of them ALWAYS have four sides of equal length?', '[]', '2', NULL, 'A square and a rhombus always have four equal sides. A rectangle and a parallelogram only have equal opposite sides, so they do not always have four equal sides. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Always four equal sides: square and rhombus. Rectangle and parallelogram not always. Count = 2.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69d9bb6f-7785-478a-961d-db96ec54be59', 'NC26.5.SGMR.2', 1, 'numeric', 'Read a coordinate', 'The point $(5, 2)$ is plotted on a coordinate plane. How many units above the x-axis is the point?', '[]', '2', NULL, 'In $(5, 2)$ the first number says how far right and the second number says how far up. The point is 2 units above the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-coordinate is 2, so 2 units above the x-axis.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
