INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fae19af-9245-473b-a3fa-0a9e9b768e01', 'NC26.5.SGMR.2', 1, 'choice', 'Name a point reached by moving from the origin', 'Starting at the origin $(0, 0)$, you move 3 units right and 6 units up. Which ordered pair names where you are?', '["$(6, 3)$","$(3, 6)$","$(3, 9)$","$(0, 9)$"]', '$(3, 6)$', NULL, 'The first number is the move right (3) and the second is the move up (6), so you are at $(3, 6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right 3 gives x = 3, up 6 gives y = 6: (3, 6).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
