INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e346e8e5-7213-4297-b165-91bb09a23b99', 'NC26.5.SGMR.2', 1, 'choice', 'Points on an axis', 'Which point is on the y-axis?', '["$(0, 5)$","$(5, 0)$","$(5, 5)$","$(2, 3)$"]', '$(0, 5)$', NULL, 'A point on the y-axis is 0 units right of it, so its first number is 0. That is $(0, 5)$. The point $(5, 0)$ is on the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points on the y-axis have x = 0: (0, 5).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
