INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2f8cc02-c012-4893-ae11-5321ab96eb81', 'NC26.5.SGMR.2', 2, 'numeric', 'Distance between two points on a vertical line', 'On a coordinate plane, Point A is at $(2, 3)$ and Point B is at $(2, 9)$. How many units apart are A and B?', '[]', '6', '9-3', 'Both points have x-coordinate 2, so they are on a vertical line. The distance is $9 - 3 = 6$ units.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x; 9 - 3 = 6 units.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
