INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fecc83a-c43f-4a00-985d-a89c6fdb027c', 'NC26.5.SGMR.2', 2, 'choice', 'Move a point on the coordinate plane', 'Point P is at $(3, 4)$. Dana moves it 5 units right and 2 units up. What are the new coordinates?', '["$(5, 9)$","$(8, 2)$","$(8, 6)$","$(6, 8)$"]', '$(8, 6)$', NULL, 'Moving right adds to the first number: $3 + 5 = 8$. Moving up adds to the second number: $4 + 2 = 6$. The new point is $(8, 6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(8, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 + 5, 4 + 2) = (8, 6).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
