INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7420d5ed-f8d2-40a2-8c5d-f333385f29a0', 'NC26.5.SGMR.2', 2, 'numeric', 'Perimeter of a rectangle from its corners', 'A rectangle on a coordinate plane has corners at $(1, 1)$, $(6, 1)$, $(6, 4)$ and $(1, 4)$. What is its perimeter, in units?', '[]', '16', '2*(5+3)', 'The width is $6 - 1 = 5$ units and the height is $4 - 1 = 3$ units. The perimeter is $2 \times (5 + 3) = 16$ units.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 6 - 1 = 5, width 4 - 1 = 3. Perimeter 2(5 + 3) = 16.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
