INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6de252a2-065c-4ac6-8081-5b7931402d2b', 'NC26.5.SGMR.2', 3, 'numeric', 'Distance along a path on the coordinate plane', 'On a coordinate plane, a bug crawls in a straight line from $(2, 3)$ to $(7, 3)$ and then in a straight line to $(7, 9)$. How many units does it crawl in all?', '[]', '11', '(7-2)+(9-3)', 'First part: the y-coordinate stays 3, so the distance is $7 - 2 = 5$ units. Second part: the x-coordinate stays 7, so the distance is $9 - 3 = 6$ units. Total: $5 + 6 = 11$ units.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3) to (7,3): 5 units; (7,3) to (7,9): 6 units. Total 11.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71ba71db-a373-4f61-857a-7cf67dd50847', 'NC26.5.SGMR.2', 3, 'choice', 'Ordered pairs made from two patterns', 'Pattern 1 starts at 0 and adds 2. Pattern 2 starts at 0 and adds 6. Matching numbers form ordered pairs (Pattern 1 number, Pattern 2 number), such as $(0, 0)$ and $(2, 6)$. Which ordered pair is also one of these pairs?', '["$(12, 4)$","$(4, 8)$","$(6, 12)$","$(4, 12)$"]', '$(4, 12)$', NULL, 'Pattern 1: 0, 2, 4, 6. Pattern 2: 0, 6, 12, 18. The third numbers make the pair $(4, 12)$. The pair $(6, 12)$ is wrong because the pair for 6 is $(6, 18)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs are (2k, 6k): (0,0), (2,6), (4,12), (6,18)... (4,12) is one; (4,8), (12,4), (6,12) are not.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f17789d5-523b-41ca-a3fc-b3b81a0f60a1', 'NC26.5.SGMR.2', 3, 'choice', 'Find the missing corner of a rectangle', 'Three corners of a rectangle on a coordinate plane are $(2, 2)$, $(8, 2)$ and $(8, 5)$. What are the coordinates of the fourth corner?', '["$(5, 2)$","$(2, 5)$","$(2, 8)$","$(5, 8)$"]', '$(2, 5)$', NULL, 'The fourth corner is above $(2, 2)$ and left of $(8, 5)$. So it has x-coordinate 2 and y-coordinate 5: $(2, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides are horizontal/vertical. Corners use x in {2,8}, y in {2,5}: missing (2, 5).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
