INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36cf4e8e-4ef0-4b58-bb0a-d8e7cf298bef', 'NC26.5.SGMR.3', 2, 'choice', 'Check that a conversion is reasonable', 'Lena changes 24 inches to feet and gets 288 feet. Why can you tell that her answer is not reasonable?', '["A foot is shorter than an inch, so there should be more feet than inches.","A foot is longer than an inch, so there should be more feet than inches.","A foot is longer than an inch, so there should be fewer feet than inches.","Feet cannot be changed into inches or the other way around."]', 'A foot is longer than an inch, so there should be fewer feet than inches.', NULL, 'A foot is a longer unit, so it takes fewer feet than inches to measure the same length. 24 inches is $24 \div 12 = 2$ feet, not 288 feet.', 'checked', '{"lint":[],"solve":{"answer":"A foot is longer than an inch, so there should be fewer feet than inches.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 inches = 2 feet. A foot is longer than an inch, so the number of feet must be smaller than 24; 288 is what you get by multiplying by 12 instead of dividing.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
