VALUES ('7c7f3a43-6fa9-4377-8f7f-ffb58137d64c', 'NC26.5.SGMR.3', 3, 'numeric', 'Two-step problem with metric units', 'A bucket holds 5 liters of water. Jo pours out 1,200 milliliters. How many milliliters of water are left in the bucket?', '[]', '3800', '5*1000-1200', '5 liters is $5 \times 1{,}000 = 5{,}000$ milliliters. Then $5{,}000 - 1{,}200 = 3{,}800$ milliliters are left.', 'checked', '{"lint":[],"solve":{"answer":"3800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 L = 5,000 mL; 5,000 - 1,200 = 3,800 mL.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
