INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed09ffb3-9317-490f-941b-2731819bcfc9', 'NC26.5.SGMR.3', 3, 'numeric', 'Two-step conversion with customary units', 'A ribbon is 3 yards long. Mia cuts it into pieces that are each 9 inches long. How many pieces does she get? (1 yard = 3 feet and 1 foot = 12 inches)', '[]', '12', '3*3*12/9', '3 yards is $3 \times 3 = 9$ feet, which is $9 \times 12 = 108$ inches. Then $108 \div 9 = 12$ pieces.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 yd = 9 ft = 108 in; 108 / 9 = 12 pieces.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
