VALUES ('88b8a58d-8114-4c7a-933e-38f187aac621', 'NC26.5.SGMR.4', 1, 'numeric', 'Count unit cubes in a rectangular prism', 'A rectangular prism is built from unit cubes. It is 4 cubes long, 3 cubes wide and 2 cubes tall. How many unit cubes make the prism?', '[]', '24', '4*3*2', 'One layer has $4 \times 3 = 12$ cubes. There are 2 layers, so $12 \times 2 = 24$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 x 2 = 24 cubes.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
