INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e7bcb8e-908c-4bbf-a44d-579d2fe90ddf', 'NC26.5.SGMR.4', 1, 'choice', 'Volume of a rectangular prism from its dimensions', 'A box is 5 centimeters long, 2 centimeters wide and 3 centimeters tall. What is its volume, in cubic centimeters?', '["10","30","15","62"]', '30', '5*2*3', 'Volume = length $\times$ width $\times$ height $= 5 \times 2 \times 3 = 30$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 2 x 3 = 30 cubic cm.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
