INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27ce1f87-2d02-434b-9ac1-66798391b285', 'NC26.5.SGMR.4', 2, 'numeric', 'Find a missing dimension from the volume', 'A rectangular prism has a volume of 240 cubic centimeters. Its length is 8 centimeters and its width is 5 centimeters. How tall is it, in centimeters?', '[]', '6', '240/(8*5)', 'The base area is $8 \times 5 = 40$ square centimeters. Since volume = base area $\times$ height, the height is $240 \div 40 = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area 8 x 5 = 40; height = 240 / 40 = 6 cm.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
