INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b44c4541-fa7d-4464-baa7-bfa249d8bccf', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume of a composite solid', 'Two rectangular prisms are joined to make one solid. They touch along a face but do not overlap. One prism is 6 cm by 4 cm by 3 cm. The other is 5 cm by 2 cm by 3 cm. What is the volume of the whole solid, in cubic centimeters?', '[]', '102', '6*4*3+5*2*3', 'First prism: $6 \times 4 \times 3 = 72$. Second prism: $5 \times 2 \times 3 = 30$. Add the volumes: $72 + 30 = 102$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 3 = 72; 5 x 2 x 3 = 30; total 72 + 30 = 102 (no overlap).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
