INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f62c13f-7ccf-450f-b128-adacc4e24126', 'NC26.5.RD.1', 1, 'numeric', 'Compare values of data that change over time', 'A class counted the books it read each week. Week 1: 4 books. Week 2: 6 books. Week 3: 9 books. Week 4: 12 books. How many more books were read in Week 4 than in Week 1?', '[]', '8', '12-4', 'Week 4 had 12 books and Week 1 had 4 books. $12 - 4 = 8$ more books.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 4 = 8 more books.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
