INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce4c1f81-cc50-4059-8f1a-871a717431a9', 'NC26.5.RD.1', 1, 'choice', 'Read where a line graph goes down', 'A bakery sold 40 loaves on Monday, 35 on Tuesday, 50 on Wednesday, 55 on Thursday and 60 on Friday. A line graph of these sales joins the points for the days in order. Between which two days does the line go down?', '["Wednesday to Thursday","Thursday to Friday","Tuesday to Wednesday","Monday to Tuesday"]', 'Monday to Tuesday', NULL, 'The line goes down when the number sold gets smaller from one day to the next. From Monday (40) to Tuesday (35) the number falls. From Tuesday to Wednesday (50), Wednesday to Thursday (55) and Thursday to Friday (60) it rises. So the line goes down between Monday and Tuesday.', 'checked', '{"lint":[],"solve":{"answer":"Monday to Tuesday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mon 40 -> Tue 35: down. Tue 35 -> Wed 50: up. Wed 50 -> Thu 55: up. Thu 55 -> Fri 60: up. Only Monday to Tuesday goes down.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9539d1f5-3fbf-4d4c-9c7a-32e416e7c6f7', 'NC26.5.RD.1', 2, 'numeric', 'Read a line plot of data', 'The number of pets that each of 10 students has was put on a line plot. The data are: 0, 1, 1, 2, 2, 2, 3, 3, 4, 5. How many of the students have more than 2 pets?', '[]', '4', NULL, 'The values greater than 2 are 3, 3, 4 and 5. That is 4 students.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More than 2 pets: 3, 3, 4, 5 -> 4 students.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a14022e-1d42-4d6f-b997-a00ae2f8188c', 'NC26.5.RD.1', 2, 'choice', 'Plan how to collect data', 'Carlos wants to find out which sport the students at his school like best. Which is the best way to collect the data?', '["Ask his 4 closest friends","Ask 30 students chosen from many different classes","Ask only students who play soccer","Ask only the students in his own class"]', 'Ask 30 students chosen from many different classes', NULL, 'To learn about the whole school, ask a larger group that comes from many parts of the school. The other groups would leave out many students, or favor one sport.', 'checked', '{"lint":[],"solve":{"answer":"Ask 30 students chosen from many different classes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sample from many classes represents the whole school; the other choices are biased or too narrow.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dedd725d-dc32-4080-9e22-bb322b130984', 'NC26.5.RD.1', 2, 'choice', 'Draw a conclusion from data over time', 'Maria measured a plant at the end of each month. Month 1: 10 cm. Month 2: 14 cm. Month 3: 18 cm. Month 4: 22 cm. Which statement is supported by the data?', '["The plant grew 22 cm in Month 4.","The plant grew faster in Month 4 than in Month 2.","The plant was shorter in Month 4 than in Month 3.","The plant grew 4 cm each month."]', 'The plant grew 4 cm each month.', NULL, 'The heights go up by 4 each month: $14 - 10 = 4$, $18 - 14 = 4$, $22 - 18 = 4$. The plant was 22 cm tall in Month 4, which is not the same as growing 22 cm.', 'checked', '{"lint":[],"solve":{"answer":"The plant grew 4 cm each month.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Changes: 14-10 = 4, 18-14 = 4, 22-18 = 4. Constant 4 cm per month. Not faster in Month 4; did not grow 22 cm; got taller.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56b4242a-2cb1-48c0-aa85-87355add4583', 'NC26.5.RD.1', 3, 'numeric', 'Add up the amounts in a line plot with fractions', 'A line plot shows the amount of juice, in cups, in 8 glasses: $\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{2}$, $\frac{3}{4}$, $\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{2}$, $\frac{3}{4}$. All of the juice is poured into one pitcher. How many cups of juice are in the pitcher?', '[]', '4', '4*(1/2)+2*(1/4)+2*(3/4)', 'There are 4 glasses of $\frac{1}{2}$ cup (2 cups in all), 2 glasses of $\frac{1}{4}$ cup ($\frac{1}{2}$ cup in all) and 2 glasses of $\frac{3}{4}$ cup ($1\frac{1}{2}$ cups in all). Total: $2 + \frac{1}{2} + 1\frac{1}{2} = 4$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four 1/2 = 2; two 1/4 = 1/2; two 3/4 = 3/2. Total 2 + 1/2 + 3/2 = 4 cups.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('541c0c3c-0c3d-433c-966a-6e076173b7f1', 'NC26.5.RD.1', 3, 'numeric', 'Make a prediction from data over time', 'A store counted its visitors each day. Day 1: 20. Day 2: 35. Day 3: 50. Day 4: 65. If the pattern continues, how many visitors will the store have on Day 7?', '[]', '110', '65+3*15', 'The number goes up by 15 each day ($35 - 20 = 15$, and so on). Day 5: 80, Day 6: 95, Day 7: 110.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 15 per day: Day 5 = 80, Day 6 = 95, Day 7 = 110.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eea01a11-ab1e-4310-a126-cf793c50222a', 'NC26.5.RD.1', 3, 'choice', 'Draw a true conclusion from a bar graph''s data', 'Students voted for a sport. Soccer got 18 votes, swimming 12 votes, tennis 8 votes and running 24 votes. Which statement is true?', '["Running got twice as many votes as swimming.","Soccer got 3 times as many votes as tennis.","Swimming and tennis together got more votes than running.","Tennis got half as many votes as soccer."]', 'Running got twice as many votes as swimming.', NULL, '$24 = 2 \times 12$, so running got twice as many as swimming. The others are false: $3 \times 8 = 24$, not 18; $12 + 8 = 20$, which is less than 24; and half of 18 is 9, not 8.', 'checked', '{"lint":[],"solve":{"answer":"Running got twice as many votes as swimming.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24 not 18; half of 18 is 9 not 8; 2 x 12 = 24 = running (true); 12 + 8 = 20 < 24.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('743fceb9-b8d4-4b43-b945-855bb582d5c3', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-part ratio language', 'A bag has 5 red marbles and 3 blue marbles. What is the ratio of red marbles to blue marbles?', '["3 to 5","5 to 8","5 to 3","3 to 8"]', '5 to 3', NULL, '"Red to blue" puts red first and blue second, so the ratio is 5 to 3. The ratio 3 to 5 is in the wrong order, and 5 to 8 and 3 to 8 compare one color to all 8 marbles.', 'checked', '{"lint":[],"solve":{"answer":"5 to 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red to blue is 5 to 3, in the order named.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f25a7775-5886-42dd-971c-0b823b21841d', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-whole ratio language', 'A class has 9 girls and 11 boys. What is the ratio of girls to all of the students in the class?', '["9 to 20","11 to 20","20 to 9","9 to 11"]', '9 to 20', NULL, 'There are 9 + 11 = 20 students in all. Girls to all students is 9 to 20. The ratio 9 to 11 compares girls to boys, not to all students.', 'checked', '{"lint":[],"solve":{"answer":"9 to 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total students = 9 + 11 = 20. Girls to all students = 9 to 20.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c92c9a1d-1337-450f-9c2e-58b2d022b26b', 'NC26.6.RPR.1', 1, 'numeric', 'Equivalent ratios', 'The ratios $2 : 5$ and $6 : n$ are equivalent. What is the value of $n$?', '[]', '15', '6*5/2', 'To go from 2 to 6, multiply by 3. Multiply the 5 by 3 as well: $5 \times 3 = 15$. So $n = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2:5 = 6:n. 2 x 3 = 6, so n = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('569144e6-6d6a-4752-b943-2a540dd20815', 'NC26.6.RPR.1', 2, 'numeric', 'Unit ratio (amount per 1)', 'A car uses 6 gallons of gas to travel 150 miles. How many miles does the car travel on 1 gallon of gas?', '[]', '25', '150/6', 'Divide the miles by the gallons: $150 \div 6 = 25$. The car travels 25 miles on 1 gallon.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit rate: 150 / 6 = 25 miles per gallon.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0e76a7e-43a2-4c4f-8959-8e1468dfc3a3', 'NC26.6.RPR.1', 2, 'choice', 'Writing a ratio as a fraction', 'A fruit bowl has 3 pears and 5 apples. Which fraction shows the ratio of pears to apples?', '["$\\frac{5}{3}$","$\\frac{3}{8}$","$\\frac{5}{8}$","$\\frac{3}{5}$"]', '$\frac{3}{5}$', NULL, 'The ratio of pears to apples is 3 to 5, which is written $\frac{3}{5}$ with pears on top. $\frac{5}{3}$ has the order reversed, and $\frac{3}{8}$ and $\frac{5}{8}$ compare one fruit to all 8 pieces of fruit.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pears to apples = 3 to 5 = 3/5.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a37d108-7fd4-44c4-ab0c-39a9fd005b7b', 'NC26.6.RPR.1', 2, 'choice', 'Recognizing equivalent ratios', 'Which ratio is equivalent to $12 : 18$?', '["$3 : 2$","$2 : 3$","$6 : 12$","$13 : 19$"]', '$2 : 3$', NULL, 'Divide both numbers by 6: $12 \div 6 = 2$ and $18 \div 6 = 3$, giving $2 : 3$. Subtracting 6 from each number (6 : 12) or adding 1 to each (13 : 19) does not keep the ratio equivalent, and 3 : 2 is in the wrong order.', 'checked', '{"lint":[],"solve":{"answer":"$2 : 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12:18, divide both by 6: 2:3. 6:12 = 1:2 (no); 3:2 is reversed; 13:19 adds 1 (not equivalent).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3559f47-eba5-4764-a1e5-fed38bbe63ad', 'NC26.6.RPR.1', 3, 'choice', 'The two unit ratios in words', 'A school trip has 24 students and 8 teachers. Which statement is true?', '["There are 3 teachers for every 1 student.","There are 3 students for every 1 teacher.","There are 16 students for every 1 teacher.","There are 8 students for every 1 teacher."]', 'There are 3 students for every 1 teacher.', NULL, 'Divide: $24 \div 8 = 3$, so there are 3 students for every 1 teacher. (Equivalently, there is $\frac{1}{3}$ of a teacher for every student.) Subtracting 24 - 8 = 16 or using the number of teachers, 8, does not give a unit ratio.', 'checked', '{"lint":[],"solve":{"answer":"There are 3 students for every 1 teacher.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 students / 8 teachers = 3 students per teacher. Others: 16 per teacher (wrong), 3 teachers per student (reversed), 8 per teacher (wrong).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7da3662d-c042-434f-b85e-398bb6f6eab9', 'NC26.6.RPR.1', 3, 'numeric', 'Unit ratio that is a fraction', 'Mia reads 6 pages in 15 minutes at a steady pace. How many pages does she read in 1 minute?', '[]', '2/5', '6/15', 'Divide the pages by the minutes: $6 \div 15 = \frac{6}{15} = \frac{2}{5}$. She reads $\frac{2}{5}$ of a page in 1 minute.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 pages / 15 minutes = 6/15 = 2/5 = 0.4 pages per minute.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bdd8a60-8b38-4023-9ba1-2666802f7bf1', 'NC26.6.RPR.1', 3, 'choice', 'Ratio language with three quantities', 'A garden has 6 roses, 4 tulips and 10 daisies. Which statement is true?', '["The ratio of roses to tulips is 4 to 6.","The ratio of roses to all of the flowers is 6 to 14.","The ratio of daisies to roses is 6 to 10.","The ratio of tulips to all of the flowers is 4 to 20."]', 'The ratio of tulips to all of the flowers is 4 to 20.', NULL, 'There are $6 + 4 + 10 = 20$ flowers in all, so tulips to all flowers is 4 to 20. The other statements are false: roses to tulips is 6 to 4, daisies to roses is 10 to 6, and roses to all flowers is 6 to 20.', 'checked', '{"lint":[],"solve":{"answer":"The ratio of tulips to all of the flowers is 4 to 20.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 6 + 4 + 10 = 20. Roses:tulips = 6:4 (option says 4:6, false). Tulips:all = 4:20 (true). Daisies:roses = 10:6 (option says 6:10, false). Roses:all = 6:20 (option says 6:14, false).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7d860cc-b932-47fe-ab36-27b79c76c3b7', 'NC26.6.RPR.2', 1, 'numeric', 'Ratio table (scaling)', 'A recipe uses 2 cups of rice for every 3 cups of water. How many cups of water are needed for 10 cups of rice?', '[]', '15', '10/2*3', '10 cups of rice is $10 \div 2 = 5$ times as much as 2 cups, so multiply the water by 5: $3 \times 5 = 15$ cups.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rice:water = 2:3. 10 cups rice = 5 x 2, so water = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad96a58b-0e64-43fb-b621-2d019f736efd', 'NC26.6.RPR.2', 1, 'numeric', 'Percent of a quantity', 'What is 25% of 80?', '[]', '20', '25/100*80', '25% means 25 per 100, or $\frac{25}{100} = \frac{1}{4}$. One fourth of 80 is $80 \div 4 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% of 80 = 80 / 4 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7a2334c-ff9d-4b27-bbe3-bb89fd274ee9', 'NC26.6.RPR.2', 1, 'numeric', 'Finding a percent', 'Sam answered 9 out of 10 questions correctly on a quiz. What percent of the questions did Sam answer correctly?', '[]', '90', '9/10*100', '9 out of 10 is the same rate as 90 out of 100, so Sam answered 90% of the questions correctly.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 = 90/100 = 90%.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93a4467b-500a-4173-9959-0000def34cc2', 'NC26.6.RPR.2', 2, 'numeric', 'Unit conversion', 'How many inches are in 4 yards? There are 3 feet in 1 yard and 12 inches in 1 foot.', '[]', '144', '4*3*12', '4 yards is $4 \times 3 = 12$ feet. 12 feet is $12 \times 12 = 144$ inches.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 yards = 4 x 3 = 12 feet = 12 x 12 = 144 inches.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf761273-2e4a-4fa3-920b-197f9474a91e', 'NC26.6.RPR.2', 2, 'choice', 'Finding a part (percent of a price)', 'A jacket costs 40 dollars. It is on sale for 15% off. How many dollars does the sale take off the price?', '["6","25","15","34"]', '6', '15/100*40', '15% of 40 is $\frac{15}{100} \times 40 = 6$. So the sale takes off 6 dollars. (The sale price would be 40 - 6 = 34 dollars, but the question asks for the amount taken off.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15% of 40 = 0.15 x 40 = 6 dollars off (sale price would be 34).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1633c6ed-129d-471c-bba9-64ad7801c162', 'NC26.6.RPR.2', 2, 'choice', 'Independent and dependent variables', 'A plant is 5 centimeters tall and grows 2 centimeters each day. The equation $h = 5 + 2d$ gives its height $h$, in centimeters, after $d$ days. Which statement is correct?', '["The height $h$ is the independent variable, because it is the larger number.","The number of days $d$ is the dependent variable, because it changes each day.","The height $h$ is the dependent variable, because it depends on the number of days.","Both $h$ and $d$ are independent variables, because both can be any number."]', 'The height $h$ is the dependent variable, because it depends on the number of days.', NULL, 'The height is found from the number of days, so the height $h$ depends on $d$. That makes $h$ the dependent variable and $d$ the independent variable.', 'checked', '{"lint":[],"solve":{"answer":"The height $h$ is the dependent variable, because it depends on the number of days.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 5 + 2d: d (days) is chosen/independent; h depends on d, so h is the dependent variable. Other options give wrong roles or wrong reasons.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4822fa5-8306-4d7d-9074-14dc310da33c', 'NC26.6.RPR.2', 3, 'numeric', 'Finding the whole from a part and a percent', 'Jordan has read 36 pages, which is 40% of a book. How many pages are in the whole book?', '[]', '90', '36/(40/100)', '40% of the book is 36 pages, so 10% is $36 \div 4 = 9$ pages. The whole book is 100%, which is $9 \times 10 = 90$ pages.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 40% of total. 10% = 9, so 100% = 90 pages. Check 0.4 x 90 = 36.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
