INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6b4c339-459b-4afd-b7db-42cd27cb26b7', 'NC26.6.RPR.2', 3, 'numeric', 'Rate and unit conversion', 'A cyclist rides at a steady speed of 12 miles per hour. How many miles does the cyclist ride in 45 minutes?', '[]', '9', '12*45/60', '45 minutes is $\frac{45}{60} = \frac{3}{4}$ of an hour. Then $\frac{3}{4} \times 12 = 9$ miles.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 minutes = 3/4 hour. 12 x 3/4 = 9 miles.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4af5c47-f25b-48e3-ace4-1bbc80891131', 'NC26.6.RPR.2', 3, 'numeric', 'Ratio problem with a total', 'Grape juice and apple juice are mixed in the ratio 3 to 5. A pitcher holds 40 cups of the mix. How many cups of the mix are grape juice?', '[]', '15', '40*3/8', 'Each batch of the mix has $3 + 5 = 8$ parts, and 3 of the 8 parts are grape. $40 \div 8 = 5$ cups per part, so grape juice is $3 \times 5 = 15$ cups.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 3:5, 8 parts total. 40 / 8 = 5 cups per part. Grape = 3 x 5 = 15 cups.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5a43c38-fcbb-4bdf-9dc9-0f991545931e', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 12 and 18?', '[]', '6', NULL, 'Factors of 12: 1, 2, 3, 4, 6, 12. Factors of 18: 1, 2, 3, 6, 9, 18. The greatest factor in both lists is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2^2 x 3, 18 = 2 x 3^2. GCF = 2 x 3 = 6.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5d3a8d3-3aec-46ed-aaf5-76f9e6565e31', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple', 'What is the least common multiple of 4 and 6?', '[]', '12', NULL, 'Multiples of 4: 4, 8, 12, 16, ... Multiples of 6: 6, 12, 18, ... The smallest number in both lists is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4: 4, 8, 12; of 6: 6, 12. LCM = 12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2ada9f7-58b0-4dd2-bf38-a7eca420c162', 'NC26.6.ANR.1', 1, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 20 written with an exponent?', '["$2 \\times 10$","$4 \\times 5$","$2^2 \\times 5$","$2 \\times 5^2$"]', '$2^2 \times 5$', NULL, '$20 = 2 \times 2 \times 5 = 2^2 \times 5$. The options $2 \times 10$ and $4 \times 5$ use numbers that are not prime, and $2 \times 5^2$ equals 50.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 = 2 x 2 x 5 = 2^2 x 5. 4 x 5 and 2 x 10 are not prime factorizations; 2 x 5^2 = 50.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e79c317-511c-4242-927d-3d996f8b1792', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor', 'What is the greatest common factor of 36 and 48?', '[]', '12', NULL, '$36 = 2^2 \times 3^2$ and $48 = 2^4 \times 3$. Both contain $2^2$ and $3$, so the greatest common factor is $2^2 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 2^2 x 3^2, 48 = 2^4 x 3. GCF = 2^2 x 3 = 12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53a6d10d-53e2-49d2-a282-44485c0a4e31', 'NC26.6.ANR.1', 2, 'numeric', 'Least common multiple in context', 'A bus leaves a stop every 12 minutes and a tram leaves every 15 minutes. Both leave at 8:00 a.m. How many minutes later will they next leave at the same time?', '[]', '60', NULL, 'The answer is the least common multiple of 12 and 15. Multiples of 15: 15, 30, 45, 60. Of these, 60 is the first that is also a multiple of 12 ($12 \times 5 = 60$). So they next leave together 60 minutes later.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(12, 15): 12 = 2^2 x 3, 15 = 3 x 5, LCM = 60 minutes.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfe2618e-78a1-4571-af34-a1610e53d1a0', 'NC26.6.ANR.1', 2, 'choice', 'Factoring a sum with the distributive property', 'Which expression shows $24 + 36$ rewritten as the greatest common factor times a sum?', '["$12(2 + 3)$","$12(24 + 36)$","$6(4 + 5)$","$12(2 + 36)$"]', '$12(2 + 3)$', NULL, 'The greatest common factor of 24 and 36 is 12. Divide each number by 12: $24 \div 12 = 2$ and $36 \div 12 = 3$. So $24 + 36 = 12(2 + 3)$. Check: $12 \times 5 = 60$ and $24 + 36 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"$12(2 + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(24, 36) = 12. 24 + 36 = 12(2 + 3) = 60. 6(4 + 5) also equals 60 but 6 is not the GCF; others do not equal 60.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8dfdf1b-26eb-47cc-bd98-4603393538b5', 'NC26.6.ANR.1', 3, 'numeric', 'Greatest common factor in a problem', 'Ms. Cruz has 84 pencils and 126 erasers. She makes identical supply packs that use all of the pencils and all of the erasers. What is the greatest number of packs she can make?', '[]', '42', NULL, 'The number of packs must divide both 84 and 126, so it is their greatest common factor. $84 = 2^2 \times 3 \times 7$ and $126 = 2 \times 3^2 \times 7$. The shared factors are $2 \times 3 \times 7 = 42$, so she can make 42 packs.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = 2^2 x 3 x 7, 126 = 2 x 3^2 x 7. GCF = 2 x 3 x 7 = 42 packs (2 pencils and 3 erasers each).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eb07db1-d298-4654-b868-4cd474b7030c', 'NC26.6.ANR.1', 3, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 72 written with exponents?', '["$2^3 \\times 3$","$2^3 \\times 3^2$","$2^2 \\times 3^3$","$2^3 \\times 9$"]', '$2^3 \times 3^2$', NULL, '$72 = 8 \times 9 = 2^3 \times 3^2$. The option $2^3 \times 3$ equals 24, $2^2 \times 3^3$ equals 108, and $2^3 \times 9$ uses 9, which is not prime.', 'checked', '{"lint":[],"solve":{"answer":"$2^3 \\times 3^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 8 x 9 = 2^3 x 3^2. 2^3 x 9 is not fully prime; 2^3 x 3 = 24; 2^2 x 3^3 = 108.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e780a90-2960-4929-a8e4-57b34c413eba', 'NC26.6.ANR.1', 3, 'numeric', 'Value of a number written in exponent form', 'A number''s prime factorization is $2^3 \times 3 \times 5^2$. What is the number?', '[]', '600', '2^3*3*5^2', '$2^3 = 8$ and $5^2 = 25$, so the number is $8 \times 3 \times 25 = 600$.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 3 x 5^2 = 8 x 3 x 25 = 600.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f363c4bd-e2c5-4926-8326-4e1024793717', 'NC26.6.ANR.2', 1, 'numeric', 'Adding fractions with unlike denominators', 'What is $\frac{2}{3} + \frac{1}{6}$?', '[]', '5/6', '2/3+1/6', 'Write $\frac{2}{3}$ as $\frac{4}{6}$. Then $\frac{4}{6} + \frac{1}{6} = \frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6. 4/6 + 1/6 = 5/6.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35b70e73-577b-4b59-aa0e-74acc5204ded', 'NC26.6.ANR.2', 1, 'numeric', 'Multiplying fractions', 'What is $\frac{3}{4} \times \frac{2}{5}$?', '[]', '3/10', '3/4*2/5', 'Multiply the numerators and the denominators: $\frac{3 \times 2}{4 \times 5} = \frac{6}{20} = \frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 x 2)/(4 x 5) = 6/20 = 3/10.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de2f280c-1ac6-4475-9f9c-614c19215b92', 'NC26.6.ANR.2', 1, 'choice', 'Checking reasonableness by estimating', 'Rounding each mixed number to the nearest whole number, which is the best estimate of $4\frac{7}{8} + 2\frac{1}{9}$?', '["6","8","12","7"]', '7', '5+2', '$4\frac{7}{8}$ is close to 5 and $2\frac{1}{9}$ is close to 2, so the sum is about $5 + 2 = 7$. Dropping the fractions gives 6, which is too low, and 8 and 12 are too high.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 7/8 rounds to 5; 2 1/9 rounds to 2. 5 + 2 = 7 (exact sum about 6.99).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cf65fef-80f1-4b1b-9ad9-93964ae06119', 'NC26.6.ANR.2', 2, 'numeric', 'Subtracting mixed numbers', 'What is $5\frac{1}{3} - 2\frac{3}{4}$? Give the answer as a mixed number.', '[]', '2 7/12', '16/3-11/4', 'Use twelfths: $5\frac{1}{3} = 5\frac{4}{12} = 4\frac{16}{12}$ and $2\frac{3}{4} = 2\frac{9}{12}$. Then $4\frac{16}{12} - 2\frac{9}{12} = 2\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"2 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/3 = 64/12, 2 3/4 = 33/12. 64/12 - 33/12 = 31/12 = 2 7/12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1deb20a-21b4-4c70-a185-ffa0467aceb5', 'NC26.6.ANR.2', 2, 'numeric', 'Dividing a fraction by a fraction (how many fit)', 'How many $\frac{1}{8}$-cup scoops fit exactly into $\frac{3}{4}$ cup of flour?', '[]', '6', '(3/4)/(1/8)', '$\frac{3}{4} = \frac{6}{8}$, which is 6 eighths. So 6 scoops of $\frac{1}{8}$ cup fill $\frac{3}{4}$ cup. In symbols, $\frac{3}{4} \div \frac{1}{8} = \frac{3}{4} \times 8 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 / 1/8 = 3/4 x 8 = 6 scoops.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38ec236a-eea4-48d4-8fc9-15cfbb61f7e9', 'NC26.6.ANR.2', 2, 'choice', 'Interpreting a quotient', 'Which question can be answered by finding $4 \div \frac{1}{3}$?', '["What is one third of 4 cups of juice?","How much juice does each of 3 people get if they share 4 cups equally?","How many 4-cup jugs can be filled from one third of a cup of juice?","How many one-third-cup servings are in 4 cups of juice?"]', 'How many one-third-cup servings are in 4 cups of juice?', NULL, '$4 \div \frac{1}{3}$ asks how many groups of $\frac{1}{3}$ fit into 4, so the answer is 12 servings. One third of 4 is multiplication, the jug question is $\frac{1}{3} \div 4$, and sharing 4 cups among 3 people is $4 \div 3$.', 'checked', '{"lint":[],"solve":{"answer":"How many one-third-cup servings are in 4 cups of juice?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (1/3) asks how many groups of 1/3 are in 4: servings of one-third cup in 4 cups (= 12). One third of 4 is 4 x 1/3; sharing among 3 is 4 / 3; the jug option is (1/3) / 4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d0af842-284b-419f-b238-8c1081de657a', 'NC26.6.ANR.2', 3, 'numeric', 'Multiplying mixed numbers in context', 'A recipe needs $2\frac{1}{2}$ cups of flour. Maya makes $1\frac{3}{5}$ times the recipe. How many cups of flour does she need?', '[]', '4', '5/2*8/5', 'Write the mixed numbers as fractions: $2\frac{1}{2} = \frac{5}{2}$ and $1\frac{3}{5} = \frac{8}{5}$. Then $\frac{5}{2} \times \frac{8}{5} = \frac{40}{10} = 4$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 1/2 x 1 3/5 = 5/2 x 8/5 = 40/10 = 4 cups.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e846fd63-a613-4967-89ff-c9460a683337', 'NC26.6.ANR.2', 3, 'numeric', 'Interpreting a quotient greater than 1', 'A baker has $\frac{5}{6}$ kilogram of dough. Each loaf uses $\frac{2}{3}$ kilogram. How many loaves can the baker make, counting part of a loaf? Give the answer as a mixed number.', '[]', '1 1/4', '(5/6)/(2/3)', 'Divide: $\frac{5}{6} \div \frac{2}{3} = \frac{5}{6} \times \frac{3}{2} = \frac{15}{12} = \frac{5}{4} = 1\frac{1}{4}$ loaves.', 'checked', '{"lint":[],"solve":{"answer":"1 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 / 2/3 = 5/6 x 3/2 = 15/12 = 5/4 = 1 1/4 loaves.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c66b7d85-3ab8-4b98-aab8-c07a4a597aab', 'NC26.6.ANR.2', 3, 'numeric', 'Multi-step word problem with mixed numbers', 'Ben has $7\frac{1}{6}$ yards of fabric. He uses $2\frac{1}{3}$ yards for a curtain and $1\frac{3}{4}$ yards for a pillow. How many yards of fabric are left? Give the answer as a mixed number.', '[]', '3 1/12', '43/6-7/3-7/4', 'He uses $2\frac{1}{3} + 1\frac{3}{4} = 2\frac{4}{12} + 1\frac{9}{12} = 3\frac{13}{12} = 4\frac{1}{12}$ yards. Then $7\frac{1}{6} - 4\frac{1}{12} = 7\frac{2}{12} - 4\frac{1}{12} = 3\frac{1}{12}$ yards are left.', 'checked', '{"lint":[],"solve":{"answer":"3 1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In twelfths: 7 1/6 = 86/12, 2 1/3 = 28/12, 1 3/4 = 21/12. Used 49/12. Left 86/12 - 49/12 = 37/12 = 3 1/12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
