INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b15fdc3c-fcbd-402a-b240-76b80c7c88fd', 'NC26.6.ANR.3', 1, 'choice', 'Estimating a decimal product', 'Which is the best estimate of $6.82 \times 3.1$?', '["18","21","28","210"]', '21', '7*3', 'Round 6.82 to 7 and 3.1 to 3. Then $7 \times 3 = 21$. The estimate 18 comes from rounding 6.82 down to 6, 28 from rounding 3.1 up to 4, and 210 has the decimal point in the wrong place.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.82 is about 7, 3.1 is about 3; 7 x 3 = 21 (exact 21.142).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
