INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c118f8c9-143f-4ec6-963b-99cf07c3c4f7', 'NC26.6.ANR.3', 2, 'numeric', 'Multiplying decimals', 'What is $3.25 \times 1.2$?', '[]', '3.9', '3.25*1.2', 'Multiply as whole numbers: $325 \times 12 = 3900$. The factors have 2 + 1 = 3 decimal places in all, so the product is 3.900 = 3.9.', 'checked', '{"lint":[],"solve":{"answer":"3.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"325 x 12 = 3900; 3 decimal places: 3.900 = 3.9.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
