INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef3245a6-0af2-4ffd-9d50-b7622084dce1', 'NC26.6.ANR.3', 2, 'numeric', 'Decimal word problem (money)', 'A notebook costs 2.45 dollars. Kai buys 4 notebooks and pays with a 20 dollar bill. How many dollars of change should Kai get back?', '[]', '10.2', '20-4*2.45', 'The notebooks cost $4 \times 2.45 = 9.80$ dollars. The change is $20 - 9.80 = 10.20$ dollars, or 10.2.', 'checked', '{"lint":[],"solve":{"answer":"10.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 2.45 = 9.80. 20 - 9.80 = 10.20 dollars.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
