VALUES ('cf3cc8fc-ba34-4e02-81b9-11a0943a4d6a', 'NC26.6.ANR.3', 3, 'numeric', 'Dividing by a decimal in a word problem', 'A runner jogs 5.75 kilometers each day. How many days will it take the runner to jog a total of 46 kilometers?', '[]', '8', '46/5.75', 'Divide the total by the distance each day: $46 \div 5.75$. Multiply both numbers by 100 to get $4600 \div 575 = 8$. Check: $5.75 \times 8 = 46$. It takes 8 days.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"46 / 5.75 = 4600 / 575 = 8 days. Check 5.75 x 8 = 46.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
