VALUES ('91db5992-3e27-425b-97dc-bca6a8e23906', 'NC26.6.ANR.4', 1, 'numeric', 'Adding integers', 'What is $-7 + 12$?', '[]', '5', '-7+12', 'Seven of the 12 positive units cancel the 7 negative units (zero pairs). That leaves $12 - 7 = 5$ positive units.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7 + 12 = 5.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
