VALUES ('b743bf1b-c5a1-4cc2-8cd4-3fff4adf8762', 'NC26.6.ANR.4', 1, 'choice', 'Zero pairs', 'A collection has 5 positive chips and 8 negative chips. Each positive chip and negative chip together make a zero pair. What is the value of the whole collection?', '["-3","-13","3","13"]', '-3', '5-8', 'Five zero pairs cancel, using all 5 positive chips and 5 of the negative chips. That leaves 3 negative chips, so the value is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 zero pairs cancel; 3 negative chips remain: 5 + (-8) = -3.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
