INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d31eed18-ed14-4d64-bb04-259393d74bee', 'NC26.6.ANR.4', 2, 'choice', 'Subtraction as adding the opposite', 'Which expression has the same value as $7 - (-5)$?', '["$-7 + 5$","$7 - 5$","$7 + 5$","$-7 - 5$"]', '$7 + 5$', NULL, 'Subtracting $-5$ is the same as adding its opposite, 5. So $7 - (-5) = 7 + 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$7 + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtracting -5 is adding its opposite: 7 - (-5) = 7 + 5 = 12. Others: -2, 2, -12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
