VALUES ('001163e6-b4fc-46c7-b440-7d6e19442048', 'NC26.6.ANR.4', 3, 'numeric', 'Multi-step integer problem in context', 'A diver is at $-14$ meters, which is 14 meters below the surface. She swims up 6 meters and then down 11 meters. What is her position now, in meters?', '[]', '-19', '-14+6-11', 'Swimming up adds 6 and swimming down subtracts 11: $-14 + 6 - 11 = -8 - 11 = -19$ meters.', 'checked', '{"lint":[],"solve":{"answer":"-19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-14 + 6 = -8; -8 - 11 = -19 meters.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
