INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e842d582-c7f2-447e-a3a3-e12eb0c70fe2', 'NC26.6.ANR.4', 3, 'numeric', 'Reasoning with integer products and sums', 'Two integers have a product of $-20$ and a sum of $1$. What is the lesser of the two integers?', '[]', '-4', NULL, 'The product is negative, so one integer is positive and one is negative. The factor pairs of 20 are 1 and 20, 2 and 10, 4 and 5. Only 5 and $-4$ have a sum of 1 ($5 + (-4) = 1$), and $5 \times (-4) = -20$. The lesser integer is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor pairs of -20 with sum 1: 5 and -4 (5 x -4 = -20, 5 + -4 = 1). Others: 4,-5 sum -1; 10,-2 sum 8; 2,-10; 20,-1; 1,-20 - none sum 1. Lesser = -4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3035020b-9c53-4fb7-8fba-9217670d301a', 'NC26.6.ANR.5', 1, 'choice', 'Comparing negative integers', 'Which statement about integers is true?', '["$-5 < -2$","$-5 > -2$","$-2 < -5$","$5 < -2$"]', '$-5 < -2$', NULL, 'On a number line, $-5$ is farther left than $-2$, so $-5 < -2$ is true. Of two negative numbers, the one closer to zero is greater.', 'checked', '{"lint":[],"solve":{"answer":"$-5 < -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 is left of -2 on the number line, so -5 < -2. 5 < -2 false; -2 < -5 false; -5 > -2 false.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
