VALUES ('58ccd157-dfcf-416a-ace3-bcfd0a9b965c', 'NC26.6.ANR.5', 2, 'choice', 'Comparing fractions and decimals', 'Which of these numbers is the greatest?', '["$\\frac{3}{5}$","$0.58$","$0.059$","$\\frac{5}{8}$"]', '$\frac{5}{8}$', NULL, 'Write each as a decimal: $\frac{3}{5} = 0.6$, $0.58$, $0.059$, and $\frac{5}{8} = 0.625$. The greatest is $0.625 = \frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 0.6, 0.059, 0.58, 5/8 = 0.625. Greatest is 5/8.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
