VALUES ('47e83d0a-8f49-4108-b1dc-7c38d8821cac', 'NC26.6.ANR.5', 2, 'choice', 'Ordering fractions and decimals', 'Which list shows the numbers in order from least to greatest?', '["$0.35, \\frac{1}{3}, \\frac{3}{8}, 0.4$","$\\frac{1}{3}, 0.35, \\frac{3}{8}, 0.4$","$\\frac{1}{3}, \\frac{3}{8}, 0.35, 0.4$","$0.4, \\frac{3}{8}, 0.35, \\frac{1}{3}$"]', '$\frac{1}{3}, 0.35, \frac{3}{8}, 0.4$', NULL, 'As decimals: $\frac{1}{3} \approx 0.333$, $0.35$, $\frac{3}{8} = 0.375$, and $0.4$. In order from least to greatest: $\frac{1}{3}, 0.35, \frac{3}{8}, 0.4$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}, 0.35, \\frac{3}{8}, 0.4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 0.333..., 0.35, 3/8 = 0.375, 0.4. Order: 1/3, 0.35, 3/8, 0.4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
