VALUES ('47e09e09-dae2-4c47-8eb5-cc32041d78dc', 'NC26.6.ANR.5', 3, 'choice', 'Comparing a mixed number and a decimal', 'Which comparison is true?', '["$2\\frac{3}{8} > 2.4$","$2\\frac{3}{8} < 2.4$","$2\\frac{3}{8} < 2.04$","$2\\frac{3}{8} = 2.4$"]', '$2\frac{3}{8} < 2.4$', NULL, '$2\frac{3}{8} = 2.375$. Since $2.375 < 2.4$, the statement $2\frac{3}{8} < 2.4$ is true. The other three statements are false, since 2.375 is not greater than 2.4, not equal to 2.4, and not less than 2.04.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{3}{8} < 2.4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 3/8 = 2.375 < 2.4. So < is true; > and = false; 2.375 < 2.04 false.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
