INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a10811a6-3d97-401f-a2be-1d02a0bee63c', 'NC26.6.ANR.6', 2, 'choice', 'Translating words to an expression', 'Which expression means "7 less than twice a number $n$"?', '["$7 - 2n$","$2n + 7$","$2n - 7$","$2(n - 7)$"]', '$2n - 7$', NULL, '"Twice a number $n$" is $2n$. "7 less than" that is $2n - 7$. The option $7 - 2n$ reverses the order, and $2(n - 7)$ doubles the 7 less than $n$.', 'checked', '{"lint":[],"solve":{"answer":"$2n - 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice n is 2n; 7 less than that is 2n - 7.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0d392e-6227-4bd8-8a5e-5376815e7cb5', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions (distributive property)', 'Which expression is equivalent to $2(3x + 5)$?', '["$6x + 5$","$5x + 7$","$6x + 10$","$6x + 7$"]', '$6x + 10$', NULL, 'Multiply both terms inside the parentheses by 2: $2 \times 3x = 6x$ and $2 \times 5 = 10$. So $2(3x + 5) = 6x + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distribute: 2 x 3x + 2 x 5 = 6x + 10.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bf48979-9d94-47c3-95e0-9946765f5b38', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations with exponents and parentheses', 'What is the value of $(9 - 3)^2 \div 4 + 2 \times 5$?', '[]', '19', '(9-3)^2/4+2*5', 'Parentheses first: $9 - 3 = 6$. Exponent: $6^2 = 36$. Then divide and multiply: $36 \div 4 = 9$ and $2 \times 5 = 10$. Finally add: $9 + 10 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9 - 3)^2 = 6^2 = 36. 36 / 4 = 9. 2 x 5 = 10. 9 + 10 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29509d45-72ad-48a8-8b23-045b7d1dd234', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating with two variables and an exponent', 'What is the value of $2a^2 - b$ when $a = 5$ and $b = 7$?', '[]', '43', '2*5^2-7', 'Substitute: $2 \times 5^2 - 7$. The exponent comes first: $5^2 = 25$. Then $2 \times 25 = 50$ and $50 - 7 = 43$.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5^2) - 7 = 2(25) - 7 = 50 - 7 = 43.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49bc9df5-2d5a-4450-8d16-31c3275731bd', 'NC26.6.ANR.6', 3, 'choice', 'Equivalent expressions (combining like terms)', 'Which expression is equivalent to $x + x + x + 4$?', '["$3x + 4$","$4x + 3$","$x^3 + 4$","$7x$"]', '$3x + 4$', NULL, 'Three $x$''s added together make $3x$, and the 4 stays separate, so the expression is $3x + 4$. Repeated addition is not an exponent ($x^3$ means $x \times x \times x$), and $3x$ and 4 are not like terms, so they cannot be combined.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + x = 3x, so 3x + 4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4654474-f5c9-4971-b4bc-adf62dd5366a', 'NC26.6.ANR.7', 1, 'numeric', 'Solving a one-step addition equation', 'Solve $x + 8 = 15$.', '[]', '7', '15-8', 'Subtract 8 from both sides: $x = 15 - 8 = 7$. Check: $7 + 8 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 15 - 8 = 7.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d2e359d-fc41-4bad-a8a4-016456b25e03', 'NC26.6.ANR.7', 1, 'numeric', 'Solving a one-step multiplication equation', 'Solve $6n = 48$.', '[]', '8', '48/6', 'Divide both sides by 6: $n = 48 \div 6 = 8$. Check: $6 \times 8 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 48 / 6 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
