INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1f566f9-1c97-488d-a293-125311703860', 'NC26.6.ANR.7', 1, 'choice', 'Checking a solution by substitution', 'Which value of $x$ makes the equation $x - 4 = 9$ true?', '["5","13","9","36"]', '13', '9+4', 'Try 13: $13 - 4 = 9$, which is true. The value 5 gives $5 - 4 = 1$, 9 gives $9 - 4 = 5$, and 36 gives $36 - 4 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 9 + 4 = 13. Check 13 - 4 = 9.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
