INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39237fed-8d50-4f92-b51c-37008359d88a', 'NC26.6.ANR.7', 2, 'numeric', 'Solving a one-step division equation', 'Solve $\frac{x}{5} = 12$.', '[]', '60', '12*5', 'Multiply both sides by 5: $x = 12 \times 5 = 60$. Check: $60 \div 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 12 x 5 = 60.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
