INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef0f627f-cfbc-4cca-8e24-71ad86aae1e5', 'NC26.6.ANR.7', 2, 'numeric', 'Writing and solving an equation from a story', 'Sam spent 56 dollars on movie tickets that cost 7 dollars each. How many tickets did Sam buy?', '[]', '8', '56/7', 'If $t$ is the number of tickets, then $7t = 56$. Divide both sides by 7: $t = 8$. Check: $7 \times 8 = 56$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7t = 56, t = 8 tickets.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
