INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93029d8c-9ba1-4dfe-9ce0-71cb0ac29430', 'NC26.6.ANR.7', 2, 'choice', 'Solutions of an inequality', 'Which number is a solution of the inequality $x > 7$?', '["6","5","7","8"]', '8', '8', 'A solution must be greater than 7. Only 8 is greater than 7. The number 7 is not a solution because 7 is not greater than 7.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 8 is greater than 7 (7 itself is not, since the inequality is strict).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
