INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6331ba7d-0335-437e-89e6-4a7ef0ae930a', 'NC26.6.ANR.7', 3, 'numeric', 'Solving an equation with fractions', 'Solve $x + \frac{3}{4} = 2\frac{1}{2}$. Give the answer as a mixed number.', '[]', '1 3/4', '5/2-3/4', 'Subtract $\frac{3}{4}$ from both sides: $x = 2\frac{1}{2} - \frac{3}{4} = \frac{10}{4} - \frac{3}{4} = \frac{7}{4} = 1\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1 3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 2 1/2 - 3/4 = 10/4 - 3/4 = 7/4 = 1 3/4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50c48f85-f276-4beb-89f1-c731b01d9a9b', 'NC26.6.ANR.7', 3, 'choice', 'Reading an inequality from a number-line description', 'An inequality is graphed on a number line. The graph has an open circle at 5 and an arrow pointing to the right, toward the larger numbers. Which inequality does the graph show?', '["$x < 5$","$x = 5$","$x > -5$","$x > 5$"]', '$x > 5$', NULL, 'The arrow points toward numbers greater than 5, and the open circle means 5 itself is not included. That is $x > 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x > 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Open circle at 5 excludes 5; arrow right means greater: x > 5.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3178367-dde8-48fb-b96b-3f0048f6a587', 'NC26.6.ANR.7', 3, 'numeric', 'Writing and solving an equation (decimals)', 'Four friends split the cost of a gift equally. Each friend pays 7.25 dollars. What was the cost of the gift, in dollars?', '[]', '29', '7.25*4', 'If the gift costs $c$ dollars, then $\frac{c}{4} = 7.25$. Multiply both sides by 4: $c = 7.25 \times 4 = 29$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c / 4 = 7.25, so c = 4 x 7.25 = 29 dollars.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b8ecd6-0f95-43c8-abbf-d490b4088865', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a triangle from its base and height', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area in square centimeters?', '[]', '30', '1/2*10*6', 'The area of a triangle is half of the base times the height: $\frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x base x height = 1/2 x 10 x 6 = 30.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9ebfd11-a01b-4608-85e8-12be84927990', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a parallelogram from its base and height', 'A parallelogram has a base of 9 meters and a height of 4 meters. What is its area in square meters?', '["$18$","$36$","$26$","$13$"]', '$36$', '9*4', 'The area of a parallelogram is base times height: $9 \times 4 = 36$ square meters. (18 halves the product as if it were a triangle, 26 is $2 \times (9 + 4)$, and 13 adds the two numbers.)', 'checked', '{"lint":[],"solve":{"answer":"$36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area of parallelogram = base x height = 9 x 4 = 36.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31b94543-89cd-40c0-b6e6-8c67cdc3745b', 'NC26.6.SGMR.1', 1, 'numeric', 'Decomposing a rectangle into two triangles', 'A rectangular piece of paper is 14 inches long and 6 inches wide. Fran cuts it along a diagonal into two identical triangles. What is the area of one triangle in square inches?', '[]', '42', '14*6/2', 'The rectangle has area $14 \times 6 = 84$ square inches. The two triangles are identical, so each has half of that: $84 \div 2 = 42$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle area = 14 x 6 = 84. A diagonal cuts it into two identical triangles, each 84 / 2 = 42.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8524823d-2407-4a70-8931-07b0169fc153', 'NC26.6.SGMR.1', 2, 'numeric', 'Finding a triangle''s height from its area and base', 'A triangle has an area of 40 square centimeters and a base of 10 centimeters. What is its height in centimeters?', '[]', '8', '2*40/10', 'Area $= \frac{1}{2} \times \text{base} \times \text{height}$, so $40 = \frac{1}{2} \times 10 \times h = 5h$. Then $h = 40 \div 5 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 = 1/2 x 10 x h = 5h, so h = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('525030dc-570f-4012-abbc-e0f46232152b', 'NC26.6.SGMR.1', 2, 'choice', 'Parallelogram area uses the height, not the slanted side', 'A parallelogram has a base of 10 centimeters. Its slanted side is 6 centimeters long, and its height (measured at a right angle to the base) is 5 centimeters. What is its area in square centimeters?', '["$60$","$25$","$50$","$16$"]', '$50$', '10*5', 'Area is base times height: $10 \times 5 = 50$ square centimeters. The slanted side is not the height, so $10 \times 6 = 60$ is wrong. (25 halves the product as if it were a triangle, and 16 adds $10 + 6$.)', 'checked', '{"lint":[],"solve":{"answer":"$50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = base x perpendicular height = 10 x 5 = 50. The slanted side (6) is not used.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('874e264c-f4af-452c-88bc-caedfa61f8b9', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a composite figure made of two rectangles', 'An L-shaped patio is made from two rectangles that do not overlap. One rectangle is 8 meters by 5 meters. The other is 4 meters by 3 meters. What is the total area of the patio in square meters?', '["$52$","$28$","$20$","$12$"]', '$52$', '8*5+4*3', 'Add the areas of the two rectangles: $8 \times 5 = 40$ and $4 \times 3 = 12$, so the total is $40 + 12 = 52$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"$52$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 5 = 40 and 4 x 3 = 12; total 40 + 12 = 52.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be5de139-fcd9-4ef5-ab49-780ece2dde9e', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a trapezoid by decomposing it into a rectangle and triangles', 'Maya cuts a trapezoid into a rectangle and two right triangles. The trapezoid has parallel sides of 6 centimeters and 10 centimeters and a height of 4 centimeters. The rectangle is 6 centimeters by 4 centimeters. Each right triangle has a base of 2 centimeters and a height of 4 centimeters. What is the area of the trapezoid in square centimeters?', '[]', '32', '6*4+2*(1/2*2*4)', 'Rectangle: $6 \times 4 = 24$. Each triangle: $\frac{1}{2} \times 2 \times 4 = 4$, so the two triangles are $8$. Total: $24 + 8 = 32$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 4 = 24. Each triangle 1/2 x 2 x 4 = 4, two of them = 8. Total 32. Check: 6 + 2 + 2 = 10 matches the long side; formula (6 + 10)/2 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57ce856b-a27e-475c-a34d-b085e50483c2', 'NC26.6.SGMR.1', 3, 'choice', 'How changing a triangle''s height changes its area', 'The area of a triangle is 36 square inches. A second triangle has the same base but twice the height. What is the area of the second triangle in square inches?', '["$36$","$144$","$18$","$72$"]', '$72$', '36*2', 'Area is $\frac{1}{2} \times \text{base} \times \text{height}$. With the same base and double the height, the area doubles: $36 \times 2 = 72$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"$72$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 b h. Same base, twice the height doubles the area: 2 x 36 = 72.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05732ff8-b231-4abd-8358-76b9dd5b9e79', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a polygon made of a rectangle and a triangle', 'A lot is shaped like a rectangle with a triangle attached along one of its 10-meter sides. The rectangle is 10 meters by 6 meters. The triangle has a base of 10 meters and a height of 4 meters. What is the total area of the lot in square meters?', '[]', '80', '10*6+1/2*10*4', 'Rectangle: $10 \times 6 = 60$. Triangle: $\frac{1}{2} \times 10 \times 4 = 20$. Total: $60 + 20 = 80$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60. Triangle 1/2 x 10 x 4 = 20. Total 80.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79fd2371-fc6c-43b2-8f3a-2f1457a443ad', 'NC26.6.SGMR.2', 1, 'choice', 'Telling which quadrant a point is in from the signs of its coordinates', 'Which point is in the part of the coordinate plane where both the x-coordinate and the y-coordinate are negative?', '["$(4, -2)$","$(-4, 2)$","$(-4, -2)$","$(4, 2)$"]', '$(-4, -2)$', NULL, 'Both coordinates must be negative. Only $(-4, -2)$ has a negative x-coordinate and a negative y-coordinate.', 'checked', '{"lint":[],"solve":{"answer":"$(-4, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both coordinates negative is Quadrant III: (-4, -2).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
