INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcebebc6-f480-42b8-88a8-052c090035ef', 'NC26.6.SGMR.2', 1, 'choice', 'Reflecting a point across the x-axis', 'The point $(3, 5)$ is reflected across the x-axis. What are the coordinates of the new point?', '["$(3, -5)$","$(-3, 5)$","$(-3, -5)$","$(5, 3)$"]', '$(3, -5)$', NULL, 'A reflection across the x-axis keeps the x-coordinate and changes the sign of the y-coordinate, so $(3, 5)$ becomes $(3, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, -5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across the x-axis keeps x and negates y: (3, 5) -> (3, -5).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
