INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('855348a8-4dcf-4555-bbe7-8f3f76627d61', 'NC26.6.SGMR.2', 1, 'numeric', 'Distance between two points with the same x-coordinate', 'Point $A$ is at $(4, 1)$ and point $B$ is at $(4, 8)$. How many units apart are the two points?', '[]', '7', '8-1', 'The points have the same x-coordinate, so they are on one vertical line. The distance is the difference of the y-coordinates: $8 - 1 = 7$ units.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x-coordinate; distance = |8 - 1| = 7.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
