INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bcd5c0e-8945-47c2-9679-02840248c727', 'NC26.6.SGMR.2', 2, 'choice', 'Distance between points on opposite sides of an axis', 'Point $A$ is at $(-7, 2)$ and point $B$ is at $(3, 2)$. How many units apart are the two points?', '["$4$","$21$","$9$","$10$"]', '$10$', '7+3', 'The points have the same y-coordinate, and they are on opposite sides of the y-axis. Add their distances from the axis: $7 + 3 = 10$ units. (Subtracting $7 - 3 = 4$ would be right only if both were on the same side.)', 'checked', '{"lint":[],"solve":{"answer":"$10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y-coordinate; distance = |3 - (-7)| = 10.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
