INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9313c3e9-e50d-41e5-89f4-ddc228c9a4ab', 'NC26.6.SGMR.2', 2, 'numeric', 'Distance between a point and its reflection', 'The point $(-3, 4)$ is reflected across the x-axis. How many units apart are the original point and its reflection?', '[]', '8', '4+4', 'The reflection is $(-3, -4)$. The two points are 4 units above and 4 units below the x-axis, so they are $4 + 4 = 8$ units apart.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection of (-3, 4) across the x-axis is (-3, -4). Distance = |4 - (-4)| = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
