INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfcee2fd-f4c7-4cf5-8c04-d097bb52adfa', 'NC26.6.SGMR.2', 2, 'numeric', 'Perimeter of a rectangle on the coordinate plane', 'A rectangle has vertices at $(1, 2)$, $(7, 2)$, $(7, -3)$ and $(1, -3)$. What is the perimeter of the rectangle in units?', '[]', '22', '2*(6+5)', 'The width is $7 - 1 = 6$ units. The height is $2 - (-3) = 5$ units. The perimeter is $2 \times (6 + 5) = 22$ units.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width from x = 1 to 7 is 6; height from y = -3 to 2 is 5. Perimeter = 2(6 + 5) = 22.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b39bc221-2a1b-49db-bffb-da5c489ab552', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a rectangle from two opposite corners', 'A rectangle has two opposite corners at $(-4, 3)$ and $(2, -1)$, and its sides are parallel to the axes. What is the area of the rectangle in square units?', '[]', '24', '6*4', 'The width is $2 - (-4) = 6$ units and the height is $3 - (-1) = 4$ units. The area is $6 \times 4 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width |2 - (-4)| = 6; height |3 - (-1)| = 4. Area = 24.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e568bbb5-8ff8-4986-9fbf-9f40e174bf81', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a right triangle on the coordinate plane', 'A triangle has vertices at $(-3, -2)$, $(5, -2)$ and $(5, 4)$. What is its area in square units?', '[]', '24', '1/2*8*6', 'The side from $(-3, -2)$ to $(5, -2)$ is horizontal and is $5 - (-3) = 8$ units long. The side from $(5, -2)$ to $(5, 4)$ is vertical and is $4 - (-2) = 6$ units long. They meet at a right angle, so the area is $\frac{1}{2} \times 8 \times 6 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base along y = -2 from x = -3 to 5: 8. Height along x = 5 from y = -2 to 4: 6. Right triangle area = 1/2 x 8 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cee0f6ae-049b-4116-975e-039804bc3bfd', 'NC26.6.SGMR.2', 3, 'choice', 'Finding the fourth vertex of a rectangle', 'Three vertices of a rectangle are $(-3, 4)$, $(5, 4)$ and $(5, -2)$. The sides are parallel to the axes. What is the fourth vertex?', '["$(3, -2)$","$(-3, -2)$","$(-3, 2)$","$(-2, -3)$"]', '$(-3, -2)$', NULL, 'The fourth vertex shares its x-coordinate with $(-3, 4)$, which is $-3$, and its y-coordinate with $(5, -2)$, which is $-2$. So it is $(-3, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-3, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Missing corner takes x from (-3, 4) and y from (5, -2): (-3, -2).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e138ebf-b618-4e73-8efd-b34654aef49c', 'NC26.6.SGMR.3', 1, 'choice', 'Naming the solid a net folds into', 'A net is made of exactly 2 triangles and 3 rectangles joined along their edges. When it is folded up, which solid does it make?', '["A rectangular prism","A triangular pyramid","A triangular prism","A square pyramid"]', 'A triangular prism', NULL, 'A triangular prism has 2 triangular bases and 3 rectangular side faces. A rectangular prism has 6 rectangles, and the pyramids have only one base.', 'checked', '{"lint":[],"solve":{"answer":"A triangular prism","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangular bases plus three rectangular lateral faces fold into a triangular prism (a triangular pyramid has 4 triangles; a square pyramid 1 square + 4 triangles; a rectangular prism 6 rectangles).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30341452-0f82-4ca3-8e4b-ebf1572b9656', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a rectangular prism', 'A box shaped like a rectangular prism is 5 centimeters long, 4 centimeters wide and 3 centimeters tall. What is its volume in cubic centimeters?', '[]', '60', '5*4*3', 'Volume is length times width times height: $5 \times 4 \times 3 = 60$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 5 x 4 x 3 = 60.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ee5e309-85f7-413d-8b49-72d2b9174717', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a cube', 'A cube has edges that are each 3 inches long. What is its surface area in square inches?', '["$27$","$54$","$36$","$18$"]', '$54$', '6*3*3', 'A cube has 6 faces. Each face is a square of area $3 \times 3 = 9$, so the surface area is $6 \times 9 = 54$ square inches. (27 is the volume, 36 counts only four faces, and 18 counts only two.)', 'checked', '{"lint":[],"solve":{"answer":"$54$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each face 3 x 3 = 9; six faces: 54.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8545dd84-38a4-43a9-8ed5-d66724c9f03d', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a rectangular prism', 'A rectangular prism is 6 centimeters long, 4 centimeters wide and 3 centimeters tall. What is its surface area in square centimeters?', '[]', '108', '2*(6*4+6*3+4*3)', 'There are three pairs of matching faces: $6 \times 4 = 24$, $6 \times 3 = 18$ and $4 \times 3 = 12$. Add them and double: $2 \times (24 + 18 + 12) = 108$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SA = 2(6x4 + 6x3 + 4x3) = 2(24 + 18 + 12) = 2 x 54 = 108.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2f1c5c7-4f77-4cb0-b696-cad923ac8891', 'NC26.6.SGMR.3', 2, 'numeric', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism has a length of $2\frac{1}{2}$ feet, a width of $1\frac{1}{2}$ feet and a height of 2 feet. What is its volume in cubic feet?', '[]', '7 1/2', '5/2*3/2*2', 'Multiply the three edges: $\frac{5}{2} \times \frac{3}{2} \times 2 = \frac{30}{4} = 7\frac{1}{2}$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 5/2 x 3/2 x 2 = 30/4 = 15/2 = 7.5.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5139bf6d-f832-4887-838b-545a4068f61b', 'NC26.6.SGMR.3', 2, 'choice', 'Total area of the faces in a net', 'A net for a box has six rectangles: two that are 5 by 3, two that are 5 by 2 and two that are 3 by 2 (all measures in centimeters). What is the total area of the net in square centimeters?', '["$62$","$31$","$30$","$50$"]', '$62$', '2*(5*3+5*2+3*2)', 'Find the area of each kind of rectangle: $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$. There are two of each, so the total is $2 \times (15 + 10 + 6) = 62$ square centimeters. (31 counts each kind once, 30 is the volume, and 50 leaves out one pair of faces.)', 'checked', '{"lint":[],"solve":{"answer":"$62$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5x3) + 2(5x2) + 2(3x2) = 30 + 20 + 12 = 62.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69c8db82-1a0c-48c7-be83-e01e50ed9ef2', 'NC26.6.SGMR.3', 3, 'numeric', 'Surface area of a triangular prism', 'A triangular prism has two identical right-triangle bases with legs of 3 centimeters and 4 centimeters and a longest side of 5 centimeters. The prism is 10 centimeters long. What is its surface area in square centimeters?', '[]', '132', '2*(1/2*3*4)+(3+4+5)*10', 'The two triangular bases have area $2 \times \left(\frac{1}{2} \times 3 \times 4\right) = 12$. The three rectangular faces are $3 \times 10 = 30$, $4 \times 10 = 40$ and $5 \times 10 = 50$, which total $120$. The surface area is $12 + 120 = 132$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangles: 2 x (1/2 x 3 x 4) = 12. Three rectangles: 3x10 + 4x10 + 5x10 = 120. Total 132.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba7aebf3-45d4-4784-927b-021fb4d47dbb', 'NC26.6.SGMR.3', 3, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A box is 2 inches long, $1\frac{1}{2}$ inches wide and 1 inch tall. It is filled exactly with small cubes whose edges are each $\frac{1}{2}$ inch long. How many small cubes fill the box?', '[]', '24', '(2*2)*(3/2*2)*(1*2)', 'Count the cubes along each edge: $2 \div \frac{1}{2} = 4$ along the length, $1\frac{1}{2} \div \frac{1}{2} = 3$ along the width and $1 \div \frac{1}{2} = 2$ along the height. The number of cubes is $4 \times 3 \times 2 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cubes along each edge: 2 / (1/2) = 4, (3/2) / (1/2) = 3, 1 / (1/2) = 2. Count = 4 x 3 x 2 = 24. Check: volume 3 / (1/8) = 24.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c25007fe-5c7e-436b-981d-f0062128fb21', 'NC26.6.SGMR.3', 3, 'choice', 'Surface area of a square pyramid from its faces', 'A square pyramid has a square base with sides of 6 centimeters. Its four triangular faces each have a base of 6 centimeters and a height of 5 centimeters. What is the surface area of the pyramid in square centimeters?', '["$60$","$66$","$96$","$156$"]', '$96$', '6*6+4*(1/2*6*5)', 'The base is $6 \times 6 = 36$. Each triangle is $\frac{1}{2} \times 6 \times 5 = 15$, so the four triangles are $60$. The total is $36 + 60 = 96$ square centimeters. (60 leaves out the base, 66 uses only one triangle, and 156 forgets the one half.)', 'checked', '{"lint":[],"solve":{"answer":"$96$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 6 x 6 = 36. Each triangle 1/2 x 6 x 5 = 15; four = 60. Total 96.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78b8de7c-7cc0-4a3d-8b7c-0f65e61571b4', 'NC26.6.RD.1', 1, 'choice', 'Probability values must be between 0 and 1', 'Which number could NOT be the probability of an event?', '["$0$","$\\frac{1}{2}$","$1$","$\\frac{4}{3}$"]', '$\frac{4}{3}$', NULL, 'A probability is always between 0 and 1, including 0 and 1. The number $\frac{4}{3}$ is greater than 1, so it cannot be a probability.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Probabilities lie from 0 to 1 inclusive. 4/3 > 1, so it cannot be a probability; 0, 1/2 and 1 can.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c272577-53f4-4c24-a034-d679cad592b7', 'NC26.6.RD.1', 1, 'numeric', 'Theoretical probability from counting outcomes', 'A bag has 3 red marbles and 7 blue marbles. One marble is picked without looking. What is the probability that it is red? Give your answer as a fraction.', '[]', '3/10', '3/10', 'There are $3 + 7 = 10$ marbles and 3 of them are red, so the probability is $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 red out of 3 + 7 = 10 marbles: 3/10.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f22f97a-cb79-4752-8b36-b8b34413a11c', 'NC26.6.RD.1', 1, 'choice', 'Probability of rolling a number less than 3', 'A fair six-sided die has faces numbered 1 to 6. It is rolled once. What is the probability of rolling a number less than 3?', '["$\\frac{1}{3}$","$\\frac{1}{6}$","$\\frac{2}{3}$","$\\frac{1}{2}$"]', '$\frac{1}{3}$', NULL, 'The numbers less than 3 are 1 and 2, which is 2 of the 6 equally likely outcomes. So the probability is $\frac{2}{6} = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 3: {1, 2}, 2 outcomes of 6: 2/6 = 1/3.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d9df91e-f931-4315-be4c-fc3557f29477', 'NC26.6.RD.1', 2, 'numeric', 'Probability that an event does not happen', 'A bag has 5 red, 3 green and 2 yellow marbles. One marble is picked without looking. What is the probability that it is NOT green? Give your answer as a fraction.', '[]', '7/10', '7/10', 'There are $5 + 3 + 2 = 10$ marbles. The marbles that are not green number $5 + 2 = 7$, so the probability is $\frac{7}{10}$. (Another way: $1 - \frac{3}{10} = \frac{7}{10}$.)', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 10; not green = 5 + 2 = 7. P = 7/10.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bfe6c6d-afda-4d37-b109-136ed34cf251', 'NC26.6.RD.1', 2, 'choice', 'Describing a probability close to 0 in words', 'The probability of rain tomorrow is $0.05$. Which statement best describes this?', '["Rain is certain not to happen","Rain is very unlikely but not impossible","Rain is as likely as not","Rain is very likely"]', 'Rain is very unlikely but not impossible', NULL, 'A probability of 0.05 is very close to 0, so the event is very unlikely. It is not exactly 0, so it is not impossible.', 'checked', '{"lint":[],"solve":{"answer":"Rain is very unlikely but not impossible","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05 is close to 0 but greater than 0: very unlikely, not impossible.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dae7068b-91fc-4e9f-9272-9baa6825b74e', 'NC26.6.RD.1', 2, 'numeric', 'Experimental probability from a trial', 'Ana tosses a fair coin 50 times and gets heads 28 times. What is the experimental probability of getting heads, as a decimal?', '[]', '0.56', '28/50', 'Experimental probability is the number of times the event happened divided by the number of trials: $\frac{28}{50} = 0.56$.', 'checked', '{"lint":[],"solve":{"answer":"0.56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 50 = 0.56.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d06742f1-0385-452f-9190-4dd6c1229243', 'NC26.6.RD.1', 3, 'numeric', 'Comparing an experiment with theory', 'A spinner has 4 equal sections numbered 1, 2, 3 and 4. Leo spins it 80 times and it lands on 3 a total of 26 times. How many more times than the theoretical probability predicts did it land on 3?', '[]', '6', '26-80/4', 'The theoretical probability of landing on 3 is $\frac{1}{4}$, so in 80 spins you would expect $\frac{1}{4} \times 80 = 20$ times. It landed on 3 a total of 26 times, which is $26 - 20 = 6$ more times than expected.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Wording is slightly awkward (''than the theoretical probability predicts''); clearer: ''How many more times did it land on 3 than the theoretical probability predicts?'' Answer is still unambiguous.","work":"P(3) = 1/4; predicted 80 x 1/4 = 20. Actual 26; 26 - 20 = 6 more.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36d2ce14-37a9-4a8f-b3a0-ff5c55935b24', 'NC26.6.RD.1', 3, 'numeric', 'Finding how many items to add to reach a target probability', 'A bag has 4 red marbles and 6 blue marbles. How many blue marbles must be added so that the probability of picking a red marble is $\frac{1}{4}$?', '[]', '6', '4/(1/4)-10', 'The number of red marbles stays at 4. For the probability to be $\frac{1}{4}$, the bag needs $4 \div \frac{1}{4} = 16$ marbles in all. It now has 10, so add $16 - 10 = 6$ blue marbles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red stays 4. Need 4 / total = 1/4, so total = 16. Currently 10, so add 6 blue. Check 4/16 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcc79f24-b1b2-41e2-9846-84507e887ef5', 'NC26.6.RD.1', 3, 'choice', 'Comparing the probabilities of several events', 'Which event has the greatest probability? In each event, every outcome is equally likely.', '["Rolling a number greater than 2 on a fair six-sided die","Tossing a fair coin and getting tails","Picking a prime number from cards numbered 1 to 10","Picking a red marble from a bag with 3 red and 7 blue marbles"]', 'Rolling a number greater than 2 on a fair six-sided die', NULL, 'Rolling a number greater than 2: 3, 4, 5 or 6, so $\frac{4}{6} \approx 0.67$. Tails: $\frac{1}{2} = 0.5$. A prime from 1 to 10 (2, 3, 5, 7): $\frac{4}{10} = 0.4$. A red marble: $\frac{3}{10} = 0.3$. The die has the greatest probability.', 'checked', '{"lint":[],"solve":{"answer":"Rolling a number greater than 2 on a fair six-sided die","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Die > 2: {3,4,5,6} = 4/6 = 2/3. Primes 1-10: 2,3,5,7 = 4/10 = 0.4. Red: 3/10 = 0.3. Tails: 1/2. Greatest is 2/3.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0c88353-dc0f-4afc-b854-a491816a65c0', 'NC26.6.RD.2', 1, 'choice', 'Telling a statistical question from other questions', 'Which of these is a statistical question?', '["How many pets do the students in a sixth-grade class have?","How many pets does Sam have?","How old is the teacher of the sixth-grade class?","What time does school start on Monday?"]', 'How many pets do the students in a sixth-grade class have?', NULL, 'A statistical question is one where you expect the answers to vary, so you need data from a group. Each student in a class may have a different number of pets. The other questions each have one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many pets do the students in a sixth-grade class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects variability in the answers. Pets of students in a class vary; the others have a single answer.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae33b87e-c5b0-4a95-9a12-2d929e814fd8', 'NC26.6.RD.2', 1, 'numeric', 'Organizing data by counting in a category', 'Ten students were asked how they get to school. Their answers were: bus, bus, walk, car, bus, walk, bike, bus, car, bus. How many of the students ride the bus?', '[]', '5', NULL, 'Count the answers that say bus: the 1st, 2nd, 5th, 8th and 10th answers. That is 5 students.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"bus(1), bus(2), walk, car, bus(3), walk, bike, bus(4), car, bus(5): 5 ride the bus.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce889d42-f465-4126-a35d-7c34fe954cb7', 'NC26.6.RD.2', 1, 'choice', 'Sample versus population', 'Nia asks 20 students in her school about their favorite sport. She wants to know the favorite sport of all 400 students in the school. What are the 20 students she asked?', '["The population","A sample","A statistical question","The data display"]', 'A sample', NULL, 'The population is everyone she wants to learn about, which is all 400 students. The 20 students she asked are a part of that group, which is called a sample.', 'checked', '{"lint":[],"solve":{"answer":"A sample","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 400 students are the population; the 20 asked are a sample.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb3da64-bb0b-47f5-8fae-9f5c748ac7e8', 'NC26.6.RD.2', 2, 'choice', 'Spotting a biased survey question', 'Mr. Cole wants to know where students like to read. Which survey question is worded in a way that pushes people toward one answer?', '["Where do you like to read best: the library, a classroom, or home?","Everyone loves the fantastic new library, so isn''t it the best place to read?","How many times a week do you read at the library?","What is your favorite place to read?"]', 'Everyone loves the fantastic new library, so isn''t it the best place to read?', NULL, 'The question that says "Everyone loves the fantastic new library" tells people what answer to give, so it is biased. The other questions are neutral.', 'checked', '{"lint":[],"solve":{"answer":"Everyone loves the fantastic new library, so isn''t it the best place to read?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question that states ''Everyone loves the fantastic new library'' leads respondents to agree; it is the biased one.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afd60d88-824e-478d-8216-4969ae2c439f', 'NC26.6.RD.2', 2, 'numeric', 'Organizing survey results in a frequency table', 'A survey of 25 students asked how many brothers and sisters each has. The results were: 0 siblings, 4 students; 1 sibling, 9 students; 2 siblings, 8 students; 3 siblings, 4 students. How many students have at least 2 siblings?', '[]', '12', '8+4', '"At least 2" means 2 or more. Add the students with 2 siblings and with 3 siblings: $8 + 4 = 12$ students.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 2 siblings: 2 siblings (8) + 3 siblings (4) = 12. Totals check: 4 + 9 + 8 + 4 = 25.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8e6d13-0b1a-4e7e-ba1a-2937fbbdd31c', 'NC26.6.RD.2', 2, 'choice', 'Choosing a representative sample', 'A school has 600 students. The principal wants to know the favorite lunch of all students. Which way of choosing 40 students to ask is most likely to give a representative sample?', '["Ask the first 40 students in the pizza line","Ask the 40 students on the soccer team","Ask 40 students who volunteer in the cafeteria","Choose 40 names at random from a list of all students"]', 'Choose 40 names at random from a list of all students', NULL, 'A random choice from the list of everyone gives every student the same chance of being asked. The other groups all favor certain kinds of students.', 'checked', '{"lint":[],"solve":{"answer":"Choose 40 names at random from a list of all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random selection from the full list gives every student an equal chance; the other methods are biased groups.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c602e0d3-5ad2-4c53-8c05-86a416c5dca5', 'NC26.6.RD.2', 3, 'choice', 'A large sample can still be biased', 'Ruth wants to know which sport is the favorite of the people in her town. Plan A is to ask 500 people leaving a basketball game. Plan B is to ask 50 people chosen at random from a list of all the town''s residents. Which statement is true?', '["Plan B is better, because a random sample is more likely to represent the whole town","Plan A is better, because a larger sample is always more representative","Plan A is better, because basketball fans know the most about sports","The plans are equally good, because both ask people"]', 'Plan B is better, because a random sample is more likely to represent the whole town', NULL, 'People leaving a basketball game are probably more likely than other residents to name basketball, so Plan A is biased no matter how many are asked. A smaller random sample of all residents represents the town better.', 'checked', '{"lint":[],"solve":{"answer":"Plan B is better, because a random sample is more likely to represent the whole town","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Plan A samples only basketball spectators (biased); Plan B is random from the whole town, so more representative despite being smaller.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfc0a331-4ff7-4b2b-b635-ec96740a182a', 'NC26.6.RD.2', 3, 'numeric', 'Taking an equal share from each group for a sample', 'A school has 200 sixth graders, 200 seventh graders and 200 eighth graders. Mia wants a sample of 60 students that includes the same number from each grade. How many students should she choose from each grade?', '[]', '20', '60/3', 'There are 3 grades and the sample must have the same number from each, so each grade gets $60 \div 3 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 split equally among 3 grades: 60 / 3 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0253e399-b173-43f1-932f-5e6df22728ce', 'NC26.6.RD.2', 3, 'numeric', 'Organizing data into a fraction of the whole', 'Twelve students recorded how many books they read last month: 2, 3, 3, 5, 0, 2, 3, 4, 2, 3, 5, 3. What fraction of the students read more than 3 books? Give your answer as a fraction.', '[]', '1/4', '3/12', 'The values greater than 3 are 5, 4 and 5, which is 3 students out of 12. The fraction is $\frac{3}{12} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values greater than 3: 5, 4, 5 = 3 students out of 12. 3/12 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50c8d37f-18cb-40c2-abea-37ddfd86fbc1', 'NC26.6.RD.3', 1, 'numeric', 'Reading the total from a dot plot', 'A dot plot shows the number of pets owned by students, with one dot for each student. It has these dots: 0 pets, 3 dots; 1 pet, 5 dots; 2 pets, 4 dots; 3 pets, 2 dots. How many students are shown on the dot plot?', '[]', '14', '3+5+4+2', 'Each dot is one student, so add the dots: $3 + 5 + 4 + 2 = 14$ students.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 5 + 4 + 2 = 14 dots, one per student.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('150f58f4-fcf8-41d1-9b06-785b1c0c2dbb', 'NC26.6.RD.3', 1, 'choice', 'Finding the tallest bar of a histogram', 'A histogram of 16 quiz scores has bars with these heights: 0 to 9, 2 scores; 10 to 19, 6 scores; 20 to 29, 5 scores; 30 to 39, 3 scores. Which interval contains the most scores?', '["0 to 9","20 to 29","10 to 19","30 to 39"]', '10 to 19', NULL, 'The tallest bar is the one with the greatest height. The interval 10 to 19 has 6 scores, which is more than any other interval.', 'checked', '{"lint":[],"solve":{"answer":"10 to 19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights 2, 6, 5, 3 (total 16). Tallest bar is 10 to 19 with 6.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db1ed497-11b9-4e7b-9628-7a1d63d80212', 'NC26.6.RD.3', 1, 'choice', 'Range from the five key values of a box plot', 'A box plot of daily visitors to a park has a minimum of 12, a first quartile of 20, a median of 26, a third quartile of 34 and a maximum of 50. What is the range of the data?', '["$14$","$26$","$30$","$38$"]', '$38$', '50-12', 'The range is the maximum minus the minimum: $50 - 12 = 38$. (14 is the IQR, $34 - 20$; 26 is the median.)', 'checked', '{"lint":[],"solve":{"answer":"$38$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = max - min = 50 - 12 = 38.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cfd38b8-bbd6-435e-9adb-7ebf68a0bad2', 'NC26.6.RD.3', 2, 'numeric', 'Interquartile range from five key values', 'Forty students recorded how many minutes they read. The smallest time was 4, the first quartile was 9, the median was 15, the third quartile was 22 and the largest time was 31. What is the interquartile range (IQR) in minutes?', '[]', '13', '22-9', 'The interquartile range is the third quartile minus the first quartile: $22 - 9 = 13$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3 - Q1 = 22 - 9 = 13.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dbab2d4-e3e3-4992-b6db-78393e9b251a', 'NC26.6.RD.3', 2, 'choice', 'Describing a gap and an outlier in a dot plot', 'A dot plot shows the number of goals scored in 19 games: 0 goals, 4 dots; 1 goal, 6 dots; 2 goals, 5 dots; 3 goals, 3 dots; 4 goals, 0 dots; 5 goals, 0 dots; 6 goals, 1 dot. Which statement is true?', '["The most common number of goals was 6","There is a gap between 3 and 6, and the value 6 is far from the rest of the data","Every number of goals from 0 to 6 occurred at least once","Most games had 4 or more goals"]', 'There is a gap between 3 and 6, and the value 6 is far from the rest of the data', NULL, 'No game had 4 or 5 goals, so there is a gap between 3 and 6. Only one game had 6 goals, far from the others. The most common number was 1 goal (6 games), and 4 or more goals happened in only 1 game.', 'checked', '{"lint":[],"solve":{"answer":"There is a gap between 3 and 6, and the value 6 is far from the rest of the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 4+6+5+3+0+0+1 = 19. Games with 4+ goals: 1 (not most). Mode is 1 goal, not 6. 4 and 5 goals never occurred. So there is a gap (4, 5) between 3 and 6, and 6 is an outlier.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49a0912a-59e2-4f61-ac73-25fad3be53e7', 'NC26.6.RD.3', 2, 'choice', 'Finding the interval that holds the median of a histogram', 'A histogram of 19 ages has these bars: 1 to 5, 6 values; 6 to 10, 5 values; 11 to 15, 4 values; 16 to 20, 4 values. In which interval is the median age?', '["6 to 10","1 to 5","11 to 15","16 to 20"]', '6 to 10', NULL, 'With 19 values, the median is the 10th value in order. The first bar holds values 1 to 6, and the second bar holds values 7 to 11. So the 10th value is in the interval 6 to 10.', 'checked', '{"lint":[],"solve":{"answer":"6 to 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19 values (6+5+4+4), median is the 10th. Values 1-6 are in 1 to 5; values 7-11 are in 6 to 10. The 10th lies in 6 to 10.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e579c22-2bfa-42fa-b0b5-3510532a9470', 'NC26.6.RD.3', 3, 'numeric', 'Comparing the spread of two box plots', 'Class A''s test scores have these five key values: smallest 50, first quartile 62, median 70, third quartile 78, largest 90. Class B''s have: smallest 40, first quartile 60, median 70, third quartile 84, largest 100. How much greater is Class B''s IQR than Class A''s IQR?', '[]', '8', '(84-60)-(78-62)', 'Class A''s IQR is $78 - 62 = 16$. Class B''s IQR is $84 - 60 = 24$. The difference is $24 - 16 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class A IQR = 78 - 62 = 16. Class B IQR = 84 - 60 = 24. Difference 24 - 16 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61b66ccf-52bd-4910-a2d8-1330d75f63e7', 'NC26.6.RD.3', 3, 'numeric', 'Counting the values in the tallest bar when building a histogram', 'Thirteen quiz scores are: 47, 52, 58, 61, 63, 65, 68, 72, 75, 79, 83, 88, 91. Jin makes a histogram with the bins 40 to 49, 50 to 59, 60 to 69, 70 to 79, 80 to 89 and 90 to 99. How many scores are in the tallest bar?', '[]', '4', NULL, 'Count the scores in each bin: 40 to 49 has 1, 50 to 59 has 2, 60 to 69 has 4 (61, 63, 65, 68), 70 to 79 has 3, 80 to 89 has 2 and 90 to 99 has 1. The tallest bar is 60 to 69, with 4 scores.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-49: 47 (1). 50-59: 52, 58 (2). 60-69: 61, 63, 65, 68 (4). 70-79: 72, 75, 79 (3). 80-89: 83, 88 (2). 90-99: 91 (1). Total 13. Tallest bar has 4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c78cf3c-05bf-4cd9-a7fc-2410ebfa7d0b', 'NC26.6.RD.3', 3, 'choice', 'Comparing center and spread of two dot plots', 'Plot A shows the values 5, 5, 6, 6, 6, 7, 7. Plot B shows the values 2, 4, 6, 6, 6, 8, 10. Which statement is true?', '["Plot A has a greater median than Plot B","The two plots have the same range","Both have a median of 6, but Plot B is more spread out","Plot A is more spread out than Plot B"]', 'Both have a median of 6, but Plot B is more spread out', NULL, 'Both sets have 7 values and the middle (4th) value is 6, so both medians are 6. Plot A has a range of $7 - 5 = 2$ and Plot B has a range of $10 - 2 = 8$, so Plot B is more spread out.', 'checked', '{"lint":[],"solve":{"answer":"Both have a median of 6, but Plot B is more spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: median 6 (4th of 7), range 7 - 5 = 2. B: median 6, range 10 - 2 = 8. Same median, B more spread out. Other options false.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98148096-a60c-40e1-96d4-d326364fa2b7', 'NC26.6.RD.4', 1, 'numeric', 'Finding a mean', 'What is the mean of the numbers 4, 6, 8, 10 and 12?', '[]', '8', '(4+6+8+10+12)/5', 'Add the numbers: $4 + 6 + 8 + 10 + 12 = 40$. Divide by how many there are: $40 \div 5 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4+6+8+10+12 = 40; 40 / 5 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cd0f6bf-25b6-4a7e-b9db-5b6eb2e37064', 'NC26.6.RD.4', 1, 'choice', 'Finding a median of an unordered list', 'What is the median of the numbers 9, 3, 12, 5 and 6?', '["$7$","$6$","$12$","$9$"]', '$6$', '6', 'Put the numbers in order: 3, 5, 6, 9, 12. The middle number is 6. (7 is the mean, 12 is the middle of the unordered list, and 9 is the range.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 3, 5, 6, 9, 12. Middle value 6.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e4cb29b-6c7d-413a-9183-8402f3037fcd', 'NC26.6.RD.4', 1, 'numeric', 'The mean as a fair share', 'Four friends have 3, 5, 6 and 10 stickers. They put all the stickers together and share them equally. How many stickers does each friend get?', '[]', '6', '(3+5+6+10)/4', 'There are $3 + 5 + 6 + 10 = 24$ stickers in all. Shared equally among 4 friends, each gets $24 \div 4 = 6$ stickers. This is the mean.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 3 + 5 + 6 + 10 = 24; 24 / 4 = 6 each (the mean as fair share).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
