INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c7ed238-6fb9-4068-acc0-9cc3df8b5632', 'NC26.6.RD.4', 2, 'numeric', 'Median of an even number of values', 'What is the median of the numbers 25, 12, 30, 18, 15 and 20?', '[]', '19', '(18+20)/2', 'Put the numbers in order: 12, 15, 18, 20, 25, 30. With six numbers, the median is halfway between the two middle ones: $(18 + 20) \div 2 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 12, 15, 18, 20, 25, 30. Median = (18 + 20) / 2 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('549d7603-189d-48b5-af3a-53cc81ab202b', 'NC26.6.RD.4', 2, 'numeric', 'Finding a missing value from a mean', 'Dev took five tests and his mean score was 82. His first four scores were 78, 85, 90 and 80. What was his fifth score?', '[]', '77', '5*82-(78+85+90+80)', 'A mean of 82 over 5 tests means the total is $5 \times 82 = 410$. The first four scores add to $78 + 85 + 90 + 80 = 333$. The fifth score is $410 - 333 = 77$.', 'checked', '{"lint":[],"solve":{"answer":"77","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total needed 5 x 82 = 410. First four: 78 + 85 + 90 + 80 = 333. Fifth = 410 - 333 = 77.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c9d6667-7b49-4e61-a56f-2ec1aeff84f9', 'NC26.6.RD.4', 2, 'choice', 'Choosing the better measure of center when there is an outlier', 'Five students'' walking times to school, in minutes, are 6, 7, 8, 9 and 60. Which measure best describes a typical walking time, and why?', '["The mean, because it uses every value","The mean, because outliers do not affect it","The median, because the value 60 pulls the mean up","The range, because it uses the smallest and largest values"]', 'The median, because the value 60 pulls the mean up', NULL, 'The median is 8 minutes. The mean is $90 \div 5 = 18$ minutes, which is larger than four of the five times because the 60 pulls it up. The median describes a typical time better here.', 'checked', '{"lint":[],"solve":{"answer":"The median, because the value 60 pulls the mean up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean = 90 / 5 = 18, pulled up by the outlier 60; median 8 is typical. Range is spread, not centre; outliers do affect the mean.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3312d8f3-1946-4d39-8266-ba5d03423090', 'NC26.6.RD.4', 3, 'numeric', 'How adding a value changes a mean', 'The mean of 5 numbers is 20. A sixth number, 32, is added to the set. What is the mean of all 6 numbers?', '[]', '22', '(5*20+32)/6', 'The first 5 numbers add to $5 \times 20 = 100$. With 32 added the total is $132$ for 6 numbers, and $132 \div 6 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of 5 = 100. Add 32: 132. Mean = 132 / 6 = 22.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1524faa6-be56-41e4-9b6e-37a7c2098710', 'NC26.6.RD.4', 3, 'numeric', 'How an outlier changes the mean', 'A data set is 4, 5, 6, 7 and 8. The 8 is changed to 38. By how much does the mean increase?', '[]', '6', '(4+5+6+7+38)/5-(4+5+6+7+8)/5', 'The original total is $30$, so the mean is $30 \div 5 = 6$. The new total is $60$, so the new mean is $60 \div 5 = 12$. The mean increases by $12 - 6 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum rises by 38 - 8 = 30; mean rises by 30 / 5 = 6 (from 6 to 12).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f174fcfc-0ec6-4670-bf94-864497c47c36', 'NC26.6.RD.4', 3, 'choice', 'Building a data set with a given mean and median', 'Which set of numbers has a mean of 10 and a median of 8?', '["$8, 8, 9, 12, 13$","$5, 8, 10, 13, 14$","$4, 6, 8, 9, 10$","$6, 8, 8, 12, 16$"]', '$6, 8, 8, 12, 16$', NULL, 'For $6, 8, 8, 12, 16$: the total is 50, so the mean is $50 \div 5 = 10$, and the middle number is 8. The set $8, 8, 9, 12, 13$ has mean 10 but median 9; $5, 8, 10, 13, 14$ has mean 10 but median 10; and $4, 6, 8, 9, 10$ has median 8 but a mean of 7.4.', 'checked', '{"lint":[],"solve":{"answer":"$6, 8, 8, 12, 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 50, mean 10, median 9. B: sum 50, mean 10, median 10. C: sum 37, mean 7.4. D: 6+8+8+12+16 = 50, mean 10, median 8. Only D.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e38bcd8-2018-4ca0-887e-f8ee7042ba25', 'NC26.6.RD.5', 1, 'choice', 'What a comparison of means does and does not show', 'Two classes took the same quiz. The mean score in Class 1 was 18 and the mean score in Class 2 was 15. Which statement does this information support?', '["On average, Class 1 scored higher than Class 2","Every student in Class 1 scored higher than every student in Class 2","Class 1 had a smaller range of scores than Class 2","Class 1 had more students than Class 2"]', 'On average, Class 1 scored higher than Class 2', NULL, 'A higher mean tells us that, on average, Class 1 scored higher. It does not tell us about every student, the spread of the scores or the number of students.', 'checked', '{"lint":[],"solve":{"answer":"On average, Class 1 scored higher than Class 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means compare averages only; they say nothing about every individual, range, or class size.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60e249f6-06c4-481c-b973-829d1e200d0d', 'NC26.6.RD.5', 1, 'numeric', 'Describing spread with the range', 'A student recorded the hours of sleep that 10 classmates got last night: 7, 8, 8, 9, 9, 9, 9, 10, 10, 11. What is the range of the data in hours?', '[]', '4', '11-7', 'The range is the greatest value minus the least value: $11 - 7 = 4$ hours.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = 11 - 7 = 4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35406896-397b-47c6-9897-ad9f66220fd1', 'NC26.6.RD.5', 1, 'choice', 'Summarizing a distribution with its center and spread', 'Nine students'' waiting times for the bus, in minutes, were 5, 6, 6, 7, 7, 7, 8, 8 and 9. Which sentence summarizes the data correctly?', '["The median is 6 minutes and the times go from 5 to 9 minutes","The median is 7 minutes and the times go from 5 to 8 minutes","The median is 7 minutes and the times go from 5 to 9 minutes","The median is 9 minutes and the times go from 5 to 7 minutes"]', 'The median is 7 minutes and the times go from 5 to 9 minutes', NULL, 'The 9 values are already in order, and the middle (5th) value is 7, so the median is 7 minutes. The smallest time is 5 and the largest is 9.', 'checked', '{"lint":[],"solve":{"answer":"The median is 7 minutes and the times go from 5 to 9 minutes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 sorted values; median is the 5th: 7. Min 5, max 9.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f99ade84-2fd3-4282-bba8-bca378024404', 'NC26.6.RD.5', 2, 'choice', 'Using variability to compare two sets of data', 'Over five days, Maya''s bike ride to school took 20, 21, 20, 22 and 21 minutes. Jon''s took 12, 30, 15, 28 and 19 minutes. Both have a mean of 20.8 minutes. Which statement is supported by the data?', '["Jon''s rides are faster on average","Maya''s times vary less than Jon''s times","Maya''s times vary more than Jon''s times","Maya''s mean time is greater than Jon''s"]', 'Maya''s times vary less than Jon''s times', NULL, 'The means are equal, so neither rides faster on average. Maya''s times range from 20 to 22 (a range of 2) and Jon''s from 12 to 30 (a range of 18), so Maya''s times vary less.', 'checked', '{"lint":[],"solve":{"answer":"Maya''s times vary less than Jon''s times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maya sum 104, Jon sum 104, both mean 20.8 (checked). Maya range 22 - 20 = 2; Jon range 30 - 12 = 18. Maya varies less. Means equal, so C and D false.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b536122-0349-4861-af55-5bda63eeeac9', 'NC26.6.RD.5', 2, 'numeric', 'Measuring the effect of an outlier on a summary', 'Ten classmates reported how many books they read last month: 3, 4, 4, 5, 5, 5, 6, 6, 7 and 25. The mean of the first nine numbers is 5. By how much does the 25 raise the mean when it is included?', '[]', '2', '70/10-45/9', 'The first nine numbers add to $9 \times 5 = 45$, so with the 25 the total is $70$. The mean of all ten is $70 \div 10 = 7$. The 25 raises the mean from 5 to 7, which is by 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First nine: 3+4+4+5+5+5+6+6+7 = 45, mean 5 (checked). With 25: 70 / 10 = 7. Raised by 7 - 5 = 2.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dff7ad3e-19ad-40a0-94b9-0cf25ee911e9', 'NC26.6.RD.5', 2, 'choice', 'Reflecting on the methods of an investigation', 'Sofia wants to find the typical number of hours that students at her school spend on video games. She asks 20 members of the school gaming club. What should she change to make her investigation better?', '["Ask the same 20 students a second time","Ask only the students who play the most","Ask fewer students","Ask students chosen at random from the whole school"]', 'Ask students chosen at random from the whole school', NULL, 'Gaming club members probably play more than most students, so her sample is biased. A random sample from the whole school would better represent all of its students.', 'checked', '{"lint":[],"solve":{"answer":"Ask students chosen at random from the whole school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gaming club members are a biased sample; a random sample of the whole school is representative.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dcd0a2b-d2c7-48f8-ac33-fa96fef6cf3e', 'NC26.6.RD.5', 3, 'choice', 'Drawing an inference from the mean and median together', 'On a test, 12 students had a mean score of 78 and a median score of 85. Which conclusion is best supported?', '["A few very high scores probably pulled the mean above the median","More than half of the students scored below 78","A few low scores probably pulled the mean below the median","Every student scored between 78 and 85"]', 'A few low scores probably pulled the mean below the median', NULL, 'The median is 85, so half of the students scored 85 or more. The mean is lower, at 78, which happens when a few very low scores pull the mean down. The other statements are not supported, or are impossible, when the median is 85 and the mean is 78.', 'checked', '{"lint":[],"solve":{"answer":"A few low scores probably pulled the mean below the median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean (78) below median (85) indicates a few low scores pulled the mean down. A: not implied. C: opposite. D: median 85 means about half scored at or above 85, so not more than half below 78.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('201b485c-dc33-4467-b678-7cebe1e31965', 'NC26.6.RD.5', 3, 'numeric', 'Describing the spread of the middle half of the data', 'Twelve runners'' times, in seconds, were 14, 15, 16, 16, 17, 17, 18, 19, 20, 20, 21 and 29. The middle half of the times lie between the first quartile and the third quartile. How many seconds wide is that middle part (the IQR)?', '[]', '4', '20-16', 'The lower six times are 14, 15, 16, 16, 17, 17, so the first quartile is the middle of those: $(16 + 16) \div 2 = 16$. The upper six times are 18, 19, 20, 20, 21, 29, so the third quartile is $(20 + 20) \div 2 = 20$. The IQR is $20 - 16 = 4$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 sorted values. Lower half 14, 15, 16, 16, 17, 17: Q1 = (16 + 16)/2 = 16. Upper half 18, 19, 20, 20, 21, 29: Q3 = (20 + 20)/2 = 20. IQR = 4. (Interpolation methods also give 16 and 20.)","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('689b02fd-237a-4b9d-a11c-281f872673ea', 'NC26.6.RD.5', 3, 'numeric', 'Using a representative sample to estimate for the whole group', 'A representative sample of 40 students from a school of 600 students was asked how long they spend on homework each night. In the sample, 14 students said they spend more than an hour. About how many of the 600 students would you expect to spend more than an hour?', '[]', '210', '14/40*600', 'In the sample, $\frac{14}{40} = 0.35$ of the students spend more than an hour. If the sample is representative, about $0.35 \times 600 = 210$ students in the school do.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample proportion 14/40 = 0.35. 0.35 x 600 = 210.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef263ee3-1c7f-4362-a332-3bcb31e596fc', 'NC26.7.RPR.1', 1, 'numeric', 'Find the constant of proportionality from a table of values', 'In a proportional relationship, $y = 10$ when $x = 2$, $y = 20$ when $x = 4$, and $y = 30$ when $x = 6$. What is the constant of proportionality $k$ in $y = kx$?', '[]', '5', '10/2', 'In $y = kx$, $k = y \div x$. Use the first pair: $k = 10 \div 2 = 5$. The other pairs agree: $20 \div 4 = 5$ and $30 \div 6 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = y/x: 10/2 = 5, 20/4 = 5, 30/6 = 5. So k = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('123da428-7571-4697-bed7-0802c0d34287', 'NC26.7.RPR.1', 1, 'choice', 'Recognize a proportional relationship from pairs of values', 'Which list of $(x, y)$ pairs shows a proportional relationship?', '["(1, 3), (2, 6), (3, 9)","(1, 3), (2, 5), (3, 7)","(1, 4), (2, 6), (3, 8)","(1, 2), (2, 5), (3, 8)"]', '(1, 3), (2, 6), (3, 9)', NULL, 'In a proportional relationship, $y \div x$ is the same for every pair. For (1, 3), (2, 6), (3, 9) it is always 3. In the other lists $y$ goes up by a fixed amount each time, but $y \div x$ changes, so they are not proportional.', 'checked', '{"lint":[],"solve":{"answer":"(1, 3), (2, 6), (3, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Proportional means y/x constant (and passes through origin). (1,4),(2,6),(3,8): 4, 3, 2.67 no. (1,2),(2,5),(3,8): 2, 2.5, 2.67 no. (1,3),(2,5),(3,7): 3, 2.5, 2.33 no. (1,3),(2,6),(3,9): 3, 3, 3 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c06eaa1b-4e4c-4edb-9127-f5da39945481', 'NC26.7.RPR.1', 1, 'numeric', 'Unit rate when the time is a fraction', 'Maya walks 2 miles in $\frac{1}{2}$ hour at a steady pace. How many miles does she walk in 1 hour?', '[]', '4', '2/(1/2)', 'Miles per hour is $2 \div \frac{1}{2} = 2 \times 2 = 4$. In half an hour she walks 2 miles, so in a whole hour she walks twice as far, 4 miles.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit rate = 2 / (1/2) = 4 miles per hour.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8490ee53-7b54-4ed0-a67f-4e567eb0bfac', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate from two fractional quantities', 'Ben reads $\frac{3}{4}$ of a chapter in $\frac{1}{2}$ hour. At this rate, how many chapters does he read in 1 hour?', '[]', '3/2', '(3/4)/(1/2)', 'The unit rate is $\frac{3}{4} \div \frac{1}{2} = \frac{3}{4} \times 2 = \frac{3}{2}$, which is $1\frac{1}{2}$ chapters per hour.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4) / (1/2) = 3/4 x 2 = 3/2 = 1.5 chapters per hour.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6b29c43-f5f4-4c38-963b-4c1003b70a48', 'NC26.7.RPR.1', 2, 'choice', 'Write an equation y = kx for a proportional situation', 'Ribbon is sold at a constant price per meter. 4 meters cost 10 dollars. Which equation gives the cost $y$, in dollars, of $x$ meters of ribbon?', '["$y = 4x$","$y = x + 6$","$y = 0.4x$","$y = 2.5x$"]', '$y = 2.5x$', NULL, 'The price for 1 meter is $10 \div 4 = 2.5$ dollars, so $k = 2.5$ and $y = 2.5x$. Check: $x = 4$ gives $y = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2.5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit price = 10/4 = 2.5 dollars per meter, proportional, so y = 2.5x. Check: 2.5 x 4 = 10.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c0ec78d-9909-43ad-ba3b-129d682ba211', 'NC26.7.RPR.1', 2, 'numeric', 'Interpret a point on a proportional relationship in context', 'A proportional relationship between hours worked $x$ and pay $y$, in dollars, includes the point $(4, 52)$. How many dollars is the pay for 1 hour of work?', '[]', '13', '52/4', 'The point $(4, 52)$ means 4 hours earn 52 dollars. The pay for 1 hour is the unit rate $52 \div 4 = 13$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 52/4 = 13 dollars per hour.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26b75ed9-46b2-489c-985a-cd8593c0fd07', 'NC26.7.RPR.1', 3, 'choice', 'Compare a unit rate from a description with one from an equation', 'Store A sells 3 pounds of apples for 7.50 dollars. At Store B, the cost $y$ in dollars of $x$ pounds is given by $y = 2.4x$. Which statement is true?', '["Store A costs 0.10 dollars less per pound.","Store B costs 0.10 dollars less per pound.","Store B costs 5.10 dollars less per pound.","The two stores charge the same price per pound."]', 'Store B costs 0.10 dollars less per pound.', NULL, 'Store A: $7.50 \div 3 = 2.50$ dollars per pound. Store B: $k = 2.4$ dollars per pound. Store B is cheaper by $2.50 - 2.40 = 0.10$ dollars per pound.', 'checked', '{"lint":[],"solve":{"answer":"Store B costs 0.10 dollars less per pound.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Store A: 7.50/3 = 2.50 dollars per pound. Store B: 2.40 per pound. B is cheaper by 2.50 - 2.40 = 0.10 dollars per pound.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
