INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dac47a5f-0ed4-4df6-a92c-37151c086f20', 'NC26.7.RPR.1', 3, 'numeric', 'Use a unit rate with decimals to find a missing value', 'A paint covers an area proportional to the amount used. 3.5 liters of paint cover 5.6 square meters. At this rate, how many square meters can 8 liters of paint cover?', '[]', '12.8', '5.6/3.5*8', 'One liter covers $5.6 \div 3.5 = 1.6$ square meters. So 8 liters cover $1.6 \times 8 = 12.8$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"12.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = 5.6/3.5 = 1.6 square meters per liter. 8 x 1.6 = 12.8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d03f10eb-fe2c-4bee-ab4d-7ec1938ecc78', 'NC26.7.RPR.1', 3, 'choice', 'Find another point on a proportional relationship', 'A proportional relationship includes the point $(6, 15)$. Which point is also on this relationship?', '["$(10, 19)$","$(4, 13)$","$(4, 10)$","$(5, 2)$"]', '$(4, 10)$', NULL, 'The constant of proportionality is $15 \div 6 = 2.5$, so $y = 2.5x$. For $x = 4$, $y = 2.5 \times 4 = 10$, so $(4, 10)$ is on it. The other points do not have $y \div x = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 10)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 15/6 = 2.5. Check: (5,2): 0.4 no; (10,19): 1.9 no; (4,13): 3.25 no; (4,10): 2.5 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c39e47bc-f7f2-4845-8297-1c991532ff77', 'NC26.7.RPR.2', 1, 'numeric', 'Use a map scale', 'On a map, 1 centimeter stands for 5 kilometers. Two towns are 6 centimeters apart on the map. How many kilometers apart are the towns?', '[]', '30', '6*5', 'Each map centimeter is 5 kilometers, so 6 centimeters is $6 \times 5 = 30$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 5 = 30 km.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffb2195f-fcca-4195-8962-489fa0b6129a', 'NC26.7.RPR.2', 1, 'numeric', 'Find a tip as a percent', 'A meal costs 40 dollars. Sam leaves a tip of 15% of the cost of the meal. How many dollars is the tip?', '[]', '6', '40*15/100', '15% of 40 is $0.15 \times 40 = 6$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.15 x 40 = 6 dollars.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92aaa418-e29b-46ce-a5bd-38c54b54f99c', 'NC26.7.RPR.2', 1, 'choice', 'Find a total price with sales tax', 'A book costs 20 dollars before tax. The sales tax is 8%. What is the total cost of the book with tax, in dollars?', '["1.60","21.60","28.00","20.08"]', '21.60', '20*1.08', 'The tax is 8% of 20, which is $0.08 \times 20 = 1.60$ dollars. The total is $20 + 1.60 = 21.60$ dollars. (Or multiply by $1.08$.)', 'checked', '{"lint":[],"solve":{"answer":"21.60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tax = 0.08 x 20 = 1.60. Total = 20 + 1.60 = 21.60.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03321989-51a2-4508-9790-fba8ac1e33d0', 'NC26.7.RPR.2', 2, 'numeric', 'Use a scale drawing with fractional measurements', 'A scale drawing of a room uses 1 inch for every 3 feet. On the drawing, the room''s length is $4\frac{1}{2}$ inches. What is the room''s actual length, in feet?', '[]', '13.5', '4.5*3', 'Each inch on the drawing is 3 feet, so $4\frac{1}{2}$ inches is $4.5 \times 3 = 13.5$ feet.', 'checked', '{"lint":[],"solve":{"answer":"13.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.5 inches x 3 feet per inch = 13.5 feet.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e3c0b12-6262-4812-90d9-541662ad0923', 'NC26.7.RPR.2', 2, 'choice', 'Find a percent increase', 'The price of a game rose from 40 dollars to 46 dollars. What is the percent increase?', '["15%","6%","13%","115%"]', '15%', NULL, 'The increase is $46 - 40 = 6$ dollars. Compare it with the ORIGINAL price: $6 \div 40 = 0.15$, which is 15%.', 'checked', '{"lint":[],"solve":{"answer":"15%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase = 6. 6/40 = 0.15 = 15%.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0d31fc3-4947-48ab-b368-632df063a1ff', 'NC26.7.RPR.2', 2, 'choice', 'Find a selling price after a markup', 'A store buys a jacket for 50 dollars and sells it for 40% more than it paid. What is the selling price, in dollars?', '["125","90","20","70"]', '70', '50*1.4', 'The markup is 40% of 50, which is 20 dollars. The selling price is $50 + 20 = 70$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Markup = 0.40 x 50 = 20. Selling price = 50 + 20 = 70.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d175d50-79c7-4a31-87e8-2dc15a09f2ce', 'NC26.7.RPR.2', 3, 'numeric', 'How a scale affects area', 'On a scale drawing, 1 centimeter represents 4 meters. A rectangular field is drawn 3 centimeters wide and 5 centimeters long. What is the actual area of the field, in square meters?', '[]', '240', '(3*4)*(5*4)', 'Actual width: $3 \times 4 = 12$ meters. Actual length: $5 \times 4 = 20$ meters. Area: $12 \times 20 = 240$ square meters. (The drawing''s area, 15 square centimeters, is multiplied by $4 \times 4 = 16$.)', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Actual: 3 x 4 = 12 m wide, 5 x 4 = 20 m long. Area = 12 x 20 = 240 square meters.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa38d286-60bf-4284-b8a9-9337ce499f1a', 'NC26.7.RPR.2', 3, 'numeric', 'Pay with a base amount plus commission', 'Priya earns a base pay of 200 dollars each week plus a commission of 6% of her sales. One week her sales are 1200 dollars. How many dollars does she earn that week in all?', '[]', '272', '200+1200*6/100', 'Commission: 6% of 1200 is $0.06 \times 1200 = 72$ dollars. Total pay: $200 + 72 = 272$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"272","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Commission = 0.06 x 1200 = 72. Total = 200 + 72 = 272.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29b49ab6-6d83-4f66-a426-9db7f1ffda3c', 'NC26.7.RPR.2', 3, 'numeric', 'Convert units within a rate', 'A cyclist rides at a steady 18 kilometers per hour. How many meters does she ride in 10 minutes?', '[]', '3000', '18*1000/60*10', '18 kilometers per hour is $18 \times 1000 = 18000$ meters per hour, or $18000 \div 60 = 300$ meters per minute. In 10 minutes she rides $300 \times 10 = 3000$ meters.', 'checked', '{"lint":[],"solve":{"answer":"3000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 km/h = 18000 m per 60 min = 300 m per min. 10 min x 300 = 3000 m.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4ffca69-5e57-4d6c-ae2d-f964c0a7d114', 'NC26.7.RPR.3', 1, 'numeric', 'Read a circle graph sector in degrees and percent', 'A sector of a circle graph measures 90 degrees. What percent of the whole circle graph is this sector?', '[]', '25', '90/360*100', 'A whole circle is 360 degrees. $90 \div 360 = \frac{1}{4}$, which is 25%.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90/360 = 1/4 = 25%.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
