INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42820aef-f691-4dcc-bd63-b862b097fcd3', 'NC26.7.RPR.3', 1, 'choice', 'Know that circumference divided by diameter is pi', 'For any circle, the circumference divided by the diameter is closest to which number?', '["6.28","3.14","1.57","0.32"]', '3.14', '3.14', 'The ratio of circumference to diameter is the same for every circle. It is called $\pi$, about 3.14.', 'checked', '{"lint":[],"solve":{"answer":"3.14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C/d = pi = 3.14159..., closest to 3.14. Others: 0.32 (about 1/pi), 1.57 (pi/2), 6.28 (2 pi).","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c94c2505-6e27-4730-8266-6c1047b907dd', 'NC26.7.RPR.3', 1, 'numeric', 'Find circumference from diameter', 'A circle has a diameter of 10 centimeters. Use 3.14 for $\pi$. What is its circumference, in centimeters?', '[]', '31.4', '3.14*10', 'Circumference $= \pi \times d = 3.14 \times 10 = 31.4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"31.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = pi d = 3.14 x 10 = 31.4 cm.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adec6877-392f-4a44-822c-278c9a8492ea', 'NC26.7.RPR.3', 2, 'choice', 'Convert a circle graph percent to degrees', 'In a circle graph, one sector shows 35% of the data. How many degrees is the angle of that sector?', '["35","63","126","12.6"]', '126', '35/100*360', 'The whole circle is 360 degrees. 35% of 360 is $0.35 \times 360 = 126$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.35 x 360 = 126 degrees.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
