INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a288427-590d-4ab3-b0b7-c7940128e802', 'NC26.7.RPR.3', 2, 'numeric', 'Find circumference from radius', 'A circular rug has a radius of 4.5 feet. Use 3.14 for $\pi$. What is the distance around the rug, in feet?', '[]', '28.26', '2*3.14*4.5', 'The distance around is the circumference: $2 \times \pi \times r = 2 \times 3.14 \times 4.5 = 28.26$ feet.', 'checked', '{"lint":[],"solve":{"answer":"28.26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r = 2 x 3.14 x 4.5 = 3.14 x 9 = 28.26 ft.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
