INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82aff4c0-9f09-4026-bf44-354141118b8a', 'NC26.7.RPR.3', 2, 'numeric', 'Find diameter from circumference', 'The circumference of a circle is 47.1 centimeters. Use 3.14 for $\pi$. What is the diameter, in centimeters?', '[]', '15', '47.1/3.14', 'Since $C = \pi d$, the diameter is $d = C \div \pi = 47.1 \div 3.14 = 15$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = C/pi = 47.1/3.14 = 15 cm (3.14 x 15 = 47.1).","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ee15c1f-5d3d-4dac-b0a5-16503842f03d', 'NC26.7.RPR.3', 3, 'numeric', 'Use a circle graph sector to find a count', 'In a survey of 240 students, a circle graph shows their favorite sports. The sector for soccer measures 75 degrees. How many of the students chose soccer?', '[]', '50', '75/360*240', 'Soccer is $\frac{75}{360}$ of the circle, so $\frac{75}{360} \times 240 = 50$ students.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fraction = 75/360 = 5/24. 240 x 5/24 = 50 students.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2b68e76-8532-4f30-8059-cdca479fa76d', 'NC26.7.RPR.3', 3, 'numeric', 'Use circumference to count turns of a wheel', 'A wheel has a diameter of 60 centimeters. Use 3.14 for $\pi$. How many complete turns does the wheel make while rolling 1884 centimeters in a straight line?', '[]', '10', '1884/(3.14*60)', 'One turn moves the wheel one circumference: $3.14 \times 60 = 188.4$ centimeters. The number of turns is $1884 \div 188.4 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = circumference = 3.14 x 60 = 188.4 cm. 1884/188.4 = 10 complete turns.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3266fc4f-f427-4441-9d1e-2789405cc385', 'NC26.7.RPR.3', 3, 'choice', 'Find radius from circumference', 'The circumference of a circle is 18.84 centimeters. Use 3.14 for $\pi$. What is the radius, in centimeters?', '["3","6","59.16","9.42"]', '3', '18.84/(2*3.14)', '$C = 2\pi r$, so $r = C \div (2 \times 3.14) = 18.84 \div 6.28 = 3$ centimeters. (6 is the diameter.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 18.84/3.14 = 6, r = d/2 = 3 cm.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7741f1e-9f47-49d1-a0ab-70837de864f0', 'NC26.7.ANR.1', 1, 'numeric', 'Subtract integers', 'Evaluate $-8 - (-5)$.', '[]', '-3', '(-8)-(-5)', 'Subtracting $-5$ is the same as adding 5: $-8 + 5 = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-8 - (-5) = -8 + 5 = -3.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
