VALUES ('40944651-e3d0-4eea-b5c6-0e927706edcb', 'NC26.7.ANR.1', 1, 'choice', 'Convert a fraction to a decimal', 'Which decimal is equal to $\frac{3}{8}$?', '["0.125","0.375","0.38","3.8"]', '0.375', '3/8', 'Divide 3 by 8: $3 \div 8 = 0.375$.', 'checked', '{"lint":[],"solve":{"answer":"0.375","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 3 / 8 = 0.375.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
