INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af5142ff-b3a9-4bb4-8538-e741f6fcd81e', 'NC26.7.ANR.1', 1, 'numeric', 'Add fractions with different signs', 'Evaluate $-\frac{3}{4} + \frac{1}{2}$.', '[]', '-1/4', '-3/4+1/2', 'Use a common denominator: $-\frac{3}{4} + \frac{2}{4} = -\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3/4 + 2/4 = -1/4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
