INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8bef645-0e1f-4843-9fa4-ff216390a81f', 'NC26.7.ANR.1', 2, 'numeric', 'Divide fractions with a negative', 'Evaluate $\left(-\frac{2}{3}\right) \div \frac{4}{9}$.', '[]', '-3/2', '(-2/3)/(4/9)', 'Multiply by the reciprocal: $-\frac{2}{3} \times \frac{9}{4} = -\frac{18}{12} = -\frac{3}{2}$, or $-1\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2/3) x (9/4) = -18/12 = -3/2.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
