INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2746b658-6d89-4a1c-9685-e00b6c5a1c3f', 'NC26.7.ANR.1', 2, 'choice', 'Tell which fractions are repeating decimals', 'Which fraction is equal to a repeating decimal instead of a terminating decimal?', '["$\\frac{3}{8}$","$\\frac{7}{20}$","$\\frac{5}{12}$","$\\frac{9}{25}$"]', '$\frac{5}{12}$', NULL, '$\frac{3}{8} = 0.375$, $\frac{7}{20} = 0.35$ and $\frac{9}{25} = 0.36$ all end. $\frac{5}{12} = 0.41666\ldots$ never ends, because 12 has a factor of 3 that cannot be removed to make a power of 10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375, 7/20 = 0.35, 9/25 = 0.36 all terminate (denominators only 2s and 5s). 5/12 = 0.41666... repeats (factor 3 in denominator).","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce1ba10b-342d-46f7-8893-f241d26566c3', 'NC26.7.ANR.1', 2, 'numeric', 'Multiply decimals with different signs in context', 'The temperature changes by $-1.5$ degrees each hour for 2.4 hours. What is the total change in temperature, in degrees?', '[]', '-3.6', '(-1.5)*2.4', 'Multiply: $(-1.5) \times 2.4$. Since $1.5 \times 2.4 = 3.6$ and one factor is negative, the product is $-3.6$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"-3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1.5 x 2.4 = -3.6 degrees.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
