INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25f9806c-3ed1-4b1d-b0cc-350ac46778bf', 'NC26.7.ANR.1', 3, 'numeric', 'Evaluate with mixed numbers and several operations', 'Use the order of operations to find the value of $2\frac{1}{2} - 3\frac{3}{4} \div \left(-1\frac{1}{2}\right)$.', '[]', '5', '5/2-(15/4)/(-3/2)', 'Divide first: $3\frac{3}{4} \div \left(-1\frac{1}{2}\right) = \frac{15}{4} \times \left(-\frac{2}{3}\right) = -\frac{5}{2}$. Then $2\frac{1}{2} - \left(-\frac{5}{2}\right) = \frac{5}{2} + \frac{5}{2} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Division first: 3 3/4 / (-1 1/2) = (15/4) x (-2/3) = -30/12 = -5/2. Then 2 1/2 - (-5/2) = 5/2 + 5/2 = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af598a9-f169-4c9f-8a71-020501851feb', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'Which is the best estimate of $\frac{-39.8 \times 2.1}{4.2}$?', '["-20","-80","20","-200"]', '-20', '-20', 'Round: $-39.8 \approx -40$ and $2.1 \approx 2$, and $4.2 \approx 4$. Then $\frac{-40 \times 2}{4} = -20$. The answer is negative, and about 20 in size.', 'checked', '{"lint":[],"solve":{"answer":"-20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.1/4.2 = 1/2, so value = -39.8/2 = -19.9, about -20. Estimate: -40 x 2 / 4 = -20.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72f10b05-972f-47b5-906e-8310e6b7e7ba', 'NC26.7.ANR.1', 3, 'numeric', 'Solve a problem with mixed rational numbers', 'A diver is at $-12.5$ meters, which is 12.5 meters below the surface. She rises $3\frac{1}{4}$ meters and then dives down 5.75 meters. What is her final position, in meters?', '[]', '-15', '-12.5+3.25-5.75', 'Start at $-12.5$. Rising adds: $-12.5 + 3.25 = -9.25$. Diving subtracts: $-9.25 - 5.75 = -15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-12.5 + 3.25 = -9.25; -9.25 - 5.75 = -15 meters.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbd83b50-7a18-4409-8a6f-810a53034d43', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which expression is equivalent to $4x + 7 + 2x - 3$?', '["$6x + 4$","$13x$","$6x + 10$","$6x - 4$"]', '$6x + 4$', NULL, 'Combine the $x$ terms: $4x + 2x = 6x$. Combine the numbers: $7 - 3 = 4$. The result is $6x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 2x = 6x; 7 - 3 = 4. So 6x + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b65b4f4-55c6-495b-bbea-b17f29480c0a', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'The expression $3(x + 4)$ is equivalent to $3x + k$. What is the value of $k$?', '[]', '12', '3*4', 'Distribute: $3(x + 4) = 3x + 3 \times 4 = 3x + 12$, so $k = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 4) = 3x + 12, so k = 12.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf151c3-713f-4b6d-9f40-1921aadeb945', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $6x + 9$?', '["$6(x + 3)$","$3(2x + 9)$","$3(x + 3)$","$3(2x + 3)$"]', '$3(2x + 3)$', NULL, '6 and 9 have the common factor 3. $6x \div 3 = 2x$ and $9 \div 3 = 3$, so $6x + 9 = 3(2x + 3)$. Multiplying back gives $6x + 9$.', 'checked', '{"lint":[],"solve":{"answer":"$3(2x + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+3) = 3x+9 no; 3(2x+9) = 6x+27 no; 3(2x+3) = 6x+9 yes; 6(x+3) = 6x+18 no.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80fc6ada-e220-4b6b-bd9c-16a84c850639', 'NC26.7.ANR.2', 2, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $2(3x - 4) + 5x$?', '["$11x - 4$","$11x - 8$","$11x + 8$","$x - 8$"]', '$11x - 8$', NULL, 'Distribute: $2(3x - 4) = 6x - 8$. Add $5x$: $6x + 5x - 8 = 11x - 8$.', 'checked', '{"lint":[],"solve":{"answer":"$11x - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3x - 4) = 6x - 8; plus 5x gives 11x - 8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d65d561-3dfe-493d-8cb4-b02ac3332335', 'NC26.7.ANR.2', 2, 'numeric', 'Distribute a negative factor', 'The expression $-2(x - 3) + 4x$ is equivalent to $2x + k$. What is the value of $k$?', '[]', '6', '(-2)*(-3)', 'Distribute: $-2(x - 3) = -2x + 6$. Then $-2x + 6 + 4x = 2x + 6$, so $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(x - 3) = -2x + 6; plus 4x gives 2x + 6, so k = 6.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f843ccb6-cea1-470c-8557-c47d31625ddb', 'NC26.7.ANR.2', 2, 'numeric', 'Factor a linear expression and read the factors', 'The expression $12x + 18$ can be written as $6(ax + b)$. What is the value of $a + b$?', '[]', '5', '12/6+18/6', '$12x \div 6 = 2x$ and $18 \div 6 = 3$, so $12x + 18 = 6(2x + 3)$. Then $a = 2$, $b = 3$ and $a + b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(ax + b) = 6ax + 6b = 12x + 18, so a = 2, b = 3 (unique). a + b = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('109e2fb4-78d1-409c-9d44-abf53749af99', 'NC26.7.ANR.2', 3, 'choice', 'Write a total in context as one simplified expression', 'Tickets to a show cost $t$ dollars each, and every purchase has a 2-dollar service fee. Mia buys 3 tickets and Sam buys 4 tickets, in separate purchases. Which expression is equivalent to the total they pay together, in dollars?', '["$7t + 2$","$12t + 4$","$7t + 4$","$7t$"]', '$7t + 4$', NULL, 'Mia pays $3t + 2$ and Sam pays $4t + 2$. Together: $(3t + 2) + (4t + 2) = 7t + 4$. Each of the two purchases has its own fee, so the fees add to 4.', 'checked', '{"lint":[],"solve":{"answer":"$7t + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia pays 3t + 2, Sam pays 4t + 2 (each purchase has its own fee). Total = 7t + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bc7f811-76c6-4032-8564-77d08db4ba61', 'NC26.7.ANR.2', 3, 'numeric', 'Simplify an expression with two distributions', 'The expression $3(2x - 5) - 4(x - 2)$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '-7', '3*(-5)-4*(-2)', '$3(2x - 5) = 6x - 15$ and $-4(x - 2) = -4x + 8$. Add: $6x - 4x - 15 + 8 = 2x - 7$. So $b = -7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x - 5) = 6x - 15; -4(x - 2) = -4x + 8. Sum = 2x - 7, so b = -7.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fe28c6b-d961-4ff2-8c5e-90c7f1c0ee50', 'NC26.7.ANR.2', 3, 'choice', 'Simplify an expression with fraction coefficients', 'Which expression is equivalent to $\frac{1}{2}(6x - 10) + \frac{3}{4}(8x + 4)$?', '["$9x - 7$","$9x + 2$","$9x - 1$","$9x - 2$"]', '$9x - 2$', NULL, '$\frac{1}{2}(6x - 10) = 3x - 5$ and $\frac{3}{4}(8x + 4) = 6x + 3$. Add: $3x + 6x - 5 + 3 = 9x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$9x - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(6x - 10) = 3x - 5; (3/4)(8x + 4) = 6x + 3. Sum = 9x - 2.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee6466c9-755e-4866-9bdb-417131bc6832', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'Solve for $x$: $3x + 5 = 20$.', '[]', '5', '(20-5)/3', 'Subtract 5 from both sides: $3x = 15$. Divide by 3: $x = 5$. Check: $3 \times 5 + 5 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
