INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6425c32e-261a-43ac-b28f-415b9cf4c033', 'NC26.7.ANR.3', 1, 'choice', 'Solve a one-step inequality', 'Which inequality shows all the solutions of $x + 7 < 12$?', '["$x < 5$","$x > 5$","$x < 19$","$x > 19$"]', '$x < 5$', NULL, 'Subtract 7 from both sides: $x < 5$. The direction of the inequality does not change.', 'checked', '{"lint":[],"solve":{"answer":"$x < 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract 7: x < 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
