INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4840c986-bcca-4616-80ff-286248fd0c30', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation with division', 'Solve for $x$: $\frac{x}{4} - 3 = 2$.', '[]', '20', '(2+3)*4', 'Add 3 to both sides: $\frac{x}{4} = 5$. Multiply both sides by 4: $x = 20$. Check: $20 \div 4 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/4 = 5, x = 20.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
