INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('637493d2-8ea4-4acf-a6cf-ec288653f464', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with parentheses', 'Solve for $x$: $4(x - 3) = 28$.', '[]', '10', '28/4+3', 'Divide both sides by 4: $x - 3 = 7$. Add 3: $x = 10$. Check: $4 \times 7 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 3 = 7, x = 10. Check: 4 x 7 = 28.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
