INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05703b48-942d-4406-83f7-a5316572714c', 'NC26.7.ANR.3', 2, 'choice', 'Solve a two-step inequality', 'What are all the solutions of $2x + 7 > 15$?', '["$x > 11$","$x > 6$","$x < 4$","$x > 4$"]', '$x > 4$', NULL, 'Subtract 7: $2x > 8$. Divide by 2: $x > 4$. Dividing by a positive number keeps the direction of the inequality.', 'checked', '{"lint":[],"solve":{"answer":"$x > 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x > 8, x > 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
