INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4adda3f8-acef-4690-8055-49d21753d1cc', 'NC26.7.ANR.3', 2, 'numeric', 'Write and solve an equation from a situation', 'Jo has 15 dollars and saves 6 dollars each week. After how many weeks will she have exactly 63 dollars?', '[]', '8', '(63-15)/6', 'Let $w$ be the number of weeks: $15 + 6w = 63$. Subtract 15: $6w = 48$. Divide by 6: $w = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 6w = 63, 6w = 48, w = 8 weeks.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d68ced4c-c735-4810-b2cc-92fc2dc9ff77', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with a fraction coefficient', 'Solve for $x$: $\frac{2}{3}x - 5 = 7$.', '[]', '18', '(7+5)*3/2', 'Add 5: $\frac{2}{3}x = 12$. Multiply by the reciprocal $\frac{3}{2}$: $x = 12 \times \frac{3}{2} = 18$. Check: $\frac{2}{3} \times 18 - 5 = 12 - 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)x = 12, x = 12 x 3/2 = 18.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('516c2b2d-79db-45da-8924-545e3013d198', 'NC26.7.ANR.3', 3, 'choice', 'Choose the inequality that fits a situation', 'A taxi ride costs a 3-dollar starting fee plus 2 dollars for each mile. Kim has at most 25 dollars to spend. Which inequality can be used to find the number of miles $m$ she can ride?', '["$3 + 2m \\ge 25$","$2 + 3m \\le 25$","$3 + 2m = 25$","$3 + 2m \\le 25$"]', '$3 + 2m \le 25$', NULL, 'The cost is the fee plus 2 dollars per mile: $3 + 2m$. "At most 25 dollars" means the cost is less than or equal to 25, so $3 + 2m \le 25$.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 2m \\le 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = 3 + 2m, at most 25 means cost <= 25: 3 + 2m <= 25.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3542622a-e99e-4ffa-be15-543600dc436f', 'NC26.7.ANR.3', 3, 'choice', 'Find a solution of an inequality with parentheses', 'Which value is a solution of $3(x - 2) > 12$?', '["3","4","6","7"]', '7', '7', 'Divide by 3: $x - 2 > 4$. Add 2: $x > 6$. Only 7 is greater than 6. (At $x = 6$ the two sides are equal, $12 > 12$ is false.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 2 > 4, x > 6. Options: 6 (gives 12, not > 12), 4, 3 no; 7 gives 15 > 12 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c6386e2-123a-4248-b64f-10a57ba7bbbb', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a triangle', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area, in square centimeters?', '[]', '30', '10*6/2', 'Area of a triangle $= \frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (1/2)(10)(6) = 30.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
