INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a2a6051-d35f-40ce-a628-db0de21bc846', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a circle from the radius', 'A circle has a radius of 5 centimeters. Use 3.14 for $\pi$. What is its area, in square centimeters?', '[]', '78.5', '3.14*5^2', 'Area $= \pi r^2 = 3.14 \times 5 \times 5 = 78.5$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"78.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3.14 x 25 = 78.5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
