INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('600cdb3e-fb72-409a-80d2-5dcfeb5e6e75', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle from the diameter', 'A circle has a diameter of 8 centimeters. Use 3.14 for $\pi$. What is its area, in square centimeters?', '["200.96","25.12","50.24","12.56"]', '50.24', '3.14*4^2', 'The radius is half the diameter: $8 \div 2 = 4$. Area $= 3.14 \times 4^2 = 3.14 \times 16 = 50.24$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"50.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4, A = 3.14 x 16 = 50.24.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e26dba8-14e6-4a4d-87dd-11dc43736fec', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a trapezoid', 'A trapezoid has parallel sides of 6 centimeters and 10 centimeters, and a height of 4 centimeters. What is its area, in square centimeters?', '[]', '32', '(6+10)/2*4', 'Area $= \frac{1}{2}(b_1 + b_2) \times h = \frac{1}{2}(6 + 10) \times 4 = 8 \times 4 = 32$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (6 + 10)/2 x 4 = 8 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
