INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01311a2b-8c50-417a-9273-c34f374ab49e', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by subtraction', 'A rectangular garden is 12 meters long and 9 meters wide. A rectangular pond that is 4 meters by 3 meters sits inside the garden. How many square meters of the garden are not covered by the pond?', '[]', '96', '12*9-4*3', 'Garden: $12 \times 9 = 108$ square meters. Pond: $4 \times 3 = 12$ square meters. Not covered: $108 - 12 = 96$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Garden 12 x 9 = 108; pond 4 x 3 = 12. 108 - 12 = 96.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e55d7485-41db-4951-848b-9735273a443f', 'NC26.7.SGMR.1', 2, 'numeric', 'Relate circumference, radius and area', 'The circumference of a circle is 37.68 centimeters. Use 3.14 for $\pi$. What is the area of the circle, in square centimeters?', '[]', '113.04', '3.14*(37.68/(2*3.14))^2', 'First find the radius from $C = 2\pi r$: $r = 37.68 \div (2 \times 3.14) = 37.68 \div 6.28 = 6$ centimeters. Then area $= 3.14 \times 6^2 = 3.14 \times 36 = 113.04$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"113.04","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 37.68/3.14 = 12, r = 6. A = 3.14 x 36 = 113.04.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a34c7f9b-aaeb-4403-a9ca-2d6314a72798', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a rectangle with a half circle on top', 'A window is a rectangle 6 feet wide and 8 feet tall, with a half circle on top. The half circle''s diameter is the 6-foot width of the window. Use 3.14 for $\pi$. What is the total area of the window, in square feet?', '[]', '62.13', '6*8+3.14*3^2/2', 'Rectangle: $6 \times 8 = 48$ square feet. The half circle has radius $6 \div 2 = 3$ feet, so its area is $\frac{1}{2} \times 3.14 \times 3^2 = 14.13$ square feet. Total: $48 + 14.13 = 62.13$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"62.13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 8 = 48. Half circle r = 3: (1/2)(3.14)(9) = 14.13. Total = 62.13.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9946127-8080-4bb1-a340-d8716cbb1b5d', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a ring around a circle', 'A circular pond has a radius of 4 meters. A path 2 meters wide goes all the way around the pond. Use 3.14 for $\pi$. What is the area of the path, in square meters?', '[]', '62.8', '3.14*6^2-3.14*4^2', 'The pond and path together form a circle of radius $4 + 2 = 6$ meters: $3.14 \times 36 = 113.04$. The pond alone: $3.14 \times 16 = 50.24$. The path: $113.04 - 50.24 = 62.8$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer radius 4 + 2 = 6. Path = 3.14 x (36 - 16) = 3.14 x 20 = 62.8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8950f60d-eb52-4047-836f-30a22ecf4f37', 'NC26.7.SGMR.1', 3, 'choice', 'How doubling the radius changes the area of a circle', 'One pizza has a radius of 6 inches and another has a radius of 12 inches. The area of the larger pizza is how many times the area of the smaller pizza?', '["4","2","8","6"]', '4', '(12/6)^2', 'The area is $\pi r^2$. The radius doubles, so the area is multiplied by $2^2 = 4$. Check: $\pi \times 12^2 = 144\pi$ and $\pi \times 6^2 = 36\pi$, and $144 \div 36 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Areas scale with r^2: (12/6)^2 = 4. (144 pi / 36 pi = 4.)","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0391ce-1839-47ce-999d-fd1d4dc216ba', 'NC26.7.SGMR.2', 1, 'numeric', 'Volume from base area and height', 'The base of a right prism has an area of 12 square centimeters. The prism is 7 centimeters tall. What is its volume in cubic centimeters?', '[]', '84', '12*7', 'A right prism is the base layer repeated for the whole height. Volume = area of base $\times$ height = $12 \times 7 = 84$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = base area x height = 12 x 7 = 84.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44f62f3b-6391-4e0b-af81-edf3b800e6b0', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a cube', 'A cube has edges that are each 5 centimeters long. What is its surface area in square centimeters?', '["125","150","30","100"]', '150', '6*5*5', 'A cube has 6 faces. Each face is a square with area $5 \times 5 = 25$ square centimeters. Surface area = $6 \times 25 = 150$. (125 is the volume, 30 is $6 \times 5$, and 100 counts only 4 faces.)', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 faces, each 5 x 5 = 25; SA = 6 x 25 = 150.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('424cb64e-15d5-4845-b6b2-dedefa028864', 'NC26.7.SGMR.2', 1, 'numeric', 'Find the height from the volume', 'A rectangular box has a volume of 90 cubic centimeters. Its base measures 6 centimeters by 5 centimeters. How tall is the box in centimeters?', '[]', '3', '90/(6*5)', 'The base has area $6 \times 5 = 30$ square centimeters. Volume = base area $\times$ height, so height = $90 \div 30 = 3$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area 6 x 5 = 30; height = 90 / 30 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
