INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbc0d3ed-b965-4771-9355-215870d9fa9a', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a triangular prism', 'The two triangular faces of a prism are each a triangle with base 6 centimeters and height 4 centimeters. The distance between the two triangular faces is 10 centimeters. What is the volume of the prism in cubic centimeters?', '["240","60","120","12"]', '120', '1/2*6*4*10', 'The area of one triangular base is $\frac{1}{2} \times 6 \times 4 = 12$ square centimeters. Volume = base area $\times$ length = $12 \times 10 = 120$ cubic centimeters. (240 forgets the one half; 12 is only the area of the base.)', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle area = 1/2 x 6 x 4 = 12; V = 12 x 10 = 120.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb9094c7-dffd-48b3-b878-d88037e29e39', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a cylinder', 'A can is shaped like a cylinder with a radius of 3 centimeters and a height of 10 centimeters. Use 3.14 for $\pi$. What is its volume in cubic centimeters?', '[]', '282.6', '3.14*3^2*10', 'The base is a circle with area $3.14 \times 3^2 = 3.14 \times 9 = 28.26$ square centimeters. Volume = base area $\times$ height = $28.26 \times 10 = 282.6$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"282.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = pi r^2 h = 3.14 x 9 x 10 = 282.6.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd1e7aa0-d241-44e2-8c12-aff2dad62263', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a triangular prism', 'A prism has two triangular faces. Each is a right triangle with sides of 3 centimeters, 4 centimeters and 5 centimeters. The prism is 10 centimeters long (the distance between the two triangles). What is its total surface area in square centimeters?', '["132","120","126","144"]', '132', '2*(1/2*3*4)+(3+4+5)*10', 'Each triangle has area $\frac{1}{2} \times 3 \times 4 = 6$, so the two triangles give 12 square centimeters. The three rectangles are $3 \times 10 = 30$, $4 \times 10 = 40$ and $5 \times 10 = 50$, which give 120. Total = $12 + 120 = 132$.', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangles: 2 x (1/2 x 3 x 4) = 12. Three rectangles: (3 + 4 + 5) x 10 = 120. Total 132.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('216befba-31b1-4172-b4a0-1f851ea67c3c', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A solid is made by placing a rectangular prism that is 5 centimeters by 6 centimeters by 3 centimeters on top of a larger rectangular prism that is 10 centimeters by 6 centimeters by 4 centimeters. What is the volume of the whole solid in cubic centimeters?', '[]', '330', '5*6*3+10*6*4', 'Top prism: $5 \times 6 \times 3 = 90$. Bottom prism: $10 \times 6 \times 4 = 240$. Whole solid: $90 + 240 = 330$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"330","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top: 5 x 6 x 3 = 90. Bottom: 10 x 6 x 4 = 240. Total 330 (volume does not depend on orientation).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45a06e81-e039-4902-9e6d-57b3d2a8ef1f', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a closed cylinder', 'A closed cylinder (it has a top and a bottom) has a radius of 2 centimeters and a height of 5 centimeters. Use 3.14 for $\pi$. What is its surface area in square centimeters?', '[]', '87.92', '2*3.14*2^2+2*3.14*2*5', 'The top and bottom are two circles: $2 \times 3.14 \times 2^2 = 25.12$. The side unrolls into a rectangle as wide as the distance around the circle ($2 \times 3.14 \times 2 = 12.56$) and 5 tall: $12.56 \times 5 = 62.8$. Total = $25.12 + 62.8 = 87.92$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"87.92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two circles: 2 x 3.14 x 4 = 25.12. Curved side: 2 x 3.14 x 2 x 5 = 62.8. Total 87.92.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e59c5cb3-e072-456e-adfa-361fe0200cac', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a solid with a hole', 'A solid block is a rectangular prism that is 8 centimeters by 6 centimeters by 5 centimeters. A square hole 2 centimeters by 2 centimeters is cut all the way through the 5-centimeter thickness. What is the volume of the solid that is left, in cubic centimeters?', '[]', '220', '8*6*5-2*2*5', 'The full block has volume $8 \times 6 \times 5 = 240$. The hole removes a prism $2 \times 2 \times 5 = 20$. What is left: $240 - 20 = 220$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"220","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Block 8 x 6 x 5 = 240. Hole 2 x 2 x 5 = 20. Left 240 - 20 = 220.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b2ebdc0-07b3-4868-8413-248fadeea553', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles', 'Two angles are complementary. One of them measures $35^\circ$. What is the measure of the other angle in degrees?', '[]', '55', '90-35', 'Complementary angles add to $90^\circ$. The other angle is $90 - 35 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - 35 = 55.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e15aee17-a992-4970-a598-7cab23f36d5e', 'NC26.7.SGMR.3', 1, 'choice', 'Supplementary angles', 'Two angles are supplementary. One of them measures $112^\circ$. What is the measure of the other angle in degrees?', '["68","22","248","112"]', '68', '180-112', 'Supplementary angles add to $180^\circ$, so the other angle is $180 - 112 = 68$ degrees. (22 subtracts from 90, 248 subtracts from 360, and 112 assumes the angles are equal.)', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 112 = 68.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4938336f-68b9-421f-a8dc-cf4dea4a53e6', 'NC26.7.SGMR.3', 1, 'numeric', 'Vertical angles', 'Two straight lines cross and form four angles. One of the angles measures $65^\circ$. What is the measure of the angle directly across from it (its vertical angle) in degrees?', '[]', '65', '65', 'Vertical angles, the ones directly across from each other where two lines cross, are equal. The angle is also $65^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are equal: 65.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b1d0d1-e6ff-49b7-a9d8-209c4a800b01', 'NC26.7.SGMR.3', 2, 'numeric', 'Equation for complementary angles', 'Two complementary angles measure $3x^\circ$ and $(2x + 10)^\circ$. What is the measure of the larger angle in degrees?', '[]', '48', '3*(90-10)/5', 'Complementary angles add to 90, so $3x + 2x + 10 = 90$. Then $5x = 80$ and $x = 16$. The angles are $3 \times 16 = 48$ and $2 \times 16 + 10 = 42$. The larger angle is 48 degrees.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2x + 10 = 90, 5x = 80, x = 16. Angles 48 and 42. Larger is 48.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('591750a4-9689-42dc-8f3d-9b2bd856b202', 'NC26.7.SGMR.3', 2, 'numeric', 'Equation for vertical angles', 'Two lines cross. A pair of vertical angles measure $(4x + 5)^\circ$ and $(6x - 15)^\circ$. What is the measure of each of these two angles in degrees?', '[]', '45', '4*((5+15)/2)+5', 'Vertical angles are equal, so $4x + 5 = 6x - 15$. Then $20 = 2x$ and $x = 10$. Each angle measures $4 \times 10 + 5 = 45$ degrees. Check: $6 \times 10 - 15 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 5 = 6x - 15, 20 = 2x, x = 10. Each angle 4(10) + 5 = 45 = 6(10) - 15.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b426014d-93c1-4576-abb4-36d8bd1c2791', 'NC26.7.SGMR.3', 2, 'choice', 'Angles that form a straight line', 'Three adjacent angles together form a straight line. Two of them measure $50^\circ$ and $75^\circ$, and the third measures $x^\circ$. What is $x$?', '["125","15","235","55"]', '55', '180-50-75', 'Angles that form a straight line add to $180^\circ$. So $50 + 75 + x = 180$, and $x = 180 - 125 = 55$. (125 is the sum of the two known angles, 235 subtracts that from 360, and 15 subtracts from 90.)', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 + 75 + x = 180, x = 55.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e33d8aaf-1383-4e03-9149-300c7399dec9', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles in a ratio', 'Two lines cross. One of the angles formed is 4 times as large as an angle next to it. What is the measure of the smaller angle in degrees?', '[]', '36', '180/(1+4)', 'Two angles next to each other where lines cross add to $180^\circ$. If the smaller angle is $x$, the larger is $4x$, so $x + 4x = 180$. Then $5x = 180$ and $x = 36$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles at a crossing are supplementary: x + 4x = 180, x = 36 (other is 144).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a4fc3cf-e92a-4728-939c-11fd0eead808', 'NC26.7.SGMR.3', 3, 'numeric', 'Supplement and complement together', 'The supplement of an angle is $20^\circ$ more than twice the angle''s complement. What is the measure of the angle in degrees?', '[]', '20', '(2*90+20)-180', 'Let the angle be $x$. Its supplement is $180 - x$ and its complement is $90 - x$. So $180 - x = 2(90 - x) + 20 = 200 - 2x$. Adding $2x$ to both sides: $180 + x = 200$, so $x = 20$. Check: supplement 160, complement 70, and $2 \times 70 + 20 = 160$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - x = 2(90 - x) + 20 = 200 - 2x, so x = 20. Check: supplement 160, complement 70, 2 x 70 + 20 = 160.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5162135-d0e0-4b37-a9c8-a0d8cd42ee54', 'NC26.7.SGMR.3', 3, 'numeric', 'Unknown angle at an intersection', 'Lines $AB$ and $CD$ cross at point $O$. Angle $AOC$ measures $(3x + 10)^\circ$ and angle $COB$ measures $(2x + 20)^\circ$. What is the measure of angle $AOD$ in degrees?', '[]', '80', '180-(3*((180-30)/5)+10)', 'Angles $AOC$ and $COB$ are next to each other along the straight line $AB$, so they add to 180: $3x + 10 + 2x + 20 = 180$. Then $5x = 150$ and $x = 30$, so angle $AOC$ is $3 \times 30 + 10 = 100$ degrees. Angle $AOD$ is next to angle $AOC$ along the straight line $CD$, so it measures $180 - 100 = 80$ degrees. (It is also the vertical angle of $COB$, which is $2 \times 30 + 20 = 80$.)', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC and COB form straight angle AOB: 3x + 10 + 2x + 20 = 180, x = 30. AOC = 100, COB = 80. AOD is vertical to COB (OA opposite OB, OD opposite OC), so AOD = 80 (also 180 - AOC).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08349673-5ad4-4f5f-85de-6f3662a7340c', 'NC26.7.RD.1', 1, 'numeric', 'Theoretical probability of one event', 'A bag has 3 red marbles, 5 blue marbles and 2 green marbles. One marble is drawn at random. What is the probability that it is green? Write your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 5 + 2 = 10$ marbles and 2 of them are green. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 marbles, 2 green: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
