INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d1a249a-5f2f-46fe-b0dd-8366def5c8c8', 'NC26.7.RD.1', 1, 'numeric', 'Size of a sample space', 'A fair coin is flipped and a fair six-sided die is rolled. How many outcomes are in the sample space?', '[]', '12', '2*6', 'The coin can land 2 ways and the die can land 6 ways. Every coin result pairs with every die result: $2 \times 6 = 12$ outcomes, such as (heads, 1) and (tails, 6).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 6 = 12 outcomes.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53c9a2c4-f81c-4352-861d-b71295135871', 'NC26.7.RD.1', 1, 'choice', 'Probability of two heads', 'A fair coin is flipped two times. What is the probability of getting two heads?', '["1/2","1/3","1/4","3/4"]', '1/4', '1/4', 'List the equally likely outcomes: HH, HT, TH, TT. Only HH is two heads, so the probability is $\frac{1}{4}$. (1/3 wrongly counts HT and TH as one outcome; 3/4 is the chance of at least one head.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HH, HT, TH, TT: 1 of 4 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29038d30-2b12-42d6-9ccc-d60c95c1f8c0', 'NC26.7.RD.1', 2, 'numeric', 'List a sample space of three flips', 'A fair coin is flipped 3 times. What is the probability of getting exactly 1 head? Write your answer as a fraction.', '[]', '3/8', '3/8', 'List all 8 equally likely outcomes: HHH, HHT, HTH, HTT, THH, THT, TTH, TTT. Exactly one head happens in HTT, THT and TTH, which is 3 outcomes. The probability is $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 outcomes; exactly one head: HTT, THT, TTH = 3. 3/8.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('443cb9e2-6c9e-4b0e-8f52-00b00531aab8', 'NC26.7.RD.1', 2, 'numeric', 'Compound event with replacement', 'A bag has 2 red marbles and 3 blue marbles. A marble is drawn at random, its color is noted, and it is put back in the bag. Then a second marble is drawn. What is the probability that both marbles are blue? Write your answer as a fraction.', '[]', '9/25', '3/5*3/5', 'Because the first marble is put back, each draw has the same chance of blue: $\frac{3}{5}$. The chance of two blues is $\frac{3}{5} \times \frac{3}{5} = \frac{9}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"9/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With replacement: 3/5 x 3/5 = 9/25.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('568c7602-38a2-433f-9da2-e2096b6245d8', 'NC26.7.RD.1', 2, 'choice', 'Experiments approach theory with more trials', 'Mia flips a fair coin 10 times and gets 7 heads. Then she flips it 1,000 times. Which statement is true?', '["The fraction of heads will probably be close to $\\frac{1}{2}$","The fraction of heads will probably stay close to $\\frac{7}{10}$","The fraction of heads will be exactly $\\frac{1}{2}$","The fraction of heads will probably be below $\\frac{1}{2}$ to even things out"]', 'The fraction of heads will probably be close to $\frac{1}{2}$', NULL, 'A fair coin has a theoretical probability of $\frac{1}{2}$ for heads. With many more flips, the fraction of heads usually gets close to $\frac{1}{2}$, although it will rarely be exactly $\frac{1}{2}$. The coin does not remember the first 10 flips, so it does not try to even things out.', 'checked', '{"lint":[],"solve":{"answer":"The fraction of heads will probably be close to $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fair coin: with many trials the relative frequency approaches 1/2; it is not guaranteed exact, and the coin has no memory. Choose ''probably close to 1/2''.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3cc4411-0726-45bc-94a0-f9bc52b9c2b4', 'NC26.7.RD.1', 3, 'numeric', 'Compound event without replacement', 'A bag has 3 red marbles and 2 blue marbles. Two marbles are drawn at random, one after the other, and the first is NOT put back. What is the probability that both marbles are red? Write your answer as a fraction.', '[]', '3/10', '3/5*2/4', 'The first marble is red with probability $\frac{3}{5}$. Then 2 red marbles remain among 4, so the second is red with probability $\frac{2}{4}$. Both red: $\frac{3}{5} \times \frac{2}{4} = \frac{6}{20} = \frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 x 2/4 = 6/20 = 3/10.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bce1a22-b1a6-4e61-b7cb-357ba686f096', 'NC26.7.RD.1', 3, 'choice', 'Compound event with unequal outcomes', 'A spinner lands on red with probability $\frac{1}{2}$, on blue with probability $\frac{1}{3}$ and on green with probability $\frac{1}{6}$. A fair coin is flipped and the spinner is spun. What is the probability of getting tails and a spinner color that is not red?', '["1/2","1/4","1/6","1/12"]', '1/4', '1/2*(1/3+1/6)', 'The chance of tails is $\frac{1}{2}$. The chance the spinner is not red is $\frac{1}{3} + \frac{1}{6} = \frac{1}{2}$. Both together: $\frac{1}{2} \times \frac{1}{2} = \frac{1}{4}$. (1/6 leaves out green, and 1/12 leaves out blue.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(tails) = 1/2. P(not red) = 1/3 + 1/6 = 1/2. Independent: 1/2 x 1/2 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67a3e9c9-3687-471c-b6cc-13e36552c807', 'NC26.7.RD.1', 3, 'choice', 'Design a simulation', 'A basketball player makes 70% of her free throws. Sam uses random digits from 0 to 9, each equally likely, to simulate one shot. Which rule matches the player?', '["Digits 0 to 7 are a made shot, and 8 and 9 are a miss","Digits 0 to 3 are a made shot, and 4 to 9 are a miss","Digits 7 to 9 are a made shot, and 0 to 6 are a miss","Digits 0 to 6 are a made shot, and 7 to 9 are a miss"]', 'Digits 0 to 6 are a made shot, and 7 to 9 are a miss', NULL, 'Of the 10 digits, 70% is 7 digits. The digits 0 to 6 are seven digits, so they stand for a made shot and the other three stand for a miss. The other rules give 80%, 40% and 30%.', 'checked', '{"lint":[],"solve":{"answer":"Digits 0 to 6 are a made shot, and 7 to 9 are a miss","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70% needs 7 of 10 digits as makes: 0-6 is 7 digits. 0-3 is 40%, 7-9 is 30%, 0-7 is 80%.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a67f78b-91c0-433d-b8fd-82b371094ae9', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'Which of these is a statistical question?', '["How many pets does each student in our class have?","How tall is the school flagpole?","How many pets does Ava have?","How many students are in Room 12 today?"]', 'How many pets does each student in our class have?', NULL, 'A statistical question expects answers that vary, so you need to collect data from many people or things. Each student in the class may have a different number of pets. The other questions each have a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How many pets does each student in our class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects variability in the answers; only ''each student in our class'' gathers varied data. The others have one answer.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('772169f9-456c-4dcf-9234-b9b4fcdd04a7', 'NC26.7.RD.2', 1, 'choice', 'Choose a representative sample', 'A school has 400 students. Which is the best way to choose 40 students to find out the favorite sport of all the students?', '["Ask the 40 students on the basketball team","Ask 40 students watching a soccer game","Choose 40 names at random from the list of all students","Ask 40 of the survey writer''s friends"]', 'Choose 40 names at random from the list of all students', NULL, 'A random sample gives every student the same chance of being chosen, so it is likely to look like the whole school. The other groups are likely to favor one sport.', 'checked', '{"lint":[],"solve":{"answer":"Choose 40 names at random from the list of all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample from the whole list is representative; the others are biased toward sports or friends.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4c75670-5aca-4e18-b7a9-8ea6cb888517', 'NC26.7.RD.2', 1, 'numeric', 'Proportion in a sample', 'In a random sample of 50 students, 20 said math is their favorite subject. What fraction of the sample said math is their favorite subject? Write your answer as a fraction.', '[]', '2/5', '20/50', 'The fraction is $\frac{20}{50}$. Dividing the top and bottom by 10 gives $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Accepting 20/50 as well as 2/5 would be fair, since the stem only asks for a fraction.","work":"20/50 = 2/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81af24f4-e7f1-457c-a362-77e17683e093', 'NC26.7.RD.2', 2, 'numeric', 'Predict a population from a sample', 'A random sample of 60 students from a school of 1,200 students was asked whether they like the new lunch menu. Of the 60 students, 45 said yes. Based on the sample, about how many of the 1,200 students like the new lunch menu?', '[]', '900', '45/60*1200', 'In the sample, $\frac{45}{60} = \frac{3}{4}$ said yes. A random sample is likely to match the whole school, so about $\frac{3}{4}$ of 1,200 students like the menu: $\frac{3}{4} \times 1200 = 900$.', 'checked', '{"lint":[],"solve":{"answer":"900","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45/60 = 3/4; 3/4 x 1200 = 900.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1379e58e-3b90-4020-abae-494bfe478a60', 'NC26.7.RD.2', 2, 'choice', 'Spot a biased sample', 'To find out how all 500 students at a school feel about a new music class, a survey is given to 100 students as they leave a band concert. Why might the results be biased?', '["100 students is too few for any survey to be fair","Students at a band concert are more likely to like music than other students","The survey should have been given to teachers instead","The students were asked as they left, not as they arrived"]', 'Students at a band concert are more likely to like music than other students', NULL, 'A sample is biased when some members of the population are more likely to be chosen or to answer a certain way. People at a band concert probably like music more than the average student. A sample of 100 out of 500 is large enough, and when they were asked does not matter.', 'checked', '{"lint":[],"solve":{"answer":"Students at a band concert are more likely to like music than other students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is drawn from concert-goers, who are more likely to favour music: selection bias.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('550e8a37-cb35-4f9c-ae13-60cad38f4775', 'NC26.7.RD.2', 2, 'choice', 'Compare two groups using fractions', 'In a random sample, 18 of 20 sixth graders and 21 of 30 seventh graders said they like the school lunch. Which group had the greater fraction who like the lunch?', '["The seventh graders","Neither; the fractions are equal","Neither; the sample sizes are different","The sixth graders"]', 'The sixth graders', NULL, 'Compare the fractions, not the counts. Sixth graders: $\frac{18}{20} = 0.9$. Seventh graders: $\frac{21}{30} = 0.7$. The sixth graders have the greater fraction, even though fewer of them were asked. Groups of different sizes can be compared using fractions or percents.', 'checked', '{"lint":[],"solve":{"answer":"The sixth graders","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sixth: 18/20 = 0.9. Seventh: 21/30 = 0.7. Sixth graders greater.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56f57a6e-3bca-46f4-ba09-d6710c08cfb5', 'NC26.7.RD.2', 3, 'numeric', 'Combine several random samples', 'A jar holds 500 marbles, some red and the rest blue. Four different random samples of 20 marbles each have 4, 6, 5 and 5 red marbles. Use all four samples together to estimate how many red marbles are in the jar.', '[]', '125', '(4+6+5+5)/(4*20)*500', 'Together the samples hold $4 \times 20 = 80$ marbles, and $4 + 6 + 5 + 5 = 20$ of them are red. That is $\frac{20}{80} = \frac{1}{4}$. A quarter of 500 marbles is $500 \div 4 = 125$.', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red in samples: 4 + 6 + 5 + 5 = 20 of 80 = 1/4. Estimate 1/4 x 500 = 125.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52647ad4-c596-419d-961f-eb746b092dfc', 'NC26.7.RD.2', 3, 'choice', 'Sample size and reliability', 'Two students each want to estimate the fraction of 900 students who like the school mascot. Ana asks 15 students chosen at random. Ben asks 150 students chosen at random. Whose estimate is likely to be closer to the true fraction, and why?', '["Ana''s, because a smaller sample has less bias","Neither, because random samples are never close to the truth","Ben''s, because a larger random sample varies less","They are equally likely to be close, because both samples are random"]', 'Ben''s, because a larger random sample varies less', NULL, 'Both samples are random, so neither is biased. But a small sample can easily land far from the true fraction by chance, while a larger random sample tends to stay close to it. Ben''s sample of 150 is more likely to give a good estimate.', 'checked', '{"lint":[],"solve":{"answer":"Ben''s, because a larger random sample varies less","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples have less sampling variability, so Ben''s estimate is likely closer.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9613b346-9cc6-4a41-9add-c5b7e6556ae7', 'NC26.7.RD.2', 3, 'numeric', 'Draw a random sample with random numbers', 'Mr. Lee numbers his 30 students from 01 to 30. He reads two-digit numbers in order from a list of random numbers. He keeps each number that is from 01 to 30 and is not already chosen, and he stops when 4 students are chosen. The list is 31, 17, 45, 08, 17, 30, 09, 25. What is the number of the fourth student chosen?', '[]', '9', '9', 'Go through the list in order. 31 is too big, so skip it. 17 is kept (first). 45 is too big. 08 is kept (second). 17 has already been chosen, so skip it. 30 is kept (third). 09 is kept (fourth). The fourth student is number 09, which is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Student may type 09; the key should accept 9 and 09 as the same number.","work":"31 skip; 17 first; 45 skip; 08 second; 17 repeat skip; 30 third; 09 fourth. Stop.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f20f125b-8913-4f35-a57e-fff48d21b6a3', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centres of two data sets', 'Data set A has the values 2, 3, 3, 4, 5. Data set B has the values 6, 7, 7, 8, 9. How much greater is the median of B than the median of A?', '[]', '4', '7-3', 'The values are already in order. The middle value of A is 3. The middle value of B is 7. The difference is $7 - 3 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median A = 3, median B = 7; 7 - 3 = 4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79ee8411-d6fa-4f41-bb67-c52c75071c77', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two data sets', 'Data set P has the values 10, 12, 14, 16, 18. Data set Q has the values 4, 10, 14, 18, 24. Both have a median of 14. Which statement about their spread is correct?', '["Q is more spread out, since its values go from 4 to 24","P is more spread out, since its values go from 10 to 18","They have the same spread, since the medians are equal","They have the same spread, since both have 5 values"]', 'Q is more spread out, since its values go from 4 to 24', NULL, 'The range of P is $18 - 10 = 8$ and the range of Q is $24 - 4 = 20$. Q''s values are farther apart, so Q is more spread out. Having the same center or the same number of values does not make the spread equal.', 'checked', '{"lint":[],"solve":{"answer":"Q is more spread out, since its values go from 4 to 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 8, range Q = 20; Q more spread out.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a5f6e01-25de-4aef-9413-ca23d773ce90', 'NC26.7.RD.3', 1, 'choice', 'Recognize an outlier in a distribution', 'Most of the values in a data set are between 20 and 30, but one value is 75. What do we call the value 75?', '["The median","The mode","An outlier","The mean"]', 'An outlier', NULL, 'A value that is far away from the rest of the data is called an outlier. The value 75 is much larger than the values between 20 and 30.', 'checked', '{"lint":[],"solve":{"answer":"An outlier","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A value far from the rest is an outlier.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b85b8695-d1c8-4095-ae60-2629db96073b', 'NC26.7.RD.3', 2, 'numeric', 'Compare the means of two data sets', 'Team A scored 6, 8, 9, 10 and 12 points in five games. Team B scored 7, 10, 11, 12 and 15 points in five games. How much greater is the mean of Team B''s scores than the mean of Team A''s scores?', '[]', '2', '(7+10+11+12+15)/5-(6+8+9+10+12)/5', 'Mean of A: $(6 + 8 + 9 + 10 + 12) \div 5 = 45 \div 5 = 9$. Mean of B: $(7 + 10 + 11 + 12 + 15) \div 5 = 55 \div 5 = 11$. The difference is $11 - 9 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 45/5 = 9. B: 55/5 = 11. Difference 2.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f717866a-ff4d-4829-b5d8-7024fc8ab001', 'NC26.7.RD.3', 2, 'choice', 'Interpret overlapping distributions', 'Heights of plants grown with fertilizer, in centimeters, are 14, 16, 17, 18, 18 and 20. Heights of plants grown without fertilizer are 10, 11, 12, 13, 14 and 15. Which statement do these data support?', '["Every plant with fertilizer was taller than every plant without","Plants with fertilizer tended to be taller, but the two sets overlap","Plants without fertilizer tended to be taller","The two sets are centered at about the same place"]', 'Plants with fertilizer tended to be taller, but the two sets overlap', NULL, 'The median with fertilizer is $(17 + 18) \div 2 = 17.5$ and without is $(12 + 13) \div 2 = 12.5$, so the plants with fertilizer tended to be taller. But the sets overlap: a plant without fertilizer reached 15 centimeters, which is taller than the 14 centimeter plant that had fertilizer.', 'checked', '{"lint":[],"solve":{"answer":"Plants with fertilizer tended to be taller, but the two sets overlap","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With: median 17.5; without: median 12.5, so fertilized taller. Overlap: 14 (with) is below 15 (without), so not every one taller. Overlap option is correct.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5d583b0-dd11-4966-9bd1-80eb46097d10', 'NC26.7.RD.3', 2, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot of ages has these rows: stem 1 with leaves 2, 5, 8; stem 2 with leaves 0, 3, 3, 9; stem 3 with leaves 1, 4. A stem of 2 and a leaf of 3 means 23. What is the median age?', '[]', '23', '23', 'The plot shows the ages 12, 15, 18, 20, 23, 23, 29, 31 and 34, which is 9 values in order. The median is the 5th value, which is 23.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values: 12, 15, 18, 20, 23, 23, 29, 31, 34 (9 values). Median is the 5th: 23.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8f77338-927b-42d6-b5f6-4efe3ebc0037', 'NC26.7.RD.3', 3, 'choice', 'Compare mean and median of two sets', 'Data set P has the values 18, 19, 20, 21, 22. Data set Q has the values 18, 19, 20, 21, 42. Which statement is true?', '["The means are equal, but Q has the greater median","The medians are equal, but Q has the greater mean","The medians and the means are both equal","Q has both the greater median and the greater mean"]', 'The medians are equal, but Q has the greater mean', NULL, 'Both sets have a middle value of 20, so the medians are equal. The mean of P is $100 \div 5 = 20$. The mean of Q is $120 \div 5 = 24$. The large value 42 pulls the mean of Q up but does not change its median.', 'checked', '{"lint":[],"solve":{"answer":"The medians are equal, but Q has the greater mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both medians 20. Mean P = 100/5 = 20; mean Q = 120/5 = 24.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('938333c1-6a65-4cbe-a090-dab9b2231197', 'NC26.7.RD.3', 3, 'numeric', 'Compare medians of sets with an even count', 'Set A has the values 14, 9, 21, 12, 17, 15. Set B has the values 22, 30, 25, 28, 27, 24. How much greater is the median of Set B than the median of Set A?', '[]', '11.5', '(25+27)/2-(14+15)/2', 'Order Set A: 9, 12, 14, 15, 17, 21. With 6 values, the median is the mean of the middle two: $(14 + 15) \div 2 = 14.5$. Order Set B: 22, 24, 25, 27, 28, 30. Its median is $(25 + 27) \div 2 = 26$. The difference is $26 - 14.5 = 11.5$.', 'checked', '{"lint":[],"solve":{"answer":"11.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted: 9, 12, 14, 15, 17, 21; median 14.5. B sorted: 22, 24, 25, 27, 28, 30; median 26. Difference 11.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e137ca13-7113-4de0-aa6b-42b2ef189252', 'NC26.7.RD.3', 3, 'numeric', 'Read two distributions plotted together', 'Two dot plots share one number line, and both have a mean of 5. Plot X has 1 dot at 3, 2 dots at 4, 6 dots at 5, 2 dots at 6 and 1 dot at 7. Plot Y has 4 dots at 2, 4 dots at 5 and 4 dots at 8. In all, how many dots (from both plots) are 2 or more units away from 5?', '[]', '10', '1+1+4+4', 'Dots 2 or more units from 5 are at values 3 or less, or 7 or more. In plot X, that is 1 dot at 3 and 1 dot at 7, which is 2 dots. In plot Y, the 4 dots at 2 and the 4 dots at 8 qualify, which is 8 dots. In all, $2 + 8 = 10$ dots.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: dots at 3 and 7 are 2 away: 1 + 1 = 2. Y: dots at 2 and 8 are 3 away: 4 + 4 = 8. Total 10. (Means check: X 60/12 = 5, Y 60/12 = 5.)","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9284fc1b-3e01-400e-813a-b87eb9032c5c', 'NC26.7.RD.4', 1, 'numeric', 'Range', 'A set of data is 12, 7, 15, 9, 20, 11. What is the range?', '[]', '13', '20-7', 'The range is the greatest value minus the least value: $20 - 7 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 20, min 7; range 13.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5e7220a-3097-4d41-8dd9-d2297eeb7935', 'NC26.7.RD.4', 1, 'choice', 'Choose a measure of spread', 'A coach wants to describe how much the heights of her players vary from the shortest to the tallest. Which should she find?', '["The median","The mean","The mode","The range"]', 'The range', NULL, 'The range, the greatest value minus the least value, describes how spread out the data are. The median, mean and mode describe the center, not the spread.', 'checked', '{"lint":[],"solve":{"answer":"The range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest to tallest spread is the range.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98ce3cb6-6eaa-41cf-b7b9-17d48ca349e0', 'NC26.7.RD.4', 1, 'numeric', 'Interquartile range from quartiles', 'The first quartile of a data set is 18 and the third quartile is 31. What is the interquartile range?', '[]', '13', '31-18', 'The interquartile range (IQR) is the third quartile minus the first quartile: $31 - 18 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = 31 - 18 = 13.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bff3730-512f-4c37-a9a7-65c03e4b0cb0', 'NC26.7.RD.4', 2, 'numeric', 'Mean absolute deviation', 'Find the mean absolute deviation (MAD) of the data set 2, 5, 5, 8.', '[]', '1.5', '(3+0+0+3)/4', 'The mean is $(2 + 5 + 5 + 8) \div 4 = 5$. The distances from 5 are 3, 0, 0 and 3. The mean of these distances is $6 \div 4 = 1.5$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 20/4 = 5. Distances 3, 0, 0, 3; MAD = 6/4 = 1.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed90802c-f78a-4673-bf7d-ce8e019a38b9', 'NC26.7.RD.4', 2, 'numeric', 'Interquartile range from raw data', 'Find the interquartile range of the data set 13, 3, 8, 5, 11, 2, 9, 6.', '[]', '6', '(9+11)/2-(3+5)/2', 'Put the values in order: 2, 3, 5, 6, 8, 9, 11, 13. The lower half is 2, 3, 5, 6, so the first quartile is $(3 + 5) \div 2 = 4$. The upper half is 8, 9, 11, 13, so the third quartile is $(9 + 11) \div 2 = 10$. The IQR is $10 - 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 2, 3, 5, 6, 8, 9, 11, 13. Lower half 2, 3, 5, 6: Q1 = 4. Upper half 8, 9, 11, 13: Q3 = 10. IQR = 6.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82c81912-d71f-4b63-b746-72ee69ec35bc', 'NC26.7.RD.4', 2, 'choice', 'Which measure resists extreme values', 'Which of these is least affected by one very extreme value in a data set?', '["Interquartile range","Range","Mean absolute deviation","Mean"]', 'Interquartile range', NULL, 'The range uses the extreme values directly, and the mean and the MAD both use every value, so an extreme value changes them. The interquartile range uses only the middle half of the data, so one extreme value barely affects it.', 'checked', '{"lint":[],"solve":{"answer":"Interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR uses only the middle half, so one extreme value barely moves it; mean, range and MAD all use every value.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e6d444-ec08-4608-97cf-aef1f039dc9b', 'NC26.7.RD.4', 3, 'choice', 'Effect of an extreme value', 'The value 30 is added to the data set 4, 5, 6, 7, 8. Which statement is true?', '["The median increases a lot, but the range changes only a little","Neither the range nor the median changes","The range increases a lot, but the median changes only a little","The range and the median increase by the same amount"]', 'The range increases a lot, but the median changes only a little', NULL, 'Before: the range is $8 - 4 = 4$ and the median is 6. After adding 30 the data are 4, 5, 6, 7, 8, 30. The range is $30 - 4 = 26$, an increase of 22. The median is $(6 + 7) \div 2 = 6.5$, an increase of only 0.5.', 'checked', '{"lint":[],"solve":{"answer":"The range increases a lot, but the median changes only a little","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before: range 4, median 6. After: 4, 5, 6, 7, 8, 30: range 26, median 6.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b00d53e-1c8d-4729-9b5e-5de29c8146be', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using MAD', 'Set A is 6, 8, 10, 12, 14. Set B is 2, 6, 10, 14, 18. Both sets have a mean of 10. The MAD of Set B is how many times the MAD of Set A?', '[]', '2', '((8+4+0+4+8)/5)/((4+2+0+2+4)/5)', 'Set A: the distances from 10 are 4, 2, 0, 2, 4. Their mean is $12 \div 5 = 2.4$. Set B: the distances from 10 are 8, 4, 0, 4, 8. Their mean is $24 \div 5 = 4.8$. Since $4.8 \div 2.4 = 2$, the MAD of B is 2 times the MAD of A.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: distances 4, 2, 0, 2, 4; MAD 12/5 = 2.4. B: 8, 4, 0, 4, 8; MAD 24/5 = 4.8. Ratio 2.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0baf79a5-681b-49ef-8d0f-9740724297c7', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using IQR', 'Set X is 3, 5, 6, 8, 9, 12, 14, 17. Set Y is 10, 11, 12, 13, 14, 15, 16, 17. How much greater is the interquartile range of Set X than the interquartile range of Set Y?', '[]', '3.5', '((12+14)/2-(5+6)/2)-((15+16)/2-(11+12)/2)', 'Set X: the lower half is 3, 5, 6, 8 with first quartile $(5 + 6) \div 2 = 5.5$. The upper half is 9, 12, 14, 17 with third quartile $(12 + 14) \div 2 = 13$. IQR = $13 - 5.5 = 7.5$. Set Y: the lower half is 10, 11, 12, 13 with first quartile 11.5. The upper half is 14, 15, 16, 17 with third quartile 15.5. IQR = $15.5 - 11.5 = 4$. The difference is $7.5 - 4 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: lower 3, 5, 6, 8 -> Q1 5.5; upper 9, 12, 14, 17 -> Q3 13; IQR 7.5. Y: lower 10-13 -> 11.5; upper 14-17 -> 15.5; IQR 4. Difference 3.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a696698b-3cff-4a61-8143-0662ef4b586b', 'NC26.7.RD.5', 1, 'choice', 'Compare two groups by their medians', 'The median reading time of Group A is 24 minutes and the median reading time of Group B is 30 minutes. Which statement is best supported by these medians?', '["A typical student in Group B read longer than a typical student in Group A","Every student in Group B read longer than every student in Group A","A typical student in Group A read longer than a typical student in Group B","Both groups read for about the same amount of time"]', 'A typical student in Group B read longer than a typical student in Group A', NULL, 'The median describes a typical value. Group B''s median is greater, so a typical student in Group B read longer. The medians do not tell us that every student in B read longer than every student in A.', 'checked', '{"lint":[],"solve":{"answer":"A typical student in Group B read longer than a typical student in Group A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median B 30 > median A 24, so a typical B student read longer. Medians say nothing about every student.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20c09b8c-d0fa-47ee-b3d5-0ab127f01c71', 'NC26.7.RD.5', 1, 'numeric', 'Compare two groups by their means', 'Group A read for 20, 25, 30 and 35 minutes. Group B read for 12, 14, 18 and 22 minutes. How many more minutes did Group A read than Group B, on average (using the mean)?', '[]', '11', '(20+25+30+35)/4-(12+14+18+22)/4', 'Mean of A: $110 \div 4 = 27.5$ minutes. Mean of B: $66 \div 4 = 16.5$ minutes. The difference is $27.5 - 16.5 = 11$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 110/4 = 27.5. B: 66/4 = 16.5. Difference 11.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b147a346-8b2f-4b35-8e58-649b2bafb8c3', 'NC26.7.RD.5', 1, 'choice', 'Plan an investigation of two groups', 'A student wants to compare how many books sixth graders and seventh graders read in a month. Which plan is best?', '["Ask 20 students who are checking out books at the library","Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month","Ask 20 seventh graders and use the answers for both grades","Ask 20 sixth graders and 20 seventh graders which grade reads more"]', 'Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month', NULL, 'To compare two groups we need numerical data from a random sample of each group. Library visitors are likely to read more than other students, using only one grade says nothing about the other, and asking which grade reads more gathers opinions instead of counts.', 'checked', '{"lint":[],"solve":{"answer":"Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random samples from both groups, asking the numeric question, is the sound comparison.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f80deb-1d6d-4edf-815d-1e3dffed9d6c', 'NC26.7.RD.5', 2, 'choice', 'Describe centre and spread together', 'Group A has a median score of 78 and an IQR of 6. Group B has a median score of 78 and an IQR of 18. Which statement is correct?', '["Group B scored higher, since its IQR is greater","The typical scores are about the same, but A''s scores vary more","The typical scores are about the same, but B''s scores vary more","Group A''s typical score is lower, since its IQR is smaller"]', 'The typical scores are about the same, but B''s scores vary more', NULL, 'The medians are equal, so the typical scores are the same. The IQR measures spread, and B''s IQR is greater, so B''s scores vary more. A greater IQR does not mean a higher score.', 'checked', '{"lint":[],"solve":{"answer":"The typical scores are about the same, but B''s scores vary more","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same medians, so typical scores alike; B''s IQR 18 > 6, so B varies more.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48722eb7-2405-4c03-bbd7-755868e2b5af', 'NC26.7.RD.5', 2, 'numeric', 'Compare the medians of two groups', 'Group A traveled to school for 10, 15, 20, 25 and 30 minutes. Group B traveled for 5, 10, 12, 15 and 20 minutes. How many more minutes is the median travel time of Group A than the median of Group B?', '[]', '8', '20-12', 'Both lists are in order. The middle value of A is 20 and the middle value of B is 12. The difference is $20 - 12 = 8$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median A = 20, median B = 12; 20 - 12 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7acc5b0c-dbc1-46a0-869a-c74a2c05519f', 'NC26.7.RD.5', 2, 'choice', 'Draw a conclusion the data support', 'A teacher compares quiz scores of the 15 students in her morning class with the 15 in her afternoon class. The afternoon class had the higher mean. Which conclusion is best supported by this data?', '["Afternoon classes make students learn more","Every student scores higher in the afternoon","Every afternoon student scored higher than every morning student","The 15 afternoon students scored higher on this quiz, on average"]', 'The 15 afternoon students scored higher on this quiz, on average', NULL, 'The data show only that the mean score of these 15 afternoon students was higher. They do not show that the time of day caused the difference, that it holds for every student, or that every individual score was higher.', 'checked', '{"lint":[],"solve":{"answer":"The 15 afternoon students scored higher on this quiz, on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A higher mean supports only that these afternoon students scored higher on average on this quiz; no causal or every-student claim.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('302fb59f-891b-4989-8939-f3f8c36ea4b9', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison of two groups', 'Plants in the sun had a median height of 24 cm and an IQR of 4 cm. Plants in the shade had a median height of 15 cm and an IQR of 5 cm. Which statement best summarizes the comparison?', '["Sun plants were typically 9 cm taller, and varied much more than shade plants","Sun plants were typically 9 cm taller, and both groups varied by a similar amount","Shade plants were typically 9 cm taller, and both groups varied by a similar amount","The groups were typically the same height, but shade plants varied more"]', 'Sun plants were typically 9 cm taller, and both groups varied by a similar amount', NULL, 'The medians differ by $24 - 15 = 9$ cm, with the sun plants taller. The IQRs, 4 cm and 5 cm, are close compared with a 9 cm difference, so the spread is similar. Only the first statement reports both correctly.', 'checked', '{"lint":[],"solve":{"answer":"Sun plants were typically 9 cm taller, and both groups varied by a similar amount","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sun median 24 vs shade 15: sun 9 cm taller. IQRs 4 and 5: similar spread.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b61172c-72c9-42e0-9e40-a4e62aadb6dd', 'NC26.7.RD.5', 3, 'numeric', 'Difference of means in units of MAD', 'Group A has the values 8, 10 and 12. Group B has the values 12, 14 and 16. The difference between the two means is how many times the mean absolute deviation (MAD) of Group A?', '[]', '3', '(14-10)/((2+0+2)/3)', 'Mean of A is 10 and mean of B is 14, so the difference is 4. The distances of A''s values from 10 are 2, 0 and 2, so the MAD of A is $4 \div 3 = \frac{4}{3}$. Then $4 \div \frac{4}{3} = 3$, so the difference is 3 times the MAD.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means 10 and 14; difference 4. MAD A: distances 2, 0, 2; 4/3. 4 / (4/3) = 3.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072c6387-2267-4e3b-8a69-378d0438a0af', 'NC26.7.RD.5', 3, 'numeric', 'Compare the variability of two groups with the IQR', 'Two groups of students timed how many minutes they took to finish a puzzle. Group A: 3, 7, 9, 12, 17, 20. Group B: 10, 12, 13, 15, 17, 19. Each list is in order. The quartiles are the medians of the lower half and the upper half of the data. The IQR of Group A is how many times the IQR of Group B?', '[]', '2', '(17-7)/(17-12)', 'Group A: the lower half is 3, 7, 9 so Q1 = 7, and the upper half is 12, 17, 20 so Q3 = 17. The IQR is 17 - 7 = 10. Group B: the lower half is 10, 12, 13 so Q1 = 12, and the upper half is 15, 17, 19 so Q3 = 17. The IQR is 17 - 12 = 5. Then 10 / 5 = 2, so the IQR of Group A is 2 times the IQR of Group B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group A (6 values): lower half 3, 7, 9 -> Q1 = 7; upper half 12, 17, 20 -> Q3 = 17; IQR = 10. Group B: lower half 10, 12, 13 -> Q1 = 12; upper half 15, 17, 19 -> Q3 = 17; IQR = 5. Ratio 10 / 5 = 2.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c997d68-a63b-4cda-a2f8-6bcbf25d49ab', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve a linear equation with the variable on both sides', 'Solve for $x$: $5x + 3 = 2x + 15$', '[]', '4', '(15-3)/(5-2)', 'Subtract $2x$ from both sides: $3x + 3 = 15$. Subtract 3 from both sides: $3x = 12$. Divide by 3: $x = 4$. Check: $5(4) + 3 = 23$ and $2(4) + 15 = 23$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 3 = 2x + 15 -> 3x = 12 -> x = 4. Check: 23 = 23.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a90734e-30cc-4df9-9446-4f3fadcf7b23', 'NC26.8.ANFR.1', 1, 'choice', 'Write an equation from a situation with two quantities', 'Maya has 5 dollars and saves 2 dollars each week. Leo has 11 dollars and saves 1 dollar each week. Let $w$ be the number of weeks. Which equation says that they have the same amount of money after $w$ weeks?', '["$2 + 5w = 1 + 11w$","$5 + 2w = 11 + w$","$5 + 2w = 11w$","$5 + 11 = 2w + w$"]', '$5 + 2w = 11 + w$', NULL, 'After $w$ weeks Maya has $5 + 2w$ dollars (5 to start, 2 more each week). Leo has $11 + w$ dollars. "The same amount" means the two are equal: $5 + 2w = 11 + w$.', 'checked', '{"lint":[],"solve":{"answer":"$5 + 2w = 11 + w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maya after w weeks: 5 + 2w. Leo: 11 + 1w = 11 + w. Same amount: 5 + 2w = 11 + w. Other options mix up the start and the rate.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084c344b-7ea5-4dd8-bc0a-7dfe6b9bf52e', 'NC26.8.ANFR.1', 1, 'numeric', 'Find the whole numbers that satisfy an inequality with the variable on both sides', 'What is the greatest whole number $x$ that makes $4x - 5 < x + 7$ true?', '[]', '3', '12/3-1', 'Subtract $x$ from both sides: $3x - 5 < 7$. Add 5: $3x < 12$. Divide by 3: $x < 4$. The greatest whole number less than 4 is 3. Check: for $x = 3$, $4(3) - 5 = 7$ and $3 + 7 = 10$, and $7 < 10$. For $x = 4$ both sides equal 11, so 4 does not work.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 < x + 7 -> 3x < 12 -> x < 4. Greatest whole number below 4 is 3. Check x=3: 7 < 10 true; x=4: 11 < 11 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b02d8e1e-e415-42a8-9894-990ef1b2db96', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation that needs the distributive property', 'Solve for $x$: $4(x - 2) = 2x + 6$', '[]', '7', '(6+8)/(4-2)', 'Distribute: $4x - 8 = 2x + 6$. Subtract $2x$: $2x - 8 = 6$. Add 8: $2x = 14$. Divide by 2: $x = 7$. Check: $4(7 - 2) = 20$ and $2(7) + 6 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 8 = 2x + 6 -> 2x = 14 -> x = 7. Check: 4(5) = 20 = 14 + 6.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb299894-ce21-4e7d-918e-ac884fba4a43', 'NC26.8.ANFR.1', 2, 'choice', 'Recognise an equation with infinitely many solutions', 'How many solutions does the equation $3(x + 2) = 3x + 6$ have?', '["Infinitely many solutions","No solution","Exactly one solution, $x = 0$","Exactly one solution, $x = 6$"]', 'Infinitely many solutions', NULL, 'Distribute on the left: $3x + 6 = 3x + 6$. Both sides are exactly the same expression, so the equation is true for every value of $x$. It has infinitely many solutions.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many solutions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6, identical to the right side, so every x works: infinitely many solutions.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94684697-319e-4880-8eaa-82608bd61087', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality where dividing by a negative reverses the sign', 'Which inequality shows all the solutions of $5 - 2x \ge x - 7$?', '["$x \\ge 4$","$x \\ge -4$","$x \\le 4$","$x \\le 12$"]', '$x \le 4$', NULL, 'Add $2x$ to both sides: $5 \ge 3x - 7$. Add 7: $12 \ge 3x$. Divide by 3: $4 \ge x$, which is the same as $x \le 4$. Check: $x = 0$ gives $5 \ge -7$, which is true.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2x >= x - 7 -> 12 >= 3x -> x <= 4. Check x=4: -3 >= -3 true; x=5: -5 >= -2 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e26f99e-67b3-4ea4-8885-9455f67ae762', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with fraction coefficients on both sides', 'Solve for $x$: $\frac{1}{2}x + 3 = \frac{1}{4}x + 8$', '[]', '20', '(8-3)/(1/2-1/4)', 'Subtract $\frac{1}{4}x$ from both sides: $\frac{1}{4}x + 3 = 8$. Subtract 3: $\frac{1}{4}x = 5$. Multiply by 4: $x = 20$. Check: $\frac{1}{2}(20) + 3 = 13$ and $\frac{1}{4}(20) + 8 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)x - (1/4)x = 8 - 3 -> (1/4)x = 5 -> x = 20. Check: 10 + 3 = 13 = 5 + 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96a68c46-383c-4294-86e1-3d0eaa5c7660', 'NC26.8.ANFR.1', 3, 'choice', 'Find the constant that gives infinitely many solutions', 'The equation $3(2x - 4) = 6x + k$ has infinitely many solutions. What is the value of $k$?', '["$12$","$-4$","$0$","$-12$"]', '$-12$', '0-12', 'Distribute on the left: $6x - 12 = 6x + k$. The $x$ terms already match. The equation is true for every $x$ only when the constants match too, so $k = -12$.', 'checked', '{"lint":[],"solve":{"answer":"$-12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x - 4) = 6x - 12. For infinitely many solutions 6x - 12 = 6x + k for all x, so k = -12. Any other k gives no solution.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1010f3ba-a88f-4542-8bfb-ad60b98ff79b', 'NC26.8.ANFR.1', 3, 'numeric', 'Use an equation with the variable on both sides to solve a problem', 'Gym A charges 20 dollars to join plus 8 dollars for each visit. Gym B charges 50 dollars to join plus 5 dollars for each visit. After how many visits is the total cost the same at both gyms?', '[]', '10', '(50-20)/(8-5)', 'Let $v$ be the number of visits. Gym A costs $20 + 8v$ and Gym B costs $50 + 5v$. Set them equal: $20 + 8v = 50 + 5v$. Subtract $5v$: $20 + 3v = 50$. Subtract 20: $3v = 30$. So $v = 10$. Check: both cost 100 dollars.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 8v = 50 + 5v -> 3v = 30 -> v = 10. Check: 20 + 80 = 100; 50 + 50 = 100.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfd7cd33-6da2-4b25-81af-1266d1442291', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of input-output pairs is a function', 'Each pair below is written as (input, output). Which set of pairs is a function?', '["(1, 4), (1, 5), (2, 6), (3, 7)","(2, 3), (3, 4), (2, 5), (4, 6)","(5, 1), (6, 2), (7, 3), (5, 4)","(1, 4), (2, 5), (3, 6), (4, 7)"]', '(1, 4), (2, 5), (3, 6), (4, 7)', NULL, 'A function gives exactly one output for each input. In the first set every input appears once. In the other sets an input is repeated with two different outputs: 1 gives 4 and 5, 2 gives 3 and 5, and 5 gives 1 and 4.', 'checked', '{"lint":[],"solve":{"answer":"(1, 4), (2, 5), (3, 6), (4, 7)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A repeats input 2 with outputs 3 and 5; B repeats input 1; D repeats input 5. C has inputs 1,2,3,4 each once, so it is a function.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e503e807-2094-4fc7-be51-942303181737', 'NC26.8.ANFR.2', 1, 'numeric', 'Use a function rule to find an output', 'A function''s rule is: the output is 3 more than twice the input. What is the output when the input is 5?', '[]', '13', '2*5+3', 'Twice the input is $2 \times 5 = 10$. Three more than that is $10 + 3 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Output = 2(5) + 3 = 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82f8f8cc-1e93-4490-8a0f-40ed1465a29f', 'NC26.8.ANFR.2', 1, 'choice', 'Describe how a quantity changes as time passes', 'A candle is measured at 0, 1, 2 and 3 hours. Its heights are 20, 17, 14 and 11 centimeters. Which statement describes the height as time goes on?', '["The height increases by 3 centimeters each hour","The height decreases by 20 centimeters each hour","The height decreases by 3 centimeters each hour","The height decreases by 11 centimeters each hour"]', 'The height decreases by 3 centimeters each hour', NULL, 'Each hour the height goes from 20 to 17 to 14 to 11. It drops by 3 centimeters every hour, so the function is decreasing.', 'checked', '{"lint":[],"solve":{"answer":"The height decreases by 3 centimeters each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 -> 17 -> 14 -> 11: each hour the height drops by 3 cm.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('763cd066-6a1f-4613-ab9c-85145c8415a7', 'NC26.8.ANFR.2', 2, 'choice', 'Decide whether a function from a list of pairs is linear', 'A function has these (input, output) pairs: (1, 2), (2, 5), (3, 10), (4, 17). Is the function linear?', '["No, because the output does not change by the same amount each time","Yes, because the output always goes up","Yes, because the input goes up by 1 each time","Yes, because the output is always greater than the input"]', 'No, because the output does not change by the same amount each time', NULL, 'The outputs change by 3, then 5, then 7. A linear function changes by the same amount each time the input goes up by 1, so this function is not linear.', 'checked', '{"lint":[],"solve":{"answer":"No, because the output does not change by the same amount each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Output changes: 2->5 (+3), 5->10 (+5), 10->17 (+7). Equal input steps but unequal output changes, so not linear (outputs are x^2 + 1).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e4a7009-c109-4876-adc1-0e5fc350e084', 'NC26.8.ANFR.2', 2, 'choice', 'Tell which relationship gives exactly one output for each input', 'Which relationship gives exactly one output for every input?', '["Input: a letter of the alphabet. Output: a word that starts with that letter","Input: a whole number from 1 to 20. Output: a whole number that divides it evenly","Input: the side length of a square. Output: the area of that square","Input: a country. Output: a city in that country"]', 'Input: the side length of a square. Output: the area of that square', NULL, 'A square with a given side length has only one area, so this is a function. A letter can start many words, 12 is divided evenly by 1, 2, 3, 4, 6 and 12, and a country has many cities, so those inputs have more than one possible output.', 'checked', '{"lint":[],"solve":{"answer":"Input: the side length of a square. Output: the area of that square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A letter has many words; a number like 6 has divisors 1,2,3,6; a country has many cities. A square''s side determines exactly one area (s^2). So C.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16a4113b-fb0d-4c1f-8af8-165ef904080f', 'NC26.8.ANFR.2', 2, 'numeric', 'Find how long a quantity is decreasing', 'A hiker''s height above sea level is measured every hour. At hours 0, 1, 2, 3, 4 and 5 the heights in meters are 100, 300, 500, 500, 300 and 100. For how many hours is the height decreasing?', '[]', '2', '5-3', 'The height rises from hour 0 to hour 2, stays at 500 from hour 2 to hour 3, and falls from hour 3 to hour 5 (500, then 300, then 100). It is decreasing for $5 - 3 = 2$ hours.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hours 0-1: up; 1-2: up; 2-3: level (500 to 500); 3-4: down; 4-5: down. Decreasing during 2 hours.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5225943-2cf3-4b4c-b55b-aba1a97f6090', 'NC26.8.ANFR.2', 3, 'choice', 'Tell a non-linear equation from linear ones', 'Which equation represents a non-linear function?', '["$y = 3 - 2x$","$y = 2x^2 - 3$","$y = \\frac{x}{2} - 3$","$y = 5x$"]', '$y = 2x^2 - 3$', NULL, 'A linear function can be written $y = mx + b$, with $x$ only to the first power. The equation $y = 3 - 2x$ is linear (slope $-2$), $y = \frac{x}{2} - 3$ is linear (slope $\frac{1}{2}$), and $y = 5x$ is linear. The equation $y = 2x^2 - 3$ has $x^2$, so its graph is not a line.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x^2 - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2x^2 - 3 has an x^2 term, so it is not linear. The others are y = -2x + 3, y = x/2 - 3, y = 5x, all linear.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed6a6168-ab3d-457e-a00b-11a067a1e4e7', 'NC26.8.ANFR.2', 3, 'numeric', 'Continue a pattern of change in a non-linear function', 'The outputs of a function for the inputs 0, 1, 2, 3 and 4 are 5, 7, 11, 17 and 25. Each time, the amount the output increases by is 2 more than the amount it increased by the time before. What is the output when the input is 5?', '[]', '35', '25+10', 'The increases are $7 - 5 = 2$, $11 - 7 = 4$, $17 - 11 = 6$ and $25 - 17 = 8$. They go up by 2 each time, so the next increase is 10. The output for input 5 is $25 + 10 = 35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increases: 2, 4, 6, 8. Next increase is 10, so output at 5 is 25 + 10 = 35.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1019ed24-c01e-470a-8443-1cadd2f49ea7', 'NC26.8.ANFR.2', 3, 'numeric', 'Fix a relation so that it becomes a function', 'The pairs (1, 2), (1, 3), (1, 4), (2, 5), (3, 7), (3, 9) are written as (input, output) and do not make a function. What is the fewest number of pairs that must be removed so that every input has exactly one output?', '[]', '3', '(3-1)+(2-1)', 'Input 1 has three pairs, so two must be removed. Input 2 has one pair, which is fine. Input 3 has two pairs, so one must be removed. In total $2 + 0 + 1 = 3$ pairs are removed.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Input 1 has 3 outputs (keep 1, remove 2). Input 2 has 1. Input 3 has 2 outputs (remove 1). Fewest removals = 2 + 1 = 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('425be7cb-2b1f-40dc-89b2-8676be10581c', 'NC26.8.ANFR.3', 1, 'numeric', 'Read the slope from slope-intercept form', 'What is the slope of the line $y = -5x + 9$?', '[]', '-5', '0-5', 'In $y = mx + b$ the slope is $m$, the number multiplied by $x$. Here the slope is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b with m = -5.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b66fa5a-8f83-4cb2-b755-20825eec66fa', 'NC26.8.ANFR.3', 1, 'choice', 'Read the y-intercept when the terms are written in a different order', 'What is the $y$-intercept of the line $y = 3 - 4x$?', '["$-4$","$4$","$3$","$-3$"]', '$3$', '3', 'Rewrite as $y = -4x + 3$. The constant term is the $y$-intercept, so it is 3. (The $-4$ is the slope.)', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3 - 4x = -4x + 3; at x = 0, y = 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfcdac1f-103b-494e-a029-28437def46da', 'NC26.8.ANFR.3', 1, 'choice', 'Write the equation of a line from its slope and y-intercept', 'Which equation is for a line with slope 2 and $y$-intercept $-4$?', '["$y = 2x - 4$","$y = -4x + 2$","$y = 2x + 4$","$y = -2x - 4$"]', '$y = 2x - 4$', NULL, 'Use $y = mx + b$ with $m = 2$ and $b = -4$: $y = 2x - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b with m = 2, b = -4: y = 2x - 4.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
