INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a820287-334d-4be2-878e-f32ad3243ac8', 'NC26.8.ANFR.3', 2, 'numeric', 'Find the slope of the line through two points', 'What is the slope of the line through the points $(2, 9)$ and $(5, 0)$?', '[]', '-3', '(0-9)/(5-2)', 'Slope is the change in $y$ divided by the change in $x$: $\frac{0 - 9}{5 - 2} = \frac{-9}{3} = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (0 - 9)/(5 - 2) = -9/3 = -3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a4cb05e-e921-4ef7-8978-f87ed029ded0', 'NC26.8.ANFR.3', 2, 'choice', 'Interpret the slope of a linear model in context', 'A plumber''s charge in dollars is given by $y = 45x + 30$, where $x$ is the number of hours worked. What does the 45 tell us?', '["A fixed fee charged once for coming to the job","The total charge for 30 hours of work","The number of hours worked","The charge for each hour of work"]', 'The charge for each hour of work', NULL, 'The slope 45 is the change in the charge for each 1 hour of work. The 30 is the fixed fee, charged even for 0 hours.', 'checked', '{"lint":[],"solve":{"answer":"The charge for each hour of work","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In y = 45x + 30, 45 multiplies the hours, so it is the rate per hour; 30 is the fixed fee.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e62970f-b1d8-4a08-90d0-258605705147', 'NC26.8.ANFR.3', 2, 'choice', 'Find the equation of a linear function from a list of pairs', 'A linear function has these $(x, y)$ pairs: (0, 4), (2, 10), (4, 16). Which equation matches it?', '["$y = 6x + 4$","$y = 3x + 4$","$y = 4x + 3$","$y = 3x - 4$"]', '$y = 3x + 4$', NULL, 'When $x = 0$, $y = 4$, so the $y$-intercept is 4. When $x$ goes up by 2, $y$ goes up by 6, so the slope is $\frac{6}{2} = 3$. The equation is $y = 3x + 4$. Check: $x = 4$ gives $3(4) + 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (10 - 4)/(2 - 0) = 3; intercept 4 (from (0,4)). y = 3x + 4. Check (4,16): 12 + 4 = 16.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1835b01-541b-44a4-9c8c-7206463f4a4f', 'NC26.8.ANFR.3', 3, 'numeric', 'Compare the rates of change of two linear functions shown in different ways', 'Function A is $y = 5x - 1$. Function B is the line through the points $(1, 2)$ and $(4, 11)$. How much greater is the slope of Function A than the slope of Function B?', '[]', '2', '5-(11-2)/(4-1)', 'The slope of A is 5. The slope of B is $\frac{11 - 2}{4 - 1} = \frac{9}{3} = 3$. The difference is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope A = 5. Slope B = (11 - 2)/(4 - 1) = 9/3 = 3. Difference 5 - 3 = 2.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba59d9de-7544-4f44-9bf0-932eaadf80fc', 'NC26.8.ANFR.3', 3, 'numeric', 'Find the y-intercept of a line from its slope and one point', 'A line has slope $-3$ and passes through the point $(4, 1)$. What is its $y$-intercept?', '[]', '13', '1+3*4', 'Write $y = -3x + b$. Put in the point: $1 = -3(4) + b = -12 + b$. Then $b = 1 + 12 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -3x + b; 1 = -3(4) + b = -12 + b -> b = 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af4a0305-d0d7-49aa-82d3-9d978c782b05', 'NC26.8.ANFR.3', 3, 'numeric', 'Find where a line crosses the x-axis', 'At what value of $x$ does the line $y = \frac{3}{4}x - 6$ cross the $x$-axis?', '[]', '8', '6/(3/4)', 'The line crosses the $x$-axis where $y = 0$: $0 = \frac{3}{4}x - 6$. Add 6: $\frac{3}{4}x = 6$. Multiply by $\frac{4}{3}$: $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Crosses x-axis where y = 0: (3/4)x = 6 -> x = 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54c7a41b-84b5-4023-ad2a-bb7ee962200f', 'NC26.8.ANFR.4', 1, 'choice', 'Recognise an irrational number', 'Which number is irrational?', '["$\\sqrt{49}$","$\\frac{22}{7}$","$\\sqrt{7}$","$0.125$"]', '$\sqrt{7}$', NULL, 'An irrational number cannot be written as a fraction of two integers. 7 is not a perfect square, so $\sqrt{7}$ is irrational. But $\sqrt{49} = 7$, $\frac{22}{7}$ is a fraction, and $0.125 = \frac{1}{8}$, so those are rational.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.125 = 1/8, 22/7 is a fraction, sqrt(49) = 7. sqrt(7) is not a perfect square root, so irrational.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce6d0804-2019-4596-ac15-088f3afe07b8', 'NC26.8.ANFR.4', 1, 'choice', 'Classify a number within the real numbers', 'Which statement about the number $-6$ is true?', '["It is an integer and a rational number","It is a whole number and an integer","It is a counting number and a rational number","It is an irrational number"]', 'It is an integer and a rational number', NULL, 'The number $-6$ is an integer, and every integer is rational ($-6 = \frac{-6}{1}$). It is not a whole number or a counting number, because those are 0, 1, 2, ... or 1, 2, 3, ... and have no negatives. It is not irrational.', 'checked', '{"lint":[],"solve":{"answer":"It is an integer and a rational number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6 is an integer and equals -6/1, so rational. It is not irrational, not a counting number and not a whole number (whole numbers are 0, 1, 2, ...).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('654c84a3-9d7a-495c-8873-995d6ac86e18', 'NC26.8.ANFR.4', 1, 'numeric', 'Place a square root between whole numbers', 'What is the greatest whole number that is less than $\sqrt{50}$?', '[]', '7', NULL, 'Since $7^2 = 49$ and $8^2 = 64$, and 50 is between 49 and 64, $\sqrt{50}$ is between 7 and 8. The greatest whole number less than it is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2 = 49 < 50 < 64 = 8^2, so 7 < sqrt(50) < 8. Greatest whole number less than it is 7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68524fe7-7d29-4824-bb03-ba703dfa6098', 'NC26.8.ANFR.4', 2, 'choice', 'Approximate an expression with pi', 'What is the value of $4\pi$, rounded to the nearest whole number?', '["12","13","16","7"]', '13', '13', 'Since $\pi \approx 3.14$, we get $4\pi \approx 12.56$. Rounded to the nearest whole number that is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3.14159 = 12.566..., rounds to 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e603fb09-6e51-428e-bf81-9b2d40d3db34', 'NC26.8.ANFR.4', 2, 'choice', 'Estimate a square root', 'Which value is the best estimate of $\sqrt{20}$?', '["4","5","10","4.5"]', '4.5', '4.5', 'Since $4^2 = 16$ and $5^2 = 25$, $\sqrt{20}$ is between 4 and 5. Check $4.5^2 = 20.25$, which is very close to 20, so 4.5 is the best estimate.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^2 = 16, 5^2 = 25, 4.5^2 = 20.25. sqrt(20) = 4.472..., closest to 4.5 (distance 0.03 vs 0.47 and 0.53).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0e3848a-d8d0-4fce-a718-6b1feecd8224', 'NC26.8.ANFR.4', 2, 'numeric', 'Evaluate an expression with pi using a given approximation', 'Use 3.14 as the value of $\pi$. What is the value of $5\pi - 2$?', '[]', '13.7', '5*3.14-2', 'Multiply: $5 \times 3.14 = 15.7$. Subtract 2: $15.7 - 2 = 13.7$.', 'checked', '{"lint":[],"solve":{"answer":"13.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 3.14 = 15.7; 15.7 - 2 = 13.7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
