INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9310d9-71b8-4bbf-90e7-5f807fff6091', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate a square root to the nearest tenth', 'What is $\sqrt{60}$, rounded to the nearest tenth?', '[]', '7.7', NULL, 'Since $7.7^2 = 59.29$ and $7.8^2 = 60.84$, $\sqrt{60}$ is between 7.7 and 7.8. The halfway point is 7.75, and $7.75^2 = 60.0625$, which is more than 60, so $\sqrt{60}$ is below 7.75. Rounded to the nearest tenth, $\sqrt{60} \approx 7.7$.', 'checked', '{"lint":[],"solve":{"answer":"7.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.7^2 = 59.29, 7.8^2 = 60.84; 7.75^2 = 60.0625 > 60, so sqrt(60) is between 7.7 and 7.75 (about 7.746). Rounds to 7.7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('654cb301-5089-450a-82e2-caafc0a3bca6', 'NC26.8.ANFR.4', 3, 'choice', 'Find a number that is irrational and lies in a given interval', 'Which number is irrational and lies between 5 and 6?', '["$\\sqrt{28}$","$\\sqrt{25}$","$\\frac{16}{3}$","$\\sqrt{40}$"]', '$\sqrt{28}$', NULL, '$\sqrt{28}$ is between $\sqrt{25} = 5$ and $\sqrt{36} = 6$, and 28 is not a perfect square, so it is irrational. $\sqrt{25} = 5$ is rational and not between 5 and 6. $\frac{16}{3} \approx 5.33$ is between 5 and 6 but rational. $\sqrt{40} \approx 6.3$ is irrational but greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{28}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 5 and 6 means between sqrt(25) and sqrt(36). sqrt(40) > 6; sqrt(25) = 5 rational; 16/3 = 5.33 rational. sqrt(28) is about 5.29 and irrational.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22e4eed2-5ceb-4faf-ada7-4291dd07f0d9', 'NC26.8.ANFR.4', 3, 'choice', 'Order rational and irrational numbers', 'Which list puts $3$, $\pi$, $\sqrt{10}$ and $3.2$ in order from least to greatest?', '["$3, \\sqrt{10}, \\pi, 3.2$","$\\pi, 3, \\sqrt{10}, 3.2$","$3, \\pi, \\sqrt{10}, 3.2$","$3, \\pi, 3.2, \\sqrt{10}$"]', '$3, \pi, \sqrt{10}, 3.2$', NULL, 'Approximate each number: $\pi \approx 3.14$, $\sqrt{10} \approx 3.16$ (because $3.16^2 \approx 9.99$), and 3.2 and 3 are given. In order: $3 < 3.14 < 3.16 < 3.2$, that is $3, \pi, \sqrt{10}, 3.2$.', 'checked', '{"lint":[],"solve":{"answer":"$3, \\pi, \\sqrt{10}, 3.2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3; pi = 3.14159...; sqrt(10) = 3.1623 (3.16^2 = 9.9856, 3.17^2 = 10.0489); 3.2. Order: 3, pi, sqrt(10), 3.2.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb113841-778f-4507-af75-9c6502ebca62', 'NC26.8.ANFR.5', 1, 'choice', 'Multiply powers with the same base', 'Which expression is equal to $5^4 \times 5^3$?', '["$5^{12}$","$25^7$","$5^{1}$","$5^7$"]', '$5^7$', NULL, 'When you multiply powers with the same base, add the exponents: $5^4 \times 5^3 = 5^{4+3} = 5^7$.', 'checked', '{"lint":[],"solve":{"answer":"$5^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base: add exponents, 5^(4+3) = 5^7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05add28c-8739-42b7-9eb0-7d77f8edda8b', 'NC26.8.ANFR.5', 1, 'choice', 'Solve x squared equals a positive number', 'Which choice shows all the solutions of $x^2 = 49$?', '["$x = 7$ and $x = -7$","$x = 7$ only","$x = -7$ only","$x = 24.5$"]', '$x = 7$ and $x = -7$', NULL, 'Both $7 \times 7 = 49$ and $(-7) \times (-7) = 49$, so $x = 7$ and $x = -7$ are both solutions.', 'checked', '{"lint":[],"solve":{"answer":"$x = 7$ and $x = -7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2 = 49 and (-7)^2 = 49, so x = 7 and x = -7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3431ee0-1c95-4dd2-a995-16b6ce4f8cdc', 'NC26.8.ANFR.5', 1, 'numeric', 'Write a number in scientific notation as an ordinary number', 'Write $4.7 \times 10^3$ as a whole number.', '[]', '4700', '4.7*10^3', '$10^3 = 1{,}000$ and $4.7 \times 1{,}000 = 4{,}700$. Moving the decimal point 3 places to the right gives the same result.', 'checked', '{"lint":[],"solve":{"answer":"4700","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.7 x 1000 = 4700.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fa60040-5e94-4bf8-bfb5-8de43678a27d', 'NC26.8.ANFR.5', 2, 'numeric', 'Evaluate a negative exponent', 'What is the value of $3^{-2}$? Give your answer as a fraction.', '[]', '1/9', '1/3^2', 'A negative exponent means the reciprocal: $3^{-2} = \frac{1}{3^2} = \frac{1}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"1/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^-2 = 1/3^2 = 1/9.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8ae1055-07fe-40ec-a93a-9a1807101529', 'NC26.8.ANFR.5', 2, 'numeric', 'Use a cube root to solve x cubed equals a number', 'A cube has a volume of 512 cubic centimeters. How long is each edge, in centimeters?', '[]', '8', NULL, 'The volume of a cube is edge $\times$ edge $\times$ edge, so $x^3 = 512$. Since $8 \times 8 \times 8 = 512$, each edge is 8 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge = cube root of 512; 8^3 = 512, so 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e51559-eed4-437a-ba9b-1f4bfaaaa55b', 'NC26.8.ANFR.5', 2, 'choice', 'Compare numbers in scientific notation', 'Which number is the greatest?', '["$9.2 \\times 10^{5}$","$7.9 \\times 10^{4}$","$4.5 \\times 10^{6}$","$3.1 \\times 10^{5}$"]', '$4.5 \times 10^{6}$', NULL, 'Compare the powers of 10 first. $10^6$ is the largest power, so $4.5 \times 10^6 = 4{,}500{,}000$ is greater than $9.2 \times 10^5 = 920{,}000$, $3.1 \times 10^5 = 310{,}000$ and $7.9 \times 10^4 = 79{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"$4.5 \\times 10^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values: 310,000; 79,000; 920,000; 4,500,000. Greatest is 4.5 x 10^6.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b620394f-638b-43b1-b6b5-02f213d5231c', 'NC26.8.ANFR.5', 3, 'choice', 'Multiply numbers in scientific notation', 'Which choice shows $(3 \times 10^4) \times (2 \times 10^3)$ in scientific notation?', '["$6 \\times 10^{12}$","$6 \\times 10^{7}$","$5 \\times 10^{7}$","$6 \\times 10^{1}$"]', '$6 \times 10^{7}$', NULL, 'Multiply the numbers in front: $3 \times 2 = 6$. Add the exponents of 10: $10^4 \times 10^3 = 10^7$. The product is $6 \times 10^7$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 10^{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 x 2) x 10^(4+3) = 6 x 10^7, already in scientific notation.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d84171de-31de-4d2a-a981-3eaaf3ff6c94', 'NC26.8.ANFR.5', 3, 'numeric', 'Combine exponent properties', 'What is the value of $\frac{(3^2)^3}{3^4}$?', '[]', '9', '(3^2)^3/3^4', 'A power of a power multiplies the exponents: $(3^2)^3 = 3^6$. Dividing powers of the same base subtracts the exponents: $\frac{3^6}{3^4} = 3^2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3^2)^3 = 3^6; 3^6 / 3^4 = 3^2 = 9.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66d0979f-d561-4ada-a9be-4903ea6c822b', 'NC26.8.ANFR.5', 3, 'numeric', 'Divide numbers in scientific notation in a problem', 'A signal travels $3 \times 10^8$ meters each second. How many seconds does it take to travel $6 \times 10^{10}$ meters?', '[]', '200', '(6*10^10)/(3*10^8)', 'Time = distance $\div$ speed $= \frac{6 \times 10^{10}}{3 \times 10^8}$. Divide the numbers in front: $6 \div 3 = 2$. Subtract the exponents: $10^{10} \div 10^8 = 10^2$. So the time is $2 \times 10^2 = 200$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Time = (6 x 10^10)/(3 x 10^8) = 2 x 10^2 = 200 seconds.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8317e9aa-ec92-405c-8d94-bb85f1c05ca8', 'NC26.8.SGMR.1', 1, 'choice', 'Translate a point', 'Point A is at (2, 5). It is moved 3 units to the right and 4 units down. What are its new coordinates?', '["(5, 9)","(-1, 1)","(5, 1)","(-1, 9)"]', '(5, 1)', NULL, 'Moving right adds to $x$: $2 + 3 = 5$. Moving down subtracts from $y$: $5 - 4 = 1$. The new point is (5, 1).', 'checked', '{"lint":[],"solve":{"answer":"(5, 1)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2 + 3, 5 - 4) = (5, 1).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef653049-ad32-4144-82d4-2f6fbc29ab7c', 'NC26.8.SGMR.1', 1, 'numeric', 'Reflect a point across the y-axis', 'A point at (6, -2) is reflected across the $y$-axis. What is the $x$-coordinate of its image?', '[]', '-6', '0-6', 'A reflection across the $y$-axis changes the sign of the $x$-coordinate and keeps the $y$-coordinate. The image is $(-6, -2)$, so its $x$-coordinate is $-6$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across y-axis: (x, y) -> (-x, y). (6, -2) -> (-6, -2). x-coordinate -6.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('023d7d75-10cd-4b0c-8e7d-4542273ddbb1', 'NC26.8.SGMR.1', 1, 'numeric', 'Know that rigid transformations keep lengths', 'A triangle has a perimeter of 24 centimeters. It is translated 5 units to the right and 2 units up. What is the perimeter of the new triangle, in centimeters?', '[]', '24', '24', 'A translation is a rigid transformation. It moves the triangle without changing any side length, so the perimeter stays 24 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A translation is rigid: lengths are kept, so the perimeter stays 24.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28936f7b-f356-4219-8273-b2bd48d38dd2', 'NC26.8.SGMR.1', 2, 'choice', 'Rotate a point 90 degrees about the origin', 'Point P is at (3, 1). It is rotated $90^\circ$ counterclockwise about the origin. What are the coordinates of its image?', '["(-1, 3)","(1, -3)","(-3, -1)","(1, 3)"]', '(-1, 3)', NULL, 'A $90^\circ$ counterclockwise rotation about the origin takes $(x, y)$ to $(-y, x)$. So (3, 1) goes to (-1, 3).', 'checked', '{"lint":[],"solve":{"answer":"(-1, 3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 degrees counterclockwise about origin: (x, y) -> (-y, x). (3, 1) -> (-1, 3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d00d06b-93a9-4a17-928f-d06c9d760e00', 'NC26.8.SGMR.1', 2, 'choice', 'Combine a translation and a reflection', 'Point Q is at (1, 2). It is first moved 4 units to the left and 1 unit up, and then reflected across the $x$-axis. What are the coordinates of its final image?', '["(-3, 3)","(3, 3)","(5, -3)","(-3, -3)"]', '(-3, -3)', NULL, 'Moving 4 left and 1 up takes (1, 2) to (-3, 3). Reflecting across the $x$-axis changes the sign of the $y$-coordinate, giving (-3, -3).', 'checked', '{"lint":[],"solve":{"answer":"(-3, -3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, 2) -> (1 - 4, 2 + 1) = (-3, 3). Reflect across x-axis: (-3, -3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4038bd36-8532-4f2a-b98a-483db4a68d9a', 'NC26.8.SGMR.1', 2, 'choice', 'Name the transformation that maps a triangle onto its image', 'Triangle ABC has vertices A(2, 3), B(5, 3) and C(2, 7). Its image has vertices A''(2, -3), B''(5, -3) and C''(2, -7). Which transformation moved the triangle?', '["A reflection across the $y$-axis","A reflection across the $x$-axis","A translation 6 units down","A rotation of $90^\\circ$ clockwise about the origin"]', 'A reflection across the $x$-axis', NULL, 'Every vertex keeps its $x$-coordinate and has the sign of its $y$-coordinate changed, which is a reflection across the $x$-axis. A translation 6 units down would take C(2, 7) to (2, 1), not (2, -7).', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each (x, y) -> (x, -y): reflection across the x-axis. Translation 6 down would send C(2,7) to (2,1), not (2,-7). Rotation 90 cw sends A to (3,-2). y-axis reflection changes x.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aff3ed8f-afe3-438b-b71b-e6f9084a4b3c', 'NC26.8.SGMR.1', 3, 'numeric', 'Combine a rotation and a translation', 'Point R is at (-2, 6). It is rotated $90^\circ$ clockwise about the origin and then moved 3 units to the left. What is the $x$-coordinate of its final image?', '[]', '3', '6-3', 'A $90^\circ$ clockwise rotation about the origin takes $(x, y)$ to $(y, -x)$, so (-2, 6) goes to (6, 2). Moving 3 units left subtracts 3 from $x$: (3, 2). The $x$-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 degrees clockwise: (x, y) -> (y, -x). (-2, 6) -> (6, 2). Left 3: (3, 2). x-coordinate 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('959de84a-8848-4c94-900f-07e128803bda', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image of a vertex from a given translation', 'A triangle has vertices (1, 1), (4, 1) and (1, 5). It is translated so that the vertex (4, 1) moves to (-2, 6). What is the $y$-coordinate of the image of the vertex (1, 5)?', '[]', '10', '5+(6-1)', 'The vertex (4, 1) moves to (-2, 6), which is 6 units left and 5 units up. Every point moves the same way, so (1, 5) moves to (-5, 10). Its $y$-coordinate is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector: (-2 - 4, 6 - 1) = (-6, 5). (1, 5) -> (-5, 10). y-coordinate 10.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0d1f98-14cb-444b-9414-e3adc8974983', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'Triangle ABC has vertices A(1, 2), B(3, 2) and C(1, 5). Its image has vertices A''(-1, -2), B''(-3, -2) and C''(-1, -5). Which sequence of transformations maps the triangle onto its image?', '["A reflection across the $x$-axis, then a translation 2 units left","A reflection across the $y$-axis only","A reflection across the $x$-axis, then a reflection across the $y$-axis","A rotation of $90^\\circ$ clockwise about the origin"]', 'A reflection across the $x$-axis, then a reflection across the $y$-axis', NULL, 'Reflecting across the $x$-axis takes A(1, 2) to (1, -2), B to (3, -2) and C to (1, -5). Reflecting that across the $y$-axis gives (-1, -2), (-3, -2) and (-1, -5), which match the image. The translation option works for A but takes B to (1, -2), not (-3, -2).', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis, then a reflection across the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Map is (x, y) -> (-x, -y). Reflect over x-axis (x,-y) then y-axis (-x,-y): matches all three. Rotation 90 cw: A -> (2,-1), no. x-reflection then 2 left: B(3,2) -> (1,-2), not (-3,-2). y-reflection only: A -> (-1,2), no.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a51b780a-32ea-4843-9b48-0a786495689d', 'NC26.8.SGMR.2', 1, 'choice', 'Dilate a point about the origin', 'Point A is at (3, 4). It is dilated about the origin with a scale factor of 2. What are the coordinates of its image?', '["(5, 6)","(6, 8)","(1.5, 2)","(6, 4)"]', '(6, 8)', NULL, 'A dilation about the origin with scale factor $k$ takes $(x, y)$ to $(kx, ky)$. With $k = 2$, (3, 4) goes to (6, 8).', 'checked', '{"lint":[],"solve":{"answer":"(6, 8)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply both coordinates by 2: (6, 8).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e532b6d-33cd-49e0-b580-66e3aac685c0', 'NC26.8.SGMR.2', 1, 'numeric', 'Find a scale factor from two lengths', 'A dilation changes a segment of length 4 centimeters into a segment of length 12 centimeters. What is the scale factor?', '[]', '3', '12/4', 'The scale factor is the new length divided by the old length: $12 \div 4 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6093ef0c-9ed6-4a25-8ccc-7f101b1b9801', 'NC26.8.SGMR.2', 1, 'choice', 'Know that dilations keep angle measures', 'A triangle has angles of $40^\circ$, $60^\circ$ and $80^\circ$. It is dilated with a scale factor of 3. Which statement about the image is true?', '["Its angles are $120^\\circ$, $180^\\circ$ and $240^\\circ$","Its angles are $43^\\circ$, $63^\\circ$ and $83^\\circ$","Its angles are $37^\\circ$, $57^\\circ$ and $77^\\circ$","Its angles are still $40^\\circ$, $60^\\circ$ and $80^\\circ$"]', 'Its angles are still $40^\circ$, $60^\circ$ and $80^\circ$', NULL, 'A dilation changes lengths by the scale factor but does not change angle measures. The image is the same shape, only bigger, so its angles are still $40^\circ$, $60^\circ$ and $80^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Its angles are still $40^\\circ$, $60^\\circ$ and $80^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilations preserve angle measures, so they stay 40, 60, 80 degrees.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae7be4a9-d4ef-4133-9299-5d0229284285', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a point by a scale factor less than 1', 'Point B is at (12, -9). It is dilated about the origin with a scale factor of $\frac{1}{3}$. What are the coordinates of its image?', '["(4, -3)","(36, -27)","(9, -6)","(4, 3)"]', '(4, -3)', NULL, 'Multiply both coordinates by $\frac{1}{3}$: $12 \times \frac{1}{3} = 4$ and $-9 \times \frac{1}{3} = -3$. The image is (4, -3).', 'checked', '{"lint":[],"solve":{"answer":"(4, -3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12/3, -9/3) = (4, -3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8453267-9601-40a2-b26c-83ee850cb4df', 'NC26.8.SGMR.2', 2, 'numeric', 'Find a scale factor from the coordinates of a point and its image', 'A dilation about the origin takes the point (4, 6) to the point (10, 15). What is the scale factor?', '[]', '5/2', '10/4', 'Each coordinate is multiplied by the scale factor $k$. From $4k = 10$ we get $k = \frac{10}{4} = \frac{5}{2}$. Check: $6 \times \frac{5}{2} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/4 = 2.5 and 15/6 = 2.5, consistent. Scale factor 2.5.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5804e0f7-3add-4fe3-973e-2355b998bea4', 'NC26.8.SGMR.2', 2, 'numeric', 'Find the perimeter of a dilated triangle', 'A triangle has sides of 6 cm, 8 cm and 10 cm. It is dilated with a scale factor of 1.5. What is the perimeter of the new triangle, in centimeters?', '[]', '36', '(6+8+10)*1.5', 'The original perimeter is $6 + 8 + 10 = 24$ cm. Every length is multiplied by 1.5, so the new perimeter is $24 \times 1.5 = 36$ cm. (The new sides are 9, 12 and 15, which also add to 36.)', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original perimeter 6 + 8 + 10 = 24; times 1.5 = 36. (Sides 9, 12, 15.)","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9914d394-f8eb-49aa-93a7-41df1ee50c4c', 'NC26.8.SGMR.2', 3, 'numeric', 'Find the area of a dilated triangle', 'A triangle has vertices (0, 0), (4, 0) and (0, 3). It is dilated about the origin with a scale factor of 2. What is the area of the image, in square units?', '[]', '24', '(4*2)*(3*2)/2', 'The image has vertices (0, 0), (8, 0) and (0, 6). It is a right triangle with legs 8 and 6, so its area is $\frac{1}{2} \times 8 \times 6 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image vertices (0,0), (8,0), (0,6): right triangle with legs 8 and 6, area = 1/2 x 8 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b22abd7a-209a-4870-bd6b-a59eff474faa', 'NC26.8.SGMR.2', 3, 'numeric', 'Find the scale factor of a dilation and apply it to another point', 'A dilation about the origin takes the point (6, 9) to the point (4, 6). The same dilation takes the point (15, -3) to a new point. What is the sum of the two coordinates of the new point?', '[]', '8', '(15-3)*4/6', 'The scale factor is $\frac{4}{6} = \frac{2}{3}$ (check: $9 \times \frac{2}{3} = 6$). The point (15, -3) goes to $(15 \times \frac{2}{3}, -3 \times \frac{2}{3}) = (10, -2)$. The sum of the coordinates is $10 + (-2) = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 4/6 = 6/9 = 2/3. (15, -3) -> (10, -2). Sum 10 + (-2) = 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a05a9a9b-4824-4421-bae6-5924156c3f99', 'NC26.8.SGMR.2', 3, 'numeric', 'Use a scale factor found from one pair of sides to find another side', 'A triangle has sides of 9 cm, 12 cm and 15 cm. A dilation makes a new triangle whose shortest side is 6 cm. What is the length of the longest side of the new triangle, in centimeters?', '[]', '10', '15*6/9', 'The shortest side goes from 9 to 6, so the scale factor is $\frac{6}{9} = \frac{2}{3}$. The longest side becomes $15 \times \frac{2}{3} = 10$ cm.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest 9 -> 6, scale factor 2/3. Longest 15 x 2/3 = 10.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dec18ce-a043-4363-9e5d-096cdee9f20f', 'NC26.8.SGMR.3', 1, 'choice', 'Use the side-length condition for a triangle', 'Which three lengths, in centimeters, can be the sides of a triangle?', '["3, 4, 8","2, 3, 5","4, 4, 9","5, 6, 10"]', '5, 6, 10', NULL, 'The two shorter sides must add up to more than the longest side. $5 + 6 = 11 > 10$ works. $3 + 4 = 7 < 8$, $2 + 3 = 5$ (equal, not more), and $4 + 4 = 8 < 9$ all fail.', 'checked', '{"lint":[],"solve":{"answer":"5, 6, 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4=7 < 8 no; 2+3=5 = 5 no (flat); 4+4=8 < 9 no; 5+6=11 > 10 yes (and 5+10>6, 6+10>5).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aacc70fd-a01f-4757-a08f-edfa2349c019', 'NC26.8.SGMR.3', 1, 'numeric', 'Use the angle sum of a triangle', 'Two angles of a triangle measure $48^\circ$ and $75^\circ$. What is the measure of the third angle, in degrees?', '[]', '57', '180-48-75', 'The angles of a triangle add up to $180^\circ$. The first two add to $48 + 75 = 123$, so the third is $180 - 123 = 57$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 48 - 75 = 57.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a408a89a-d652-4335-927a-c82949b4bf94', 'NC26.8.SGMR.3', 1, 'choice', 'Tell which sets of three angles can form a triangle', 'Which three angle measures can be the angles of a triangle?', '["$35^\\circ, 55^\\circ, 80^\\circ$","$40^\\circ, 60^\\circ, 80^\\circ$","$50^\\circ, 60^\\circ, 80^\\circ$","$70^\\circ, 70^\\circ, 60^\\circ$"]', '$40^\circ, 60^\circ, 80^\circ$', NULL, 'The angles of a triangle must add to $180^\circ$. $40 + 60 + 80 = 180$ works. The other sets add to 170, 190 and 200.', 'checked', '{"lint":[],"solve":{"answer":"$40^\\circ, 60^\\circ, 80^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 200, 190, 180, 170. Only 40, 60, 80 sums to 180.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8c47a85-1c41-44f7-9d37-dfe2ae60d230', 'NC26.8.SGMR.3', 2, 'numeric', 'Find the greatest possible third side', 'Two sides of a triangle are 5 cm and 9 cm long. The third side is a whole number of centimeters. What is the greatest possible length of the third side, in centimeters?', '[]', '13', '5+9-1', 'The third side must be less than the sum of the other two: less than $5 + 9 = 14$. The greatest whole number less than 14 is 13. (Check: $5 + 13 > 9$ and $9 + 13 > 5$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 5 < s < 9 + 5 -> 4 < s < 14. Greatest whole number is 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
