INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bac3dfb6-721a-4763-af47-7da44d183099', 'NC26.8.SGMR.3', 2, 'numeric', 'Use the angle sum in a right triangle', 'In a right triangle, one acute angle is 4 times as large as the other acute angle. What is the measure of the smaller acute angle, in degrees?', '[]', '18', '90/5', 'The two acute angles of a right triangle add to $90^\circ$ (since the right angle uses 90 of the 180). If the smaller is $x$, then $x + 4x = 90$, so $5x = 90$ and $x = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acute angles sum to 90: x + 4x = 90 -> x = 18. Angles 18 and 72.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8ded595-424e-4d00-8563-8c589ee932ed', 'NC26.8.SGMR.3', 2, 'choice', 'Tell which information fixes exactly one triangle', 'Which information is enough to build exactly one triangle, so that every triangle that fits it has the same size and shape?', '["Side lengths of 4 cm, 6 cm and 9 cm","Angles of $40^\\circ$, $60^\\circ$ and $80^\\circ$","Two side lengths, 5 cm and 7 cm","One side of 6 cm and one angle of $50^\\circ$"]', 'Side lengths of 4 cm, 6 cm and 9 cm', NULL, 'Three side lengths that satisfy the triangle condition ($4 + 6 > 9$) give one triangle. Three angles fix only the shape, so triangles of any size fit. Two sides, or one side and one angle, leave other measures free.', 'checked', '{"lint":[],"solve":{"answer":"Side lengths of 4 cm, 6 cm and 9 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One side and one angle: many triangles. Two sides alone: many. Three angles: same shape, any size. Three sides 4, 6, 9 (4+6=10>9, valid): exactly one triangle (SSS).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aa38b38-8ab4-4c4b-aa4d-01a9cf121daf', 'NC26.8.SGMR.3', 3, 'numeric', 'Count the possible whole-number lengths of a third side', 'Two sides of a triangle are 8 cm and 11 cm long. The third side is a whole number of centimeters. How many different lengths are possible for the third side?', '[]', '15', '(8+11-1)-(11-8+1)+1', 'The third side must be greater than $11 - 8 = 3$ and less than $8 + 11 = 19$. The whole numbers from 4 to 18 work, and there are $18 - 4 + 1 = 15$ of them.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 - 8 < s < 11 + 8 -> 3 < s < 19, so s = 4, 5, ..., 18: 18 - 4 + 1 = 15 lengths.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c85fbb4-46b6-472a-b112-5dbc809d40cd', 'NC26.8.SGMR.3', 3, 'numeric', 'Use an algebra equation with the angle sum of a triangle', 'The angles of a triangle measure $x$ degrees, $(2x + 10)$ degrees and $(3x - 10)$ degrees. What is the measure of the largest angle, in degrees?', '[]', '80', '3*(180/6)-10', 'The angles add to 180: $x + (2x + 10) + (3x - 10) = 6x = 180$, so $x = 30$. The angles are $30$, $2(30) + 10 = 70$ and $3(30) - 10 = 80$. The largest is 80 degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 10 + 3x - 10 = 6x = 180 -> x = 30. Angles 30, 70, 80. Largest 80.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3cc5c2-4b6b-44fb-b18b-36ffc666598f', 'NC26.8.SGMR.3', 3, 'choice', 'Decide how many triangles fit given sides and the angle between them', 'A triangle has one side of 10 cm and another side of 12 cm, and the angle between those two sides is $30^\circ$. How many triangles with different shapes or sizes can be built with these measurements?', '["Exactly two","None","Exactly one","Infinitely many"]', 'Exactly one', NULL, 'Two sides and the angle between them fix the third side and the other two angles, so only one triangle (up to identical size and shape) can be built.', 'checked', '{"lint":[],"solve":{"answer":"Exactly one","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two sides and the included angle (SAS) fix the triangle: exactly one.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8aa8497-7af7-42c0-af68-d784e80e0109', 'NC26.8.SGMR.4', 1, 'numeric', 'Angle sum of a triangle', 'Two angles of a triangle measure $48^\circ$ and $67^\circ$. What is the measure of the third angle, in degrees?', '[]', '65', '180-48-67', 'The three angles of a triangle add up to $180^\circ$. First, $48 + 67 = 115$. Then $180 - 115 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 48 - 67 = 65.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ae32a1-302a-4128-9f2f-4d910519ae16', 'NC26.8.SGMR.4', 1, 'choice', 'Corresponding angles and parallel lines', 'Two parallel lines are cut by a transversal. Angle 1 and angle 2 are corresponding angles. Angle 1 measures $110^\circ$. What is the measure of angle 2, in degrees?', '["70","110","55","250"]', '110', '110', 'When two parallel lines are cut by a transversal, corresponding angles are equal. So angle 2 also measures $110^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles formed by parallel lines and a transversal are congruent, so angle 2 = 110.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4997cbef-2039-4292-9200-935b5620c79f', 'NC26.8.SGMR.4', 1, 'numeric', 'Exterior angle of a triangle', 'One side of a triangle is extended to form an exterior angle. The two interior angles that are not next to the exterior angle measure $40^\circ$ and $55^\circ$. What is the measure of the exterior angle, in degrees?', '[]', '95', '40+55', 'An exterior angle of a triangle equals the sum of the two interior angles that are not next to it. $40 + 55 = 95$. Check: the third interior angle is $180 - 95 = 85$, and $40 + 55 + 85 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle = sum of the two remote interior angles = 40 + 55 = 95.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5546ac1-c07d-4d8b-aa38-6bf7c394b146', 'NC26.8.SGMR.4', 2, 'numeric', 'Unknown angles in a triangle (algebra)', 'The angles of a triangle measure $(x+10)^\circ$, $(2x)^\circ$ and $(x+30)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '70', '2*(180-40)/4', 'The angles add up to $180$: $(x+10) + 2x + (x+30) = 4x + 40 = 180$, so $4x = 140$ and $x = 35$. The angles are $45^\circ$, $70^\circ$ and $65^\circ$. The largest is $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+10) + 2x + (x+30) = 180 -> 4x + 40 = 180 -> x = 35. Angles: 45, 70, 65. Largest = 70.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8aa47413-92fe-4336-b197-26e143899abc', 'NC26.8.SGMR.4', 2, 'numeric', 'Alternate interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two alternate interior angles measure $(3x+5)^\circ$ and $65^\circ$. What is the value of $x$?', '[]', '20', '(65-5)/3', 'Alternate interior angles are equal when the lines are parallel. So $3x + 5 = 65$. Subtract 5: $3x = 60$. Divide by 3: $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior angles are congruent: 3x + 5 = 65 -> 3x = 60 -> x = 20.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06f64e13-493f-4479-a52c-24a49bbcc5ec', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two angles on the same side of the transversal and between the parallel lines measure $(2x+10)^\circ$ and $(x+20)^\circ$. What is the value of $x$?', '["10","50","60","70"]', '50', '(180-30)/3', 'Same-side interior angles add up to $180^\circ$ when the lines are parallel. So $(2x+10) + (x+20) = 180$, which gives $3x + 30 = 180$. Then $3x = 150$ and $x = 50$. The angles are $110^\circ$ and $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angles are supplementary: (2x+10) + (x+20) = 180 -> 3x + 30 = 180 -> x = 50. Check: 110 + 70 = 180.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949c46c2-de6a-4c64-a2ed-f78efc709385', 'NC26.8.SGMR.4', 3, 'numeric', 'Exterior angle used to find an interior angle', 'In triangle $ABC$, angle $A$ measures $50^\circ$. The exterior angle at vertex $B$ (formed by extending a side of the triangle past $B$) measures $115^\circ$. What is the measure of angle $C$, in degrees?', '[]', '65', '115-50', 'The exterior angle at $B$ equals the sum of the two interior angles that are not next to it, angles $A$ and $C$. So $50 + C = 115$ and $C = 65$. Check: angle $B$ is $180 - 115 = 65$, and $50 + 65 + 65 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle at B = A + C, so C = 115 - 50 = 65. Check: B = 180 - 115 = 65; 50 + 65 + 65 = 180.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3386c128-bccf-47a5-8f91-77f90f9a8a90', 'NC26.8.SGMR.4', 3, 'choice', 'Exterior angle with algebra', 'A triangle has an exterior angle that measures $(4x-10)^\circ$. The two interior angles that are not next to it measure $(x+20)^\circ$ and $(x+30)^\circ$. What is the measure of the exterior angle, in degrees?', '["30","70","110","120"]', '110', '4*30-10', 'The exterior angle equals the sum of the two far interior angles: $4x - 10 = (x+20) + (x+30) = 2x + 50$. So $2x = 60$ and $x = 30$. The exterior angle is $4(30) - 10 = 110^\circ$. Check: $50 + 60 = 110$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle = sum of remote interiors: 4x - 10 = (x+20) + (x+30) = 2x + 50 -> 2x = 60 -> x = 30. Exterior = 4(30) - 10 = 110 (remote interiors 50 and 60).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e59dc14-f6f3-4f76-af4a-c73b5312bdba', 'NC26.8.SGMR.4', 3, 'numeric', 'Multi-step angle problem with parallel lines', 'Two parallel lines are cut by a transversal. Two corresponding angles measure $(5x-12)^\circ$ and $(3x+18)^\circ$. What is the measure, in degrees, of an angle that forms a linear pair with the angle measuring $(5x-12)^\circ$?', '[]', '117', '180-(5*15-12)', 'Corresponding angles are equal, so $5x - 12 = 3x + 18$. Then $2x = 30$ and $x = 15$. The angle is $5(15) - 12 = 63^\circ$. A linear pair adds up to $180^\circ$, so the other angle is $180 - 63 = 117^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"117","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles equal: 5x - 12 = 3x + 18 -> 2x = 30 -> x = 15. Angle = 5(15) - 12 = 63. Linear pair: 180 - 63 = 117.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('121fb7eb-1fab-46f9-a3de-49d85fac053a', 'NC26.8.SGMR.5', 1, 'numeric', 'Find the hypotenuse (whole-number answer)', 'The legs of a right triangle are 6 inches and 8 inches long. How long is the hypotenuse, in inches?', '[]', '10', '(6^2+8^2)/10', 'Use $a^2 + b^2 = c^2$. $6^2 + 8^2 = 36 + 64 = 100$, so $c = \sqrt{100} = 10$ inches.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = sqrt(6^2 + 8^2) = sqrt(36 + 64) = sqrt(100) = 10.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86728be9-589b-48fc-8e73-af9b0df955d3', 'NC26.8.SGMR.5', 1, 'choice', 'State the Pythagorean Theorem', 'A right triangle has legs of length $a$ and $b$ and a hypotenuse of length $c$. Which equation is always true?', '["$a+b=c$","$a^2+b^2=c^2$","$a^2+c^2=b^2$","$a^2-b^2=c^2$"]', '$a^2+b^2=c^2$', NULL, 'The Pythagorean Theorem says that the sum of the squares of the two legs equals the square of the hypotenuse: $a^2 + b^2 = c^2$.', 'checked', '{"lint":[],"solve":{"answer":"$a^2+b^2=c^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pythagorean Theorem with legs a, b and hypotenuse c: a^2 + b^2 = c^2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('570ecc02-6a37-4271-86bc-8b7ea6ecf5b2', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a leg of a right triangle in context', 'A 20-foot ladder leans against a wall. The bottom of the ladder is 16 feet from the wall. How high up the wall does the ladder reach, in feet?', '[]', '12', '(20^2-16^2)/12', 'The ladder is the hypotenuse of a right triangle. $16^2 + h^2 = 20^2$, so $h^2 = 400 - 256 = 144$ and $h = 12$ feet.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = sqrt(20^2 - 16^2) = sqrt(400 - 256) = sqrt(144) = 12.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('289d0be1-06ce-4b23-a212-bbd388a9dd19', 'NC26.8.SGMR.5', 2, 'choice', 'Find the hypotenuse (square root answer)', 'The legs of a right triangle are 5 cm and 7 cm long. What is the length of the hypotenuse, in centimeters?', '["$74$","$12$","$\\sqrt{74}$","$\\sqrt{24}$"]', '$\sqrt{74}$', NULL, '$c^2 = 5^2 + 7^2 = 25 + 49 = 74$, so $c = \sqrt{74}$. (Adding the legs, $5 + 7 = 12$, is not the hypotenuse, and $74$ is $c^2$, not $c$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{74}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 5^2 + 7^2 = 25 + 49 = 74, so c = sqrt(74).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6659e1c-20c9-4a0b-8bda-abf893a89600', 'NC26.8.SGMR.5', 2, 'numeric', 'Distance on the coordinate plane', 'Point $A$ is at $(1, 2)$ and point $B$ is at $(6, 14)$ on a coordinate plane. What is the distance from $A$ to $B$, in units?', '[]', '13', '(5^2+12^2)/13', 'The horizontal change is $6 - 1 = 5$ and the vertical change is $14 - 2 = 12$. These are the legs of a right triangle, so the distance is $\sqrt{5^2 + 12^2} = \sqrt{169} = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 6 - 1 = 5, dy = 14 - 2 = 12. d = sqrt(25 + 144) = sqrt(169) = 13.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('988f2dbc-3f69-4b15-ab84-cd5c118cfc91', 'NC26.8.SGMR.5', 2, 'choice', 'Converse of the Pythagorean Theorem', 'A triangle has side lengths 8 cm, 15 cm and 17 cm. Which statement is correct?', '["It is a right triangle, because $8^2+15^2=17^2$","It is not a right triangle, because $8+15\\ne 17$","It is not a right triangle, because $8^2+17^2\\ne 15^2$","It is not a right triangle, because its three sides are all different lengths"]', 'It is a right triangle, because $8^2+15^2=17^2$', NULL, 'Test the converse with the longest side as the hypotenuse: $8^2 + 15^2 = 64 + 225 = 289$ and $17^2 = 289$. The two are equal, so the triangle is a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"It is a right triangle, because $8^2+15^2=17^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8^2 + 15^2 = 64 + 225 = 289 = 17^2, so by the converse it is a right triangle.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2637e58b-8633-4cf1-831d-a8d89a82597c', 'NC26.8.SGMR.5', 3, 'numeric', 'Distance between points with negative coordinates', 'Point $A$ is at $(-5, -2)$ and point $B$ is at $(2, 22)$ on a coordinate plane. What is the distance from $A$ to $B$, in units?', '[]', '25', '(7^2+24^2)/25', 'The horizontal change is $2 - (-5) = 7$ and the vertical change is $22 - (-2) = 24$. The distance is $\sqrt{7^2 + 24^2} = \sqrt{49 + 576} = \sqrt{625} = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 2 - (-5) = 7, dy = 22 - (-2) = 24. d = sqrt(49 + 576) = sqrt(625) = 25.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c10e86d-7d0b-4286-af0f-0818ce1e473c', 'NC26.8.SGMR.5', 3, 'choice', 'Distance on the coordinate plane (square root answer)', 'Point $P$ is at $(-2, 5)$ and point $Q$ is at $(3, -1)$ on a coordinate plane. What is the distance from $P$ to $Q$, in units?', '["$11$","$\\sqrt{61}$","$\\sqrt{17}$","$\\sqrt{11}$"]', '$\sqrt{61}$', NULL, 'The horizontal change is $3 - (-2) = 5$ and the vertical change is $5 - (-1) = 6$. The distance is $\sqrt{5^2 + 6^2} = \sqrt{25 + 36} = \sqrt{61}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{61}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 3 - (-2) = 5, dy = -1 - 5 = -6. d = sqrt(25 + 36) = sqrt(61).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('778704a0-e33c-4792-b511-90236eb8c1f0', 'NC26.8.SGMR.5', 3, 'numeric', 'Pythagorean Theorem in an isosceles triangle', 'An isosceles triangle has two sides that are each 17 cm long and a base that is 16 cm long. What is the height of the triangle from the base to the opposite corner, in centimeters?', '[]', '15', '(17^2-8^2)/15', 'The height cuts the base into two halves of 8 cm and makes a right triangle with hypotenuse 17 cm. So $h^2 + 8^2 = 17^2$, which gives $h^2 = 289 - 64 = 225$ and $h = 15$ cm.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The height bisects the base: half-base 8, side 17. h = sqrt(17^2 - 8^2) = sqrt(289 - 64) = sqrt(225) = 15.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53d6aac8-d156-4b91-900f-e91c84f6daf6', 'NC26.8.SGMR.6', 1, 'numeric', 'Pyramid volume compared with a prism', 'A prism and a pyramid have the same base and the same height. The volume of the prism is 90 cubic centimeters. What is the volume of the pyramid, in cubic centimeters?', '[]', '30', '90/3', 'A pyramid holds one third of the volume of a prism with the same base and height. $90 \div 3 = 30$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pyramid volume = 1/3 of prism with same base and height: 90 / 3 = 30.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31ed1ad2-41d9-45d8-935e-ff7ce21ff7b5', 'NC26.8.SGMR.6', 1, 'choice', 'Cone volume compared with a cylinder', 'A cone and a cylinder have the same radius and the same height. The volume of the cylinder is $60\pi$ cubic centimeters. What is the volume of the cone?', '["$30\\pi$ cubic centimeters","$60\\pi$ cubic centimeters","$20\\pi$ cubic centimeters","$180\\pi$ cubic centimeters"]', '$20\pi$ cubic centimeters', NULL, 'A cone holds one third of the volume of a cylinder with the same radius and height. $\frac{1}{3} \times 60\pi = 20\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$20\\pi$ cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone volume = 1/3 of cylinder with same radius and height: 60pi / 3 = 20pi.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('973dc9be-e8da-442a-b2e5-6443770c4824', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a square pyramid', 'A square pyramid has a base edge of 6 cm and a height of 10 cm. What is its volume, in cubic centimeters?', '[]', '120', '1/3*6^2*10', 'The base area is $6 \times 6 = 36$ square centimeters. Volume $= \frac{1}{3} \times 36 \times 10 = 120$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(6^2)(10) = (1/3)(36)(10) = 120.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d995d1b1-37a0-4c76-afc4-c1beae593e44', 'NC26.8.SGMR.6', 2, 'numeric', 'Surface area of a square pyramid', 'A square pyramid has a base edge of 10 cm. The height of each triangular face (the slant height) is 13 cm. What is the total surface area of the pyramid, in square centimeters?', '[]', '360', '10^2+4*(1/2*10*13)', 'The square base has area $10 \times 10 = 100$. Each triangular face has area $\frac{1}{2} \times 10 \times 13 = 65$, and there are 4 of them, so $4 \times 65 = 260$. The total is $100 + 260 = 360$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base = 10^2 = 100. Each triangular face = (1/2)(10)(13) = 65; four faces = 260. Total = 100 + 260 = 360.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc496dbe-4174-4cf7-b81c-db5591659c7a', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'A cone has a radius of 3 cm and a height of 8 cm. What is its volume, in cubic centimeters?', '["$24\\pi$","$72\\pi$","$8\\pi$","$36\\pi$"]', '$24\pi$', NULL, 'Volume $= \frac{1}{3}\pi r^2 h = \frac{1}{3} \times \pi \times 3^2 \times 8 = \frac{1}{3} \times 72\pi = 24\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$24\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi r^2 h = (1/3)pi(9)(8) = 24pi.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91880cf9-a38c-4852-a389-98d9551281da', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a sphere', 'A sphere has a radius of 3 cm. Its volume is $k\pi$ cubic centimeters. What is the value of $k$?', '[]', '36', '4/3*3^3', 'Volume $= \frac{4}{3}\pi r^3 = \frac{4}{3} \times \pi \times 27 = 36\pi$. So $k = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)pi(3^3) = (4/3)(27)pi = 36pi, so k = 36.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12730f45-9959-4656-9c81-6c34d590c3f8', 'NC26.8.SGMR.6', 3, 'numeric', 'Find the height of a cone from its volume', 'A cone has a radius of 4 cm and a volume of $48\pi$ cubic centimeters. What is its height, in centimeters?', '[]', '9', '48*3/16', 'Volume $= \frac{1}{3}\pi r^2 h$, so $48\pi = \frac{1}{3} \times \pi \times 16 \times h$. Divide by $\pi$ and multiply by 3: $144 = 16h$, so $h = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)pi(4^2)h = 48pi -> (16/3)h = 48 -> h = 9.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b35fb82-6d60-4e66-b910-527112a24194', 'NC26.8.SGMR.6', 3, 'choice', 'Sphere inside a cylinder', 'A sphere fits exactly inside a cylinder: it touches the top, the bottom and the curved side of the cylinder. The volume of the cylinder is $54\pi$ cubic centimeters. What is the volume of the sphere, in cubic centimeters?', '["$18\\pi$","$27\\pi$","$72\\pi$","$36\\pi$"]', '$36\pi$', NULL, 'The cylinder has radius $r$ and height $2r$, so its volume is $\pi r^2 (2r) = 2\pi r^3 = 54\pi$. Then $r^3 = 27$ and $r = 3$. The sphere has volume $\frac{4}{3}\pi (3^3) = 36\pi$ cubic centimeters. (It is $\frac{2}{3}$ of the cylinder: $\frac{2}{3} \times 54\pi = 36\pi$.)', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder has radius r and height 2r: 2pi r^3 = 54pi -> r^3 = 27 -> r = 3. Sphere = (4/3)pi(27) = 36pi (equivalently 2/3 of the cylinder).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc135c39-c281-4779-8ebf-0674fa44e14b', 'NC26.8.SGMR.6', 3, 'numeric', 'Surface area of a pyramid using its height', 'A square pyramid has a base edge of 16 cm and a height of 15 cm, measured straight up from the center of the base to the top. What is its total surface area, in square centimeters?', '[]', '800', '16^2+4*(1/2*16*17)', 'First find the slant height (the height of a triangular face). It is the hypotenuse of a right triangle with legs 15 and $16 \div 2 = 8$: $\sqrt{15^2 + 8^2} = \sqrt{289} = 17$. The base has area $16^2 = 256$. Each triangular face has area $\frac{1}{2} \times 16 \times 17 = 136$, and $4 \times 136 = 544$. The total is $256 + 544 = 800$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slant height: from base centre to midpoint of an edge is 8; slant = sqrt(15^2 + 8^2) = sqrt(225 + 64) = sqrt(289) = 17. Lateral = 4 * (1/2)(16)(17) = 4 * 136 = 544. Base = 16^2 = 256. Total = 800.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8abf898-e74a-4f4f-b8cf-8deeafbe7a1d', 'NC26.8.RD.1', 1, 'choice', 'Identify mutually exclusive events', 'A number cube with faces numbered 1 to 6 is rolled once. Which pair of events is mutually exclusive?', '["Rolling an even number and rolling an odd number","Rolling an even number and rolling a number greater than 3","Rolling a prime number and rolling an odd number","Rolling a number less than 4 and rolling an odd number"]', 'Rolling an even number and rolling an odd number', NULL, 'Mutually exclusive events cannot both happen on the same roll. A number cannot be both even and odd. The other pairs share an outcome: 4 and 6 are even and greater than 3; 3 and 5 are prime and odd; 1 and 3 are less than 4 and odd.', 'checked', '{"lint":[],"solve":{"answer":"Rolling an even number and rolling an odd number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even {2,4,6} and odd {1,3,5} share nothing: mutually exclusive. Others overlap: even & >3 share 4,6; <4 & odd share 1,3; prime & odd share 3,5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cc5ff25-0c1b-45e6-bcab-0077d7ed8115', 'NC26.8.RD.1', 1, 'numeric', 'Probability of one event or another (mutually exclusive)', 'A bag holds 4 red marbles, 3 blue marbles and 5 green marbles. One marble is drawn at random. What is the probability that it is red or blue?', '[]', '7/12', '(4+3)/12', 'There are $4 + 3 + 5 = 12$ marbles. A marble cannot be both red and blue, so add: $\frac{4}{12} + \frac{3}{12} = \frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 marbles; red or blue = 4 + 3 = 7. P = 7/12.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1175d36a-b86f-48b4-84ff-9f6131fd9f46', 'NC26.8.RD.1', 1, 'numeric', 'Probability of an "or" event on a spinner', 'A spinner has 10 equal sections numbered 1 to 10. It is spun once. What is the probability that it lands on a number less than 3 or greater than 8?', '[]', '2/5', '4/10', 'Numbers less than 3: 1 and 2. Numbers greater than 8: 9 and 10. No number is in both lists, so 4 of the 10 outcomes work. The probability is $\frac{4}{10} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 3: {1,2}; greater than 8: {9,10}; disjoint. 4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8888b1c9-1dfc-4dc1-b95a-7f57cf1da7a4', 'NC26.8.RD.1', 2, 'numeric', 'Probability of mutually exclusive events from a list of outcomes', 'A bag holds 12 tiles numbered 1 to 12. One tile is drawn at random. What is the probability that it is a prime number or the number 9?', '[]', '1/2', '(5+1)/12', 'The prime numbers from 1 to 12 are 2, 3, 5, 7 and 11, which is 5 tiles. The number 9 is not prime, so the events are mutually exclusive: $5 + 1 = 6$ tiles work. The probability is $\frac{6}{12} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Primes 1-12: 2,3,5,7,11 (5). 9 is not prime, so add 1: 6/12 = 1/2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2492f874-718b-40dd-bf83-416d10a49385', 'NC26.8.RD.1', 2, 'choice', 'Justify adding probabilities', 'A fair number cube is rolled once. Jamal finds the probability of rolling a 2 or a 5 by adding $\frac{1}{6} + \frac{1}{6} = \frac{1}{3}$. Why is it correct to add the two probabilities?', '["Both probabilities have the same denominator","The two probabilities are equal","One roll cannot be both a 2 and a 5","Both numbers are less than 6"]', 'One roll cannot be both a 2 and a 5', NULL, 'Probabilities can be added when the events are mutually exclusive, which means they cannot both happen at once. One roll cannot be both a 2 and a 5, so the probabilities may be added.', 'checked', '{"lint":[],"solve":{"answer":"One roll cannot be both a 2 and a 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding is valid because the events are mutually exclusive: a single roll cannot show both 2 and 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25d6016b-e919-4235-8b0f-0480b4fce099', 'NC26.8.RD.1', 2, 'numeric', 'Probability of overlapping (inclusive) events from counts', 'In a class of 30 students, 12 play soccer, 9 play basketball and 4 play both sports. One student is chosen at random. What is the probability that the student plays soccer or basketball or both?', '[]', '17/30', '(12+9-4)/30', 'The 4 students who play both sports are counted in both the 12 and the 9, so subtract them once: $12 + 9 - 4 = 17$ students play at least one of the sports. The probability is $\frac{17}{30}$.', 'checked', '{"lint":[],"solve":{"answer":"17/30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Soccer or basketball = 12 + 9 - 4 = 17 students. P = 17/30.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eedbd3e6-9b12-4b40-b67a-fa0a5cb2620a', 'NC26.8.RD.1', 3, 'numeric', 'Probability of both events from the probability of either', 'For two events $A$ and $B$, $P(A) = 0.5$, $P(B) = 0.45$ and $P(A \text{ or } B) = 0.8$. What is $P(A \text{ and } B)$, the probability that both events happen?', '[]', '0.15', '0.5+0.45-0.8', 'For any two events, $P(A \text{ or } B) = P(A) + P(B) - P(A \text{ and } B)$. So $0.8 = 0.5 + 0.45 - P(A \text{ and } B)$, which gives $P(A \text{ and } B) = 0.95 - 0.8 = 0.15$.', 'checked', '{"lint":[],"solve":{"answer":"0.15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(A and B) = P(A) + P(B) - P(A or B) = 0.5 + 0.45 - 0.8 = 0.15.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('304e1f68-2fd5-481f-99d9-4a021e2d04b9', 'NC26.8.RD.1', 3, 'choice', 'Complement of mutually exclusive events', 'On a certain day, the probability of rain is 0.35 and the probability of snow is 0.2. Rain and snow are mutually exclusive on this day. What is the probability that it neither rains nor snows?', '["0.55","0.45","0.15","0.07"]', '0.45', '1-(0.35+0.2)', 'Because the events are mutually exclusive, $P(\text{rain or snow}) = 0.35 + 0.2 = 0.55$. The probability of neither is $1 - 0.55 = 0.45$.', 'checked', '{"lint":[],"solve":{"answer":"0.45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mutually exclusive: P(rain or snow) = 0.35 + 0.2 = 0.55. Neither = 1 - 0.55 = 0.45.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94792b6a-e8ab-4739-b55b-96bc312a5fc2', 'NC26.8.RD.1', 3, 'numeric', 'Probability of overlapping events among integers', 'One integer from 1 to 40 is chosen at random. What is the probability that it is a multiple of 4 or a multiple of 6?', '[]', '13/40', '(10+6-3)/40', 'Multiples of 4: 4, 8, ..., 40, which is 10 numbers. Multiples of 6: 6, 12, ..., 36, which is 6 numbers. Numbers that are both are multiples of 12: 12, 24 and 36, which is 3 numbers. Count them once: $10 + 6 - 3 = 13$. The probability is $\frac{13}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"13/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4 up to 40: 10. Multiples of 6: 6 (6,...,36). Multiples of both (12): 12, 24, 36 = 3. 10 + 6 - 3 = 13. P = 13/40.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ad53dc6-ecd4-4a4c-9825-d3a6e9a98fd0', 'NC26.8.RD.2', 1, 'choice', 'Recognize a statistical question', 'Which of these is a statistical question?', '["How many minutes do the students in our school spend on homework each night?","How many students are in our school on the first day of class?","What time does the first bell ring at our school each day?","How many minutes are there in one hour of the day?"]', 'How many minutes do the students in our school spend on homework each night?', NULL, 'A statistical question expects answers that vary, so it needs data from many people. Each student may spend a different number of minutes on homework. The other questions each have a single fixed answer.', 'checked', '{"lint":[],"solve":{"answer":"How many minutes do the students in our school spend on homework each night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question anticipates variability in the data. Homework minutes vary among students; the others each have one fixed answer.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0b5f2e6-83a2-4a5c-9a91-b4e243c2ce49', 'NC26.8.RD.2', 1, 'choice', 'Identify a random sample', 'A school has 600 students. The principal wants to know what students think of the lunch menu. Which method gives a random sample of students?', '["Ask the first 30 students who arrive in the lunch line","Ask 30 members of the school''s cooking club","Draw 30 names from a hat that holds every student''s name","Ask the 30 students who volunteer after seeing a sign"]', 'Draw 30 names from a hat that holds every student''s name', NULL, 'In a random sample, every student has an equal chance of being chosen. Drawing names from a hat that holds everyone''s name does this. The other methods favor students who are early, who like cooking, or who choose to take part.', 'checked', '{"lint":[],"solve":{"answer":"Draw 30 names from a hat that holds every student''s name","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing names from a hat holding every student gives every student an equal chance: a random sample. The others are convenience or voluntary samples.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de1fff23-2067-4230-9255-d7adec294d21', 'NC26.8.RD.2', 1, 'numeric', 'Use a sample to predict for a population', 'In a random sample of 50 students at a school, 20 said they walk to school. The school has 600 students. About how many students at the school would you predict walk to school?', '[]', '240', '20/50*600', '$\frac{20}{50} = \frac{2}{5}$ of the sample walk. Assuming the sample is representative, predict $\frac{2}{5} \times 600 = 240$ students.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample rate 20/50 = 40%. 0.4 * 600 = 240.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34892d35-4130-4b97-ad25-5e36fa7c94ec', 'NC26.8.RD.2', 2, 'choice', 'Identify bias in a sample', 'A town wants to know whether its residents want a new park. The town surveys 100 people as they leave a sports store. Why might this sample be biased?', '["One hundred people is always too few for a survey","People at a sports store may not represent all of the town''s residents","Surveys cannot be given outside a person''s home","People who are leaving a store cannot answer honestly"]', 'People at a sports store may not represent all of the town''s residents', NULL, 'A sample is biased when it does not represent the whole population. People shopping at a sports store may like outdoor activities more than other residents, so their answers may not match the whole town.', 'checked', '{"lint":[],"solve":{"answer":"People at a sports store may not represent all of the town''s residents","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sports-store shoppers are likely more interested in parks/sports than the general town population, so they may not represent all residents.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c178ea5-dd7a-44ce-a0a2-4a0bf0649b88', 'NC26.8.RD.2', 2, 'choice', 'Choose a simulation', 'About 40% of the students at a school are in the band. Which tool could be used to simulate choosing one student at random and seeing whether the student is in the band?', '["A spinner with 10 equal sections, 4 of them labeled \"band\"","A coin: heads means the student is in the band","A number cube: rolling a 4 means the student is in the band","A spinner with 4 equal sections, 1 of them labeled \"band\""]', 'A spinner with 10 equal sections, 4 of them labeled "band"', NULL, 'The tool must give "band" with probability 40%, which is $\frac{4}{10}$. A 10-section spinner with 4 band sections does that. A coin gives 50%, a number cube gives about 17%, and a 4-section spinner with one band section gives 25%.', 'checked', '{"lint":[],"solve":{"answer":"A spinner with 10 equal sections, 4 of them labeled \"band\"","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need a 40% chance: 4 of 10 equal sections = 40%. Others give 25%, 50%, 1/6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25aa734a-1f4a-432c-8548-adf7de552f1c', 'NC26.8.RD.2', 2, 'numeric', 'Compare samples from several populations', 'A researcher asks 40 randomly chosen students at each of three schools whether they own a bike. At School A, 22 of the 40 students say yes. At School B, 26 say yes. At School C, 30 say yes. How many percentage points higher is the percent of bike owners in the sample from School C than in the sample from School A?', '[]', '20', '30/40*100-22/40*100', 'School C: $\frac{30}{40} = 75\%$. School A: $\frac{22}{40} = 55\%$. (School B, $\frac{26}{40} = 65\%$, is not needed.) The difference is $75 - 55 = 20$ percentage points.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"School A: 22/40 = 55%. School C: 30/40 = 75%. Difference = 20 percentage points.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a714afcb-abe5-4de9-b472-58c75f7cf8c3', 'NC26.8.RD.2', 3, 'choice', 'Choose the sample that best represents several populations', 'A school has 300 students in each of grades 6, 7 and 8. A researcher wants to compare how much sleep students in each grade get. Which sample would best represent all of the school''s students?', '["The first 60 students who arrive at school in the morning","60 students who are on the school''s sports teams","60 students who choose to answer a poll on the school website","20 students chosen at random from each grade''s class list"]', '20 students chosen at random from each grade''s class list', NULL, 'A good sample is random and includes students from every grade. Choosing 20 at random from each grade''s list does that. The other samples are not random and may over-represent early arrivals, athletes or students who like to answer polls.', 'checked', '{"lint":[],"solve":{"answer":"20 students chosen at random from each grade''s class list","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from each grade (equal-sized grades) represents the whole school; the others are voluntary, convenience or biased (sports teams).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99d529be-c75e-4c16-ae96-714e3172428a', 'NC26.8.RD.2', 3, 'numeric', 'Estimate a probability from simulation results', 'Mia simulates choosing random samples of 10 students from a population in which 30% of students like soccer. She runs 25 trials. In 6 of the 25 trials, 5 or more of the 10 students in the sample liked soccer. Based on her simulation, what is the estimated probability, as a percent, that a random sample of 10 students has 5 or more who like soccer?', '[]', '24', '6/25*100', 'The estimate is the fraction of trials in which the event happened: $\frac{6}{25} = 0.24 = 24\%$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimated probability = 6/25 = 0.24 = 24%.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cdd81a0-10f8-4b72-8929-0c191f2c89f9', 'NC26.8.RD.2', 3, 'choice', 'Recognize an unbiased survey question', 'A student wants to ask classmates about their sleep. Which survey question is the least biased, meaning it does not push people toward a particular answer?', '["Don''t you agree that students sleep far too little?","How many hours do you usually sleep on a school night?","How terribly do you sleep on school nights?","Wouldn''t you say that you are always too tired at school?"]', 'How many hours do you usually sleep on a school night?', NULL, 'A fair question uses neutral wording. The other three questions use loaded words ("far too little", "terribly", "always too tired") that suggest the answer the writer expects.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do you usually sleep on a school night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The neutral question asks for hours without leading wording.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d171f08c-e5c9-4df7-874c-6cb707dedf90', 'NC26.8.RD.3', 1, 'numeric', 'Compare the ranges of two data sets', 'Data set P is 3, 5, 5, 8, 9. Data set Q is 1, 4, 6, 7, 12. How much greater is the range of Q than the range of P?', '[]', '5', '(12-1)-(9-3)', 'The range of P is $9 - 3 = 6$. The range of Q is $12 - 1 = 11$. The difference is $11 - 6 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 9 - 3 = 6. Range Q = 12 - 1 = 11. Difference = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d18d25c-03ec-4b5a-b664-3f25fb1ec448', 'NC26.8.RD.3', 1, 'choice', 'Compare the medians of two data sets', 'Quiz scores for two classes are listed. Class A: 70, 75, 80, 85, 90. Class B: 60, 78, 82, 84, 96. Which statement is true?', '["Class B''s median is 2 points higher than Class A''s median","Class A''s median is 2 points higher than Class B''s median","The two classes have the same median","Class B''s median is 16 points higher than Class A''s median"]', 'Class B''s median is 2 points higher than Class A''s median', NULL, 'The median is the middle value of the ordered list. Class A: 80. Class B: 82. So Class B''s median is 2 points higher. (The two classes have the same mean, 80, but not the same median. The ranges are 20 and 36, which differ by 16.)', 'checked', '{"lint":[],"solve":{"answer":"Class B''s median is 2 points higher than Class A''s median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median A = 80 (middle of 5). Median B = 82. B is 2 points higher.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b49d5a-bc05-449b-9099-7fb372e41e17', 'NC26.8.RD.3', 1, 'numeric', 'Find the smallest range among three data sets', 'Three data sets are listed. Set X: 12, 15, 18, 20. Set Y: 10, 11, 13, 14. Set Z: 5, 9, 12, 21. What is the smallest range of the three sets?', '[]', '4', '14-10', 'Set X: $20 - 12 = 8$. Set Y: $14 - 10 = 4$. Set Z: $21 - 5 = 16$. The smallest range is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range X = 20 - 12 = 8; Y = 14 - 10 = 4; Z = 21 - 5 = 16. Smallest = 4.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014759da-0a02-4600-8168-ec102660b2a9', 'NC26.8.RD.3', 2, 'choice', 'Compare distributions: outliers and medians', 'Test scores are listed for two groups. Group 1: 45, 82, 84, 85, 85, 86, 88. Group 2: 70, 75, 78, 80, 82, 85, 88. Which statement is true?', '["Group 2 has an outlier, and its median is higher than Group 1''s median","Neither group has an outlier, and the medians are equal","Group 1 has an outlier, and its median is lower than Group 2''s median","Group 1 has an outlier, and its median is higher than Group 2''s median"]', 'Group 1 has an outlier, and its median is higher than Group 2''s median', NULL, 'Group 1 has one score, 45, far below all of the others, so it is an outlier. Group 2''s scores are spread fairly evenly with no outlier. The median of Group 1 is the 4th of 7 values, 85. The median of Group 2 is 80. So Group 1 has an outlier and the higher median.', 'checked', '{"lint":[],"solve":{"answer":"Group 1 has an outlier, and its median is higher than Group 2''s median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group 1 median = 85; Q1 = 82, Q3 = 86, IQR 4, lower fence 76, so 45 is an outlier. Group 2 median = 80; Q1 = 75, Q3 = 85, IQR 10, fences 60 and 100, no outlier. Group 1 has an outlier and higher median.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84257947-9259-47ab-8b69-6381109471b8', 'NC26.8.RD.3', 2, 'numeric', 'Compare the means of two data sets', 'Data set A is 10, 12, 14, 16. Data set B is 9, 13, 19, 23. How much greater is the mean of B than the mean of A?', '[]', '3', '(9+13+19+23)/4-(10+12+14+16)/4', 'Mean of A: $\frac{10+12+14+16}{4} = \frac{52}{4} = 13$. Mean of B: $\frac{9+13+19+23}{4} = \frac{64}{4} = 16$. The difference is $16 - 13 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean A = 52/4 = 13. Mean B = 64/4 = 16. Difference = 3.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc6011ff-19cc-478e-a39f-a6d048513158', 'NC26.8.RD.3', 2, 'choice', 'Compare the spread of three data sets with equal means', 'Three data sets each have six values and a mean of 10. Set A: 9, 9, 10, 10, 11, 11. Set B: 5, 8, 10, 10, 12, 15. Set C: 10, 10, 10, 10, 10, 10. Which set''s values are the most spread out?', '["Set A","Set B","Set C","They are equally spread out because their means are equal"]', 'Set B', NULL, 'Set A ranges from 9 to 11 (range 2). Set B ranges from 5 to 15 (range 10). Set C has no spread at all (range 0). Set B is the most spread out. Equal means do not mean equal spread.', 'checked', '{"lint":[],"solve":{"answer":"Set B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A = 2, B = 10, C = 0; B''s values are farthest from 10.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('376052da-2055-4797-aafd-34784da72eec', 'NC26.8.RD.3', 3, 'numeric', 'Mean of two data sets combined', 'Group 1 has the values 3, 7 and 8. Group 2 has the values 5, 9, 11 and 13. What is the mean of all seven values together?', '[]', '8', '(3+7+8+5+9+11+13)/7', 'Add all seven values: $3 + 7 + 8 + 5 + 9 + 11 + 13 = 56$. Divide by 7: $56 \div 7 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 3+7+8 + 5+9+11+13 = 18 + 38 = 56. Mean = 56/7 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('489208b7-dcfa-4dbc-9bc1-9da34b0a2a01', 'NC26.8.RD.3', 3, 'choice', 'Compare interquartile ranges of four data sets', 'Four data sets are summarized by their minimum, first quartile, median, third quartile and maximum, in that order. Set A: 5, 12, 15, 20, 30. Set B: 3, 15, 18, 21, 45. Set C: 8, 10, 16, 22, 28. Set D: 14, 18, 21, 24, 26. Which set has the greatest interquartile range?', '["Set A","Set B","Set C","Set D"]', 'Set C', NULL, 'The interquartile range is the third quartile minus the first quartile. Set A: $20 - 12 = 8$. Set B: $21 - 15 = 6$. Set C: $22 - 10 = 12$. Set D: $24 - 18 = 6$. Set C has the greatest. (Set B has the greatest range, but that is a different measure.)', 'checked', '{"lint":[],"solve":{"answer":"Set C","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3 - Q1: A 20 - 12 = 8; B 21 - 15 = 6; C 22 - 10 = 12; D 24 - 18 = 6. Greatest: C.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1d7fefb-cf8d-437c-9679-2f905ecdde64', 'NC26.8.RD.3', 3, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display for 9 test scores is described here. Stem 6 has leaves 2 and 5. Stem 7 has leaves 0, 4, 4 and 8. Stem 8 has leaves 1, 3 and 9. (Stem 6 with leaf 2 means a score of 62.) What is the median score?', '[]', '74', NULL, 'The scores in order are 62, 65, 70, 74, 74, 78, 81, 83, 89. There are 9 scores, so the median is the 5th one, which is 74.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scores in order: 62, 65, 70, 74, 74, 78, 81, 83, 89. Median (5th of 9) = 74.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e108ecb8-4239-43ac-8cc4-ea99813e2ca4', 'NC26.8.RD.4', 1, 'numeric', 'Compute a variance', 'The variance of a data set is the mean of the squared distances of the values from the mean. The data set 3, 5, 7, 9 has a mean of 6. What is its variance?', '[]', '5', '(9+1+1+9)/4', 'The distances from the mean 6 are 3, 1, 1 and 3. Their squares are 9, 1, 1 and 9. The mean of the squares is $\frac{9+1+1+9}{4} = \frac{20}{4} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 6: -3, -1, 1, 3; squares 9, 1, 1, 9; sum 20; mean 20/4 = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f165d422-07a9-48fa-b5da-0ea7a126d133', 'NC26.8.RD.4', 1, 'choice', 'Interpret standard deviation as spread', 'Two data sets have the same mean. Set X has a standard deviation of 2 and Set Y has a standard deviation of 7. Which statement is true?', '["The values in Set Y are more spread out than the values in Set X","The values in Set X are more spread out than the values in Set Y","Both sets are equally spread out, because they have the same mean","Set Y has a greater mean than Set X"]', 'The values in Set Y are more spread out than the values in Set X', NULL, 'The standard deviation measures how far values typically are from the mean. A larger standard deviation means more spread. Set Y''s is larger, so its values are more spread out.', 'checked', '{"lint":[],"solve":{"answer":"The values in Set Y are more spread out than the values in Set X","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger standard deviation means more spread: Y (7) is more spread than X (2).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('335b06d5-4f0b-4ca9-af2a-b518ca1350ca', 'NC26.8.RD.4', 1, 'numeric', 'Relate variance and standard deviation', 'A data set has a variance of 25. What is its standard deviation?', '[]', '5', '25/5', 'The standard deviation is the square root of the variance. $\sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Standard deviation = sqrt(25) = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86df02fd-6b50-46f6-b547-23377be36378', 'NC26.8.RD.4', 2, 'numeric', 'Compute a standard deviation', 'The data set 2, 4, 4, 4, 5, 5, 7, 9 has a mean of 5. What is its standard deviation? (The standard deviation is the square root of the mean of the squared distances from the mean.)', '[]', '2', '(9+1+1+1+0+0+4+16)/8/2', 'The distances from 5 are 3, 1, 1, 1, 0, 0, 2 and 4. Their squares are 9, 1, 1, 1, 0, 0, 4 and 16, which add up to 32. The mean of the squares is $32 \div 8 = 4$. The standard deviation is $\sqrt{4} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations from 5: -3, -1, -1, -1, 0, 0, 2, 4; squares 9, 1, 1, 1, 0, 0, 4, 16; sum 32; mean 32/8 = 4; SD = sqrt(4) = 2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfd65034-058e-42e4-afd5-6d4377481b58', 'NC26.8.RD.4', 2, 'choice', 'Effect of adding a constant on center and spread', 'Every value in a data set is increased by 10. What happens to the mean and to the standard deviation of the data set?', '["The mean and the standard deviation both go up by 10","The mean goes up by 10 and the standard deviation stays the same","The mean stays the same and the standard deviation goes up by 10","The mean goes up by 10 and the standard deviation is multiplied by 10"]', 'The mean goes up by 10 and the standard deviation stays the same', NULL, 'Adding 10 to every value slides the whole data set up by 10, so the mean goes up by 10. The distances between the values and the mean do not change, so the standard deviation stays the same.', 'checked', '{"lint":[],"solve":{"answer":"The mean goes up by 10 and the standard deviation stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 10 shifts every value and the mean by 10; distances from the mean are unchanged, so SD stays the same.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('957bc7f5-314b-4bbf-a1de-1f32d4689903', 'NC26.8.RD.4', 2, 'choice', 'Compare standard deviations without computing', 'Three data sets each have five values and a mean of 10. Set 1: 9, 10, 10, 10, 11. Set 2: 6, 8, 10, 12, 14. Set 3: 0, 5, 10, 15, 20. Which set has the greatest standard deviation?', '["Set 1","Set 3","Set 2","All three have the same standard deviation, because the means are equal"]', 'Set 3', NULL, 'The standard deviation is larger when values are farther from the mean. Set 3''s values are the farthest from 10, and Set 1''s are the closest. Equal means do not mean equal standard deviations.', 'checked', '{"lint":[],"solve":{"answer":"Set 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 3 has values farthest from 10 (deviations 10, 5, 0, 5, 10) versus Set 2 (4, 2, 0, 2, 4) and Set 1 (1, 0, 0, 0, 1). Set 3 greatest SD.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f8c1362-c609-4038-b68d-4c5f6c4e1d83', 'NC26.8.RD.4', 3, 'numeric', 'Compare standard deviations of two data sets', 'Data set X is 6, 6, 14, 14. Data set Y is 8, 8, 12, 12. Both sets have a mean of 10. How much greater is the standard deviation of X than the standard deviation of Y?', '[]', '2', '(16+16+16+16)/4/4-(4+4+4+4)/4/2', 'In X, every value is 4 away from the mean, so every squared distance is 16, the variance is 16 and the standard deviation is 4. In Y, every value is 2 away, so every squared distance is 4, the variance is 4 and the standard deviation is 2. The difference is $4 - 2 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: every value is 4 from 10, so SD = 4. Y: every value is 2 from 10, so SD = 2. Difference = 2.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d89e636-2b6f-4c12-91ca-4b223bf528e1', 'NC26.8.RD.4', 3, 'numeric', 'Use the mean and standard deviation to compare two scores', 'On a test, the mean score is 70 and the standard deviation is 5. Mia''s score is 2 standard deviations above the mean. Leo''s score is 1.5 standard deviations below the mean. How many points higher is Mia''s score than Leo''s score?', '[]', '17.5', '(70+2*5)-(70-1.5*5)', 'Mia''s score is $70 + 2 \times 5 = 80$. Leo''s score is $70 - 1.5 \times 5 = 62.5$. The difference is $80 - 62.5 = 17.5$ points.', 'checked', '{"lint":[],"solve":{"answer":"17.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia = 70 + 2(5) = 80. Leo = 70 - 1.5(5) = 62.5. Difference = 17.5 (= 3.5 * 5).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70d82f6d-b628-434f-b766-0a2f3cd97145', 'NC26.8.RD.4', 3, 'choice', 'Choose a measure of spread when there are outliers', 'A data set has a few extremely large values that are far from the rest of the data. Which measure of spread is least affected by those extreme values?', '["The range","The variance","The interquartile range","The standard deviation"]', 'The interquartile range', NULL, 'The range, the variance and the standard deviation all use the extreme values, so a few very large values change them a lot. The interquartile range uses only the middle half of the data, so it is hardly affected.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The IQR uses only the middle 50% of the data, so extreme values barely affect it; range, variance and SD all use the extremes.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('200cc912-1a67-4e3f-b8a2-bb9c919f275f', 'NC26.8.RD.5', 1, 'numeric', 'Compare the means of several populations', 'The mean test scores of students at three schools are 72 for School A, 78 for School B and 75 for School C. How many points higher is the greatest mean than the least mean?', '[]', '6', '78-72', 'The greatest mean is 78 (School B) and the least is 72 (School A). $78 - 72 = 6$ points.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 78 - least 72 = 6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68be8afd-ce4c-4f84-a27e-1f924fc957e1', 'NC26.8.RD.5', 1, 'choice', 'Draw a conclusion supported by group means', 'A survey finds the mean number of minutes students exercise each day. Class 1 has a mean of 25, Class 2 has a mean of 40 and Class 3 has a mean of 32. Which statement is supported by these means?', '["On average, Class 2 students exercise more than Class 1 students","Every student in Class 2 exercises more than every student in Class 1","On average, Class 3 students exercise more than Class 2 students","Class 1 students vary the most in how long they exercise"]', 'On average, Class 2 students exercise more than Class 1 students', NULL, 'Class 2''s mean (40) is greater than Class 1''s mean (25), so on average Class 2 students exercise more. Means say nothing about every individual student or about how much the students vary.', 'checked', '{"lint":[],"solve":{"answer":"On average, Class 2 students exercise more than Class 1 students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 mean 40 > Class 1 mean 25, so on average Class 2 exercises more. Means say nothing about variability or every individual.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f427040-ef4c-4dcc-8904-247344396ddc', 'NC26.8.RD.5', 1, 'numeric', 'Mean of three equal-sized groups', 'Three groups of 10 students each took a typing test. The mean scores, in words per minute, were 70 for Group A, 80 for Group B and 90 for Group C. What is the mean score of all 30 students?', '[]', '80', '(70+80+90)/3', 'The groups are the same size, so the overall mean is the mean of the three group means: $\frac{70+80+90}{3} = \frac{240}{3} = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal group sizes: (10*70 + 10*80 + 10*90)/30 = 2400/30 = 80.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('466f9744-0161-4c08-b1b8-75b9312fce46', 'NC26.8.RD.5', 2, 'numeric', 'Combined mean of groups of different sizes', 'Group 1 has 10 students with a mean score of 80 points. Group 2 has 30 students with a mean score of 60 points. What is the mean score of all 40 students together?', '[]', '65', '(10*80+30*60)/40', 'Group 1''s total is $10 \times 80 = 800$ and Group 2''s total is $30 \times 60 = 1800$. The total for all 40 students is $2600$, so the mean is $2600 \div 40 = 65$. (It is closer to 60 than to 80 because Group 2 is larger.)', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10*80 + 30*60)/40 = (800 + 1800)/40 = 2600/40 = 65.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245e609e-ab46-4316-81b5-8341c120ef21', 'NC26.8.RD.5', 2, 'choice', 'Compare center and spread across populations', 'Plants were grown with three fertilizers, and their heights after four weeks were recorded in centimeters. Fertilizer A: mean 12, range 3. Fertilizer B: mean 14, range 12. Fertilizer C: mean 13, range 4. Which statement is supported by these data?', '["Fertilizer A has the highest mean height and varies the least","Fertilizer C has the lowest mean height and varies the most","Fertilizer B has the highest mean height, but its heights vary the most","Every plant grown with Fertilizer B was taller than every plant grown with Fertilizer A"]', 'Fertilizer B has the highest mean height, but its heights vary the most', NULL, 'B has the highest mean (14) and the largest range (12), so it varies the most. A has the lowest mean (12), so the second statement is false, and C is neither the lowest in mean nor the most variable. The last statement is not supported: means and ranges do not tell us that every plant was taller.', 'checked', '{"lint":[],"solve":{"answer":"Fertilizer B has the highest mean height, but its heights vary the most","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B has highest mean (14) and largest range (12). A has lowest mean; C does not vary most; means/ranges cannot show every B plant taller.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a3f420-fc29-45e4-ab2c-86d8ec67b1be', 'NC26.8.RD.5', 2, 'choice', 'Compare percents when sample sizes differ', 'Students in three grades were asked whether they like a new class schedule. In Grade 6, 18 of 20 students said yes. In Grade 7, 30 of 50 said yes. In Grade 8, 33 of 44 said yes. Which grade had the greatest percent of students saying yes?', '["Grade 6","Grade 7","Grade 8","The three grades are tied"]', 'Grade 6', NULL, 'Compare percents, not counts. Grade 6: $\frac{18}{20} = 90\%$. Grade 7: $\frac{30}{50} = 60\%$. Grade 8: $\frac{33}{44} = 75\%$. Grade 6 is greatest, even though Grade 8 had the most students saying yes.', 'checked', '{"lint":[],"solve":{"answer":"Grade 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 6: 18/20 = 90%. Grade 7: 30/50 = 60%. Grade 8: 33/44 = 75%. Greatest: Grade 6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe9d70dc-a93b-47c2-864a-11eb23daa34f', 'NC26.8.RD.5', 3, 'numeric', 'Find a missing group mean from the overall mean', 'Three classes of 10 students each recorded how many books they read this year. Class A had a mean of 7 books and Class B had a mean of 9 books. The mean for Class C is not known. All 30 students together had a mean of 9 books. What was the mean for Class C?', '[]', '11', '(30*9-10*7-10*9)/10', 'All 30 students read $30 \times 9 = 270$ books. Class A read $10 \times 7 = 70$ and Class B read $10 \times 9 = 90$, so Class C read $270 - 70 - 90 = 110$ books. The mean for Class C is $110 \div 10 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 30 * 9 = 270. A total 70, B total 90. C total = 270 - 160 = 110. Mean C = 110/10 = 11.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cf8831c-a641-4d95-95ef-6687c510529d', 'NC26.8.RD.5', 3, 'choice', 'Choose the better summary measure for a skewed population', 'The sale prices of homes in a town, in thousands of dollars, have a mean of 310 and a median of 220. Most homes sold for between 150 and 250, but a few sold for over 1000. Which measure better describes a typical home price, and why?', '["The mean, because it includes every price, so extreme prices cannot affect it","The median, because a few very high prices pull the mean up","The range, because it shows how much homes usually cost","The mean, because it is always greater than the median"]', 'The median, because a few very high prices pull the mean up', NULL, 'A few very expensive homes raise the mean to 310, higher than what most homes cost. The median, 220, stays in the middle of the typical prices, so it describes a typical home better.', 'checked', '{"lint":[],"solve":{"answer":"The median, because a few very high prices pull the mean up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The data are skewed by a few very high prices that pull the mean (310) above most prices; the median (220) is typical.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b56b9d1-978a-426d-ab64-fe5eafb24d4f', 'NC26.8.RD.5', 3, 'choice', 'Reflect on methods when comparing several populations', 'Dev surveyed 12 students in each of four grades about how many hours they read each week, and the grade means differed a lot. Dev is not sure the differences are real. Which step would best help Dev decide?', '["Survey only the grade with the highest mean","Ignore any grade whose mean is different from the others","Ask only friends, since they will answer honestly","Repeat the survey with a larger random sample from each grade"]', 'Repeat the survey with a larger random sample from each grade', NULL, 'Small samples can give means that differ just by chance. Taking larger random samples from every grade gives more reliable means. The other steps leave out data or add bias.', 'checked', '{"lint":[],"solve":{"answer":"Repeat the survey with a larger random sample from each grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Small samples vary a lot; a larger random sample from each grade gives more reliable means to compare.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f29312ff-be2e-4a06-809a-e4b3bbebe17d', 'NC26.M1.RMM.1', 1, 'choice', 'Name an assumption built into a model', 'Maya models the cost of a taxi ride with $C = 3 + 2m$, where $C$ is the cost in dollars and $m$ is the number of miles. Which assumption is built into this model?', '["Longer rides cost more per mile","Every mile costs the same amount","There is no charge before the ride begins","The cost changes with the time of day"]', 'Every mile costs the same amount', NULL, 'In $C = 3 + 2m$ the cost rises by 2 dollars for every extra mile, so each mile costs the same. The 3 is a starting charge, and time of day does not appear in the model.', 'checked', '{"lint":[],"solve":{"answer":"Every mile costs the same amount","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3 + 2m: a fixed 3 dollars plus 2 dollars for each mile, so every mile adds the same 2 dollars (constant rate). Time of day is not in the model; cost per mile does not grow; and at m = 0 the cost is 3, so there IS a charge before any miles, making the last option false.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('681cc83f-c99e-4ec1-9bc6-af1b142806b5', 'NC26.M1.RMM.1', 1, 'numeric', 'Use a model to make a prediction', 'A candle is 20 centimeters tall when lit and burns down 2 centimeters each hour. A student models its height with $h = 20 - 2t$, where $h$ is the height in centimeters after $t$ hours. According to the model, how tall is the candle after 6 hours, in centimeters?', '[]', '8', '20-2*6', 'Put $t = 6$ into the model: $h = 20 - 2 \times 6 = 20 - 12 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 20 - 2(6) = 20 - 12 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('680f53f0-b2fe-48c5-96a7-182aa63516e5', 'NC26.M1.RMM.1', 1, 'choice', 'Revise a model when it disagrees with measurements', 'A student''s model predicts that a plant will be 30 centimeters tall after 4 weeks. After 4 weeks the plant is measured and is 22 centimeters tall. What should the student do next?', '["Revise the model so it fits the measurement better","Keep the model, because the prediction must be correct","Change the measurement to match the prediction","Decide that plants cannot be modeled"]', 'Revise the model so it fits the measurement better', NULL, 'A model is tested against real data. The prediction is 8 centimeters too high, so the student should look for what the model missed and revise it. Changing the measurement or giving up is not how the modeling cycle works.', 'checked', '{"lint":[],"solve":{"answer":"Revise the model so it fits the measurement better","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prediction 30, measurement 22: the model does not fit the data, so in the modeling cycle the student revises the model. Changing data, insisting the model is right, or giving up are all wrong.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9246e2c0-74bb-444a-9b9d-f79276a32fc6', 'NC26.M1.RMM.1', 2, 'numeric', 'Compare a model prediction with observed data', 'A student models her savings with $S = 40 + 15w$, where $S$ is her savings in dollars after $w$ weeks. After 3 weeks she really has 90 dollars. How many dollars more is her real savings than the model predicts?', '[]', '5', '90-(40+15*3)', 'The model predicts $S = 40 + 15 \times 3 = 85$ dollars. She really has 90 dollars, which is $90 - 85 = 5$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Model: S = 40 + 15(3) = 85. Real 90. 90 - 85 = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc4bcb2b-88b4-42d6-b718-4125b864404b', 'NC26.M1.RMM.1', 2, 'choice', 'Critique a model using measured data', 'A student models a tank that starts with 100 liters and empties at a constant 4 liters per minute: $V = 100 - 4t$. Measurements show 60 liters after 10 minutes and 35 liters after 20 minutes. Which statement is the best critique of the model?', '["The tank empties faster over time, so the rate should be larger","The model matches at 10 minutes, so it is right at every time","The model is wrong because the tank cannot start with 100 liters","The tank empties more slowly over time, so a constant rate is a poor assumption"]', 'The tank empties more slowly over time, so a constant rate is a poor assumption', NULL, 'At 10 minutes the model gives $100 - 40 = 60$ liters, which matches. At 20 minutes it gives $100 - 80 = 20$ liters, but 35 liters were measured. The tank has more water left than predicted, so it empties more slowly as time goes on. Matching at one time does not make a model right everywhere.', 'checked', '{"lint":[],"solve":{"answer":"The tank empties more slowly over time, so a constant rate is a poor assumption","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Model: V(10) = 60 (matches), V(20) = 20 but measured 35. Data: lost 40 L in first 10 min (4 L/min), 25 L in next 10 min (2.5 L/min), so draining slows; constant rate is a poor assumption. Option 1 overgeneralizes, option 3 is unsupported, option 4 has the direction wrong.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a87967fc-fe6d-4d73-8a2a-e31bb4482d62', 'NC26.M1.RMM.1', 2, 'numeric', 'Use a model to answer a question within a limit', 'Printing $n$ flyers costs $C = 12 + 0.25n$ dollars. A club has 62 dollars to spend. What is the greatest number of flyers the club can print?', '[]', '200', '(62-12)/0.25', 'The club can spend at most 62 dollars: $12 + 0.25n \le 62$, so $0.25n \le 50$ and $n \le 200$. The greatest number is 200 flyers.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 0.25n <= 62 -> 0.25n <= 50 -> n <= 200. Check: 12 + 0.25(200) = 62 exactly. Greatest is 200.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be79fe34-8744-4fe2-9a01-f8bbca535ff4', 'NC26.M1.RMM.1', 3, 'choice', 'Choose the model that fits recorded data', 'A scientist counts bacteria each hour and records 800, 1200, 1800 and 2700 at hours 0, 1, 2 and 3. Which model fits all of these counts?', '["$N = 800 + 400t$","$N = 800(1.4)^t$","$N = 800(1.5)^t$","$N = 1200t$"]', '$N = 800(1.5)^t$', NULL, 'Each count is 1.5 times the one before: $800 \times 1.5 = 1200$, $1200 \times 1.5 = 1800$, $1800 \times 1.5 = 2700$. So $N = 800(1.5)^t$. The linear model $800 + 400t$ matches only the first two counts (it gives 1600 at hour 2).', 'checked', '{"lint":[],"solve":{"answer":"$N = 800(1.5)^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratios: 1200/800 = 1.5, 1800/1200 = 1.5, 2700/1800 = 1.5, so N = 800(1.5)^t. Check t=3: 800*3.375 = 2700. 1.4 gives 1120 at t=1; 1200t gives 0 at t=0; 800+400t gives 1600 at t=2.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54e34c3f-00c2-42cc-815c-2bf2c942ed4f', 'NC26.M1.RMM.1', 3, 'numeric', 'Test a model against a dealer value and find the error', 'A student models the value of a car with $V = 20{,}000(0.8)^t$ dollars after $t$ years, assuming it loses 20% of its value each year. A dealer says the car is worth $10{,}500$ dollars after 3 years. How many dollars more is the dealer''s value than the model predicts?', '[]', '260', '10500-20000*0.8^3', 'The model predicts $V = 20{,}000(0.8)^3 = 20{,}000 \times 0.512 = 10{,}240$ dollars. The dealer says $10{,}500$, which is $10{,}500 - 10{,}240 = 260$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V(3) = 20000(0.8)^3 = 20000(0.512) = 10240. Dealer 10500. 10500 - 10240 = 260.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('daa25ceb-fd82-444a-a8d0-d89aba1f2b3b', 'NC26.M1.RMM.1', 3, 'choice', 'Judge the limits of a model', 'A student models the height of a young tree with $h = 2 + 3t$ meters after $t$ years, and uses it to predict a height of 152 meters after 50 years. Which is the best critique of this prediction?', '["The model assumes steady growth, but trees slow down as they get very tall","The model is invalid because the tree starts above zero height","The prediction is reliable because the formula was worked out correctly","The model is invalid because time is measured in years"]', 'The model assumes steady growth, but trees slow down as they get very tall', NULL, 'The model adds 3 meters every year without end, which gives an unrealistic 152 meters. A good critique looks at whether the assumption (constant growth) still makes sense far from the data. The starting height and the unit of time are not problems.', 'checked', '{"lint":[],"solve":{"answer":"The model assumes steady growth, but trees slow down as they get very tall","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(50) = 2 + 150 = 152 m, arithmetically right but unrealistic: a linear model assumes the tree keeps growing 3 m a year forever, while real trees slow down. Units in years and a nonzero start are not flaws; correct arithmetic does not make the extrapolation reliable.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe2c67b-3982-455a-a975-adb67cae1792', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply powers with the same base', 'Simplify $x^3 \cdot x^4$.', '["$x^7$","$x^{12}$","$2x^7$","$x^{-1}$"]', '$x^7$', NULL, 'When you multiply powers with the same base, add the exponents: $x^3 \cdot x^4 = x^{3+4} = x^7$.', 'checked', '{"lint":[],"solve":{"answer":"$x^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: x^(3+4) = x^7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebd0103b-5e4b-4d38-be71-1e826504c98a', 'NC26.M1.ANFR.1', 1, 'numeric', 'Evaluate zero and positive integer exponents', 'What is the value of $5^0 + 3^2$?', '[]', '10', '5^0+3^2', 'Any nonzero number to the power 0 is 1, so $5^0 = 1$. Also $3^2 = 9$. The sum is $1 + 9 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^0 = 1, 3^2 = 9, sum 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b17b0c24-ecd0-46b5-8340-4ffd35abc21d', 'NC26.M1.ANFR.1', 1, 'numeric', 'Add polynomials by combining like terms', 'Add $(4x^2 + 3x + 1) + (x^2 + 6x + 5)$. What is the coefficient of $x$ in the sum?', '[]', '9', '3+6', 'Combine like terms: $(4x^2 + x^2) + (3x + 6x) + (1 + 5) = 5x^2 + 9x + 6$. The coefficient of $x$ is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 5x^2 + 9x + 6. Coefficient of x is 3 + 6 = 9.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56688d7f-0094-4f48-b47a-2de6071305ec', 'NC26.M1.ANFR.1', 2, 'choice', 'Subtract polynomials, distributing the negative', 'Subtract: $(5x^2 + 3x - 4) - (2x^2 - x + 6)$.', '["$3x^2 + 2x + 2$","$7x^2 + 2x + 2$","$3x^2 + 4x - 10$","$3x^2 + 4x + 2$"]', '$3x^2 + 4x - 10$', NULL, 'Subtracting changes the sign of every term in the second polynomial: $5x^2 + 3x - 4 - 2x^2 + x - 6$. Combine like terms: $3x^2 + 4x - 10$.', 'checked', '{"lint":[],"solve":{"answer":"$3x^2 + 4x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x^2 - 2x^2 = 3x^2; 3x - (-x) = 4x; -4 - 6 = -10. Result 3x^2 + 4x - 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d73b262-0e31-4f50-9a3e-4c975e59a99f', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply two binomials', 'Multiply: $(x + 4)(x - 2)$.', '["$x^2 - 8$","$x^2 + 2x - 8$","$x^2 + 6x - 8$","$x^2 + 2x + 8$"]', '$x^2 + 2x - 8$', NULL, 'Multiply each term by each term: $x \cdot x + x(-2) + 4 \cdot x + 4(-2) = x^2 - 2x + 4x - 8 = x^2 + 2x - 8$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 + 2x - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 2x + 4x - 8 = x^2 + 2x - 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d99576fa-d9db-472d-b132-27ad20435190', 'NC26.M1.ANFR.1', 2, 'numeric', 'Use an area model for a product', 'A rectangle has width $x + 2$ and length $x + 6$. Cutting it into four smaller rectangles gives areas $x^2$, $6x$, $2x$ and 12. The total area is $x^2 + bx + c$. What is $b$?', '[]', '8', '2+6', 'The four parts add to $x^2 + 6x + 2x + 12 = x^2 + 8x + 12$. So $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 2)(x + 6) = x^2 + 6x + 2x + 12 = x^2 + 8x + 12, matching the four pieces. b = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1a0afe8-218a-4dda-8fe8-8f420ebf731c', 'NC26.M1.ANFR.1', 3, 'choice', 'Divide powers with negative exponents', 'Simplify $\frac{x^5 y^{-2}}{x^2 y^{-6}}$, where $x$ and $y$ are not zero.', '["$x^3 y^{-4}$","$x^3 y^{-8}$","$x^7 y^4$","$x^3 y^4$"]', '$x^3 y^4$', NULL, 'When you divide powers with the same base, subtract the exponents. For $x$: $5 - 2 = 3$. For $y$: $-2 - (-6) = -2 + 6 = 4$. The result is $x^3 y^4$.', 'checked', '{"lint":[],"solve":{"answer":"$x^3 y^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^(5-2) = x^3; y^(-2 - (-6)) = y^4. Result x^3 y^4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e8ed3b-cde0-426c-be8d-6776d34b4605', 'NC26.M1.ANFR.1', 3, 'numeric', 'Find a coefficient after multiplying binomials', 'When $(2x - 1)(x + 4)$ is written in the form $ax^2 + bx + c$, what is $b$?', '[]', '7', '2*4-1*1', '$(2x - 1)(x + 4) = 2x^2 + 8x - x - 4 = 2x^2 + 7x - 4$. The middle terms $8x$ and $-x$ combine to $7x$, so $b = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x - 1)(x + 4) = 2x^2 + 8x - x - 4 = 2x^2 + 7x - 4. b = 7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('598e6fdb-fd4e-44b5-8f4e-b1dbcc027614', 'NC26.M1.ANFR.1', 3, 'choice', 'Raise a product to a power', 'Simplify $(3x^2 y)^3$.', '["$27x^5y^3$","$27x^6y^3$","$3x^6y^3$","$9x^6y^3$"]', '$27x^6y^3$', NULL, 'Cube every factor: $3^3 = 27$, $(x^2)^3 = x^6$ (multiply exponents) and $y^3$. The result is $27x^6y^3$.', 'checked', '{"lint":[],"solve":{"answer":"$27x^6y^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^3 = 27, (x^2)^3 = x^6, y^3. Result 27x^6y^3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3763fa3c-ef8a-489b-a878-da2c1b1cec75', 'NC26.M1.ANFR.2', 1, 'choice', 'Recognize an arithmetic sequence', 'Which list of numbers is an arithmetic sequence?', '["2, 6, 18, 54","1, 2, 4, 7","5, 9, 13, 17","3, 6, 12, 24"]', '5, 9, 13, 17', NULL, 'An arithmetic sequence adds the same number each time. 5, 9, 13, 17 adds 4 every time. 2, 6, 18, 54 and 3, 6, 12, 24 multiply by the same number, and 1, 2, 4, 7 adds 1, then 2, then 3.', 'checked', '{"lint":[],"solve":{"answer":"5, 9, 13, 17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,9,13,17: differences 4,4,4 -> arithmetic. 1,2,4,7: differences 1,2,3 no. 3,6,12,24 and 2,6,18,54 are geometric with non-constant differences.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f17e147-ec2e-4214-87c1-84eefd68152e', 'NC26.M1.ANFR.2', 1, 'numeric', 'Continue a geometric pattern', 'A pattern begins 4, 12, 36, 108. Each number is the same multiple of the number before it. What is the next number in the pattern?', '[]', '324', '108*3', 'Each number is 3 times the one before it: $4 \times 3 = 12$, $12 \times 3 = 36$, $36 \times 3 = 108$. The next is $108 \times 3 = 324$.', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 12/4 = 3, 36/12 = 3, 108/36 = 3. Next: 108 * 3 = 324.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43222945-b49f-40f7-a4f7-79232e00b7eb', 'NC26.M1.ANFR.2', 1, 'choice', 'Match a situation to exponential growth', 'Which situation is best described by exponential growth?', '["A plumber charges 40 dollars plus 15 dollars per hour","The number of views of a video doubles every day","A runner covers 3 kilometers every 15 minutes","A tree grows 4 centimeters every year"]', 'The number of views of a video doubles every day', NULL, 'Exponential growth multiplies by the same factor each step. Doubling every day is multiplying by 2. The other three situations add the same amount each time, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"The number of views of a video doubles every day","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling every day is a constant multiplier -> exponential. The other three add a constant amount per unit -> linear.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1825c0f-58f6-4d99-b2da-f879f1af7fef', 'NC26.M1.ANFR.2', 2, 'choice', 'Tell linear from exponential in a table', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 3, 6, 12, 24. Which statement describes the pattern?', '["Exponential: $y$ is multiplied by 2 each time $x$ increases by 1","Linear: $y$ increases by 3 each time $x$ increases by 1","Linear: $y$ increases by 6 each time $x$ increases by 1","Exponential: $y$ is multiplied by 3 each time $x$ increases by 1"]', 'Exponential: $y$ is multiplied by 2 each time $x$ increases by 1', NULL, 'The differences are 3, 6, 12, which are not equal, so the pattern is not linear. The ratios are $6 \div 3 = 2$, $12 \div 6 = 2$ and $24 \div 12 = 2$, so $y$ is multiplied by 2 each time.', 'checked', '{"lint":[],"solve":{"answer":"Exponential: $y$ is multiplied by 2 each time $x$ increases by 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,6,12,24: differences 3,6,12 not constant; ratios 2,2,2 -> exponential, multiplied by 2.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce3e7f25-668d-4b8a-b40d-519df3a41553', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value in an exponential decay pattern', 'A table gives $P$ for $t = 0, 1, 2, 3$: the values of $P$ are 640, 320, 160, 80. The pattern continues in the same way. What is $P$ when $t = 6$?', '[]', '10', '640*(1/2)^6', 'Each value is half the one before it. So $P = 640 \times \left(\frac{1}{2}\right)^t$. At $t = 6$: $640 \div 64 = 10$. (Continuing the list: 80, 40, 20, 10.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halving each step: 640, 320, 160, 80, 40 (t=4), 20 (t=5), 10 (t=6).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2488f536-ef8c-4590-8782-3eca13048890', 'NC26.M1.ANFR.2', 2, 'numeric', 'Predict a value in a linear pattern from a table', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 10, 14, 18, 22. The pattern continues in the same way. What is $y$ when $x = 6$?', '[]', '34', '10+4*6', 'The values go up by 4 each time, so $y = 10 + 4x$. When $x = 6$: $y = 10 + 24 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adds 4 each step: y = 10 + 4x. At x = 6: 10 + 24 = 34.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2656b6a4-9bc3-45f0-b160-1cf8f3c3c128', 'NC26.M1.ANFR.2', 3, 'choice', 'Recognize a table that is neither linear nor exponential', 'Four tables each give $y$ for $x = 1, 2, 3, 4$. Which table is neither linear nor exponential?', '["y: 2, 5, 8, 11","y: 2, 6, 18, 54","y: 2, 5, 10, 17","y: 32, 16, 8, 4"]', 'y: 2, 5, 10, 17', NULL, 'For 2, 5, 10, 17 the differences are 3, 5, 7 (not equal) and the ratios are 2.5, 2, 1.7 (not equal), so it is neither. 2, 5, 8, 11 adds 3 each time, 2, 6, 18, 54 multiplies by 3, and 32, 16, 8, 4 multiplies by one half.', 'checked', '{"lint":[],"solve":{"answer":"y: 2, 5, 10, 17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32,16,8,4: ratio 1/2 exponential. 2,5,10,17: differences 3,5,7 (not constant), ratios 2.5, 2, 1.7 (not constant) -> neither (quadratic, x^2+1). 2,6,18,54: ratio 3 exponential. 2,5,8,11: difference 3 linear.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78dc96f2-4df1-40ec-ac42-55b303912c7e', 'NC26.M1.ANFR.2', 3, 'numeric', 'Compare a linear and an exponential plan', 'Plan A has value $A = 100 + 20t$ and Plan B has value $B = 20(2)^t$ after $t$ whole years. For the first whole number of years $t$ where Plan B is greater than Plan A, what is $t$?', '[]', '4', NULL, 'Compare year by year. $t = 0$: A is 100, B is 20. $t = 1$: 120 and 40. $t = 2$: 140 and 80. $t = 3$: 160 and 160, which are equal, not greater. $t = 4$: A is 180 and B is 320, so Plan B is greater for the first time at $t = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t=0: A 100, B 20. t=1: 120 vs 40. t=2: 140 vs 80. t=3: 160 vs 160 (equal, not greater). t=4: 180 vs 320 -> B greater. t = 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58de2bd1-ce2f-4797-852a-48ea396e06f0', 'NC26.M1.ANFR.2', 3, 'numeric', 'Find a later term of an arithmetic sequence from two terms', 'In an arithmetic sequence, the 3rd term is 11 and the 7th term is 31. What is the 10th term?', '[]', '46', '31+3*(31-11)/4', 'From the 3rd to the 7th term there are 4 steps, and the terms rise by $31 - 11 = 20$, so each step adds $20 \div 4 = 5$. The 10th term is 3 steps after the 7th: $31 + 3 \times 5 = 46$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a7 - a3 = 4d = 31 - 11 = 20, d = 5. a10 = a7 + 3d = 31 + 15 = 46.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3dd3e73-76ea-4e46-9e37-76a5c81222d8', 'NC26.M1.ANFR.3', 1, 'numeric', 'Evaluate a function written with function notation', 'If $f(x) = 3x - 2$, what is $f(4)$?', '[]', '10', '3*4-2', 'Replace $x$ with 4: $f(4) = 3(4) - 2 = 12 - 2 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(4) = 3(4) - 2 = 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f714a6b-64a2-4726-b0f1-60b99d714b32', 'NC26.M1.ANFR.3', 1, 'choice', 'Choose a reasonable domain in context', 'A bakery sells muffins for 2 dollars each, so the cost of $n$ muffins is $C(n) = 2n$ dollars. Which set is the most reasonable domain of $C$?', '["All real numbers","The even numbers 0, 2, 4, 6, and so on","All real numbers greater than 2","Whole numbers: 0, 1, 2, 3, and so on"]', 'Whole numbers: 0, 1, 2, 3, and so on', NULL, 'The domain is the set of possible inputs. You cannot buy part of a muffin or a negative number of muffins, so the inputs are the whole numbers. The even numbers 0, 2, 4, 6 are the possible costs (outputs), not the inputs.', 'checked', '{"lint":[],"solve":{"answer":"Whole numbers: 0, 1, 2, 3, and so on","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"You buy a whole number of muffins, including possibly 0: domain {0,1,2,...}. Not all reals, not only evens, not reals > 2.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35814cec-22d2-423f-b410-0dea192baf73', 'NC26.M1.ANFR.3', 1, 'choice', 'Tell growth from decay', 'Which statement describes $f(x) = 5(0.8)^x$?', '["Exponential decay","Exponential growth","Linear increase","Linear decrease"]', 'Exponential decay', NULL, 'The variable is in the exponent, so the function is exponential. The base 0.8 is less than 1, so each step multiplies the value by 0.8 and it gets smaller: decay.', 'checked', '{"lint":[],"solve":{"answer":"Exponential decay","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Form a(b)^x with a = 5 > 0 and 0 < b = 0.8 < 1 -> exponential decay.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('280e8909-ca47-4754-8697-fd7dc79926df', 'NC26.M1.ANFR.3', 2, 'numeric', 'Evaluate a function in context', 'A plant''s height after $w$ weeks is $h(w) = 4 + 2.5w$ centimeters. What is $h(6)$, in centimeters?', '[]', '19', '4+2.5*6', '$h(6) = 4 + 2.5(6) = 4 + 15 = 19$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(6) = 4 + 2.5(6) = 4 + 15 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1340d717-16a0-42d9-8467-a6288724dcda', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find an average rate of change', 'For a function $f$, $f(2) = 7$ and $f(6) = 19$. What is the average rate of change of $f$ from $x = 2$ to $x = 6$?', '[]', '3', '(19-7)/(6-2)', 'Average rate of change is the change in output divided by the change in input: $\frac{19 - 7}{6 - 2} = \frac{12}{4} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(19 - 7)/(6 - 2) = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
