INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44484717-1c68-4b81-83b9-774d4fd9d808', 'NC26.M1.ANFR.3', 2, 'choice', 'Decide whether a function in context is discrete or continuous', 'A car travels at a steady 60 miles per hour, so after $t$ hours it has gone $d(t) = 60t$ miles, where $t$ can be any time from 0 to 5 hours. Which statement is true?', '["The graph is discrete because distance is measured in miles","The graph is continuous because $t$ can be any value from 0 to 5","The graph is discrete because 60 is a whole number","The graph is continuous only because it passes through the origin"]', 'The graph is continuous because $t$ can be any value from 0 to 5', NULL, 'A function is continuous when its inputs can be any value in an interval. Time can be any value from 0 to 5 hours, including parts of an hour, so the graph is continuous. The units and the number 60 do not decide this.', 'checked', '{"lint":[],"solve":{"answer":"The graph is continuous because $t$ can be any value from 0 to 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Time can take any value in [0, 5], so the graph is an unbroken segment: continuous for that reason. The other options give wrong reasons.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50d4bafc-e6ac-4f0b-ae1c-23e20d386906', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the range of an exponential function', 'Let $g(x) = 2(3)^x$ for all real numbers $x$. What is the range of $g$?', '["All real numbers","$y \\ge 2$","$y > 0$","$y \\ge 0$"]', '$y > 0$', NULL, 'A positive number raised to any power is positive, and $2(3)^x$ gets as close to 0 as you like for very negative $x$ without ever reaching it. So every output is greater than 0, and every positive number is an output: $y > 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y > 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^x > 0 for all real x and takes every positive value, so 2(3)^x takes every value > 0, never 0. Range y > 0. (y >= 2 is wrong: e.g. g(-1) = 2/3.)","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('513b73f4-58d1-4fef-a12f-4fac631be0d4', 'NC26.M1.ANFR.3', 3, 'choice', 'Compare the rates of change of two functions', 'Function $f$ is $f(x) = 5x - 2$. Function $g$ is linear with $g(0) = 1$, $g(2) = 9$ and $g(4) = 17$. Which function has the greater rate of change, and what are the two rates?', '["$g$ has the greater rate: 8 compared with 5","$g$ has the greater rate: 16 compared with 5","$f$ has the greater rate: 5 compared with 4","The rates are equal: both are 4"]', '$f$ has the greater rate: 5 compared with 4', NULL, 'The rate of change of $f$ is its slope, 5. For $g$, the output rises from 1 to 9 while the input rises by 2, so the rate is $\frac{9 - 1}{2} = 4$ (the same from 2 to 4: $\frac{17 - 9}{2} = 4$). Since $5 > 4$, $f$ has the greater rate.', 'checked', '{"lint":[],"solve":{"answer":"$f$ has the greater rate: 5 compared with 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f slope 5. g: (9 - 1)/(2 - 0) = 4, (17 - 9)/2 = 4. f is greater: 5 vs 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a9f8d04-7f6d-4b2d-851d-9d0c4594a548', 'NC26.M1.ANFR.3', 3, 'numeric', 'Average rate of change of an exponential function', 'Let $f(x) = 3(2)^x$. What is the average rate of change of $f$ from $x = 1$ to $x = 3$?', '[]', '9', '(3*2^3-3*2^1)/(3-1)', '$f(1) = 3(2) = 6$ and $f(3) = 3(8) = 24$. The average rate of change is $\frac{24 - 6}{3 - 1} = \frac{18}{2} = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 3*2 = 6, f(3) = 3*8 = 24. (24 - 6)/(3 - 1) = 18/2 = 9.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c00483f-a5dc-4903-8a73-f1978b31beb9', 'NC26.M1.ANFR.4', 1, 'choice', 'Write a linear function from a situation', 'A gym charges 25 dollars to join and then 10 dollars per month. Which function gives the total cost $f(m)$ in dollars after $m$ months?', '["$f(m) = 25 + 10m$","$f(m) = 10 + 25m$","$f(m) = 35m$","$f(m) = 25(10)^m$"]', '$f(m) = 25 + 10m$', NULL, 'The joining fee is paid once (25), and 10 dollars is added for each month, so $f(m) = 25 + 10m$.', 'checked', '{"lint":[],"solve":{"answer":"$f(m) = 25 + 10m$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One-time 25 plus 10 per month: f(m) = 25 + 10m.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('999acb11-17fe-4a84-a397-c676537b6d33', 'NC26.M1.ANFR.4', 1, 'numeric', 'Use a recursive rule for an arithmetic sequence', 'A sequence has $a_1 = 6$ and $a_n = a_{n-1} + 4$ for $n \ge 2$. What is $a_4$?', '[]', '18', '6+3*4', 'Start with 6 and add 4 each time: $a_1 = 6$, $a_2 = 10$, $a_3 = 14$, $a_4 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1 = 6, a2 = 10, a3 = 14, a4 = 18.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
