INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e78e8e2-0f79-4ecc-9dc2-e18b56d2bf15', 'NC26.M1.ANFR.4', 1, 'choice', 'Write slope-intercept form from slope and intercept', 'A line has slope 2 and crosses the y-axis at the point $(0, -3)$. Which equation is the equation of the line?', '["$y = -3x + 2$","$y = 2x + 3$","$y = -2x - 3$","$y = 2x - 3$"]', '$y = 2x - 3$', NULL, 'Slope-intercept form is $y = mx + b$, with slope $m = 2$ and y-intercept $b = -3$. So $y = 2x - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b with m = 2, b = -3: y = 2x - 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4921b214-6615-4dc2-9ceb-83e4922cdbc7', 'NC26.M1.ANFR.4', 2, 'choice', 'Write an exponential function from a situation', 'A deposit of 300 dollars grows by 5% each year. Which function gives the balance $B(t)$ in dollars after $t$ years?', '["$B(t) = 300 + 0.05t$","$B(t) = 300(1.05)^t$","$B(t) = 300(0.05)^t$","$B(t) = 300 + 5t$"]', '$B(t) = 300(1.05)^t$', NULL, 'Growing by 5% each year means multiplying by $1 + 0.05 = 1.05$ each year, so $B(t) = 300(1.05)^t$.', 'checked', '{"lint":[],"solve":{"answer":"$B(t) = 300(1.05)^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth of 5% per year multiplies by 1.05 each year: B(t) = 300(1.05)^t.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a951aa7-01c3-468b-b9af-33db1fab61bc', 'NC26.M1.ANFR.4', 2, 'numeric', 'Find the y-intercept of a line through two points', 'A line passes through the points $(1, 5)$ and $(3, 11)$. What is its y-intercept?', '[]', '2', '5-(11-5)/(3-1)*1', 'The slope is $\frac{11 - 5}{3 - 1} = 3$. Using $y = 3x + b$ and the point $(1, 5)$: $5 = 3 + b$, so $b = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (11 - 5)/(3 - 1) = 3. 5 = 3(1) + b -> b = 2. Check (3, 11): 9 + 2 = 11. y-intercept 2.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbfb2454-8b58-4f42-b23c-b9b6872b3b52', 'NC26.M1.ANFR.4', 2, 'numeric', 'Use a recursive rule for a geometric sequence', 'A sequence has $f(1) = 2$ and $f(n) = 3 \cdot f(n-1)$ for $n \ge 2$. What is $f(5)$?', '[]', '162', '2*3^4', 'Multiply by 3 each time: $f(1) = 2$, $f(2) = 6$, $f(3) = 18$, $f(4) = 54$, $f(5) = 162$.', 'checked', '{"lint":[],"solve":{"answer":"162","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 2, f(2) = 6, f(3) = 18, f(4) = 54, f(5) = 162.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
