INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01088cb5-dc3a-4c36-9b83-cecc124ec8ab', 'NC26.M1.ANFR.4', 3, 'choice', 'Choose the function that models a table of values', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 5, 15, 45, 135. Which function fits all four values?', '["$y = 5(3)^x$","$y = 5 + 10x$","$y = 3(5)^x$","$y = 15(3)^x$"]', '$y = 5(3)^x$', NULL, 'Each value is 3 times the one before, and $y = 5$ when $x = 0$, so $y = 5(3)^x$. The linear rule $5 + 10x$ gives 25 at $x = 2$, not 45. $15(3)^x$ gives 15 at $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5(3)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5 at x = 0, ratio 3: y = 5(3)^x gives 5, 15, 45, 135. 5 + 10x gives 25 at x = 2; 15(3)^x gives 15 at x = 0; 3(5)^x gives 3 at x = 0.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e21c7e95-55fa-49d3-b8e2-5f81bf09832a', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a two-step recursive rule', 'A sequence has $a_1 = 3$ and $a_n = 2a_{n-1} - 1$ for $n \ge 2$. What is $a_5$?', '[]', '33', '2^5+1', 'Apply the rule step by step: $a_2 = 2(3) - 1 = 5$, $a_3 = 2(5) - 1 = 9$, $a_4 = 2(9) - 1 = 17$, $a_5 = 2(17) - 1 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1 = 3, a2 = 2(3) - 1 = 5, a3 = 9, a4 = 17, a5 = 33.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0fe79db-f9e5-4609-bb61-2b5577fd150f', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write a linear model from two measurements', 'A candle burns down at a constant rate. After 2 hours it is 30 centimeters tall, and after 5 hours it is 24 centimeters tall. How tall, in centimeters, was it when it was first lit (at time 0)?', '[]', '34', '30+2*(30-24)/(5-2)', 'In 3 hours the height fell by 6 centimeters, so the candle burns down 2 centimeters per hour. Going back 2 hours from the first measurement adds $2 \times 2 = 4$ centimeters: $30 + 4 = 34$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = (24 - 30)/(5 - 2) = -2 cm/h. h(0) = 30 + 2(2) = 34. Check h(5) = 34 - 10 = 24.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a652008c-eb8c-4321-a96e-4a63cea25592', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a one-step-plus-one linear equation', 'Solve for $x$: $3x + 5 = 20$.', '[]', '5', '(20-5)/3', 'Subtract 5 from both sides: $3x = 15$. Divide both sides by 3: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e68f305-b7f0-4e00-8b57-36dea56ef224', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a formula for one quantity', 'The formula $d = rt$ relates distance $d$, rate $r$ and time $t$. Solve the formula for $t$.', '["$t = dr$","$t = \\frac{r}{d}$","$t = \\frac{d}{r}$","$t = d - r$"]', '$t = \frac{d}{r}$', NULL, 'To get $t$ alone, divide both sides of $d = rt$ by $r$: $t = \frac{d}{r}$.', 'checked', '{"lint":[],"solve":{"answer":"$t = \\frac{d}{r}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide both sides of d = rt by r: t = d/r.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73989cf0-3f9f-4ddc-9bfb-2f00c5533fcb', 'NC26.M1.ANFR.5', 1, 'choice', 'Justify a step in solving an equation', 'In solving $4x - 7 = 21$, a student writes the next line as $4x = 28$. Which property justifies this step?', '["Addition property of equality","Multiplication property of equality","Distributive property","Commutative property of addition"]', 'Addition property of equality', NULL, 'The student added 7 to both sides: $4x - 7 + 7 = 21 + 7$. Adding the same number to both sides of an equation keeps it true, which is the addition property of equality.', 'checked', '{"lint":[],"solve":{"answer":"Addition property of equality","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From 4x - 7 = 21 to 4x = 28, 7 is added to both sides: addition property of equality.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79f5fc23-b6eb-491d-b0b2-3bb7647f7338', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality, reversing the sign', 'Solve the inequality $-2x + 3 < 11$.', '["$x < -4$","$x > 4$","$x < 4$","$x > -4$"]', '$x > -4$', NULL, 'Subtract 3 from both sides: $-2x < 8$. Dividing both sides by $-2$ reverses the inequality sign: $x > -4$.', 'checked', '{"lint":[],"solve":{"answer":"$x > -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 3 < 11 -> -2x < 8 -> divide by -2 and flip: x > -4. Check x = 0: 3 < 11 true.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9fe7a4c-d1cc-4572-9e15-5aff7fdf5f47', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a formula for a quantity, given a value', 'The formula $F = \frac{9}{5}C + 32$ changes a temperature in degrees Celsius $C$ to degrees Fahrenheit $F$. A temperature is 68 degrees Fahrenheit. What is it in degrees Celsius?', '[]', '20', '(68-32)*5/9', 'Put $F = 68$ in the formula: $68 = \frac{9}{5}C + 32$. Subtract 32: $36 = \frac{9}{5}C$. Multiply by $\frac{5}{9}$: $C = 36 \times \frac{5}{9} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68 = (9/5)C + 32 -> (9/5)C = 36 -> C = 36 * 5/9 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90c25faa-1050-4d16-8a75-58c5016fcfda', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a simple exponential equation in context', 'A culture starts with 3 bacteria and triples every hour, so after $t$ hours it has $3 \cdot 3^t$ bacteria. After how many hours are there 243 bacteria?', '[]', '4', '4', 'Solve $3 \cdot 3^t = 243$. Divide by 3: $3^t = 81$. Since $3^4 = 81$, $t = 4$ hours. (Check: 3, 9, 27, 81, 243.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 * 3^t = 243 -> 3^t = 81 = 3^4 -> t = 4. Check: 3 * 81 = 243.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8466950c-487a-4219-b5ba-9c53b76b3944', 'NC26.M1.ANFR.5', 3, 'choice', 'Write an exponential equation from a situation', 'A population starts at 200 and doubles every hour. Which equation can be solved to find the number of hours $t$ until the population is 3200?', '["$200 + 2t = 3200$","$200(2)^t = 3200$","$2(200)^t = 3200$","$200(2t) = 3200$"]', '$200(2)^t = 3200$', NULL, 'The starting amount is 200 and it is multiplied by 2 for each hour, so after $t$ hours the population is $200(2)^t$. Setting that equal to 3200 gives $200(2)^t = 3200$.', 'checked', '{"lint":[],"solve":{"answer":"$200(2)^t = 3200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population after t hours = 200(2)^t; set equal to 3200: 200(2)^t = 3200 (t = 4).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a33d09c5-3ce7-4619-b6c8-d32a2db66f09', 'NC26.M1.ANFR.5', 3, 'numeric', 'Interpret the solution of an inequality in context', 'You have 52 dollars. Park entry costs 14 dollars, and each ride ticket costs 3 dollars. You can only buy whole tickets. What is the greatest number of ride tickets you can buy?', '[]', '12', NULL, 'The inequality is $14 + 3r \le 52$, so $3r \le 38$ and $r \le 12.67\ldots$. You can only buy whole tickets, so the greatest number is 12 (12 tickets cost 36 dollars, for a total of 50 dollars).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 + 3n <= 52 -> 3n <= 38 -> n <= 12.67. Greatest whole n = 12 (14 + 36 = 50; 13 would cost 53).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd7dc7e6-e61b-449c-8d7b-347df0d301e1', 'NC26.M1.ANFR.5', 3, 'numeric', 'Solve a formula for time, given values', 'The formula $A = P + Prt$ gives the total $A$ in dollars after $t$ years when $P$ dollars earn simple interest at yearly rate $r$ (written as a decimal). When $P = 200$ and $r = 0.05$, the total is $A = 230$. How many years is that?', '[]', '3', '(230-200)/(200*0.05)', 'Put in the values: $230 = 200 + 200(0.05)t = 200 + 10t$. Subtract 200: $30 = 10t$. So $t = 3$ years.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"230 = 200 + 200(0.05)t = 200 + 10t -> 10t = 30 -> t = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
