INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2319747d-e118-4426-b587-34abc24717c2', 'NC26.M1.ANFR.6', 1, 'choice', 'Test a point in a two-variable inequality', 'Which point is a solution of $y \ge x + 1$?', '["$(1, 3)$","$(3, 1)$","$(2, 2)$","$(4, 4)$"]', '$(1, 3)$', NULL, 'Put each point in. For $(1, 3)$: $3 \ge 1 + 1 = 2$ is true. For $(3, 1)$: $1 \ge 4$ is false. For $(2, 2)$: $2 \ge 3$ is false. For $(4, 4)$: $4 \ge 5$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,3): 3 >= 2 yes. (4,4): 4 >= 5 no. (3,1): 1 >= 4 no. (2,2): 2 >= 3 no.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb4d5f2c-cd95-42c3-9bc7-53a9be0d7769', 'NC26.M1.ANFR.6', 1, 'numeric', 'Find the boundary value of y for a given x', 'The inequality is $y < 3x + 2$. For the point $(4, y)$ to be a solution, what is the greatest whole number that $y$ can be?', '[]', '13', '3*4+2-1', 'When $x = 4$: $y < 3(4) + 2 = 14$. The greatest whole number less than 14 is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y < 3(4) + 2 = 14 (strict). Greatest whole number y = 13.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ba17924-b40d-4198-800f-d2f24f9fd984', 'NC26.M1.ANFR.6', 1, 'choice', 'Write a linear inequality from a context', 'A theater sells child tickets for 5 dollars each ($x$ of them) and adult tickets for 8 dollars each ($y$ of them). Total ticket sales for one show must be at most 200 dollars. Which inequality models this?', '["$5x + 8y \\ge 200$","$8x + 5y \\le 200$","$5x + 8y \\le 200$","$13(x + y) \\le 200$"]', '$5x + 8y \le 200$', NULL, 'Child sales are $5x$ dollars and adult sales are $8y$ dollars, so the total is $5x + 8y$. "At most 200" means $\le 200$.', 'checked', '{"lint":[],"solve":{"answer":"$5x + 8y \\le 200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor realism: a theater capping its sales at ''at most'' 200 dollars is an odd context (a cost or budget limit reads more naturally), though the maths and key are unambiguous.","work":"Child sales 5x, adult sales 8y, total at most 200: 5x + 8y <= 200.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153cc497-1ce3-4e9f-9035-e42b6475e2b7', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from its boundary line', 'The solutions of an inequality are all the points above the line $y = 2x - 1$, and points on the line are not solutions. Which inequality is it?', '["$y \\ge 2x - 1$","$y > 2x - 1$","$y < 2x - 1$","$y > -2x - 1$"]', '$y > 2x - 1$', NULL, 'Points above the line have $y$ greater than $2x - 1$, so the sign is $>$. Points on the line are not included, so it is $>$ and not $\ge$.', 'checked', '{"lint":[],"solve":{"answer":"$y > 2x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Above the line, line excluded: strict >, same line y = 2x - 1: y > 2x - 1.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d456565-4ec3-467f-8eca-955173f84f1f', 'NC26.M1.ANFR.6', 2, 'numeric', 'Interpret a solution of an inequality in context', 'A school buys $x$ notebooks at 3 dollars each and $y$ pens at 2 dollars each. Its budget is 60 dollars, so $3x + 2y \le 60$. If the school buys 12 notebooks, what is the greatest number of pens it can buy?', '[]', '12', '(60-3*12)/2', 'With $x = 12$: $36 + 2y \le 60$, so $2y \le 24$ and $y \le 12$. The greatest number of pens is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(12) + 2y <= 60 -> 2y <= 24 -> y <= 12. Greatest 12.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8ec0be2-f67f-41da-b7ab-3febac86137f', 'NC26.M1.ANFR.6', 2, 'choice', 'Find a point that is not a solution', 'Which point is NOT a solution of $2x + 3y \le 12$?', '["$(0, 0)$","$(3, 2)$","$(-2, 4)$","$(6, 1)$"]', '$(6, 1)$', NULL, 'Test each point. $(0, 0)$: $0 \le 12$ is true. $(3, 2)$: $6 + 6 = 12 \le 12$ is true. $(-2, 4)$: $-4 + 12 = 8 \le 12$ is true. $(6, 1)$: $12 + 3 = 15 \le 12$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,2): 6 + 6 = 12 <= 12 yes. (6,1): 12 + 3 = 15 > 12 NOT a solution. (-2,4): -4 + 12 = 8 yes. (0,0): 0 yes.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('926eaf83-695d-40d1-bb2e-be8774092c2c', 'NC26.M1.ANFR.6', 3, 'numeric', 'Count whole-number solutions of an inequality', 'How many ordered pairs $(x, y)$ of positive whole numbers make $x + y \le 5$ true?', '[]', '10', '4+3+2+1', 'List by $x$. If $x = 1$, then $y$ can be 1, 2, 3 or 4 (4 pairs). If $x = 2$: $y$ is 1, 2 or 3 (3 pairs). If $x = 3$: 2 pairs. If $x = 4$: 1 pair. If $x = 5$ there is no positive $y$. Total: $4 + 3 + 2 + 1 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x, y >= 1. x=1: y = 1..4 (4); x=2: 3; x=3: 2; x=4: 1; x=5 impossible. Total 4+3+2+1 = 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd441674-299f-426c-9c09-5840421e7d5d', 'NC26.M1.ANFR.6', 3, 'choice', 'Interpret a solution point in context', 'A club sells $a$ adult tickets at 15 dollars each and $b$ child tickets at 10 dollars each. To reach its goal, it needs $15a + 10b \ge 120$. What does the solution $(a, b) = (4, 6)$ mean?', '["Selling 4 adult and 6 child tickets raises more than 120 dollars, so the goal is beaten","Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met","Selling 4 adult and 6 child tickets raises less than 120 dollars, so the goal is missed","Selling 4 adult and 6 child tickets raises 4 + 6 = 10 dollars, far below the goal"]', 'Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met', NULL, 'Put in the numbers: $15(4) + 10(6) = 60 + 60 = 120$, and $120 \ge 120$ is true. The ticket sales raise exactly the 120 dollars needed, so this point lies on the boundary.', 'checked', '{"lint":[],"solve":{"answer":"Selling 4 adult and 6 child tickets raises exactly 120 dollars, so the goal is just met","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15(4) + 10(6) = 60 + 60 = 120, which equals 120, so the goal is exactly met (>= holds with equality).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f43da357-8d05-42a3-bfb7-4bc40e2bc3c9', 'NC26.M1.ANFR.6', 3, 'numeric', 'Use the boundary line of an inequality', 'The boundary line of the inequality $3x - 2y \ge 6$ is the line $3x - 2y = 6$. The point $(4, k)$ lies on this line. What is $k$?', '[]', '3', '(3*4-6)/2', 'Put $x = 4$ in $3x - 2y = 6$: $12 - 2k = 6$, so $2k = 6$ and $k = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(4) - 2k = 6 -> 12 - 2k = 6 -> k = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e3ae02-f44e-415f-a4f3-52ba458c0073', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system by substitution', 'A system has the equations $y = 2x$ and $x + y = 12$. What is $x$?', '[]', '4', '12/3', 'Substitute $y = 2x$ into $x + y = 12$: $x + 2x = 12$, so $3x = 12$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x = 12 -> 3x = 12 -> x = 4 (y = 8).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b09707b-f842-40be-b4ee-1331c7d263cd', 'NC26.M1.ANFR.7', 1, 'choice', 'Identify the solution of a system', 'Which ordered pair is the solution of both $x + y = 7$ and $x - y = 3$?', '["$(5, 2)$","$(2, 5)$","$(4, 3)$","$(3, 4)$"]', '$(5, 2)$', NULL, 'Check each pair in both equations. For $(5, 2)$: $5 + 2 = 7$ and $5 - 2 = 3$, so it works. $(2, 5)$, $(4, 3)$ and $(3, 4)$ all add to 7 but give $x - y$ equal to $-3$, 1 and $-1$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 2x = 10, x = 5; y = 2. Check 5 - 2 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4128922-9531-4dcb-af24-788755539757', 'NC26.M1.ANFR.7', 1, 'choice', 'Build a system from a situation', 'A bakery sold 100 items in one day. Muffins ($x$ of them) cost 3 dollars each and bagels ($y$ of them) cost 2 dollars each, and the bakery took in 260 dollars. Which system models this?', '["$x + y = 100$ and $2x + 3y = 260$","$x + y = 260$ and $3x + 2y = 100$","$x + y = 100$ and $3x + 2y = 260$","$xy = 100$ and $3x + 2y = 260$"]', '$x + y = 100$ and $3x + 2y = 260$', NULL, 'The number of items is $x + y = 100$. The money taken in is 3 dollars per muffin plus 2 dollars per bagel: $3x + 2y = 260$.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 100$ and $3x + 2y = 260$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count: x + y = 100. Money: 3x + 2y = 260 (solution x = 60, y = 40).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9f92336-8d87-4d6e-a768-3a37a1a82c4c', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $y = 2x + 3$ and $y = 2x - 5$ have?', '["Exactly one solution","Infinitely many solutions","Exactly two solutions","No solution"]', 'No solution', NULL, 'Both lines have slope 2 but different y-intercepts (3 and $-5$), so they are parallel and never meet. Setting the right sides equal gives $2x + 3 = 2x - 5$, which is never true.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same slope 2, different intercepts 3 and -5: parallel lines, never meet. No solution.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28800c1a-e9f6-49c0-bce7-4e300597eceb', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'A rental shop has bikes (2 wheels each) and trikes (3 wheels each). There are 14 vehicles with 38 wheels in all. How many trikes are there?', '[]', '10', '38-2*14', 'Let $b$ be bikes and $t$ be trikes. Then $b + t = 14$ and $2b + 3t = 38$. Replacing $b$ with $14 - t$: $2(14 - t) + 3t = 38$, so $28 + t = 38$ and $t = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b + t = 14, 2b + 3t = 38. 2(14) + t = 38 -> t = 10, b = 4. Check 8 + 30 = 38.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b34525e-e29d-4a0c-b020-22dea06879db', 'NC26.M1.ANFR.7', 2, 'numeric', 'Find the intersection of two lines', 'The lines $y = x + 2$ and $y = -x + 8$ cross at one point. What is the y-coordinate of that point?', '[]', '5', '(8-2)/2+2', 'At the crossing point the y-values are equal: $x + 2 = -x + 8$, so $2x = 6$ and $x = 3$. Then $y = 3 + 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2 = -x + 8 -> 2x = 6 -> x = 3, y = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57cb8850-fea4-410c-9257-9bd9fed88666', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'A gym offers Plan A, which costs $y = 30 + 4x$ dollars for $x$ visits, and Plan B, which costs $y = 10 + 6x$ dollars for $x$ visits. The solution of the system is $(10, 70)$. What does it mean?', '["Plan A costs 10 dollars and Plan B costs 70 dollars","After 10 visits both plans cost the same total, 70 dollars","After 70 visits both plans cost the same total, 10 dollars","Plan B is cheaper no matter how many visits"]', 'After 10 visits both plans cost the same total, 70 dollars', NULL, 'The solution is the $(x, y)$ that makes both equations true: at $x = 10$ visits, Plan A costs $30 + 40 = 70$ and Plan B costs $10 + 60 = 70$. So after 10 visits the two plans cost the same, 70 dollars.', 'checked', '{"lint":[],"solve":{"answer":"After 10 visits both plans cost the same total, 70 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 10 visits, y = 70 dollars: 30 + 40 = 70 and 10 + 60 = 70. Both plans cost 70 after 10 visits.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee8bc7ec-c0c0-4f71-bcfe-dc62a5cd2952', 'NC26.M1.ANFR.7', 3, 'numeric', 'Find the value that gives infinitely many solutions', 'The system $y = 3x + 4$ and $2y = 6x + k$ has infinitely many solutions. What is $k$?', '[]', '8', '2*4', 'The system has infinitely many solutions when both equations describe the same line. Multiplying $y = 3x + 4$ by 2 gives $2y = 6x + 8$, so $k = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double the first: 2y = 6x + 8. Same line iff k = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2114a52-d059-439c-aa46-b20af868af41', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution with a coefficient', 'A system has the equations $3x + 2y = 16$ and $y = x + 3$. What is $y$?', '[]', '5', '(16-6)/5+3', 'Substitute $y = x + 3$: $3x + 2(x + 3) = 16$, so $5x + 6 = 16$ and $x = 2$. Then $y = 2 + 3 = 5$. Check: $3(2) + 2(5) = 16$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2(x + 3) = 16 -> 5x + 6 = 16 -> x = 2, y = 5. Check 6 + 10 = 16.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ed44b1c-7ff3-4294-b490-c0df562ae153', 'NC26.M1.SGMR.1', 1, 'choice', 'Find the image of a point under a translation', 'The point $(3, 5)$ is translated 4 units to the right and 2 units down. What are the coordinates of its image?', '["$(7, 7)$","$(-1, 3)$","$(7, 3)$","$(5, 9)$"]', '$(7, 3)$', NULL, 'Moving right adds to the x-coordinate: $3 + 4 = 7$. Moving down subtracts from the y-coordinate: $5 - 2 = 3$. The image is $(7, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(7, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 + 4, 5 - 2) = (7, 3).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67ccfac4-cc98-4936-815e-04105c5c9ac2', 'NC26.M1.SGMR.1', 1, 'choice', 'Know what rigid transformations preserve', 'Which pair of properties is the same for a figure and its image under any rotation, reflection or translation?', '["Side lengths and angle measures","Side lengths and orientation","Angle measures and location","Location and orientation"]', 'Side lengths and angle measures', NULL, 'Rigid transformations keep the shape and size: side lengths and angle measures do not change. A translation, rotation or reflection moves the figure, so its location changes, and a reflection reverses its orientation.', 'checked', '{"lint":[],"solve":{"answer":"Side lengths and angle measures","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motions preserve distance and angle measure. Location changes under translations; orientation is reversed by reflections.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9308cf88-e5d7-4a71-8023-2d17516aed85', 'NC26.M1.SGMR.1', 1, 'numeric', 'Find the image of a point under a reflection', 'The point $(-4, 7)$ is reflected across the y-axis. What is the x-coordinate of its image?', '[]', '4', '-(-4)', 'A reflection across the y-axis changes the sign of the x-coordinate and keeps the y-coordinate. The image of $(-4, 7)$ is $(4, 7)$, so the x-coordinate is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across y-axis: (x, y) -> (-x, y). (-4, 7) -> (4, 7). x-coordinate 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e93a9c1-3401-4045-91da-a12a6bd4cacb', 'NC26.M1.SGMR.1', 2, 'choice', 'Find the image of a point under a rotation', 'The point $(2, 5)$ is rotated 90 degrees counterclockwise about the origin. What are the coordinates of its image?', '["$(5, -2)$","$(-5, 2)$","$(-2, -5)$","$(-2, 5)$"]', '$(-5, 2)$', NULL, 'A 90 degree counterclockwise rotation about the origin takes $(x, y)$ to $(-y, x)$. So $(2, 5)$ becomes $(-5, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-5, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 deg CCW about origin: (x, y) -> (-y, x). (2, 5) -> (-5, 2).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30035f0a-9224-4129-abac-0688ee6a8bec', 'NC26.M1.SGMR.1', 2, 'numeric', 'Find a preimage using function notation', 'A translation is given by $T(x, y) = (x - 3, y + 5)$. The image of a point $P$ is $T(P) = (2, 1)$. What is the sum of the x-coordinate and the y-coordinate of $P$?', '[]', '1', '(2+3)+(1-5)', 'Undo the translation. The image has $x - 3 = 2$, so $x = 5$, and $y + 5 = 1$, so $y = -4$. So $P = (5, -4)$ and the sum is $5 + (-4) = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 3 = 2 -> x = 5; y + 5 = 1 -> y = -4. P = (5, -4), sum 1.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c8ab706-f1c8-406d-bde4-8b1d18373582', 'NC26.M1.SGMR.1', 2, 'choice', 'Identify the transformation that maps points to images', 'A single rigid transformation takes $(2, 3)$ to $(2, -3)$ and $(5, 1)$ to $(5, -1)$. Which transformation is it?', '["A reflection across the y-axis","A rotation of 180 degrees about the origin","A translation 6 units down","A reflection across the x-axis"]', 'A reflection across the x-axis', NULL, 'Each x-coordinate stays the same and each y-coordinate changes sign, which is a reflection across the x-axis. A rotation of 180 degrees would give $(-2, -3)$, a reflection across the y-axis would give $(-2, 3)$, and moving 6 units down would give $(5, -5)$ for the second point.', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the x-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (x, -y) fits both points: reflection across the x-axis. Translation 6 down sends (5,1) to (5,-5); 180 deg rotation sends (2,3) to (-2,-3); y-axis reflection changes x.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3793ef7-e5e5-4896-a212-ccb098b6353b', 'NC26.M1.SGMR.1', 3, 'numeric', 'Use congruence to find a perimeter after two moves', 'Triangle ABC has vertices $A(0, 0)$, $B(4, 0)$ and $C(0, 3)$, so $AB = 4$, $AC = 3$ and $BC = 5$. The triangle is reflected across the x-axis and then translated 6 units to the right. What is the perimeter of the final image?', '[]', '12', '4+3+5', 'Reflections and translations are rigid transformations, so side lengths do not change. The image is congruent to ABC and has perimeter $4 + 3 + 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motions preserve lengths, so the image is congruent: perimeter 4 + 3 + 5 = 12.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6003365-cb01-4e50-b599-68967118d8a4', 'NC26.M1.SGMR.1', 3, 'numeric', 'Undo a sequence of transformations to find the preimage', 'A figure is translated 5 units to the left and then reflected across the x-axis. The image of one of its points is $(-1, -6)$. What is the sum of the x-coordinate and the y-coordinate of the original point?', '[]', '10', '(-1+5)+6', 'Work backwards. Undo the reflection across the x-axis: $(-1, -6)$ becomes $(-1, 6)$. Undo the translation 5 units left by moving 5 units right: $(4, 6)$. The sum is $4 + 6 = 10$. (Check forward: $(4, 6)$ moves left to $(-1, 6)$, then reflects to $(-1, -6)$.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo reflection across x-axis: (-1, -6) -> (-1, 6). Undo translation 5 left (move 5 right): (4, 6). Check: (4,6) -> (-1,6) -> (-1,-6). Sum 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fa1cd67-4d0d-4216-9625-f11c8121022d', 'NC26.M1.SGMR.1', 3, 'choice', 'Describe a sequence of moves that shows congruence', 'Triangle $T$ has vertices $(0, 0)$, $(2, 0)$ and $(0, 1)$. Triangle $T''$ has vertices $(3, 3)$, $(3, 5)$ and $(2, 3)$. Which sequence of rigid transformations maps $T$ onto $T''$?', '["Rotate 90 degrees clockwise about the origin, then translate 3 units right and 3 units up","Reflect across the y-axis, then translate 3 units right and 3 units up","Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up","Reflect across the x-axis, then translate 3 units right and 3 units up"]', 'Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up', NULL, 'Rotating 90 degrees counterclockwise takes $(x, y)$ to $(-y, x)$: $(0, 0)$, $(0, 2)$ and $(-1, 0)$. Translating 3 right and 3 up gives $(3, 3)$, $(3, 5)$ and $(2, 3)$, which is $T''$. The other sequences give $(3, 3), (3, 1), (4, 3)$ or $(3, 3), (1, 3), (3, 4)$ or $(3, 3), (5, 3), (3, 2)$. Since a sequence of rigid moves maps $T$ onto $T''$, the triangles are congruent.', 'checked', '{"lint":[],"solve":{"answer":"Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotate 90 CCW (x,y)->(-y,x): (0,0),(2,0),(0,1) -> (0,0),(0,2),(-1,0); translate (+3,+3): (3,3),(3,5),(2,3) = T''. Others: y-reflect+translate gives (3,3),(1,3),(3,4); x-reflect gives (3,3),(5,3),(3,2); 90 CW gives (3,3),(3,1),(4,3). Only the CCW option works.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bf57d6-7915-46e7-9e86-0760f679b84f', 'NC26.M1.SGMR.2', 1, 'numeric', 'Corresponding sides of congruent triangles', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$, and $C$ matching $F$. In triangle $ABC$, $AB = 7$ cm, $BC = 9$ cm, and $AC = 11$ cm. What is the length of $EF$, in centimeters?', '[]', '9', '9', 'The letters match in order, so $B$ matches $E$ and $C$ matches $F$. That makes side $EF$ match side $BC$. Matching sides of congruent triangles are equal, so $EF = BC = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correspondence A-D, B-E, C-F, so EF corresponds to BC = 9 cm.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a1b7828-b494-42a3-a489-44dbc2d0254f', 'NC26.M1.SGMR.2', 1, 'choice', 'Naming the SSS criterion', 'Two triangles have three pairs of equal sides. Which rule shows that the two triangles are congruent?', '["SAS","ASA","SSS","AAA"]', 'SSS', NULL, 'Three pairs of equal sides is the side-side-side (SSS) rule. SAS and ASA each need an angle, and equal angles alone (AAA) do not prove congruence.', 'checked', '{"lint":[],"solve":{"answer":"SSS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three pairs of equal sides is the Side-Side-Side criterion.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949ee55d-1f09-49c5-aa5b-7faf9c55c142', 'NC26.M1.SGMR.2', 1, 'choice', 'Rigid motions and congruence', 'Which of these transformations does NOT always produce a figure congruent to the original?', '["a dilation with scale factor 2","a translation","a reflection","a rotation"]', 'a dilation with scale factor 2', NULL, 'Translations, reflections and rotations are rigid motions: they keep every length and angle, so the image is congruent to the original. A dilation with scale factor 2 doubles every length, so the image is larger and not congruent.', 'checked', '{"lint":[],"solve":{"answer":"a dilation with scale factor 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translations, rotations and reflections are rigid motions and preserve size; a dilation with scale factor 2 doubles lengths, so the image is not congruent.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4179c0f-2b5b-40ac-aa05-9e99ebff9dbc', 'NC26.M1.SGMR.2', 2, 'choice', 'Recognizing the SAS criterion', 'In triangles $ABC$ and $DEF$, $AB = DE = 6$, $BC = EF = 8$, and $\angle B = \angle E = 35^\circ$. Which rule shows that the triangles are congruent?', '["ASA","SSS","AAS","SAS"]', 'SAS', NULL, '$AB$ and $BC$ are the two sides that meet at $B$, so $\angle B$ lies between them. Two pairs of equal sides and the equal angle between them is the SAS rule.', 'checked', '{"lint":[],"solve":{"answer":"SAS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DE, BC = EF, and angle B (between AB and BC) = angle E (between DE and EF): two sides and the included angle, SAS.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c50e86b-2d6d-43b0-978d-65e0f7967df3', 'NC26.M1.SGMR.2', 2, 'numeric', 'Using congruence to find an unknown side', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$, and $C$ matching $F$. Side $AB$ has length $2x + 1$ and side $DE$ has length $13$. What is the value of $x$?', '[]', '6', '(13-1)/2', 'Matching sides of congruent triangles are equal, so $AB = DE$ and $2x + 1 = 13$. Subtract 1: $2x = 12$. Divide by 2: $x = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB corresponds to DE, so 2x + 1 = 13, 2x = 12, x = 6.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77a9540b-eec0-4ddb-819e-efc0d150fbb5', 'NC26.M1.SGMR.2', 2, 'choice', 'Why equal angles alone do not prove congruence', 'In triangles $ABC$ and $DEF$, $\angle A = \angle D$, $\angle B = \angle E$, and $\angle C = \angle F$. No side lengths are known. Which statement is correct?', '["The triangles must be congruent, because all three angles match","The triangles might not be congruent, because one could be larger than the other","The triangles cannot be congruent, because no sides are known","The triangles must be congruent by SAS"]', 'The triangles might not be congruent, because one could be larger than the other', NULL, 'Matching angles fix the shape of a triangle but not its size. A small triangle and an enlarged copy of it have equal angles and are not congruent, so equal angles (AAA) do not guarantee congruence.', 'checked', '{"lint":[],"solve":{"answer":"The triangles might not be congruent, because one could be larger than the other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AAA only gives similarity; one triangle can be a scaled copy of the other, so they might not be congruent. They are not impossible to be congruent (option 1 wrong), SAS needs sides (option 3 wrong), AAA is not a congruence rule (option 4 wrong).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fb49fdf-1ebf-4e28-9ff4-1168f56e3553', 'NC26.M1.SGMR.2', 3, 'choice', 'The ambiguous side-side-angle case', 'In triangles $ABC$ and $DEF$, $AB = DE = 8$, $BC = EF = 6$, and $\angle A = \angle D = 30^\circ$. Which statement is correct?', '["The triangles are congruent by SAS","Congruence is not guaranteed, because the angle is not between the two known sides","The triangles are congruent by SSS","The triangles are congruent by ASA"]', 'Congruence is not guaranteed, because the angle is not between the two known sides', NULL, '$\angle A$ is not the angle between sides $AB$ and $BC$; it is opposite $BC$. Two sides and a non-included angle (SSA) do not guarantee congruence. Here, side $BC = 6$ can swing to meet the third side in two different places, giving two different triangles.', 'checked', '{"lint":[],"solve":{"answer":"Congruence is not guaranteed, because the angle is not between the two known sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle A lies between AB and AC, not between AB and BC, so this is SSA. Check ambiguity: side opposite A is BC = 6, adjacent AB = 8, height 8 sin 30 = 4; 4 < 6 < 8 so two different triangles exist. Congruence not guaranteed.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f410a059-f04d-4543-8947-2b45620211ba', 'NC26.M1.SGMR.2', 3, 'numeric', 'Proving congruence, then using it to solve', 'In triangles $ABC$ and $DEF$, $AB = DE$, $AC = DF$, and $\angle A = \angle D$. Also $BC = 4x - 3$ and $EF = 2x + 11$. What is the value of $x$?', '[]', '7', '(11+3)/(4-2)', '$AB = DE$, $AC = DF$, and the angle between them is equal ($\angle A = \angle D$), so the triangles are congruent by SAS. Matching sides of congruent triangles are equal, so $BC = EF$: $4x - 3 = 2x + 11$. Subtract $2x$ and add 3: $2x = 14$, so $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DE, AC = DF, angle A = angle D is included between AB and AC, so SAS: triangles congruent, BC = EF. 4x - 3 = 2x + 11, 2x = 14, x = 7 (BC = EF = 25).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b760a45c-a879-4d3c-ba50-348e93b14496', 'NC26.M1.SGMR.2', 3, 'choice', 'Arguing ASA after finding a third angle', 'Triangle $ABC$ has $\angle A = 50^\circ$, $\angle B = 60^\circ$, and $AB = 8$. Triangle $DEF$ has $\angle D = 50^\circ$, $\angle F = 70^\circ$, and $DE = 8$. Which argument is correct?', '["Not congruent, because the $70^\\circ$ angle is given for only one of the triangles","Not congruent, because only one pair of sides is known","Congruent by SAS, because $AB = DE$ and $\\angle A = \\angle D$","Congruent by ASA, because $\\angle E = 60^\\circ$ and $DE$ lies between $\\angle D$ and $\\angle E$"]', 'Congruent by ASA, because $\angle E = 60^\circ$ and $DE$ lies between $\angle D$ and $\angle E$', NULL, 'The angles in a triangle add to $180^\circ$, so $\angle E = 180^\circ - 50^\circ - 70^\circ = 60^\circ$. Then $\angle A = \angle D = 50^\circ$, $\angle B = \angle E = 60^\circ$, and the side $AB = DE = 8$ lies between those two angles in each triangle. That is the ASA rule. SAS would need two pairs of equal sides.', 'checked', '{"lint":[],"solve":{"answer":"Congruent by ASA, because $\\angle E = 60^\\circ$ and $DE$ lies between $\\angle D$ and $\\angle E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In DEF, angle E = 180 - 50 - 70 = 60. So angle A = angle D = 50, AB = DE = 8, angle B = angle E = 60; AB and DE are the included sides. ASA holds. Option 2 lacks a second side; options 3 and 4 are false.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bf2975-9131-44bf-970f-530b5f734c32', 'NC26.M1.SGMR.3', 1, 'numeric', 'Midpoint of a segment', 'What is the $x$-coordinate of the midpoint of the segment with endpoints $(2, 4)$ and $(10, 8)$?', '[]', '6', '(2+10)/2', 'The midpoint''s $x$-coordinate is the average of the endpoints'' $x$-coordinates: $(2 + 10) \div 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-midpoint = (2 + 10)/2 = 6.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd2a18e7-4e1b-4b46-acdb-c8d378e5117d', 'NC26.M1.SGMR.3', 1, 'choice', 'Slope of a parallel line', 'A line has slope $\frac{3}{2}$. What is the slope of any line parallel to it?', '["3/2","-3/2","2/3","-2/3"]', '3/2', '3/2', 'Parallel lines have the same slope, so a line parallel to one with slope $\frac{3}{2}$ also has slope $\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel lines have equal slopes: 3/2.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6605169f-19d9-442a-85ee-30497b92ea9e', 'NC26.M1.SGMR.3', 1, 'numeric', 'Perimeter of a rectangle from coordinates', 'A rectangle has vertices $(1, 1)$, $(7, 1)$, $(7, 4)$ and $(1, 4)$. What is its perimeter, in units?', '[]', '18', '2*(7-1)+2*(4-1)', 'The rectangle is 6 units wide (from $x = 1$ to $x = 7$) and 3 units tall (from $y = 1$ to $y = 4$). Perimeter $= 2(6) + 2(3) = 18$ units.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 7 - 1 = 6, width 4 - 1 = 3. Perimeter = 2(6 + 3) = 18.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ecc192ee-d7a8-4141-951a-6f2f250bf98c', 'NC26.M1.SGMR.3', 2, 'numeric', 'Slope of a perpendicular line', 'Line $l$ passes through the points $(1, 2)$ and $(5, 10)$. What is the slope of a line perpendicular to $l$?', '[]', '-1/2', '-1/((10-2)/(5-1))', 'The slope of $l$ is $\frac{10 - 2}{5 - 1} = \frac{8}{4} = 2$. A perpendicular line has the negative reciprocal slope: $-\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope of l = (10 - 2)/(5 - 1) = 8/4 = 2. Perpendicular slope = -1/2.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1de0ab15-d145-47dc-8bce-5abbd91ebda6', 'NC26.M1.SGMR.3', 2, 'numeric', 'Finding an endpoint from the midpoint', 'The midpoint of segment $AB$ is $(3, 5)$. Point $A$ is $(1, 2)$. What is the $y$-coordinate of point $B$?', '[]', '8', '2*5-2', 'The midpoint''s $y$-coordinate is the average of the endpoints'': $\frac{2 + y_B}{2} = 5$. So $2 + y_B = 10$ and $y_B = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2 + yB)/2 = 5, so yB = 8.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49a847fc-b869-4c38-85d0-421e21153c21', 'NC26.M1.SGMR.3', 2, 'choice', 'Classifying a triangle from its vertices', 'Triangle $PQR$ has vertices $P(0, 0)$, $Q(6, 0)$ and $R(3, 4)$. What type of triangle is it?', '["scalene","right","isosceles","equilateral"]', 'isosceles', NULL, '$PQ = 6$. $PR = \sqrt{3^2 + 4^2} = 5$ and $QR = \sqrt{3^2 + 4^2} = 5$. Two sides are equal and the third is different, so the triangle is isosceles. It is not a right triangle, because $5^2 + 5^2 = 50$ is not $6^2 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"isosceles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PQ = 6; PR = sqrt(9 + 16) = 5; QR = sqrt(9 + 16) = 5. Two equal sides: isosceles. Not equilateral. Right? Largest side 6: 25 + 25 = 50, not 36, so not right; other angles also not right (36 + 25 is not 25). Isosceles only.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5484f9a2-6f23-4437-b93d-5c5322b9eacd', 'NC26.M1.SGMR.3', 3, 'choice', 'Equation of a perpendicular line', 'Which is the equation of the line through $(4, 1)$ that is perpendicular to $y = 2x + 3$?', '["$y = 2x - 7$","$y = -2x + 9$","$y = \\frac{1}{2}x - 1$","$y = -\\frac{1}{2}x + 3$"]', '$y = -\frac{1}{2}x + 3$', NULL, 'The slope of $y = 2x + 3$ is 2, so a perpendicular line has slope $-\frac{1}{2}$. Write $y = -\frac{1}{2}x + b$ and use the point $(4, 1)$: $1 = -2 + b$, so $b = 3$. The line $y = 2x - 7$ is parallel to the given line, not perpendicular.', 'checked', '{"lint":[],"solve":{"answer":"$y = -\\frac{1}{2}x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perpendicular slope = -1/2. y - 1 = -1/2 (x - 4), y = -x/2 + 2 + 1 = -x/2 + 3. Option y = -2x + 9 passes through (4,1) but has slope -2, not perpendicular.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('478c1473-d834-4c0f-ae26-ce5fa52e4d19', 'NC26.M1.SGMR.3', 3, 'choice', 'Classifying a quadrilateral from its vertices', 'Quadrilateral $ABCD$ has vertices $A(0, 0)$, $B(4, 0)$, $C(5, 3)$ and $D(1, 3)$. Which statement is true?', '["$ABCD$ is a rectangle","$ABCD$ is a parallelogram but not a rectangle","$ABCD$ is a rhombus","$ABCD$ is not a parallelogram"]', '$ABCD$ is a parallelogram but not a rectangle', NULL, '$AB$ and $DC$ are both horizontal and 4 units long. $BC$ and $AD$ each run 1 unit across while rising 3, so they are parallel and equal in length. Both pairs of opposite sides are parallel, so $ABCD$ is a parallelogram. $AB = 4$ but $BC = \sqrt{10}$, so it is not a rhombus, and $AB$ (horizontal) is not perpendicular to $BC$ (slope 3), so it is not a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"$ABCD$ is a parallelogram but not a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = (4,0), DC = (4,0); AD = (1,3), BC = (1,3): both pairs of opposite sides parallel and equal, so a parallelogram. AB dot AD = 4, not 0, so no right angle: not a rectangle. |AB| = 4, |AD| = sqrt 10: not a rhombus.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf65038c-25de-4749-bfcd-c7921a7c7ed2', 'NC26.M1.SGMR.3', 3, 'numeric', 'Area of a triangle from coordinates', 'A triangle has vertices $(2, 1)$, $(8, 1)$ and $(11, 5)$. What is its area, in square units?', '[]', '12', '6*4/2', 'The side from $(2, 1)$ to $(8, 1)$ is horizontal and 6 units long; use it as the base. The height is the vertical distance from the line $y = 1$ to the point $(11, 5)$, which is 4. Area $= \frac{1}{2}(6)(4) = 12$ square units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base from (2,1) to (8,1) has length 6 on the line y = 1. Height = 5 - 1 = 4. Area = 1/2 x 6 x 4 = 12. (Shoelace check: 2(1-5) + 8(5-1) + 11(1-1) = -8 + 32 = 24, half = 12.)","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65551ed6-9385-4ec7-a034-47f00aa3e0d8', 'NC26.M1.SDSR.1', 1, 'numeric', 'Marginal total from a two-way table', 'A survey asked 40 students how they get to school. Of the 24 boys, 15 walk. Of the 16 girls, 7 walk. How many of the 40 students walk?', '[]', '22', '15+7', 'Add the boys who walk and the girls who walk: $15 + 7 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walkers = 15 boys + 7 girls = 22.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3c49c46-7db1-4e60-aa7b-6ebc0878e0d9', 'NC26.M1.SDSR.1', 1, 'choice', 'Probability of a complement', 'In a class of 30 students, 12 have a pet. One student is chosen at random. What is the probability that the student does NOT have a pet?', '["2/5","2/3","3/5","3/2"]', '3/5', '18/30', 'Students without a pet: $30 - 12 = 18$. The probability is $\frac{18}{30} = \frac{3}{5}$. The fraction $\frac{2}{5}$ is the probability of having a pet.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No pet = 30 - 12 = 18. P = 18/30 = 3/5.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('940bbb5a-2e48-490d-8fed-3ecb0196e239', 'NC26.M1.SDSR.1', 1, 'numeric', 'Joint probability from a two-way table', 'In a survey of 50 students, 14 are in grade 9 and play an instrument, 10 are in grade 9 and do not, 16 are in grade 10 and play an instrument, and 10 are in grade 10 and do not. One of the 50 students is chosen at random. What is the probability that the student is in grade 9 and plays an instrument? Write your answer as a fraction.', '[]', '7/25', '14/50', '14 of the 50 students are both in grade 9 and play an instrument, so the probability is $\frac{14}{50} = \frac{7}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"7/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check total 14 + 10 + 16 + 10 = 50. P(grade 9 and plays) = 14/50 = 7/25.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5d9643c-1b98-4345-82a0-9cb0336fccb1', 'NC26.M1.SDSR.1', 2, 'numeric', 'Finding a missing entry in a two-way table', 'A survey of 80 students recorded each student''s favorite pet. Every student chose cats or dogs. Of the students, 48 are girls. Among the girls, 30 chose cats. Among the boys, 22 chose cats. How many boys chose dogs?', '[]', '10', '80-48-22', 'Boys: $80 - 48 = 32$. Of these 32 boys, 22 chose cats, so $32 - 22 = 10$ chose dogs. (The 30 girls who chose cats are not needed.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys = 80 - 48 = 32. Boys choosing cats = 22, so boys choosing dogs = 32 - 22 = 10.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a8cf401-c388-4a9f-aaca-a85dafa1115b', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability of a union', 'In a group of 40 students, 18 take Spanish, 15 take French, and 6 take both. One student is chosen at random. What is the probability that the student takes Spanish or French (or both)?', '["27/40","33/40","21/40","3/20"]', '27/40', '(18+15-6)/40', 'Adding 18 and 15 counts the 6 students who take both twice, so subtract them once: $18 + 15 - 6 = 27$. The probability is $\frac{27}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"27/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spanish or French = 18 + 15 - 6 = 27. P = 27/40.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('160f2911-86c5-4e20-8790-d89b080612e2', 'NC26.M1.SDSR.1', 2, 'choice', 'Marginal probability from a two-way table', 'A cafe recorded 50 orders: 12 adults ordered coffee, 8 teens ordered coffee, 20 adults ordered tea, and 10 teens ordered tea. One order is chosen at random. What is the probability that it was ordered by a teen?', '["1/5","4/25","9/25","1/3"]', '9/25', '(8+10)/50', 'Teens ordered $8 + 10 = 18$ of the 50 orders, so the probability is $\frac{18}{50} = \frac{9}{25}$. The fraction $\frac{1}{5}$ is only the teens who ordered tea.', 'checked', '{"lint":[],"solve":{"answer":"9/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 12 + 8 + 20 + 10 = 50. Teens = 8 + 10 = 18. P = 18/50 = 9/25.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('122ce948-55ab-4c6b-bee8-aebb8349db15', 'NC26.M1.SDSR.1', 3, 'numeric', 'Intersection from a union and a complement', 'Of 50 students, 30 play soccer, 25 play basketball, and 8 play neither sport. How many students play both?', '[]', '13', '30+25-(50-8)', 'The students who play at least one sport number $50 - 8 = 42$. Adding the soccer and basketball players gives $30 + 25 = 55$, which counts the students who play both twice. So the number who play both is $55 - 42 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least one sport = 50 - 8 = 42. Both = 30 + 25 - 42 = 13. (Soccer only 17, basketball only 12, both 13, neither 8: total 50.)","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36cb5abc-e219-488e-bd2e-230706ed65b4', 'NC26.M1.SDSR.1', 3, 'numeric', 'Using a two-way table with several given totals', 'Of 100 students, 60 are in grade 9 and the rest are in grade 10. In all, 45 of the students ride the bus, and 28 of the grade 9 students ride the bus. One student is chosen at random. What is the probability that the student is in grade 10 and does not ride the bus? Write your answer as a fraction.', '[]', '23/100', '(100-60-(45-28))/100', 'Grade 10 students: $100 - 60 = 40$. Grade 10 students who ride the bus: $45 - 28 = 17$. Grade 10 students who do not ride the bus: $40 - 17 = 23$. The probability is $\frac{23}{100}$.', 'checked', '{"lint":[],"solve":{"answer":"23/100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 10 = 100 - 60 = 40. Grade 10 bus riders = 45 - 28 = 17. Grade 10 not on bus = 40 - 17 = 23. P = 23/100.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07680225-0d4d-477c-a007-c118f4ec95e8', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the sum of the two numbers is NOT 8? Write your answer as a fraction.', '[]', '31/36', '1-5/36', 'There are $6 \times 6 = 36$ equally likely outcomes. The sum is 8 for $(2,6)$, $(3,5)$, $(4,4)$, $(5,3)$ and $(6,2)$: 5 outcomes. So $P(\text{sum is } 8) = \frac{5}{36}$ and $P(\text{not } 8) = 1 - \frac{5}{36} = \frac{31}{36}$.', 'checked', '{"lint":[],"solve":{"answer":"31/36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 equally likely outcomes. Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2) = 5. P(not 8) = 1 - 5/36 = 31/36.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d20e0026-973f-4c35-9503-b61564714645', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling a statistical question from a non-statistical one', 'Which of these is a statistical question?', '["How many hours do students at our school sleep on school nights?","How tall is the tallest tree in the park?","What is the sum of 14 and 9?","How many students are in Ms. Lee''s class today?"]', 'How many hours do students at our school sleep on school nights?', NULL, 'A statistical question expects the answers to vary. Students sleep different numbers of hours, so the data will vary. The other three questions each have one fixed answer.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do students at our school sleep on school nights?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question anticipates variability in the data. Sleep hours of students vary from student to student. The others each have one fixed answer (a sum, one tallest tree, one class count).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80845075-bc8f-4de1-b7fa-8b9ee83f70fb', 'NC26.M1.SDSR.2', 1, 'choice', 'Categorical and numerical variables', 'For each student in a survey, a researcher records favorite color, number of siblings, height in centimeters, and minutes taken to run a mile. Which of these variables is categorical?', '["number of siblings","height in centimeters","minutes taken to run a mile","favorite color"]', 'favorite color', NULL, 'A categorical variable puts each person into a group or category, such as a color. The other three are measured or counted as numbers.', 'checked', '{"lint":[],"solve":{"answer":"favorite color","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite color is a category; minutes, siblings and height are numerical.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6550f206-dc5e-45ed-8476-f44bdc503fb7', 'NC26.M1.SDSR.2', 1, 'choice', 'Sampling bias from convenience', 'Maya wants to know the favorite lunch of all the students at her school, so she asks only the students at her own lunch table. Why might her results be biased?', '["She asked about lunch, and lunch choices cannot be counted","Her table may not represent all of the students at the school","She asked too many students","She did not ask any teachers"]', 'Her table may not represent all of the students at the school', NULL, 'Her friends at one table may have different tastes from the rest of the school, so the sample may not represent all students. That is a biased sample.', 'checked', '{"lint":[],"solve":{"answer":"Her table may not represent all of the students at the school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A convenience sample of one lunch table may not represent the whole school.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcd7ac6b-24c6-4fb3-9a4e-8b146cec8eed', 'NC26.M1.SDSR.2', 2, 'numeric', 'Counting statistical questions', 'Here are five questions. (A) How tall is the flagpole at our school? (B) How tall are the students at our school? (C) How many sides does a hexagon have? (D) How fast do drivers travel on Oak Street? (E) What is today''s date? How many of the five are statistical questions?', '[]', '2', NULL, 'A statistical question expects varying answers. (B) and (D) do: students differ in height and drivers differ in speed. (A), (C) and (E) each have one fixed answer. So 2 are statistical.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) one flagpole, one height: not statistical. (B) heights vary among students: statistical. (C) six: not. (D) speeds vary among drivers: statistical. (E) one date: not. Count = 2.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b274f63-3fc6-499f-9ee4-f075d92cc00e', 'NC26.M1.SDSR.2', 2, 'choice', 'Voluntary response bias', 'A radio station asks listeners to call in to vote on whether the town needs a new park. It then reports the result as the opinion of the whole town. What is the main problem?', '["So many people called that the data cannot be organized","Only listeners who choose to call are counted, so the votes may not represent the whole town","The question has more than one possible answer","Radio stations are not allowed to collect data"]', 'Only listeners who choose to call are counted, so the votes may not represent the whole town', NULL, 'Only people who listen and care enough to call are included (voluntary response), so they may differ from the town as a whole.', 'checked', '{"lint":[],"solve":{"answer":"Only listeners who choose to call are counted, so the votes may not represent the whole town","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Voluntary-response sample: only listeners who choose to call are counted, so it may not represent the town.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94c48f58-4cfe-4ae0-8e97-d52368baa6f9', 'NC26.M1.SDSR.2', 2, 'choice', 'Explain how non-response biases a survey', 'A survey about school lunches was sent to 400 randomly chosen students. Only 100 of them sent it back, mostly students with strong opinions about the lunches. Why might the results be biased?', '["Choosing students at random always gives biased results","The students who replied may differ from those who did not","Surveying 400 students is too many to be fair","The students should all have been in the same grade"]', 'The students who replied may differ from those who did not', NULL, 'The students were chosen at random, which is a good way to sample. But three quarters of them did not reply, and the ones who did mostly have strong opinions. Their answers may not match the views of the students who stayed silent, so the results may be biased. A large sample and a mix of grades do not cause bias.', 'checked', '{"lint":[],"solve":{"answer":"The students who replied may differ from those who did not","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 100 of 400 replied, mostly those with strong opinions: voluntary response / nonresponse bias. The responders may not represent those who did not reply. Random selection does not always bias; same grade is irrelevant; 400 is not ''too many''.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b33671e-1fc7-42cb-ac5c-b3a122166dfb', 'NC26.M1.SDSR.2', 3, 'choice', 'Biased survey wording', 'Which survey question about the school cafeteria is the most neutral (least biased)?', '["Don''t you agree that the cafeteria food is terrible and should be changed?","Most students love the new menu. Do you love it too?","Wouldn''t you say the cafeteria needs more healthy options?","How would you rate the cafeteria food: poor, fair, good, or excellent?"]', 'How would you rate the cafeteria food: poor, fair, good, or excellent?', NULL, 'The other three questions push the reader toward a particular answer (leading questions). The rating question offers balanced choices and does not suggest which to pick.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the cafeteria food: poor, fair, good, or excellent?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The rating scale question does not suggest an answer. The others are leading (love it too, don''t you agree it is terrible, wouldn''t you say it needs more).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a2e05e2-9704-4155-9260-285ec0b34812', 'NC26.M1.SDSR.2', 3, 'choice', 'Choosing an unbiased sampling method', 'A school has 1,200 students. Which method is most likely to give an unbiased estimate of the average time students spend on homework?', '["Ask 100 students chosen at random from the full list of students","Ask all 30 members of the math club","Ask the first 50 students who arrive at school in the morning","Ask the 100 students who are in the library after school"]', 'Ask 100 students chosen at random from the full list of students', NULL, 'A random sample from the complete list gives every student an equal chance of being chosen. The other groups are likely to spend more or less time on homework than the typical student.', 'checked', '{"lint":[],"solve":{"answer":"Ask 100 students chosen at random from the full list of students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample from the full list is unbiased; early arrivals, library students and math club are convenience groups likely to differ in homework time.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c9b677e-c792-4427-8f57-4d3da83842f1', 'NC26.M1.SDSR.2', 3, 'choice', 'Questions a dataset can answer', 'A student collects data from her classmates on three things: hours of sleep, hours of screen time, and last test score. Which question can she investigate with this data?', '["Which classmates prefer pizza to pasta?","How many hours do students in other countries sleep?","Is there a relationship between hours of sleep and test score among her classmates?","Will the school''s fire alarm be replaced next year?"]', 'Is there a relationship between hours of sleep and test score among her classmates?', NULL, 'A question can be investigated only with data that has been collected. Sleep and test score were recorded for each classmate, so she can look for a relationship between them. The other questions need data she does not have.', 'checked', '{"lint":[],"solve":{"answer":"Is there a relationship between hours of sleep and test score among her classmates?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She has sleep, screen time and test score for her classmates, so she can study a relationship between sleep and test score among them. The others need data she did not collect.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1a2cd46-bfcd-446d-bee5-f5cfc8f83e4c', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a source', 'Which source is the most credible for finding the average number of students per class in a state''s public schools?', '["A social media post by an anonymous account that gives no sources","An advertisement from a company that sells school supplies","A classmate''s estimate based on only her own class","A report from the state education agency that explains how its data were collected"]', 'A report from the state education agency that explains how its data were collected', NULL, 'A credible source is open about how its data were collected and covers the whole group. The other sources give no method, may have a reason to exaggerate, or look at only one class.', 'checked', '{"lint":[],"solve":{"answer":"A report from the state education agency that explains how its data were collected","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An official agency report that documents its methods is the most credible; the others are anonymous, anecdotal or commercially motivated.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b8f6d6-2701-41d1-b964-ccbb2759b525', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'A student wants to predict the selling price of a house. Which variable is the LEAST useful for this?', '["the size of the house in square feet","the favorite color of the owner","the number of bedrooms","the neighborhood"]', 'the favorite color of the owner', NULL, 'Size, number of bedrooms and neighborhood all affect what buyers pay. The owner''s favorite color has no connection to the price.', 'checked', '{"lint":[],"solve":{"answer":"the favorite color of the owner","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Size, bedrooms and neighborhood all relate to price; the owner''s favorite color does not.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7a955e5-e142-4409-b5e5-d5a1a936580b', 'NC26.M1.SDSR.3', 1, 'choice', 'Choose the variables that answer a question', 'Sara wants to know whether students who sleep more tend to score higher on quizzes. For each classmate she records hours of sleep, quiz score, shoe size and favorite color. Which two variables should she compare?', '["Shoe size and favorite color","Hours of sleep and shoe size","Hours of sleep and quiz score","Quiz score and favorite color"]', 'Hours of sleep and quiz score', NULL, 'Her question is about sleep and quiz scores, so those are the two variables that matter. Shoe size and favorite color have nothing to do with her question, so pairs that include them would not help her answer it.', 'checked', '{"lint":[],"solve":{"answer":"Hours of sleep and quiz score","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question is whether more sleep goes with higher quiz scores, so the relevant variables are hours of sleep (explanatory) and quiz score (response). Shoe size and favorite color are irrelevant.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a350ad5-53fb-47e1-a115-284540ae210e', 'NC26.M1.SDSR.3', 2, 'choice', 'Recognizing a third variable', 'A dataset shows that students who own more books tend to have higher reading scores. A researcher thinks a student''s age may affect both the number of books and the reading score. In this situation, how is age best described?', '["The only cause of the higher reading scores","A variable that can be ignored because it was not in the question","A third variable that may influence both of the others","A sign that the data were collected incorrectly"]', 'A third variable that may influence both of the others', NULL, 'Older students may own more books and also read better. Age is then a third variable related to both, and it can help explain the pattern. It should not be ignored, and it does not mean the data are wrong.', 'checked', '{"lint":[],"solve":{"answer":"A third variable that may influence both of the others","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Age may influence both books owned and reading score: a third (lurking/confounding) variable.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbdd4900-8367-4774-adad-30e3c911dfd6', 'NC26.M1.SDSR.3', 2, 'numeric', 'Comparing two groups', 'Of 50 students who used a study app, 35 passed the test. Of 50 students who did not use the app, 30 passed. How many percentage points higher is the pass percent of the app group than the pass percent of the other group?', '[]', '10', '35/50*100-30/50*100', 'App group: $\frac{35}{50} = 70$ percent. Other group: $\frac{30}{50} = 60$ percent. The difference is $70 - 60 = 10$ percentage points.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"App group 35/50 = 70 percent; other group 30/50 = 60 percent. Difference = 10 percentage points.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8342c786-05d0-4aff-a77c-e83345d05ad9', 'NC26.M1.SDSR.3', 2, 'choice', 'Doubting a claim about data', 'A website says, "Our vitamin drink raises math scores by 30 percent!" Which detail would make you the MOST doubtful of the claim?', '["The website sells the drink and does not say how scores were measured","The study included a comparison group that did not drink it","The study reports how many students took part","The data were collected by an outside research team"]', 'The website sells the drink and does not say how scores were measured', NULL, 'A seller with something to gain, and no information on how the scores were measured, is a reason to doubt. A comparison group, a stated number of students and independent researchers all make a claim more credible.', 'checked', '{"lint":[],"solve":{"answer":"The website sells the drink and does not say how scores were measured","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A seller with an interest in the result who gives no measurement method is the most reason for doubt; the other details make the claim more credible.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44d98ee9-d8b5-4b8d-9b18-03c26185381a', 'NC26.M1.SDSR.3', 3, 'choice', 'Splitting data by a third variable', 'Two tutoring programs report results. Program X had 80 beginners, 48 of whom passed, and 20 advanced students, 19 of whom passed. Program Y had 20 beginners, 10 of whom passed, and 80 advanced students, 70 of whom passed. Program X has the higher pass rate at each level, yet Program Y has the higher pass rate overall. Which statement best explains this?', '["Program Y must have recorded its results incorrectly","Program X is actually worse than Program Y at every level","Program X had a much larger share of beginners, who pass less often in both programs","Percentages from small groups should always be ignored"]', 'Program X had a much larger share of beginners, who pass less often in both programs', NULL, 'Beginners: X passed $\frac{48}{80} = 60$ percent, Y passed $\frac{10}{20} = 50$ percent. Advanced: X passed $\frac{19}{20} = 95$ percent, Y passed $\frac{70}{80} = 87.5$ percent. So X is higher at both levels. Overall, X passed $\frac{67}{100}$ and Y passed $\frac{80}{100}$. Most of X''s students were beginners, who pass less often in either program, which pulls X''s overall rate down.', 'checked', '{"lint":[],"solve":{"answer":"Program X had a much larger share of beginners, who pass less often in both programs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: beginners 48/80 = 60, advanced 19/20 = 95, overall 67/100 = 67 percent. Y: beginners 10/20 = 50, advanced 70/80 = 87.5, overall 80/100 = 80 percent. X wins in each level, Y overall (Simpson''s paradox) because X has 80 percent beginners, who pass less often in both programs.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5afdd8-506a-4b18-bba8-e854d6e37c77', 'NC26.M1.SDSR.3', 3, 'numeric', 'Combining group means', 'In a dataset, 20 students in group A have a mean quiz score of 70, and 30 students in group B have a mean quiz score of 90. What is the mean quiz score of all 50 students?', '[]', '82', '(20*70+30*90)/(20+30)', 'Total points in group A: $20 \times 70 = 1{,}400$. Total points in group B: $30 \times 90 = 2{,}700$. All 50 students: $\frac{1{,}400 + 2{,}700}{50} = \frac{4{,}100}{50} = 82$.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 20 x 70 + 30 x 90 = 1400 + 2700 = 4100. Mean = 4100/50 = 82.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72581f72-0f02-49f6-af93-5f340e746de3', 'NC26.M1.SDSR.3', 3, 'choice', 'Splitting data to improve a model', 'A student plots test score against hours studied for 60 students and finds only a weak pattern. She then separates the students into a morning class and an evening class. Each group shows a clear, steady pattern, but the two patterns are different. What does this suggest?', '["Class time is a third variable that should be included in the analysis","Hours studied has no relationship with test score","The data should be thrown away because the first pattern was weak","Evening students are better at math than morning students"]', 'Class time is a third variable that should be included in the analysis', NULL, 'The weak overall pattern comes from mixing two groups with different patterns. Splitting by class time reveals the relationship in each group, so class time should be part of the model.', 'checked', '{"lint":[],"solve":{"answer":"Class time is a third variable that should be included in the analysis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Splitting by class reveals clear but different patterns, so class time is a third variable that should be included. Hours studied clearly does relate within groups, so option 1 is wrong; option 4 is not supported.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0e768bb-261a-4a78-ac43-993fe7cd6874', 'NC26.M1.SDSR.4', 1, 'choice', 'Describing direction and form', 'A scatter plot has the points $(1, 2)$, $(2, 4)$, $(3, 5)$, $(4, 7)$ and $(5, 9)$. Which best describes the pattern?', '["negative and roughly linear","no clear pattern","a curve that levels off","positive and roughly linear"]', 'positive and roughly linear', NULL, 'As $x$ increases, $y$ increases steadily by about 2 each time, so the points rise along a roughly straight line: a positive, roughly linear association.', 'checked', '{"lint":[],"solve":{"answer":"positive and roughly linear","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y increases with x by 2,1,2,2: positive and close to a straight line.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc9b77f4-9ff5-441f-a23b-4a8a0efceb19', 'NC26.M1.SDSR.4', 1, 'choice', 'Reading a point on a scatter plot', 'In a scatter plot, each point is (hours studied, quiz score). What does the point $(3, 78)$ mean?', '["A student studied for 78 hours and scored 3","A student studied for 3 hours and scored 78","Three students each scored 78","A student scored 3 points higher after studying for 78 hours"]', 'A student studied for 3 hours and scored 78', NULL, 'The first number is the hours studied and the second is the quiz score, so the point is a student who studied 3 hours and scored 78.', 'checked', '{"lint":[],"solve":{"answer":"A student studied for 3 hours and scored 78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = hours studied = 3, y = quiz score = 78: a student studied 3 hours and scored 78.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('214bde01-5d47-45ec-be85-f6b311f53112', 'NC26.M1.SDSR.4', 1, 'numeric', 'Predicting from a line of best fit', 'A line of best fit for hours studied ($x$) and quiz score ($y$) is $y = 4x + 50$. Use the line to predict the quiz score of a student who studies 6 hours.', '[]', '74', '4*6+50', 'Substitute $x = 6$: $y = 4(6) + 50 = 24 + 50 = 74$.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 4(6) + 50 = 74.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94d7913e-a81d-44d2-bcd1-e9f0bebed7ef', 'NC26.M1.SDSR.4', 2, 'choice', 'Comparing the strength of associations', 'Data set P is $(1, 2)$, $(2, 4)$, $(3, 6)$, $(4, 8)$, $(5, 10)$. Data set Q is $(1, 3)$, $(2, 2)$, $(3, 6)$, $(4, 5)$, $(5, 8)$. Which statement is correct?', '["Q shows a stronger linear association than P","P shows a stronger linear association than Q","P and Q show equally strong associations, because both go upward","Q shows a negative association and P a positive one"]', 'P shows a stronger linear association than Q', NULL, 'Every point of P lies exactly on the line $y = 2x$, a perfectly strong linear association. Q rises overall but its points are scattered above and below any line, so the association is positive and weaker.', 'checked', '{"lint":[],"solve":{"answer":"P shows a stronger linear association than Q","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P lies exactly on y = 2x (perfect linear). Q rises overall (3,2,6,5,8) but zigzags, so its linear association is weaker. Both positive.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3cbf874-b280-446d-8377-1f8b56140427', 'NC26.M1.SDSR.4', 2, 'numeric', 'Slope of a line of best fit', 'A line of best fit for the age of a car, $x$ (in years), and its value, $y$ (in thousands of dollars), passes through $(2, 18)$ and $(6, 10)$. What is the slope of the line?', '[]', '-2', '(10-18)/(6-2)', 'Slope $= \frac{10 - 18}{6 - 2} = \frac{-8}{4} = -2$. The value drops by 2 thousand dollars for each extra year of age.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (10 - 18)/(6 - 2) = -8/4 = -2.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd6f4441-29bf-4ef4-bf46-4453731554ea', 'NC26.M1.SDSR.4', 2, 'choice', 'Recognizing a nonlinear form', 'A scatter plot has the points $(0, 1)$, $(1, 2)$, $(2, 4)$, $(3, 8)$ and $(4, 16)$. Which kind of model fits these points best?', '["A straight line with positive slope","A straight line with negative slope","No pattern at all","A curve that rises faster and faster"]', 'A curve that rises faster and faster', NULL, 'The $y$-values double each time $x$ goes up by 1 (1, 2, 4, 8, 16), so the points rise by larger and larger amounts. They follow an upward curve, not a straight line.', 'checked', '{"lint":[],"solve":{"answer":"A curve that rises faster and faster","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y doubles each step (1,2,4,8,16): exponential growth, a curve rising faster and faster.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1642d530-8c99-4aba-bbaf-1eb2ec0ceccd', 'NC26.M1.SDSR.4', 3, 'choice', 'Interpreting the slope of a line of best fit', 'A line of best fit for hours of practice ($x$) and test score ($y$) is $y = 3x + 40$. Which is the best interpretation of the slope, 3?', '["Each extra hour of practice goes with about 3 more points, on average","A student who does not practice scores about 3","A student who practices 3 hours scores exactly 40","Each extra point goes with about 3 more hours of practice"]', 'Each extra hour of practice goes with about 3 more points, on average', NULL, 'The slope is the change in $y$ for each 1-unit increase in $x$: each extra hour of practice goes with about 3 more points of score, on average. The 40 is the predicted score for 0 hours.', 'checked', '{"lint":[],"solve":{"answer":"Each extra hour of practice goes with about 3 more points, on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 3 = predicted change in score per extra hour of practice: about 3 more points per hour on average.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cd6a45e-67aa-4fbf-be05-6135c9eadb36', 'NC26.M1.SDSR.4', 3, 'numeric', 'Predicting from two points on a line', 'A line of best fit passes through $(1, 12)$ and $(5, 20)$. Use the line to predict $y$ when $x = 8$.', '[]', '26', '12+(20-12)/(5-1)*(8-1)', 'Slope $= \frac{20 - 12}{5 - 1} = 2$. From $x = 1$ to $x = 8$ is 7 units, so $y$ rises by $2 \times 7 = 14$ from 12: $y = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (20 - 12)/(5 - 1) = 2. y = 12 + 2(x - 1); at x = 8, y = 12 + 14 = 26.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df62c12d-cb00-4c5e-b4ac-0f92abf0af75', 'NC26.M1.SDSR.4', 3, 'choice', 'Critiquing a misleading display', 'A news graph shows the test pass rates of two classes as bars. Class A''s pass rate is 90 percent and Class B''s is 85 percent. The vertical axis starts at 80 percent instead of 0, so Class A''s bar looks twice as tall as Class B''s. Why is this display misleading?', '["Bars should never be used to compare two classes","The pass rates should have been shown as decimals","Starting the axis at 80 makes a small difference look much larger than it is","Class B''s bar should be taller because its class is smaller"]', 'Starting the axis at 80 makes a small difference look much larger than it is', NULL, 'With the axis starting at 80, the bars show heights of 10 and 5, which looks like a 2-to-1 difference. The real pass rates, 90 and 85 percent, differ by only 5 points.', 'checked', '{"lint":[],"solve":{"answer":"Starting the axis at 80 makes a small difference look much larger than it is","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bars from 80: A shows 10, B shows 5, so A looks twice as tall although the difference is only 5 points. Truncated axis exaggerates the difference.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75aea6af-aad5-4893-82b7-0bc78cb041d1', 'NC26.M1.SDSR.5', 1, 'choice', 'Strength of a correlation coefficient', 'Four data sets have these correlation coefficients, $r$. Which value shows the strongest linear relationship?', '["0.6","0.2","-0.4","-0.9"]', '-0.9', '-0.9', 'The strength of a linear relationship depends on how close $r$ is to $1$ or $-1$, not on its sign. Of the four, $-0.9$ is the closest to $-1$, so it is the strongest.', 'checked', '{"lint":[],"solve":{"answer":"-0.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strength is |r|: 0.9 > 0.6 > 0.4 > 0.2, so -0.9.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65317492-b01c-40f6-9dcb-42fd95bd0822', 'NC26.M1.SDSR.5', 1, 'numeric', 'Computing a residual', 'A residual is the actual value minus the predicted value. A line predicts a quiz score of 47 for a student, but the student actually scored 52. What is the residual?', '[]', '5', '52-47', 'Residual $=$ actual $-$ predicted $= 52 - 47 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Residual = 52 - 47 = 5.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('480de9e5-9d66-4e80-9fe0-90af384d4e92', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation is not causation', 'Data show that towns with more ice cream sales also have more sunburns. What is the best conclusion?', '["Eating ice cream causes people to get sunburned","Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns","Getting sunburned causes people to buy more ice cream","There is no relationship between ice cream sales and sunburns"]', 'Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns', NULL, 'The two go up together, so they are correlated. But a third variable, hot sunny weather, can explain both. A correlation alone does not show that one thing causes the other.', 'checked', '{"lint":[],"solve":{"answer":"Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correlation is not causation; hot sunny weather is a likely common cause of both.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87faf088-ae97-4fc1-8568-6c8dfa68d8f7', 'NC26.M1.SDSR.5', 2, 'numeric', 'Predicting from a least-squares line', 'The least-squares line for a plant''s height, $y$ (in centimeters), after $x$ weeks is $\hat{y} = 1.5x + 12.4$. Use the line to predict the height after 6 weeks, in centimeters.', '[]', '21.4', '1.5*6+12.4', 'Substitute $x = 6$: $\hat{y} = 1.5(6) + 12.4 = 9 + 12.4 = 21.4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"21.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 1.5(6) + 12.4 = 9 + 12.4 = 21.4.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
