INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4682bc4-808c-4047-b15d-52c0a17fb635', 'NC26.M1.SDSR.5', 2, 'choice', 'Judging an extrapolated prediction', 'A line fits the heights of children aged 5 to 12 well. A student uses the line to predict the height of a 40-year-old. Why is this prediction unreliable?', '["Predictions from a line of best fit are never reliable","A line of best fit must pass through every point to be used","Age 40 is far outside the ages in the data, and the pattern may not continue","Height cannot be predicted from age at all"]', 'Age 40 is far outside the ages in the data, and the pattern may not continue', NULL, 'The line was fitted to ages 5 to 12. Predicting far outside that range (extrapolating) assumes the same pattern continues, but people stop growing as they become adults.', 'checked', '{"lint":[],"solve":{"answer":"Age 40 is far outside the ages in the data, and the pattern may not continue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Extrapolation far outside the data range (5-12); growth stops in adulthood so the line will not hold.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5394a825-0ff1-48fb-b27e-148f09ed632e', 'NC26.M1.SDSR.5', 2, 'choice', 'Meaning of an exponential growth factor', 'A town''s population is modeled by $P = 2{,}000(1.05)^t$, where $t$ is the number of years. What does the 1.05 tell you?', '["The population grows by 5 percent each year","The population grows by 105 percent each year","The population grows by 1.05 people each year","The population shrinks by 5 percent each year"]', 'The population grows by 5 percent each year', NULL, 'Each year the population is multiplied by 1.05, which is 100 percent plus 5 percent. So it grows by 5 percent each year.', 'checked', '{"lint":[],"solve":{"answer":"The population grows by 5 percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth factor 1.05 = 1 + 0.05: the population grows by 5 percent each year (it becomes 105 percent of the previous year, not grows by 105 percent).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71b160e6-80e2-47c9-bd2e-f67015cefed0', 'NC26.M1.SDSR.5', 3, 'choice', 'Effect of an outlier on correlation', 'For a set of 20 data points, $r = 0.45$. After one point that lies far from the pattern is removed, $r$ becomes $0.92$. What does this suggest about that point?', '["It proved that the two variables are not related","Removing any point always raises the correlation","It was an outlier that was weakening the linear pattern","The two variables now cause each other"]', 'It was an outlier that was weakening the linear pattern', NULL, 'The remaining 19 points follow a strong linear pattern ($r = 0.92$). The one point far from it pulled the correlation down, so it is an outlier. Removing a point does not always raise $r$, and a correlation never proves cause.', 'checked', '{"lint":[],"solve":{"answer":"It was an outlier that was weakening the linear pattern","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Removing one far-off point raised r from 0.45 to 0.92, so that point was an outlier weakening the linear pattern.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71d79481-19e1-4251-82d2-3ea126b109f1', 'NC26.M1.SDSR.5', 3, 'numeric', 'Evaluating an exponential model', 'The value of a car is modeled by $V = 20{,}000(0.9)^t$, where $V$ is its value in dollars and $t$ is its age in years. What is the value of the car after 2 years, in dollars?', '[]', '16200', '20000*0.9^2', 'Substitute $t = 2$: $V = 20{,}000(0.9)^2 = 20{,}000(0.81) = 16{,}200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"16200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 20000 x 0.9^2 = 20000 x 0.81 = 16200.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cef7b8a-73a0-44bf-930b-1bd18a57f245', 'NC26.M1.SDSR.5', 3, 'choice', 'Reading a residual plot', 'A residual plot for a linear model shows the residuals forming a clear U-shaped curve instead of a random scatter around 0. What does this suggest?', '["A straight line is not the best model; a curve may fit better","The linear model fits the data perfectly","The correlation coefficient must be exactly 0","Every data point is an outlier"]', 'A straight line is not the best model; a curve may fit better', NULL, 'A good linear model leaves residuals scattered randomly around 0. A clear curved pattern in the residuals means the data bend away from a straight line, so a curved model, such as an exponential one, may fit better.', 'checked', '{"lint":[],"solve":{"answer":"A straight line is not the best model; a curve may fit better","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A curved pattern in residuals means the linear model misses curvature; a nonlinear model may fit better.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08a331d8-b776-4cf1-a173-01ae00b0af2c', 'NC26.M1.SDSR.6', 1, 'choice', 'Reporting a conclusion accurately', 'In a random sample of 100 students, 60 said they prefer online homework. Which statement reports this accurately?', '["60 percent of all students everywhere prefer online homework","Online homework is better for learning","Exactly 60 percent of the students in the school prefer online homework","In the sample, 60 percent of the students prefer online homework"]', 'In the sample, 60 percent of the students prefer online homework', NULL, 'The data tell us what happened in the sample: 60 of 100 students prefer online homework. They do not show that online homework is better for learning, and a sample cannot tell us the exact percent for everyone.', 'checked', '{"lint":[],"solve":{"answer":"In the sample, 60 percent of the students prefer online homework","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/100 = 60 percent of the sample. The other options over-generalize, claim exactness for the school, or claim causation.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1b77d50-bcb5-4da6-a868-08e50b109d24', 'NC26.M1.SDSR.6', 1, 'choice', 'Steps of a statistical investigation', 'A class carries out a statistical investigation. Which step should come first?', '["Collect the data","Pose a statistical question","Analyze the data","Share the conclusions"]', 'Pose a statistical question', NULL, 'An investigation starts by asking a question that data can answer. Then the data are collected, analyzed, and the conclusions are shared.', 'checked', '{"lint":[],"solve":{"answer":"Pose a statistical question","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The investigation process begins with posing a statistical question, then collecting, analyzing, interpreting/sharing.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7c1717c-c5e1-4715-b9fe-7ac20f796028', 'NC26.M1.SDSR.6', 1, 'choice', 'Judge whether a claim in an ad can be trusted', 'An ad says, "9 out of 10 people we asked like our juice best." Which information would help you decide whether the claim can be trusted?', '["What color the juice bottle is","How many seconds long the ad is","How many people were asked, and how they were picked","How much one bottle of juice costs"]', 'How many people were asked, and how they were picked', NULL, 'To trust "9 out of 10", you need to know about the survey itself: how many people were asked and how they were chosen. If only 10 friends of the company were asked, the claim says little. The color of the bottle, the length of the ad and the price do not tell you whether the survey was fair.', 'checked', '{"lint":[],"solve":{"answer":"How many people were asked, and how they were picked","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trusting a survey claim depends on the sample size and how the sample was chosen (e.g., only asking existing customers). Bottle color, price and ad length say nothing about the claim''s reliability.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0e520c5-8984-49cb-885b-1f10a5a16d7a', 'NC26.M1.SDSR.6', 2, 'choice', 'Limits of conclusions from an observational study', 'A study at one school finds that students who exercise more have higher grades. Which conclusion is best supported by the study?', '["Exercise causes higher grades for all students in the country","Exercise and grades are associated here, but this does not show that exercise causes higher grades","Higher grades cause students to exercise more","Exercise has no effect on grades"]', 'Exercise and grades are associated here, but this does not show that exercise causes higher grades', NULL, 'The study found an association at one school. It does not show cause and effect in either direction, and it cannot speak for all students in the country.', 'checked', '{"lint":[],"solve":{"answer":"Exercise and grades are associated here, but this does not show that exercise causes higher grades","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An observational study at one school shows association only, not causation, and cannot be generalized to the country.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b675ba08-f51d-495f-bc7e-13039010c70f', 'NC26.M1.SDSR.6', 2, 'choice', 'Critiquing a percent-change claim', 'An ad says, "Our tutoring raised average quiz scores by 50 percent!" The average score went from 2 points to 3 points out of 100. Why is the claim misleading?', '["A 50 percent increase is not possible with quiz scores","The score should have gone from 2 to 4 for a 50 percent increase","Percentages should never be used in advertising","A small starting value makes a gain of 1 point look like a large percent increase"]', 'A small starting value makes a gain of 1 point look like a large percent increase', NULL, 'Going from 2 to 3 is an increase of 1 point, which is $\frac{1}{2} = 50$ percent of the starting score, so the 50 percent is correct. But both scores are tiny out of 100, so the percent makes a very small gain sound large.', 'checked', '{"lint":[],"solve":{"answer":"A small starting value makes a gain of 1 point look like a large percent increase","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 to 3 is indeed a 50 percent increase (1/2), but it is only 1 point out of 100; the small base makes the gain look large. Option 1 is false (2 to 4 is 100 percent).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fba1562-c1c5-40b7-99e9-424e5986d047', 'NC26.M1.SDSR.6', 2, 'numeric', 'Applying a sample result to a population', 'A report says that 18 of the 24 students in a sample improved. Suppose the same percent of all 600 students in the school improved. How many students would that be?', '[]', '450', '18/24*600', '$\frac{18}{24} = 0.75$, which is 75 percent. 75 percent of 600 is $0.75 \times 600 = 450$ students.', 'checked', '{"lint":[],"solve":{"answer":"450","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 0.75. 0.75 x 600 = 450.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dfcb713-8440-4dc8-a225-dfe8cf85dedb', 'NC26.M1.SDSR.6', 3, 'choice', 'Generalizing beyond the sample', 'A student surveys 30 classmates in her homeroom about screen time. She then states, "Students in our whole district spend about 3 hours a day on screens." Which is the best critique?', '["Her homeroom was not a random sample of the district, so the claim may not apply to all students","She should have surveyed fewer students","Screen time cannot be measured in hours","She should have surveyed only students who use screens a lot"]', 'Her homeroom was not a random sample of the district, so the claim may not apply to all students', NULL, 'One homeroom is not chosen at random from the district, so it may differ from the other students. A conclusion about the whole district needs a sample that represents the district.', 'checked', '{"lint":[],"solve":{"answer":"Her homeroom was not a random sample of the district, so the claim may not apply to all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One homeroom is a convenience sample, not random or representative of the district, so generalizing to the district is not justified.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63abe94a-dbf3-4c76-ae78-3eb5bf18e1ac', 'NC26.M1.SDSR.6', 3, 'choice', 'Critiquing an average in the media', 'A news report says, "The average (mean) home price in the town is 450 thousand dollars." Most homes sold for about 200 thousand dollars, but a few very large homes sold for over 2 million dollars. Which is the best critique?', '["The mean is always the best measure of a typical value","The report should have used the largest price instead","A few very expensive homes raise the mean, so the median would describe a typical home better","The report is correct because most homes cost 450 thousand dollars"]', 'A few very expensive homes raise the mean, so the median would describe a typical home better', NULL, 'The very expensive homes pull the mean far above what most homes cost. The median is not affected much by a few extreme values, so it describes a typical home better here.', 'checked', '{"lint":[],"solve":{"answer":"A few very expensive homes raise the mean, so the median would describe a typical home better","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right-skewed prices: a few very expensive homes pull the mean far above the typical 200 thousand; the median is a better measure of a typical home.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca3edc8c-f12c-4b24-8694-805644d5547f', 'NC26.M1.SDSR.6', 3, 'choice', 'What a report should include', 'A student finishes a statistical investigation and writes a report for her class. Which should the report include so that readers can judge the conclusions fairly?', '["Only the results that support her conclusion","Only the final conclusion, without how the data were collected","Her opinion of which classmates answered best","How the sample was chosen, how many were included, and what the data cannot show"]', 'How the sample was chosen, how many were included, and what the data cannot show', NULL, 'Readers need to know how the data were gathered and what the study can and cannot tell them. Leaving out opposing results or the method hides information they need.', 'checked', '{"lint":[],"solve":{"answer":"How the sample was chosen, how many were included, and what the data cannot show","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fair report states the sampling method, sample size and limitations; the other options hide information or add bias.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
